  pol_eco_board_moderators                          pol_eco_board_moderators?
  pol_eco_board_admins                              pol_eco_board_admins?
  pol_eco_board_auth_sessions                       pol_eco_board_auth_sessions[]
  pol_eco_board_role_transitions                    pol_eco_board_role_transitions[]
  pol_eco_board_account_audits_of_actor_id          pol_eco_board_account_audits[]           @relation("pol_eco_board_account_audits_of_actor_id")
  pol_eco_board_account_audits_of_target_account_id pol_eco_board_account_audits[]           @relation("pol_eco_board_account_audits_of_target_account_id")
  pol_eco_board_posts                               pol_eco_board_posts[]
  pol_eco_board_post_edits                          pol_eco_board_post_edits[]
  pol_eco_board_comments                            pol_eco_board_comments[]
  pol_eco_board_comment_edits                       pol_eco_board_comment_edits[]
  pol_eco_board_votes                               pol_eco_board_votes[]
  pol_eco_board_reports                             pol_eco_board_reports[]
  pol_eco_board_attachments                         pol_eco_board_attachments[]
  pol_eco_board_sanctions                           pol_eco_board_sanctions[]
  pol_eco_board_appeals                             pol_eco_board_appeals[]
  pol_eco_board_notifications                       pol_eco_board_notifications[]
  pol_eco_board_notification_preferences            pol_eco_board_notification_preferences[]

  @@unique([email])
  @@unique([display_name])
  @@index([created_at])
  @@index([is_active])
}

/// Moderator accounts elevated from members for content/business enforcement
/// powers. Tracks appointment and privileges, with references to both the
