  pol_eco_board_board_histories             pol_eco_board_board_histories[]
  pol_eco_board_moderator_board_assignments pol_eco_board_moderator_board_assignments[]
  pol_eco_board_moderation_actions          pol_eco_board_moderation_actions[]
  pol_eco_board_escalations                 pol_eco_board_escalations[]

  @@unique([member_id])
  @@index([is_active])
}

/// Platform/system admins with authority for all
/// security/policy/analytics/role management. Each record links an admin to
