/**
 * Validate that moderators can search notification failures across all users and see full details, including fields inaccessible to standard members.
 *
 * This test authenticates as a moderator, creates notification failures for multiple different members, and then uses the moderator notification failure search API with a broad filter to retrieve all failures. It confirms:
 * - Moderator receives failures for all members (not just their own)
 * - Extra fields or details expected for moderator role are present
 * - Filtering by failure_code and provider returns only matching records
 * - Security: Only moderators can retrieve cross-user data; proper access control is enforced
 *
 * Workflow:
 * 1. Register and log in a moderator to obtain moderator privileges and JWT.
 * 2. Register at least two member (user) accounts.
 * 3. As admin, create notification failures for both members with distinguishable failure_code/provider.
 * 4. As moderator, perform PATCH search with a wide filter and confirm all created failures (for both users) are returned.
 * 5. Validate that at least required fields (including internal/provider info) are present that are not exposed to regular members, by structure inspection.
 * 6. Test filter edge cases by querying with a specific failure_code and a provider_id, validating only appropriate failures are returned.
 * 7. Confirm no unauthorized data leakage (other members, etc.), and completeness for allowed view.
 */
export async function test_api_notification_failure_moderator_search_access_control(
  connection: api.IConnection,
) {
  // 1. Register and log in as moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "Test1234!abcd";
  const moderatorDisplayName = RandomGenerator.name();
  await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: "accepted:2025-01-01",
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  const modLoginResp = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(modLoginResp);

  // 2. Register two member accounts
  const member1email = typia.random<string & tags.Format<"email">>();
  const member2email = typia.random<string & tags.Format<"email">>();
  const memberPassword = "TestMemberPass1!";
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: member1email,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: member2email,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });

  // 3. As admin, create notification failures for both members
  const notificationId1 = typia.random<string & tags.Format<"uuid">>();
  const notificationId2 = typia.random<string & tags.Format<"uuid">>();
  const providerId = typia.random<string & tags.Format<"uuid">>();
  const failureCode1 = "ERR_MEMBER1_TESTCASE";
  const failureCode2 = "ERR_MEMBER2_TESTCASE";

  // First notification failure for member 1
  const failure1 = await api.functional.polEcoBoard.admin.notificationFailures.create(connection, {
    body: {
      notification_id: notificationId1,
      provider_id: providerId,
      failure_code: failureCode1,
      failure_message: "Delivery to member 1 failed: test case",
      occurred_at: new Date().toISOString() as string & tags.Format<"date-time">,
      resolution_status: "pending",
    } satisfies IPolEcoBoardNotificationFailure.ICreate,
  });
  typia.assert(failure1);

  // Second notification failure for member 2
  const failure2 = await api.functional.polEcoBoard.admin.notificationFailures.create(connection, {
    body: {
      notification_id: notificationId2,
      provider_id: providerId,
      failure_code: failureCode2,
      failure_message: "Delivery to member 2 failed: test case",
      occurred_at: new Date().toISOString() as string & tags.Format<"date-time">,
      resolution_status: "permanent_failure",
    } satisfies IPolEcoBoardNotificationFailure.ICreate,
  });
  typia.assert(failure2);

  // 4. Moderator search with a broad filter (all failures)
  const allFailuresPage = await api.functional.polEcoBoard.moderator.notificationFailures.search(connection, {
    body: { limit: 100, page: 1 },
  });
  typia.assert(allFailuresPage);
  const foundFailureIds = allFailuresPage.data.map((f) => f.id);
  TestValidator.predicate("Both failures are visible to moderator")(
    foundFailureIds.includes(failure1.id) && foundFailureIds.includes(failure2.id),
  );

  // 5. Validate moderator sees all details (provider_id, failure_code, messages, etc.)
  for (const failure of allFailuresPage.data) {
    TestValidator.predicate("provider_id present")(typeof failure.provider_id === "string" || failure.provider_id === null);
    TestValidator.predicate("failure_code present")(typeof failure.failure_code === "string");
    TestValidator.predicate("failure_message present")(typeof failure.failure_message === "string");
    TestValidator.predicate("occurred_at is ISO")(
      typeof failure.occurred_at === "string" && !isNaN(Date.parse(failure.occurred_at)),
    );
  }

  // 6. Filtering by failure_code returns only intended records
  const failure1CodePage = await api.functional.polEcoBoard.moderator.notificationFailures.search(connection, {
    body: { failure_code: failureCode1 },
  });
  typia.assert(failure1CodePage);
  TestValidator.predicate("failure_code filter includes correct failure")(
    failure1CodePage.data.some((f) => f.id === failure1.id),
  );
  TestValidator.predicate("failure_code filter excludes wrong code")(
    failure1CodePage.data.every((f) => f.failure_code === failureCode1),
  );

  // 7. Filtering by provider_id returns both failures
  const providerFilterPage = await api.functional.polEcoBoard.moderator.notificationFailures.search(connection, {
    body: { provider_id: providerId },
  });
  typia.assert(providerFilterPage);
  TestValidator.predicate("provider_id filter yields both failures")(
    providerFilterPage.data.filter((f) => f.provider_id === providerId).length >= 2,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotificationFailure } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotificationFailure";
import type { IPageIPolEcoBoardNotificationFailure } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardNotificationFailure";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate comprehensive searching and pagination of notification failures as an admin.
 *
 * This test validates that the admin can search and paginate all notification delivery failures using advanced filters, verifying visibility and security boundaries.
 *
 * 1. Register a unique admin and log in to acquire authentication for privileged actions.
 * 2. Prepare multiple notification failure records:
 *    - Vary recipients (recipient_member_id), notification_id, provider_id, failure_code, and resolution_status.
 *    - Ensure enough records so pagination is meaningful (limit < total records).
 * 3. As admin, run search API with:
 *    - No filters, validate all created failures are visible in correct order.
 *    - Various combinations: by failure_code, by provider_id, by resolution_status, and combinations thereof. Validate returned results match expected records, filtering correctly. Check that field values are correct and complete.
 *    - Pagination: check default, custom limit, and different page returns. Confirm correct pagination metadata and sliced datasets.
 *    - Filtering for non-existent failure_code or made-up recipient_member_id: expect empty result set and correct pagination metadata.
 * 4. Security: Remove Authorization or login as a non-admin. Search attempt should be forbidden/denied (business error thrown).
 */
export async function test_api_notification_failure_admin_search_full_scope(connection: api.IConnection) {
  // 1. Register and login as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);

  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 2. Create test notification failures for several members/providers/codes/status
  const recipients = ArrayUtil.repeat(3)(() => typia.random<string & tags.Format<"uuid">>());
  const notifications = ArrayUtil.repeat(2)(() => typia.random<string & tags.Format<"uuid">>());
  const providers = [typia.random<string & tags.Format<"uuid">>(), undefined];
  const codes = ["smtp_421", "api_LIMIT", "sys_MEMFAILS"];
  const statuses = ["pending", "resolved", "permanent_failure"];

  // Flatten all combinations; create extra for pagination validation
  const allFailures: IPolEcoBoardNotificationFailure[] = [];
  for (const recipient of recipients) {
    for (const notification_id of notifications) {
      for (const provider_id of providers) {
        for (const failure_code of codes) {
          for (const resolution_status of statuses) {
            // Vary occurred_at by time for deterministic order
            const occurred_at = new Date(Date.now() - Math.floor(Math.random() * 1000000)).toISOString();
            const failure = await api.functional.polEcoBoard.admin.notificationFailures.create(connection, {
              body: {
                notification_id,
                ...(provider_id !== undefined ? { provider_id } : {}),
                failure_code,
                failure_message: `${failure_code} for recipient ${recipient}`,
                occurred_at,
                resolution_status,
              } satisfies IPolEcoBoardNotificationFailure.ICreate,
            });
            typia.assert(failure);
            // Attach recipient_member_id for search tests since API allows filter but not create
            (failure as any).recipient_member_id = recipient;
            allFailures.push(failure);
          }
        }
      }
    }
  }

  // 3. Advanced filter/search and pagination validation
  // a) No filter, get all
  let pageResp = await api.functional.polEcoBoard.admin.notificationFailures.search(connection, { body: { } });
  typia.assert(pageResp);
  TestValidator.predicate("all failures are visible")(pageResp.pagination.records >= allFailures.length);
  const returnedIds = pageResp.data.map(f => f.id);
  allFailures.forEach(f => TestValidator.predicate(`returned id ${f.id}`)(returnedIds.includes(f.id)));

  // b) Filter by failure_code
  for (const code of codes) {
    const filtered = allFailures.filter(f => f.failure_code === code);
    pageResp = await api.functional.polEcoBoard.admin.notificationFailures.search(connection, {
      body: { failure_code: code },
    });
    typia.assert(pageResp);
    TestValidator.equals(`failure_code=${code}`)(pageResp.data.length)(filtered.length);
    pageResp.data.forEach(f => TestValidator.equals("code matches")(f.failure_code)(code));
  }

  // c) Filter by provider_id
  for (const provider_id of providers) {
    const filtered = allFailures.filter(f => (f.provider_id ?? undefined) === provider_id);
    // Omit provider_id property entirely if undefined for search
    const filter: IPolEcoBoardNotificationFailure.IRequest =
      provider_id !== undefined ? { provider_id } : {};
    pageResp = await api.functional.polEcoBoard.admin.notificationFailures.search(connection, {
      body: filter,
    });
    typia.assert(pageResp);
    TestValidator.equals(`provider_id=${String(provider_id)}`)(pageResp.data.length)(filtered.length);
    pageResp.data.forEach(f => TestValidator.equals("provider_id matches")(f.provider_id ?? undefined)(provider_id));
  }

  // d) Filter by resolution_status
  for (const status of statuses) {
    const filtered = allFailures.filter(f => f.resolution_status === status);
    pageResp = await api.functional.polEcoBoard.admin.notificationFailures.search(connection, {
      body: { resolution_status: status },
    });
    typia.assert(pageResp);
    TestValidator.equals(`resolution_status=${status}`)(pageResp.data.length)(filtered.length);
    pageResp.data.forEach(f => TestValidator.equals("status matches")(f.resolution_status)(status));
  }

  // e) Combined filter (failure_code + provider + status)
  for (const code of codes) {
    for (const provider_id of providers) {
      for (const status of statuses) {
        const filtered = allFailures.filter(
          f => f.failure_code === code && (f.provider_id ?? undefined) === provider_id && f.resolution_status === status,
        );
        const filter: IPolEcoBoardNotificationFailure.IRequest = {
          failure_code: code,
          ...(provider_id !== undefined ? { provider_id } : {}),
          resolution_status: status,
        };
        pageResp = await api.functional.polEcoBoard.admin.notificationFailures.search(connection, {
          body: filter,
        });
        typia.assert(pageResp);
        TestValidator.equals(`combo filter length: ${code},${String(provider_id)},${status}`)(pageResp.data.length)(filtered.length);
        pageResp.data.forEach(
          f => {
            TestValidator.equals("combo code")(f.failure_code)(code);
            TestValidator.equals("combo provider")(f.provider_id ?? undefined)(provider_id);
            TestValidator.equals("combo status")(f.resolution_status)(status);
          },
        );
      }
    }
  }

  // f) Pagination
  const firstPageLimit = 3;
  pageResp = await api.functional.polEcoBoard.admin.notificationFailures.search(connection, { body: { limit: firstPageLimit } });
  typia.assert(pageResp);
  TestValidator.equals("pagination limit")(pageResp.pagination.limit)(firstPageLimit);
  TestValidator.equals("first page length")(pageResp.data.length)(Math.min(firstPageLimit, allFailures.length));
  if (allFailures.length > firstPageLimit) {
    pageResp = await api.functional.polEcoBoard.admin.notificationFailures.search(connection, { body: { limit: firstPageLimit, page: 2 } });
    typia.assert(pageResp);
    TestValidator.equals("pagination page 2")(pageResp.pagination.current)(2);
  }

  // g) Filter for non-existent failure_code
  pageResp = await api.functional.polEcoBoard.admin.notificationFailures.search(connection, {
    body: { failure_code: "does_NOT_exist_code" },
  });
  typia.assert(pageResp);
  TestValidator.equals("no results")(pageResp.data.length)(0);

  // h) Filter for non-existent recipient_member_id
  pageResp = await api.functional.polEcoBoard.admin.notificationFailures.search(connection, {
    body: { recipient_member_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(pageResp);
  TestValidator.equals("no results for unknown user")(pageResp.data.length)(0);

  // 4. Security: try searching without Authorization (or as non-admin)
  // Remove auth
  const noAuthConnection = { ...connection, headers: {} };
  await TestValidator.error("search with no auth/role fails")(async () => {
    await api.functional.polEcoBoard.admin.notificationFailures.search(noAuthConnection, {
      body: {},
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
