import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test successful creation of a user consent status by admin.
 *
 * This test validates the end-to-end admin workflow for registering and authenticating as a platform administrator, then successfully creating a new consent status event using the /polEcoBoard/admin/consentStatuses endpoint.
 *
 * Steps:
 * 1. Register a new admin user (unique business email and secure password)
 * 2. Log in as the registered admin to activate authentication
 * 3. Prepare a compliant consent status input for a user session and provider/consent type/region
 * 4. Call the endpoint to create the consent status event
 * 5. Validate response: confirm all properties match input, immutable fields (id, created_at) are populated, and schema is satisfied
 *
 * This verifies the endpoint supports authenticated admin consent logging for compliance and privacy record-keeping, with proper schema validation and required business logic.
 */
export async function test_api_consent_status_create_success(
  connection: api.IConnection,
) {
  // 1. Register a unique admin user for write access
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResponse = await api.functional.auth.admin.register.signUp(
    connection,
    {
      body: {
        email: adminEmail,
        password: adminPassword,
      } satisfies IPolEcoBoardAdminAuth.SignUp,
    },
  );
  typia.assert(signUpResponse);

  // 2. Log in as admin to enable authenticated requests
  const signInResponse = await api.functional.auth.admin.login.signIn(
    connection,
    {
      body: {
        email: adminEmail,
        password: adminPassword,
      } satisfies IPolEcoBoardAdminAuth.SignIn,
    },
  );
  typia.assert(signInResponse);

  // 3. Prepare a valid, compliant consent status creation input
  const consentInput: IPolEcoBoardConsentStatus.ICreate = {
    provider_key: RandomGenerator.alphaNumeric(10),
    region: "KR", // South Korea ISO region code for compliance
    consent_type: RandomGenerator.alphaNumeric(8),
    consent_status: RandomGenerator.pick([
      "opt_in",
      "opt_out",
      "revoked",
      "pending",
    ]),
    session_anon_id: RandomGenerator.alphaNumeric(16),
    audit_trail: JSON.stringify({
      actor: "admin",
      timestamp: new Date().toISOString(),
      source: "e2e_test",
      details: RandomGenerator.paragraph()(),
    }),
  };

  // 4. Create the consent status event as the authenticated admin
  const status = await api.functional.polEcoBoard.admin.consentStatuses.create(
    connection,
    {
      body: consentInput,
    },
  );
  typia.assert(status);

  // 5. Validation: ensure returned record matches input & compliance expectations
  TestValidator.equals("provider_key")(status.provider_key)(consentInput.provider_key);
  TestValidator.equals("region")(status.region)(consentInput.region);
  TestValidator.equals("consent_type")(status.consent_type)(consentInput.consent_type);
  TestValidator.equals("consent_status")(status.consent_status)(consentInput.consent_status);
  TestValidator.equals("session_anon_id")(status.session_anon_id)(consentInput.session_anon_id);
  TestValidator.equals("audit_trail")(status.audit_trail)(consentInput.audit_trail);
  TestValidator.predicate("id is a uuid")(!!status.id && typeof status.id === "string");
  TestValidator.predicate("created_at is ISO date-time")(!!status.created_at && typeof status.created_at === "string" && !isNaN(Date.parse(status.created_at)));
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardConsentStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardConsentStatus";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate consent status creation fails with invalid or missing input data.
 *
 * This test ensures the backend API properly rejects malformed, inconsistent, or incomplete input when attempting to create a new consent status event as an admin user. It is critical for compliance and privacy risk management that such erroneous attempts are blocked with descriptive validation errors, and that no non-compliant record is created in the system. Additionally, such attempts should be audit-logged for regulatory accountability.
 *
 * Steps:
 * 1. Register a new admin with a unique email and valid password.
 * 2. Log in as the admin to obtain an authorized session (JWT in connection headers).
 * 3. Attempt to create various invalid consent status records and confirm the API responds with validation errors and no record is created. All tested cases:
 *    a) Unsupported provider_key (e.g., nonsense string).
 *    b) Missing mandatory region property.
 *    c) Missing required consent_type property.
 *    d) Invalid consent_status outside allowed values ('opt_in', 'opt_out', 'revoked', 'pending').
 *    e) Completely empty request body.
 *    f) Malformed session_anon_id (e.g., empty string).
 *    g) Malformed audit_trail (e.g., empty string).
 * 4. (Optional/audit) Confirm that invalid attempts are reflected in the audit log for compliance (future: not implemented here).
 *
 * Each subcase should:
 *   - Send the invalid request and confirm the API rejects it (throws error).
 *   - Not receive a success response or create a record.
 *   - Use TestValidator.error() to confirm the error is thrown, but not inspect error content (per requirements).
 */
export async function test_api_consent_status_create_invalid_data(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Log in as the admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3a. Unsupported provider_key
  TestValidator.error("unsupported provider_key")(() =>
    api.functional.polEcoBoard.admin.consentStatuses.create(connection, {
      body: {
        provider_key: "nonsense_provider",
        region: "US",
        consent_type: "analytics",
        consent_status: "opt_in",
        session_anon_id: RandomGenerator.alphaNumeric(10),
        audit_trail: "Test audit",
      } satisfies IPolEcoBoardConsentStatus.ICreate,
    })
  );

  // 3b. Missing region
  TestValidator.error("missing region")(() =>
    api.functional.polEcoBoard.admin.consentStatuses.create(connection, {
      body: {
        provider_key: "analytics",
        // region missing
        consent_type: "analytics",
        consent_status: "opt_in",
        session_anon_id: RandomGenerator.alphaNumeric(10),
        audit_trail: "Test audit",
      } as any // forcibly missing
    })
  );

  // 3c. Missing consent_type
  TestValidator.error("missing consent_type")(() =>
    api.functional.polEcoBoard.admin.consentStatuses.create(connection, {
      body: {
        provider_key: "analytics",
        region: "US",
        // consent_type missing
        consent_status: "opt_in",
        session_anon_id: RandomGenerator.alphaNumeric(10),
        audit_trail: "Test audit",
      } as any // forcibly missing
    })
  );

  // 3d. Invalid consent_status value
  TestValidator.error("invalid consent_status")(() =>
    api.functional.polEcoBoard.admin.consentStatuses.create(connection, {
      body: {
        provider_key: "analytics",
        region: "US",
        consent_type: "analytics",
        consent_status: "invalid_status",
        session_anon_id: RandomGenerator.alphaNumeric(10),
        audit_trail: "Test audit",
      } satisfies IPolEcoBoardConsentStatus.ICreate,
    })
  );

  // 3e. Completely empty request body
  TestValidator.error("empty request body")(() =>
    api.functional.polEcoBoard.admin.consentStatuses.create(connection, {
      body: {} as any
    })
  );

  // 3f. Malformed session_anon_id (empty string)
  TestValidator.error("empty session_anon_id")(() =>
    api.functional.polEcoBoard.admin.consentStatuses.create(connection, {
      body: {
        provider_key: "analytics",
        region: "US",
        consent_type: "analytics",
        consent_status: "opt_in",
        session_anon_id: "",
        audit_trail: "Test audit",
      } satisfies IPolEcoBoardConsentStatus.ICreate,
    })
  );

  // 3g. Malformed audit_trail (empty string)
  TestValidator.error("empty audit_trail")(() =>
    api.functional.polEcoBoard.admin.consentStatuses.create(connection, {
      body: {
        provider_key: "analytics",
        region: "US",
        consent_type: "analytics",
        consent_status: "opt_in",
        session_anon_id: RandomGenerator.alphaNumeric(10),
        audit_trail: "",
      } satisfies IPolEcoBoardConsentStatus.ICreate,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Comprehensive test for moderator account login scenarios.
 *
 * This test validates the full workflow for moderator login, including both success and various failure scenarios.
 * The flow covers new account registration (prerequisite), successful sign-in, and several types of failed login attempts (invalid password, unknown email, and repeated failures for rate limiting/security).
 *
 * Steps:
 * 1. Register a new moderator account with a unique email/password/display_name/consent_status, and verify registration success.
 * 2. Attempt login with correct credentials and verify successful response (moderator ID, JWT issued, email/display_name match, Authorization header present).
 * 3. Attempt login with correct email but wrong password; expect error response (do not leak security details).
 * 4. Attempt login with unregistered email and a random password; expect error response.
 * 5. Attempt repeated login failures with the same account to trigger rate limiting—validate API returns error after threshold is reached (behavior may depend on implementation).
 * 6. Confirm all error responses do not leak account existence or security info.
 *
 * Note: Test for inactive/banned account is omitted, as there is no API to suspend or deactivate accounts using only public endpoints.
 */
export async function test_api_moderator_login_success_and_failure_cases(
  connection: api.IConnection,
) {
  // 1. Register a new moderator account
  const email = typia.random<string & tags.Format<"email">>();
  const password = "TestPassword123!";
  const displayName = RandomGenerator.name();
  const consentStatus = "v20240813";

  const registerResponse = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email,
      password,
      display_name: displayName,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(registerResponse);
  TestValidator.equals("email matches")(registerResponse.email)(email);
  TestValidator.equals("display_name matches")(registerResponse.display_name)(displayName);
  TestValidator.predicate("Authorization header present")(
    typeof registerResponse.setHeaders?.Authorization === "string" &&
    registerResponse.setHeaders?.Authorization.startsWith("Bearer ")
  );

  // 2. Attempt login with correct credentials
  const loginResponse = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(loginResponse);
  TestValidator.equals("login email matches")(loginResponse.email)(email);
  TestValidator.equals("login display_name matches")(loginResponse.display_name)(displayName);
  TestValidator.predicate("Authorization header present on login")(
    typeof loginResponse.setHeaders?.Authorization === "string" &&
    loginResponse.setHeaders?.Authorization.startsWith("Bearer ")
  );

  // 3. Attempt login with correct email but incorrect password
  await TestValidator.error("login fails with wrong password")(async () => {
    await api.functional.auth.moderator.login.signIn(connection, {
      body: {
        email,
        password: "WrongPassword!@#",
      } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
    });
  });

  // 4. Attempt login with unregistered email
  await TestValidator.error("login fails with non-existent email")(async () => {
    await api.functional.auth.moderator.login.signIn(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "AnotherFakePass1!",
      } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
    });
  });

  // 5. Repeated failed logins to check rate limit/security error
  for (let i = 0; i < 5; i++) {
    await TestValidator.error(`failed login attempt #${i + 1}`)(async () => {
      await api.functional.auth.moderator.login.signIn(connection, {
        body: {
          email,
          password: "DefinitelyWrongPassword123#",
        } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
      });
    });
  }
  // (Optional) The actual error for rate limit vs wrong password may depend on backend; ensure API gives consistent security-friendly errors.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";
import type { IPolEcoBoardModeratorSignOut } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorSignOut";

/**
 * E2E test for moderator logout and session invalidation.
 *
 * This test verifies the full logout flow for a moderator user. It ensures that upon logout, the moderator’s session token is effectively revoked so that further access to protected moderator APIs is denied. It confirms both the success of the logout operation and the idempotency of subsequent logout attempts, also checking that use of a revoked token results in access denial.
 *
 * Test workflow:
 * 1. Register a new moderator account.
 * 2. Log in as the new moderator and save the JWT from the response.
 * 3. Access a protected API with the valid token to confirm authentication is effective.
 * 4. Call logout with the token and check for success.
 * 5. Attempt another call to the protected API with the now-invalid token; confirm it is rejected (session revoked).
 * 6. Attempt to logout again with the same token; verify idempotency and a properly handled error response.
 */
export async function test_api_moderator_logout_session_invalidation(connection: api.IConnection) {
  // 1. Register new moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "P@ssword1!";
  const moderatorName = RandomGenerator.name();
  const consentStatus = "v1.0";

  const registration = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorName,
      consent_status: consentStatus
    } satisfies IPolEcoBoardModeratorRegistration.ICreate
  });
  typia.assert(registration);
  TestValidator.equals("moderator email matches")(registration.email)(moderatorEmail);
  TestValidator.equals("moderator display name matches")(registration.display_name)(moderatorName);
  TestValidator.predicate("registration setHeaders includes Authorization")(
    typeof registration.setHeaders?.Authorization === "string"
  );

  // 2. Log in as moderator
  const login = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });
  typia.assert(login);
  TestValidator.equals("login email matches")(login.email)(moderatorEmail);
  TestValidator.predicate("login setHeaders includes Authorization")(
    typeof login.setHeaders?.Authorization === "string"
  );

  // Save JWT
  const jwt = login.setHeaders.Authorization;
  const authedConnection: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: jwt
    }
  };

  // 3. Access a protected endpoint to confirm token is valid (logout works)
  const preLogoutTest = await api.functional.auth.moderator.logout.signOut(authedConnection);
  typia.assert(preLogoutTest);
  TestValidator.equals("logout success pre")(preLogoutTest.success)(true);

  // 4. Attempt again to logout with now-revoked token
  const secondLogout = await api.functional.auth.moderator.logout.signOut(authedConnection);
  typia.assert(secondLogout);
  TestValidator.equals("logout idempotency")(secondLogout.success)(false);

  // 5. Attempt another protected call (should fail)
  await TestValidator.error("re-using revoked JWT should fail access")(async () => {
    await api.functional.auth.moderator.logout.signOut(authedConnection);
  });

  // 6. Log in again to confirm valid session can be created after a clean logout
  const loginAgain = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });
  typia.assert(loginAgain);
  const jwt2 = loginAgain.setHeaders.Authorization;
  const reAuthedConnection: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: jwt2
    }
  };

  // Clean logout again
  const finalLogout = await api.functional.auth.moderator.logout.signOut(reAuthedConnection);
  typia.assert(finalLogout);
  TestValidator.equals("final logout success")(finalLogout.success)(true);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";
import type { IJwtToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtToken";

/**
 * Validate moderator JWT token acceptance and error cases.
 *
 * This test validates both the acceptance of valid JWT tokens and correct
 * handling of malformed/invalid/revoked token scenarios for moderators.
 *
 * Step-by-step process:
 * 1. Register a new moderator, acquiring a fresh JWT.
 * 2. Validate the issued token from registration; expect acceptance and correct decoded identity.
 * 3. Log in with the same credentials, receive a new JWT.
 * 4. Validate the token from login; ensure identical identity and valid context.
 * 5. Attempt validation with a clearly malformed non-JWT string; must be rejected.
 * 6. Attempt validation with an empty string token; must be rejected.
 * 7. Attempt validation with a syntactically valid but inauthentic/garbage JWT token; must be rejected and not expose sensitive fields.
 * All cases are asserted for both technical acceptance and business logic guarantees.
 */
export async function test_api_moderator_token_validation_valid_and_invalid_tokens(connection: api.IConnection) {
  // 1. Register a new moderator, acquire JWT
  const registrationInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "StrongPa55w0rd??!",
    display_name: RandomGenerator.name(),
    consent_status: "latest_terms_v1",
  } satisfies IPolEcoBoardModeratorRegistration.ICreate;
  const registrationResp = await api.functional.auth.moderator.register.signUp(connection, { body: registrationInput });
  typia.assert(registrationResp);
  const regJwt = registrationResp.setHeaders.Authorization.replace(/^Bearer /, "");
  const moderatorId = registrationResp.moderatorId;

  // 2. Validate registration JWT
  const validCheck = await api.functional.auth.moderator.validate.validateToken(connection, { body: { token: regJwt } });
  typia.assert(validCheck);
  TestValidator.predicate("token valid after registration")(validCheck.isValid === true);
  TestValidator.equals("moderatorId matches after reg")(validCheck.moderatorId)(moderatorId);
  TestValidator.equals("role == moderator")(validCheck.role)("moderator");
  TestValidator.equals("email matches")(validCheck.email)(registrationInput.email);

  // 3. Login as this moderator, get new JWT
  const loginInput = {
    email: registrationInput.email,
    password: registrationInput.password,
  } satisfies IPolEcoBoardModeratorAuthentication.ICreate;
  const loginResp = await api.functional.auth.moderator.login.signIn(connection, { body: loginInput });
  typia.assert(loginResp);
  const loginJwt = loginResp.setHeaders.Authorization.replace(/^Bearer /, "");
  TestValidator.equals("login moderatorId matches reg")(loginResp.moderatorId)(moderatorId);

  // 4. Validate login JWT
  const loginValidCheck = await api.functional.auth.moderator.validate.validateToken(connection, { body: { token: loginJwt } });
  typia.assert(loginValidCheck);
  TestValidator.predicate("token valid after login")(loginValidCheck.isValid === true);
  TestValidator.equals("moderatorId matches after login")(loginValidCheck.moderatorId)(moderatorId);
  TestValidator.equals("role == moderator")(loginValidCheck.role)("moderator");
  TestValidator.equals("email matches after login")(loginValidCheck.email)(registrationInput.email);

  // 5. Clearly malformed non-JWT token
  const malformedTokenResp = await api.functional.auth.moderator.validate.validateToken(connection, { body: { token: "NOT.A.JWT" } });
  typia.assert(malformedTokenResp);
  TestValidator.predicate("malformed token rejected")(malformedTokenResp.isValid === false);

  // 6. Empty string token
  const emptyTokenResp = await api.functional.auth.moderator.validate.validateToken(connection, { body: { token: "" } });
  typia.assert(emptyTokenResp);
  TestValidator.predicate("empty token rejected")(emptyTokenResp.isValid === false);

  // 7. Syntactically correct but fabricated JWT
  const fakeJwt = [
    "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9",
    "eyJ1c2VyIjoibm9uZSIsImV4cCI6MTYyMDAwMDAwMH0",
    "NOTASIGNATURE"
  ].join(".");
  const fakeTokenResp = await api.functional.auth.moderator.validate.validateToken(connection, { body: { token: fakeJwt } });
  typia.assert(fakeTokenResp);
  TestValidator.predicate("fake/junk JWT rejected")(fakeTokenResp.isValid === false);
  TestValidator.predicate("invalid token should not expose moderatorId")(!fakeTokenResp.moderatorId);
  TestValidator.predicate("invalid token should not expose memberId")(!fakeTokenResp.memberId);
  TestValidator.predicate("invalid token should not expose email")(!fakeTokenResp.email);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";
import type { IPolEcoBoardModeratorPasswordChange } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorPasswordChange";

/**
 * Validate moderator password change workflow, including session revocation and policy enforcement.
 *
 * Business flow:
 * 1. Register a fresh moderator account (unique email, strong password, and display name).
 * 2. Login as the moderator to confirm credentials and receive current JWT session.
 * 3. Change password using the valid current session and the correct old password with a valid new password (tests successful case).
 * 4. After password change, verify that previously issued JWTs are invalid (all sessions revoked) by attempting protected action; must require re-authentication.
 * 5. Attempt password change with invalid old/current password (should fail with an error).
 * 6. Attempt password change using a weak or short new password (should fail with error: password policy enforced).
 * 7. Successfully login with new password and confirm old password no longer works.
 *
 * Validations:
 * - Successful password change returns success and a valid message.
 * - After password is changed, using the old JWT for any protected action fails (session revoked).
 * - Login with old password after password change fails.
 * - Login with new password after password change succeeds.
 * - Password change with wrong current password fails.
 * - Password change with weak/short/invalid new password fails.
 */
export async function test_api_moderator_change_password_with_valid_and_invalid_inputs(
  connection: api.IConnection,
) {
  // 1. Register a new moderator account
  const email = typia.random<string & tags.Format<"email">>();
  const password = "ValidStr0ngP@ssw0rd!";
  const display_name = RandomGenerator.name();
  const consent_status = "2024-privacy-accepted";
  const registration = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email,
      password,
      display_name,
      consent_status,
    },
  });
  typia.assert(registration);
  TestValidator.equals("registration email matches")(registration.email)(email);

  // 2. Login as the moderator
  const login = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email,
      password,
    },
  });
  typia.assert(login);
  TestValidator.equals("login email matches")(login.email)(email);
  // Snapshot the current JWT from the connection after login
  const oldJwt = connection.headers?.Authorization;

  // 3. Change password via the authenticated session
  const new_password = "EvenStr0ngerP@ssw0rd2!";
  const passwordChange = await api.functional.auth.moderator.password.changePassword(connection, {
    body: {
      old_password: password,
      new_password,
    },
  });
