 * Business context: Members must provide their valid current password to change their account password. The system should block the change and NOT alter authentication if the current password is invalid.
 *
 * Workflow:
 * 1. Register a new member account with a unique email and password.
 * 2. Log in with the registered credentials to establish baseline authentication.
 * 3. Attempt to change the password while providing an incorrect (random) current password and a new valid password.
 * 4. Validate that the API response indicates failure (success: false), with an appropriate message, and no session/revocation occurs.
 * 5. Confirm that the member can still authenticate using the original password, and cannot authenticate using the new password.
 */
export async function test_api_member_password_change_with_incorrect_current_password(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.Format<"password">>();
  const signUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(signUpResult);

  // 2. Log in with registered credentials
  const signInResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IMemberAuthenticationMemberSignIn
  });
  typia.assert(signInResult);

  // 3. Attempt to change password using an incorrect current password
  let wrongPassword = typia.random<string & tags.Format<"password">>();
  // Ensure the wrong password is not accidentally the same as the real password
  while(wrongPassword === password) {
    wrongPassword = typia.random<string & tags.Format<"password">>();
  }
  const newPassword = typia.random<string & tags.Format<"password">>();

  const changePasswordResult = await api.functional.auth.member.password.changePassword(connection, {
    body: {
      current_password: wrongPassword,
      new_password: newPassword,
    } satisfies IMemberAuthenticationMemberChangePassword,
  });
  typia.assert(changePasswordResult);
  // 4. Check failure state and business rule enforcement
  TestValidator.equals("change password should fail")(changePasswordResult.success)(false);
  TestValidator.predicate("failure message present")(typeof changePasswordResult.message === "string" && changePasswordResult.message.length > 0);
  TestValidator.equals("reloginRequired should be false")(changePasswordResult.reloginRequired)(false);

  // 5. Authentication validity: Should accept original password and reject the new password
  // Old password should still work
  const signInResult2 = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(signInResult2);

  // New password should NOT work
  await TestValidator.error("login with new password fails")(async () =>
    api.functional.auth.member.login.signIn(connection, {
      body: {
        email,
        password: newPassword,
      } satisfies IMemberAuthenticationMemberSignIn,
    })
  );
}

