import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardModerationAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAudit";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate creation and auditing of moderation actions by admin for compliance.
 *
 * This test checks if an admin can successfully create a moderation audit record attached to an existing moderation action. It ensures that business and compliance workflows—admin registration/login, moderation action creation, moderation audit append—work end-to-end, and that the resulting audit record is immutable and includes required metadata.
 *
 * Steps:
 * 1. Register a new admin using a unique email and strong password. Obtain authentication headers upon success.
 * 2. Log in as the same admin. This ensures the admin session is set for privileged API access.
 * 3. Create a moderation action, with plausible values and the admin’s uuid for `operator_id` (best-effort, no admin id is exposed directly).
 * 4. Prepare before/after JSON snapshots (as strings) of the moderation action, simulating a status/outcome change for the audit.
 * 5. Use POST /polEcoBoard/admin/moderationActions/{moderationActionId}/audits as admin, setting all required audit fields: moderation_action_id, auditor_id, reason, pre/post state.
 * 6. Assert that the new audit record in the response matches the posted data in all business fields (moderation_action_id, auditor_id, reason, snapshots).
 * 7. Re-invoke the audit creation with the same moderation action to confirm append-only/immutability; verify audit ids differ but context remains consistent.
 */
export async function test_api_admin_create_moderation_audit_success(connection: api.IConnection) {
  // 1. Register new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, { body: { email: adminEmail, password: adminPassword } });
  typia.assert(signUpResp);

  // 2. Login as the same admin
  const signInResp = await api.functional.auth.admin.login.signIn(connection, { body: { email: adminEmail, password: adminPassword } });
  typia.assert(signInResp);

  // 3. Create moderation action
  const reportId = typia.random<string & tags.Format<"uuid">>();
  const moderationActionReq = {
    report_id: reportId,
    operator_id: reportId, // We use a generated uuid here, since admin id is not exposed to us
    action_type: "remove",
    target_type: "post",
    status: "pending",
    rationale: "Policy violation: content removed.",
    outcome: "initiated",
  } satisfies IPolEcoBoardModerationAction.ICreate;
  const moderationAction = await api.functional.polEcoBoard.admin.moderationActions.create(connection, { body: moderationActionReq });
  typia.assert(moderationAction);

  // 4. Prepare before/after state
  const pre_state_snapshot = JSON.stringify({ ...moderationAction, status: "pending" });
  const post_state_snapshot = JSON.stringify({ ...moderationAction, status: "completed", outcome: "removed" });

  // 5. Create the audit referencing moderationAction.id
  const moderationAuditReq = {
    moderation_action_id: moderationAction.id,
    auditor_id: moderationAction.operator_id,
    pre_state_snapshot,
    post_state_snapshot,
    reason: "Admin verified action, completed removal."
  } satisfies IPolEcoBoardModerationAudit.ICreate;
  const moderationAudit = await api.functional.polEcoBoard.admin.moderationActions.audits.create(connection, { moderationActionId: moderationAction.id, body: moderationAuditReq });
  typia.assert(moderationAudit);

  TestValidator.equals("moderation_action_id")(moderationAudit.moderation_action_id)(moderationAuditReq.moderation_action_id);
  TestValidator.equals("auditor_id")(moderationAudit.auditor_id)(moderationAuditReq.auditor_id);
  TestValidator.equals("reason")(moderationAudit.reason)(moderationAuditReq.reason);
  TestValidator.equals("pre_state_snapshot")(moderationAudit.pre_state_snapshot)(moderationAuditReq.pre_state_snapshot);
  TestValidator.equals("post_state_snapshot")(moderationAudit.post_state_snapshot)(moderationAuditReq.post_state_snapshot);

  // 6. Confirm immutability: create another audit for the same moderation action and confirm independent record
  const secondAuditReq = {
    moderation_action_id: moderationAction.id,
    auditor_id: moderationAction.operator_id,
    pre_state_snapshot: post_state_snapshot,
    post_state_snapshot,
    reason: "Additional immutable audit event."
  } satisfies IPolEcoBoardModerationAudit.ICreate;
  const secondAudit = await api.functional.polEcoBoard.admin.moderationActions.audits.create(connection, { moderationActionId: moderationAction.id, body: secondAuditReq });
  typia.assert(secondAudit);

  TestValidator.notEquals("audit id should be unique")(secondAudit.id)(moderationAudit.id);
  TestValidator.equals("moderation_action_id")(secondAudit.moderation_action_id)(moderationAction.id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardModerationAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAudit";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate that a moderator can successfully create a moderation audit record via the /polEcoBoard/moderator/moderationActions/{moderationActionId}/audits endpoint.
 *
 * This test simulates a real-world moderation scenario. It ensures that only authorized moderators or admins can create audit records attached to moderation actions, and that all required business fields (rationale, pre/post state, actor identity) are enforced.
 *
 * Steps:
 * 1. Register a new moderator (to have a clean account for auth & business rules).
 * 2. Login as that moderator to ensure the connection carries the JWT token as required.
 * 3. Create a moderation action (simulates handling a moderation report - must include required fields such as report_id, action_type, rationale, etc.).
 * 4. Use the newly created moderator and moderation action to create an audit record.
 *    - Supply valid pre_state_snapshot/post_state_snapshot, rationale, and moderator as auditor_id.
 *    - Verify the created audit record reflects all input fields and has audit metadata (timestamps, etc.).
 * 5. Negative test: Try to create an audit with fields missing, and confirm error is returned.
 * 6. Negative test: Try to create an audit as not logged in / as a non-moderator, and confirm access is denied.
 */
export async function test_api_moderator_create_moderation_audit_success(connection: api.IConnection) {
  // 1. Register a new moderator
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorPassword: string = RandomGenerator.alphaNumeric(12);
  const moderatorDisplayName: string = RandomGenerator.alphabets(8);
  const consentStatus: string = "accepted_v1";

  const moderatorReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorReg);

  // 2. Login as moderator (ensure that Authorization header is updated in connection)
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(moderatorLogin);
  TestValidator.equals("login moderatorId matches register")(
    moderatorLogin.moderatorId
  )(moderatorReg.moderatorId);

  // 3. Create moderation action (simulate handling a reported post/comment)
  // Simulate report target and types
  const reportId: string = typia.random<string & tags.Format<"uuid">>();
  const actionType = "remove";
  const targetType = "post";
  const status = "completed";
  const rationale = "Violation of community standards (spam post)";
  const outcome = "accepted";
  const operatorId = moderatorLogin.moderatorId;

  const moderationAction = await api.functional.polEcoBoard.moderator.moderationActions.create(connection, {
    body: {
      report_id: reportId,
      operator_id: operatorId,
      action_type: actionType,
      target_type: targetType,
      status: status,
      rationale: rationale,
      outcome: outcome,
    } satisfies IPolEcoBoardModerationAction.ICreate,
  });
  typia.assert(moderationAction);
  TestValidator.equals("moderation action operator matches moderator")(
    moderationAction.operator_id
  )(moderatorLogin.moderatorId);
  TestValidator.equals("moderation action rationale matches")(
    moderationAction.rationale
  )(rationale);

  // 4. Create moderation audit (success path)
  const preState = { status: "pending", rationale: "Initial review" };
  const postState = {
    status: moderationAction.status,
    rationale: moderationAction.rationale,
    outcome: moderationAction.outcome,
  };
  const auditReason = "Final decision documented by moderator.";

  const audit = await api.functional.polEcoBoard.moderator.moderationActions.audits.create(connection, {
    moderationActionId: moderationAction.id,
    body: {
      moderation_action_id: moderationAction.id,
      auditor_id: moderatorLogin.moderatorId,
      pre_state_snapshot: JSON.stringify(preState),
      post_state_snapshot: JSON.stringify(postState),
      reason: auditReason,
    } satisfies IPolEcoBoardModerationAudit.ICreate,
  });
  typia.assert(audit);
  TestValidator.equals("audit moderation_action_id matches")(
    audit.moderation_action_id
  )(moderationAction.id);
  TestValidator.equals("audit auditor_id matches moderator")(
    audit.auditor_id
  )(moderatorLogin.moderatorId);
  TestValidator.equals("audit reason matches")(
    audit.reason
  )(auditReason);
  TestValidator.predicate("audit has created/updated timestamps")(
    typeof audit.created_at === "string" && audit.created_at.length > 0 &&
    typeof audit.updated_at === "string" && audit.updated_at.length > 0
  );

  // 5. Negative test: Attempt audit creation with missing required fields (omit pre_state_snapshot)
  await TestValidator.error("creating audit with missing field should fail")(
    async () => {
      await api.functional.polEcoBoard.moderator.moderationActions.audits.create(
        connection,
        {
          moderationActionId: moderationAction.id,
          body: {
            moderation_action_id: moderationAction.id,
            auditor_id: moderatorLogin.moderatorId,
            // pre_state_snapshot: omitted on purpose
            post_state_snapshot: JSON.stringify(postState),
            reason: auditReason,
          } as any, // purposely use 'as any' only for error trigger (runtime, not type suppression)
        }
      );
    }
  );

  // 6. Negative test: Attempt to create audit as a non-moderator
  // Instead of manipulating connection.headers, just pass the given connection object
  // (the connection won't be authenticated as moderator unless login API is called)
  // So we can simulate by passing a fresh connection object with only the required fields (host, etc)
  const unauthConnection: api.IConnection = { host: connection.host };
  await TestValidator.error(
    "unauthenticated user should not be able to create moderation audit"
  )(async () => {
    await api.functional.polEcoBoard.moderator.moderationActions.audits.create(
      unauthConnection,
      {
        moderationActionId: moderationAction.id,
        body: {
          moderation_action_id: moderationAction.id,
          auditor_id: moderatorLogin.moderatorId,
          pre_state_snapshot: JSON.stringify(preState),
          post_state_snapshot: JSON.stringify(postState),
          reason: auditReason,
        } satisfies IPolEcoBoardModerationAudit.ICreate,
      }
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
