import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardModerationAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAudit";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate admin update of allowed moderation audit metadata fields and permission enforcement.
 *
 * This test ensures that admin users can only modify permitted fields (rationale and post-state) on a moderation audit record, and that compliance/append-only protocols are respected. It covers:
 *   1. Admin registration and login (establish privileged session)
 *   2. Creation of a moderation action as context
 *   3. Creation of an initial audit (require full valid data, can use random for state/rationale)
 *   4. Update the audit's allowed fields (post_state_snapshot, reason) using the admin session
 *   5. Confirm the update is persisted: the returned resource reflects new rationale/post-state
 *   6. Attempt update on forbidden/immutable fields (e.g., pre_state_snapshot or auditId) and confirm business error
 *   7. Attempt update by an unauthorized/non-admin connection (should be forbidden)
 * 
 * Steps:
 *   - Register a new admin (unique email/password)
 *   - Login as that admin (set JWT session tokens)
 *   - Create a moderation action (with operator id = this admin)
 *   - Create an audit entry referencing that action (use same admin as auditor)
 *   - Update the audit with new post_state_snapshot and reason (valid)
 *   - Check the updated audit returns the new values for the mutated fields only
 *   - Try to update forbidden fields (pre_state_snapshot) and expect error
 *   - Try to update as random (unauthenticated) connection and expect error
 */
export async function test_api_admin_update_moderation_audit_metadata(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin to establish session
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create a moderation action with operator_id set to admin (random UUID since admin id is not exposed)
  const moderationAction = await api.functional.polEcoBoard.admin.moderationActions.create(connection, {
    body: {
      report_id: typia.random<string & tags.Format<"uuid">>(),
      operator_id: typia.random<string & tags.Format<"uuid">>(),
      action_type: "remove",
      target_type: "post",
      status: "pending",
      rationale: RandomGenerator.paragraph()(100),
      outcome: "accepted",
    } satisfies IPolEcoBoardModerationAction.ICreate,
  });
  typia.assert(moderationAction);

  // 4. Create an audit entry for the moderation action
  const audit = await api.functional.polEcoBoard.admin.moderationActions.audits.create(connection, {
    moderationActionId: moderationAction.id,
    body: {
      moderation_action_id: moderationAction.id,
      auditor_id: typia.random<string & tags.Format<"uuid">>(),
      pre_state_snapshot: JSON.stringify({ previous: true }),
      post_state_snapshot: JSON.stringify({ after: 1 }),
      reason: RandomGenerator.paragraph()(80),
    } satisfies IPolEcoBoardModerationAudit.ICreate,
  });
  typia.assert(audit);

  // 5. Update the allowed fields (post_state_snapshot, reason)
  const newPostState = JSON.stringify({ after: 2 });
  const newReason = RandomGenerator.paragraph()(72);
  const updated = await api.functional.polEcoBoard.admin.moderationActions.audits.update(connection, {
    moderationActionId: moderationAction.id,
    auditId: audit.id,
    body: {
      post_state_snapshot: newPostState,
      reason: newReason,
    } satisfies IPolEcoBoardModerationAudit.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("post_state_snapshot updated")(updated.post_state_snapshot)(newPostState);
  TestValidator.equals("reason updated")(updated.reason)(newReason);

  // 6. Attempt to update forbidden fields (pre_state_snapshot)—should fail if business logic is enforced at runtime
  TestValidator.error("cannot update pre_state_snapshot")(() =>
    api.functional.polEcoBoard.admin.moderationActions.audits.update(connection, {
      moderationActionId: moderationAction.id,
      auditId: audit.id,
      body: {
        pre_state_snapshot: JSON.stringify({ tampered: true }),
      } as any, // Bypass TypeScript type system for runtime test only
    })
  );

  // 7. Attempt update by unauthenticated user—should fail
  const unauthConnection = { ...connection, headers: {} };
  TestValidator.error("unauthenticated cannot update audit")(() =>
    api.functional.polEcoBoard.admin.moderationActions.audits.update(unauthConnection, {
      moderationActionId: moderationAction.id,
      auditId: audit.id,
      body: {
        post_state_snapshot: "forbidden update",
        reason: "no permission",
      },
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardModerationAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAudit";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate compliance update behavior for moderation audit records (PUT /polEcoBoard/moderator/moderationActions/{moderationActionId}/audits/{auditId}).
 *
 * This end-to-end test checks that a moderator can update only permitted fields (such as rationale and clarifying metadata) of a moderation audit record linked to a moderation action. It also verifies that attempts to modify immutable audit properties are rejected, and that updates are not allowed for non-moderator or anonymous users.
 *
 * Steps:
 * 1. Register and login a moderator (receiving JWT tokens for authentication)
 * 2. Create a moderation action (to be audited)
 * 3. Add an audit record to the action
 * 4. Update allowed fields of the audit (reason and post_state_snapshot)
 * 5. Confirm only allowed fields change, and updated_at increases
 * 6. Attempt to update immutable properties (impossible via DTO, but verify no backend bugs by assertion)
 * 7. Attempt to update as anonymous/non-moderator (should fail)
 */
export async function test_api_moderator_update_moderation_audit_compliance_metadata(
  connection: api.IConnection,
) {
  // 1. Register a new moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "Moderator32!";
  const moderatorName = RandomGenerator.name();
  const consentStatus = "2024-06-terms-A";
  const registration = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorName,
      consent_status: consentStatus,
    },
  });
  typia.assert(registration);

  // 2. Login with moderator credentials for JWT auth
  const login = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  typia.assert(login);

  // 3. Create moderation action (moderator as operator)
  const action = await api.functional.polEcoBoard.moderator.moderationActions.create(connection, {
    body: {
      report_id: typia.random<string & tags.Format<"uuid">>(),
      operator_id: registration.moderatorId,
      action_type: "remove",
      target_type: "post",
      status: "pending",
      rationale: "Action rationale.",
      outcome: "accepted",
    },
  });
  typia.assert(action);

  // 4. Create audit record for the action
  const preState = JSON.stringify({ status: action.status });
  const postState = JSON.stringify({ status: "reviewed" });
  const audit = await api.functional.polEcoBoard.moderator.moderationActions.audits.create(connection, {
    moderationActionId: action.id,
    body: {
      moderation_action_id: action.id,
      auditor_id: registration.moderatorId,
      pre_state_snapshot: preState,
      post_state_snapshot: postState,
      reason: "Initial audit for moderation action.",
    },
  });
  typia.assert(audit);

  // 5. Update permissible audit fields (reason and post_state_snapshot)
  const updatedReason = "Compliance rationale updated.";
  const updatedPostState = JSON.stringify({ status: "completed", checked_by: moderatorName });
  await new Promise(r => setTimeout(r, 1000)); // ensure updated_at will be strictly greater
  const updated = await api.functional.polEcoBoard.moderator.moderationActions.audits.update(connection, {
    moderationActionId: action.id,
    auditId: audit.id,
    body: {
      reason: updatedReason,
      post_state_snapshot: updatedPostState,
    },
  });
  typia.assert(updated);
  TestValidator.equals("reason updated")(updated.reason)(updatedReason);
  TestValidator.equals("post_state_snapshot updated")(updated.post_state_snapshot)(updatedPostState);
  TestValidator.equals("pre_state_snapshot unchanged")(updated.pre_state_snapshot)(audit.pre_state_snapshot);
