import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardExternalAuthProvider } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardExternalAuthProvider";
import type { IPageIPolEcoBoardExternalAuthProvider } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardExternalAuthProvider";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

export async function test_api_external_auth_provider_search_admin_filter_sort_pagination(
  connection: api.IConnection,
) {
  /**
   * E2E test for searching and listing external authentication providers as an admin with filters, sorting, and pagination.
   *
   * Covers:
   * 1. Admin registration and authentication.
   * 2. Creating several external auth providers with varying properties (status, provider_name, region).
   * 3. Searching with no filters (should return all non-deleted providers by default, paginated).
   * 4. Searching by provider_name text (should only return matching name).
   * 5. Filtering by status (e.g., 'disabled' only).
   * 6. Filtering by jurisdiction/region (e.g., 'EU' only).
   * 7. Result pagination (limit/page, metadata validation).
   * 8. Filter combination that yields zero results.
   * 9. Attempt by non-admin (unauthenticated) user to search (should fail with error).
   */

  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Admin login
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create external auth providers with variety of props
  const createdProviders = await ArrayUtil.asyncRepeat(5)(async (i) => {
    const status = i === 0
      ? "enabled"
      : i === 1
      ? "disabled"
      : i === 2
      ? "maintenance"
      : "enabled";
    const region = ["US", "EU", "APAC", "US", "EU"][i];
    const provider = await api.functional.polEcoBoard.admin.externalAuthProviders.create(
      connection,
      {
        body: {
          provider_name: `Provider ${RandomGenerator.alphaNumeric(3)}_${i}`,
          provider_key: `provider${i}_${RandomGenerator.alphaNumeric(5).toLowerCase()}`,
          status,
          privacy_policy_uri: `https://provider${i}.example.com/privacy`,
          data_residency_region: region,
          consent_required: i % 2 === 0,
        } satisfies IPolEcoBoardExternalAuthProvider.ICreate,
      },
    );
    typia.assert(provider);
    return provider;
  });

  // 4. Search with no filters - should return all non-deleted
  const result1 = await api.functional.polEcoBoard.admin.externalAuthProviders.search(connection, {
    body: {},
  });
  typia.assert(result1);
  TestValidator.predicate("returns all created providers")(result1.data.length === createdProviders.length);

  // 5. Search: filter by provider_name
  const nameQuery = createdProviders[2].provider_name.slice(0, 8);
  const result2 = await api.functional.polEcoBoard.admin.externalAuthProviders.search(connection, {
    body: {
      provider_name: nameQuery,
    },
  });
  typia.assert(result2);
  TestValidator.predicate("name filter only returns matches")(result2.data.every((r) => r.provider_name.includes(nameQuery)));

  // 6. Search: filter by status (disabled)
  const result3 = await api.functional.polEcoBoard.admin.externalAuthProviders.search(connection, {
    body: {
      status: "disabled",
    },
  });
  typia.assert(result3);
  TestValidator.predicate("status filter only disabled")(result3.data.every((r) => r.status === "disabled"));

  // 7. Search: filter by region (jurisdiction)
  const regionFilter = "EU";
  const result4 = await api.functional.polEcoBoard.admin.externalAuthProviders.search(connection, {
    body: {
      region: regionFilter,
    },
  });
  typia.assert(result4);
  TestValidator.predicate("region filter EU")(result4.data.every((r) => r.data_residency_region === regionFilter));

  // 8. Search: pagination (page & limit)
  const result5 = await api.functional.polEcoBoard.admin.externalAuthProviders.search(connection, {
    body: {
      page: 1,
      limit: 2,
    },
  });
  typia.assert(result5);
  TestValidator.equals("pagination limit")(result5.pagination.limit)(2);
  TestValidator.equals("pagination page")(result5.pagination.current)(1);
  TestValidator.predicate("pagination count")(result5.data.length <= 2);

  // 9. Search with filter yielding zero results
  const result6 = await api.functional.polEcoBoard.admin.externalAuthProviders.search(connection, {
    body: {
      provider_name: "NO_MATCHING_PROVIDER",
    },
  });
  typia.assert(result6);
  TestValidator.equals("zero results")(result6.data.length)(0);

  // 10. Try searching as unauthenticated user (should error)
  // Remove Authorization header from a shallow copy of connection for non-admin
  const hdrs = { ...connection.headers };
  delete hdrs.Authorization;
  const anonConn: api.IConnection = { ...connection, headers: hdrs };
  await TestValidator.error("non-admin rejected")(async () => {
    await api.functional.polEcoBoard.admin.externalAuthProviders.search(anonConn, {
      body: {},
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardExternalAuthProvider } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardExternalAuthProvider";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate admin retrieval of external authentication provider details.
 *
 * This scenario tests that an authenticated admin can query for the full configuration and audit details of a single external authentication provider by its unique ID. It ensures that all contract fields—such as provider name, key, status, privacy link, jurisdiction, and compliance/consent flags—are present, valid, and correct, and that no personally identifying information or sensitive data is leaked in the response. Business edge cases include: requesting a nonexistent provider ID (should return not-found/business error), a soft-deleted provider (should show appropriate status or deleted_at), and enforcing that members/non-admins cannot access this endpoint (authorization error expected).
 *
 * Steps:
 * 1. Register a new admin and perform authentication (obtain token).
 * 2. Create a new external authentication provider via the admin endpoint, store its generated id.
 * 3. As authenticated admin, fetch the newly created provider by id and assert all properties are present, data matches creation, and no extra fields are present.
 * 4. Edge case: attempt to fetch a non-existent provider id (random uuid), ensure not-found error.
 * 5. (Optional, if delete is not implemented—simulate) Check behavior for "soft-deleted" provider: if deleted_at is not null, assert status/compliance is correct.
 * 6. Attempt access without admin authentication (simulate with connection lacking Authorization), assert authorization is rejected.
 */
export async function test_api_external_auth_provider_admin_get_by_id(connection: api.IConnection) {
  // 1. Admin registration
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  await api.functional.auth.admin.register.signUp(connection, {
    body: { email, password } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Admin login
  await api.functional.auth.admin.login.signIn(connection, {
    body: { email, password } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create provider
  const createInput: IPolEcoBoardExternalAuthProvider.ICreate = {
    provider_name: "Test SSO",
    provider_key: "test_sso_" + Date.now().toString(),
    status: "enabled",
    privacy_policy_uri: "https://www.example.com/privacy",
    data_residency_region: "US",
    consent_required: true,
  };
  const created = await api.functional.polEcoBoard.admin.externalAuthProviders.create(connection, {
    body: createInput,
  });
  typia.assert(created);
  TestValidator.equals("provider_name matches")(created.provider_name)(createInput.provider_name);
  TestValidator.equals("provider_key matches")(created.provider_key)(createInput.provider_key);
  TestValidator.equals("status matches")(created.status)(createInput.status);
  TestValidator.equals("privacy_policy_uri matches")(created.privacy_policy_uri)(createInput.privacy_policy_uri);
  TestValidator.equals("data_residency_region matches")(created.data_residency_region)(createInput.data_residency_region);
  TestValidator.equals("consent_required matches")(created.consent_required)(createInput.consent_required);
  TestValidator.predicate("has UUID id")(!!created.id && created.id.length > 0);
  TestValidator.predicate("created_at present")(!!created.created_at);
  TestValidator.predicate("updated_at present")(!!created.updated_at);
  TestValidator.equals("not soft deleted")(created.deleted_at)(null);

  // 4. Admin can fetch the provider by id
  const fetched = await api.functional.polEcoBoard.admin.externalAuthProviders.at(connection, {
    externalAuthProviderId: created.id,
  });
  typia.assert(fetched);
  TestValidator.equals("id matches")(fetched.id)(created.id);
  TestValidator.equals("provider_name matches")(fetched.provider_name)(createInput.provider_name);
  TestValidator.equals("provider_key matches")(fetched.provider_key)(createInput.provider_key);
  TestValidator.equals("status matches")(fetched.status)(createInput.status);
  TestValidator.equals("privacy_policy_uri matches")(fetched.privacy_policy_uri)(createInput.privacy_policy_uri);
  TestValidator.equals("data_residency_region matches")(fetched.data_residency_region)(createInput.data_residency_region);
  TestValidator.equals("consent_required matches")(fetched.consent_required)(createInput.consent_required);
  TestValidator.equals("not soft deleted")(fetched.deleted_at)(null);

  // 5. Fetch with nonexistent id (should not be found, expect error)
  TestValidator.error("fetching nonexistent provider returns error")(async () => {
    await api.functional.polEcoBoard.admin.externalAuthProviders.at(connection, {
      externalAuthProviderId: typia.random<string & tags.Format<"uuid">>(),
    });
  });

  // 6. Attempt fetch without admin (simulate no Authorization header)
  // Clone connection but clear Authorization
  const noAuthConnection = { ...connection, headers: { ...connection.headers } };
  delete noAuthConnection.headers?.Authorization;
  TestValidator.error("unauthorized access is rejected")(async () => {
    await api.functional.polEcoBoard.admin.externalAuthProviders.at(noAuthConnection, {
      externalAuthProviderId: created.id,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
