/**
 * E2E Test for successful and unsuccessful external authentication provider creation by admin
 *
 * This test covers:
 * 1. Admin registration and login (dependencies for privileged actions)
 * 2. Successful creation of an external authentication provider with all required fields.
 * 3. Validation that response contains all details: UUID, timestamps, and business fields.
 * 4. Duplication error check (provider_key and provider_name must be unique):
 *    - Attempt to create with the same provider_key or provider_name and expect error.
 * 5. Field validation edge-cases:
 *    - Provide an invalid status value (not one of 'enabled', 'disabled', 'maintenance') and confirm validation error.
 *    - Provide a malformed privacy_policy_uri (not a valid URI) and confirm validation error.
 * 6. Access control: Attempt creating a provider WHEN NOT authenticated as admin and confirm access denied.
 *
 * Process:
 * - Register and login as admin.
 * - Create an external auth provider successfully (fields: provider_name, provider_key, status, privacy_policy_uri, data_residency_region, consent_required).
 * - Assert all returned details available (incl. id, timestamps, fields, etc).
 * - Try to create another with duplicate provider_key or provider_name.
 * - Try to create with invalid status value.
 * - Try to create with malformed URI.
 * - Logout or reset auth; try to create with no/admin token and expect failure.
 */
export async function test_api_external_auth_provider_admin_create_success_and_duplicate_key(
  connection: api.IConnection,
) {
  // 1. Admin registration
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: password,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: password,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Successful provider creation
  const input = {
    provider_name: "TestProvider" + RandomGenerator.alphaNumeric(5),
    provider_key: "test_provider_key_" + RandomGenerator.alphaNumeric(5),
    status: "enabled",
    privacy_policy_uri: "https://privacypolicy." + RandomGenerator.alphaNumeric(8) + ".com/pp.html",
    data_residency_region: "US",
    consent_required: true,
  } satisfies IPolEcoBoardExternalAuthProvider.ICreate;
  const created = await api.functional.polEcoBoard.admin.externalAuthProviders.create(connection, { body: input });
  typia.assert(created);
  TestValidator.equals("provider_name matches")(created.provider_name)(input.provider_name);
  TestValidator.equals("provider_key matches")(created.provider_key)(input.provider_key);
  TestValidator.equals("status matches")(created.status)(input.status);
  TestValidator.equals("privacy_policy_uri matches")(created.privacy_policy_uri)(input.privacy_policy_uri);
  TestValidator.equals("region matches")(created.data_residency_region)(input.data_residency_region);
  TestValidator.equals("consent_required matches")(created.consent_required)(input.consent_required);
  TestValidator.predicate("id is UUID")(typeof created.id === "string" && created.id.length > 0);
  TestValidator.predicate("created_at date")(typeof created.created_at === "string");
  TestValidator.predicate("updated_at date")(typeof created.updated_at === "string");

  // 4. Duplicate provider_key
  await TestValidator.error("duplicate provider_key")(async () => {
    await api.functional.polEcoBoard.admin.externalAuthProviders.create(connection, {
      body: {
        ...input,
        provider_name: input.provider_name + "_dup",
      } satisfies IPolEcoBoardExternalAuthProvider.ICreate,
    });
  });
  // 5. Duplicate provider_name
  await TestValidator.error("duplicate provider_name")(async () => {
    await api.functional.polEcoBoard.admin.externalAuthProviders.create(connection, {
      body: {
        ...input,
        provider_key: input.provider_key + "_dup",
      } satisfies IPolEcoBoardExternalAuthProvider.ICreate,
    });
  });
  // 6. Invalid status value
  await TestValidator.error("invalid status value")(async () => {
    await api.functional.polEcoBoard.admin.externalAuthProviders.create(connection, {
      body: {
        ...input,
        status: "invalid_status",
        provider_key: input.provider_key + "_invalidstatus",
        provider_name: input.provider_name + "_invalidstatus",
      } satisfies IPolEcoBoardExternalAuthProvider.ICreate,
    });
  });
  // 7. Malformed privacy_policy_uri
  await TestValidator.error("malformed privacy_policy_uri")(async () => {
    await api.functional.polEcoBoard.admin.externalAuthProviders.create(connection, {
      body: {
        ...input,
        privacy_policy_uri: "not_a_uri",
        provider_key: input.provider_key + "_baduri",
        provider_name: input.provider_name + "_baduri",
      } satisfies IPolEcoBoardExternalAuthProvider.ICreate,
    });
  });
  // 8. Access denied for unauthenticated user
  const unauthConnection = { ...connection, headers: { ...connection.headers } };
  // Remove admin JWT to simulate unauthenticated
  delete unauthConnection.headers.Authorization;
  await TestValidator.error("unauthenticated provider creation")(async () => {
    await api.functional.polEcoBoard.admin.externalAuthProviders.create(unauthConnection, { body: input });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardExternalAuthProvider } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardExternalAuthProvider";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E test for updating an external authentication provider (admin-only).
 *
 * This test validates:
 * - Admin registration and login flow.
 * - Creating two external auth providers (A and B) with unique keys.
 * - Successfully updating all mutable fields of a provider and confirming returned field values and audit log field changes (updated_at).
 * - Denying duplicate provider_key on creation (enforcing uniqueness constraint).
 * - Preventing update attempts by non-admin users (access control).
 * - Type-safety and assertion best practices throughout.
 *
 * Not covered: Soft-delete update errors or audit log side-effects, as soft-deletion is not exposed in the current public API contract.
 */
export async function test_api_external_auth_provider_admin_update_fields_and_constraints(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 2. Login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 3. Create provider A
  const providerA = await api.functional.polEcoBoard.admin.externalAuthProviders.create(connection, {
    body: {
      provider_name: "Google SSO",
      provider_key: "google-auth-key",
      status: "enabled",
      privacy_policy_uri: "https://policies.google.com/privacy",
      data_residency_region: "US",
      consent_required: true,
    },
  });
  typia.assert(providerA);

  // 4. Create provider B
  const providerB = await api.functional.polEcoBoard.admin.externalAuthProviders.create(connection, {
    body: {
      provider_name: "Apple Login",
      provider_key: "apple-sso-key",
      status: "enabled",
      privacy_policy_uri: "https://www.apple.com/legal/privacy/en-ww/",
      data_residency_region: "EU",
      consent_required: false,
    },
  });
  typia.assert(providerB);

  // 5. Update provider A (all mutable fields)
  const prevUpdatedAtA = providerA.updated_at;
  const updateData = {
    provider_name: "New Google Auth",
    status: "maintenance",
    privacy_policy_uri: "https://policies.google.com/new-privacy",
    data_residency_region: "KR",
    consent_required: false,
  } satisfies IPolEcoBoardExternalAuthProvider.IUpdate;
  const updatedProviderA = await api.functional.polEcoBoard.admin.externalAuthProviders.update(connection, {
    externalAuthProviderId: providerA.id,
    body: updateData,
  });
  typia.assert(updatedProviderA);

  TestValidator.equals("provider id matches after update")(updatedProviderA.id)(providerA.id);
  TestValidator.notEquals("updated_at has changed")(updatedProviderA.updated_at)(prevUpdatedAtA);
  TestValidator.equals("created_at doesn't change")(updatedProviderA.created_at)(providerA.created_at);
  TestValidator.equals("provider name")(updatedProviderA.provider_name)(updateData.provider_name);
  TestValidator.equals("status")(updatedProviderA.status)(updateData.status);
  TestValidator.equals("privacy_policy_uri")(updatedProviderA.privacy_policy_uri)(updateData.privacy_policy_uri);
  TestValidator.equals("data_residency_region")(updatedProviderA.data_residency_region)(updateData.data_residency_region);
  TestValidator.equals("consent_required")(updatedProviderA.consent_required)(updateData.consent_required);

  // 6. Enforce uniqueness: attempt provider_key collision on create, should fail
  await TestValidator.error("should not allow duplicate provider_key")(() =>
    api.functional.polEcoBoard.admin.externalAuthProviders.create(connection, {
      body: {
        provider_name: "Provider Dup Key",
        provider_key: providerB.provider_key, // duplicate key
        status: "enabled",
        privacy_policy_uri: "https://privacy.url/dup",
        data_residency_region: "EU",
        consent_required: true,
      },
    })
  );

  // 7. Update provider B (partial fields) and verify audit
  const prevUpdatedAtB = providerB.updated_at;
  const updateBData = {
    status: "maintenance",
    provider_name: "Apple SSO Updated",
  } satisfies IPolEcoBoardExternalAuthProvider.IUpdate;
  const updatedProviderB = await api.functional.polEcoBoard.admin.externalAuthProviders.update(connection, {
    externalAuthProviderId: providerB.id,
    body: updateBData,
  });
  typia.assert(updatedProviderB);
  TestValidator.equals("provider id matches after update B")(updatedProviderB.id)(providerB.id);
  TestValidator.notEquals("updated_at has changed")(updatedProviderB.updated_at)(prevUpdatedAtB);
  TestValidator.equals("status updated")(updatedProviderB.status)(updateBData.status);
  TestValidator.equals("name updated")(updatedProviderB.provider_name)(updateBData.provider_name);

  // 8. Access control: attempt update as non-admin -- should be denied
  const newConnection = { ...connection, headers: {} };
  await TestValidator.error("should be forbidden for non-admin")(() =>
    api.functional.polEcoBoard.admin.externalAuthProviders.update(newConnection, {
      externalAuthProviderId: providerA.id,
      body: {
        provider_name: "Not Allowed",
      },
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardExternalAuthProvider } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardExternalAuthProvider";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test the admin soft-delete flow for external authentication providers and access restriction logic.
 *
 * This test validates that:
 * - An admin can soft-delete an external authentication provider by its ID
 * - After deletion, any further delete attempts or attempts as a non-admin are properly rejected
 * - Attempts to delete a non-existent provider also return errors as expected
 * - Verifies type contracts and enforcement of access control, with business context documentation
 *
 * Steps implemented:
 * 1. Register a new admin and log in to obtain privileges
 * 2. Create an external authentication provider
 * 3. Admin deletes (soft) the provider
 * 4. Verify repeated delete and deletion of non-existent records is blocked
 * 5. Confirm non-admin context cannot delete providers
 *
 * Note: Due to SDK limits, no search/list/fetch API is available for negative retrieval validation or audit logs; those checks are omitted.
 */
export async function test_api_external_auth_provider_admin_soft_delete_and_access_restriction(
  connection: api.IConnection,
) {
  // 1. Register and log in admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();

  const signUpRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpRes);

  const signInRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInRes);

  // 2. Create external authentication provider
  const createInput: IPolEcoBoardExternalAuthProvider.ICreate = {
    provider_name: "TestProvider-" + RandomGenerator.alphaNumeric(8),
    provider_key: "test_key_" + RandomGenerator.alphaNumeric(8),
    status: "enabled",
    privacy_policy_uri: "https://example.com/privacy-policy" + RandomGenerator.alphaNumeric(6),
    data_residency_region: "US",
    consent_required: true,
  };
  const provider = await api.functional.polEcoBoard.admin.externalAuthProviders.create(connection, {
    body: createInput,
  });
  typia.assert(provider);
  TestValidator.equals("provider not deleted after creation")(provider.deleted_at)(null);

  // 3. Admin soft-deletes provider by ID
  await api.functional.polEcoBoard.admin.externalAuthProviders.erase(connection, {
    externalAuthProviderId: provider.id,
  });

  // 4. Blocked: repeated delete by admin (double delete)
  await TestValidator.error("double soft-delete fails")(() =>
    api.functional.polEcoBoard.admin.externalAuthProviders.erase(connection, {
      externalAuthProviderId: provider.id,
    })
  );

  // 4. Blocked: deletion of non-existent provider
  await TestValidator.error("delete non-existent provider fails")(() =>
    api.functional.polEcoBoard.admin.externalAuthProviders.erase(connection, {
      externalAuthProviderId: typia.random<string & tags.Format<"uuid">>(),
    })
  );

  // 5. Attempt delete as non-admin (simulate by temporarily removing Authorization header)
  const origAuthorization = connection.headers?.Authorization;
  if (connection.headers) (connection.headers as any).Authorization = undefined;
  try {
    await TestValidator.error("non-admin cannot soft-delete provider")(() =>
      api.functional.polEcoBoard.admin.externalAuthProviders.erase(connection, {
        externalAuthProviderId: provider.id,
      })
    );
  } finally {
    if (connection.headers) (connection.headers as any).Authorization = origAuthorization;
  }
}

