 *   - Enforced uniqueness of the email field.
 *   - Clear error handling when attempting to register a second member with the same email address.
 *
 * Steps:
 * 1. Register a new member with valid and unique properties.
 * 2. Validate the presence and type of the returned member (no password hash, is_active true).
 * 3. Attempt registration with the same email and different display name, consent status, and password hash.
 * 4. Validate that a duplicate email error occurs (error is thrown).
 */
export async function test_api_member_registration_success_and_duplicate_email_error(connection: api.IConnection) {
