/**
 * Validate the admin moderator search endpoint with privilege and filter edge cases.
 *
 * This test ensures that:
 * - Only admin roles can search moderators - access is denied to others
 * - Filtering by appointed date, status, and privilege works correctly
 * - Empty search results return valid pagination output
 * - Pagination metadata is correct and robust to empty results
 *
 * Business Context:
 * The polEcoBoard admin moderation search supports platform governance by enabling administrator users to review and audit all current/past moderators according to a range of parameters (date-of-appointment, status, assigned admin, etc.). Strong access controls and correct filtering are essential both for compliance and operational utility.
 *
 * Steps (full scenario):
 * 1. Register new admin and login
 * 2. Register a new moderator for test data
 * 3. As admin, perform searches:
 *    a. General: no filters (expect at least one moderator in the system)
 *    b. Filter by moderator's member_id (returns exactly that moderator)
 *    c. Filter by is_active (should include newly created moderator)
 *    d. Filter by appointed_at_from = now (likely only just-created matches, but test pagination always)
 *    e. Filter by appointed_at_from far-future—should return zero/data-empty with correct pagination structure
 * 4. Switch to moderator token and attempt the search; confirm forbidden/permission error
 *
 * After each call, validate result shape with typia.assert, business conditions with TestValidator, and API error for the forbidden case.
 */
export async function test_api_admin_moderator_search_with_filters_and_no_results(
  connection: api.IConnection,
) {
  // 1. Admin registration
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AaBb!1234567";
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Admin login
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Register a moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "BbCc!9876543";
  const moderatorDisplayName = RandomGenerator.name();
  const moderatorConsent = "consented:" + new Date().toISOString();
  const moderator = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: moderatorConsent,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderator);

  // 4.a. Search as admin, no filters
  const resAll = await api.functional.polEcoBoard.admin.moderators.search(connection, {
    body: {
      page: 1,
      limit: 10,
    } satisfies IPolEcoBoardModerator.IRequest,
  });
  typia.assert(resAll);
  TestValidator.predicate("at least one moderator present")(resAll.data.length >= 1);

  // 4.b. Filter by moderator member_id
  const resByMember = await api.functional.polEcoBoard.admin.moderators.search(connection, {
    body: {
      member_id: moderator.moderatorId,
    } satisfies IPolEcoBoardModerator.IRequest,
  });
  typia.assert(resByMember);
  TestValidator.equals("only one moderator by member_id")(resByMember.data.length)(1);
  TestValidator.equals("moderator member_id matches")(resByMember.data[0].member_id)(moderator.moderatorId);

  // 4.c. Filter by is_active: true (should include the moderator)
  const resActive = await api.functional.polEcoBoard.admin.moderators.search(connection, {
    body: {
      is_active: true,
    } satisfies IPolEcoBoardModerator.IRequest,
  });
  typia.assert(resActive);
  TestValidator.predicate("has active moderators")(resActive.data.length >= 1);

  // 4.d. appointed_at_from = now (likely only just-registered, but shape must be correct regardless)
  const now = new Date().toISOString();
  const resNow = await api.functional.polEcoBoard.admin.moderators.search(connection, {
    body: {
      appointed_at_from: now,
    } satisfies IPolEcoBoardModerator.IRequest,
  });
  typia.assert(resNow);
  typia.assert(resNow.pagination);
  typia.assert(resNow.data);

  // 4.e. Appointed_at_from = far future: expect empty
  const resFuture = await api.functional.polEcoBoard.admin.moderators.search(connection, {
    body: {
      appointed_at_from: "2100-01-01T00:00:00.000Z",
    } satisfies IPolEcoBoardModerator.IRequest,
  });
  typia.assert(resFuture);
  TestValidator.equals("empty result for future date filter")(resFuture.data.length)(0);
  typia.assert(resFuture.pagination);

  // 5. Switch to moderator token (non-admin) and attempt search; must fail
  connection.headers = { ...connection.headers, Authorization: moderator.setHeaders.Authorization };
  await TestValidator.error("moderator cannot access admin search")(async () => {
    await api.functional.polEcoBoard.admin.moderators.search(connection, {
      body: {} as IPolEcoBoardModerator.IRequest,
    });
  });
}

