import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate the successful creation of a notification preference by an admin
 * and ensure event type/channel enforcement for invalid input.
 *
 * This test covers two main parts:
 * 1. Admin registers and signs in, then creates a valid notification preference
 *    (using a supported event_type and channel).
 * 2. Negative case: attempt to create a preference with unsupported event_type or channel,
 *    confirming that the API enforces constraints and returns an error for invalid values.
 *
 * Steps:
 * 1. Register a new admin account.
 * 2. Log in as the new admin to obtain authorization for privileged actions.
 * 3. Create a notification preference using valid supported values:
 *    - event_type: use a plausible, supported value (e.g., 'reply')
 *    - channel: one of ['email', 'push', 'in_app', 'sms']
 *    - opt_in: true/false
 *    - member_id: test's own admin/member uuid
 * 4. Verify the created preference, including audit fields (id, created_at, updated_at) and value echo.
 * 5. Attempt to create a notification preference using an **invalid event_type** (e.g. 'not_a_real_event') or **invalid channel** (e.g. 'carrier_pigeon').
 * 6. Assert that the API throws an error for the unsupported input (should not pass validation, error must be thrown when requested with invalid values).
 */
export async function test_api_admin_notification_preference_creation_success_and_event_channel_enforcement(
  connection: api.IConnection,
) {
  // 1. Register new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const registerResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(registerResponse);

  // 2. Login as admin
  const loginResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(loginResponse);

  // At this point connection.headers should be set with the Authorization token.

  // 3. Create a valid notification preference (success)
  // We'll use email as channel and reply as valid event_type, and opt_in true
  // For member_id, use a valid uuid (the actual admin's member_id is unknown, so typia.random or test known value)
  const validPreferenceInput: IPolEcoBoardNotificationPreference.ICreate = {
    member_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "reply",
    channel: "email",
    opt_in: true,
  };
  const createdPreference = await api.functional.polEcoBoard.admin.notificationPreferences.create(connection, {
    body: validPreferenceInput,
  });
  typia.assert(createdPreference);
  TestValidator.equals("echo values")(createdPreference.event_type)(validPreferenceInput.event_type);
  TestValidator.equals("echo values")(createdPreference.channel)(validPreferenceInput.channel);
  TestValidator.equals("echo values")(createdPreference.opt_in)(validPreferenceInput.opt_in);
  // UUID and audit fields
  TestValidator.predicate("id is uuid")(typeof createdPreference.id === "string" && /^[0-9a-fA-F-]{36}$/.test(createdPreference.id));
  TestValidator.predicate("created_at is ISO string")(typeof createdPreference.created_at === "string");
  TestValidator.predicate("updated_at is ISO string")(typeof createdPreference.updated_at === "string");

  // 4. Attempt to create with invalid event_type (should throw)
  const invalidTypePreference: IPolEcoBoardNotificationPreference.ICreate = {
    ...validPreferenceInput,
    event_type: "not_a_real_event",
  };
  await TestValidator.error("invalid event_type should fail")(() =>
    api.functional.polEcoBoard.admin.notificationPreferences.create(connection, {
      body: invalidTypePreference,
    }),
  );

  // 5. Attempt to create with invalid channel (should throw)
  const invalidChannelPreference: IPolEcoBoardNotificationPreference.ICreate = {
    ...validPreferenceInput,
    channel: "carrier_pigeon",
  };
  await TestValidator.error("invalid channel should fail")(() =>
    api.functional.polEcoBoard.admin.notificationPreferences.create(connection, {
      body: invalidChannelPreference,
    }),
  );
}

