import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotificationPreference";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Test to ensure proper permission checks are enforced when updating notification preferences.
 *
 * Business purpose: Each member must only be able to update their own notification preferences. This test ensures that a member (Member B) cannot modify another member (Member A)'s notification settings, which is critical to maintaining privacy and self-ownership semantics.
 *
 * Steps:
 * 1. Register Member A with a unique email/password.
 * 2. Register Member B with a different email/password.
 * 3. Log in as Member A and create a notification preference (record its ID).
 * 4. Log in as Member B (overwriting the connection's authentication header with B's token).
 * 5. Attempt to update the notification preference created by Member A using Member B's session.
 * 6. Assert that the update attempt is rejected due to permission denial.
 */
export async function test_api_member_notification_preference_update_admin_permission_violation(
  connection: api.IConnection,
) {
  // 1. Register Member A
  const memberAEmail = typia.random<string & tags.Format<"email">>();
  const memberAPassword = typia.random<string & tags.Format<"password">>();
  const signUpAResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberAEmail,
      password: memberAPassword,
    },
  });
  typia.assert(signUpAResult);

  // 2. Register Member B
  const memberBEmail = typia.random<string & tags.Format<"email">>();
  const memberBPassword = typia.random<string & tags.Format<"password">>();
  const signUpBResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberBEmail,
      password: memberBPassword,
    },
  });
  typia.assert(signUpBResult);

  // 3. Log in as Member A
  const signInAResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberAEmail,
      password: memberAPassword,
    },
  });
  typia.assert(signInAResult);

  // 4. Member A creates notification preference
  const notificationPreference = await api.functional.polEcoBoard.member.notificationPreferences.create(connection, {
    body: {
      member_id: typia.random<string & tags.Format<"uuid">>(), // Will be ignored by backend, as it uses authenticated user
      event_type: "reply",
      channel: "email",
      opt_in: true,
    },
  });
  typia.assert(notificationPreference);

  // 5. Log in as Member B
  const signInBResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberBEmail,
      password: memberBPassword,
    },
  });
  typia.assert(signInBResult);

  // 6. Member B attempts unauthorized update of Member A's notification preference
  await TestValidator.error("permission denied updating other's preference")(
    async () =>
      api.functional.polEcoBoard.member.notificationPreferences.update(connection, {
        notificationPreferenceId: notificationPreference.id,
        body: {
          opt_in: false,
        },
      })
  );
}

