 * This test simulates the full administrative lifecycle flow for notification preferences. It covers:
 * 1. Admin registration (with a new unique email/password), which must be allowed by service settings.
 * 2. Admin login to get privileged access (JWT token).
 * 3. Member registration (a new user to own the notification preference).
 * 4. Member login to establish session (JWT token for member).
 * 5. Creation of a notification preference by the member (the update target).
 * 6. Switching to admin account (by re-login) to perform update as admin.
 * 7. Admin updates a field in the member's notification preference by ID.
 * 8. Asserts that the returned record is updated correctly and all audit fields updated as expected.
 *
 * This covers both record creation by member and mutation by admin (with correct privilege boundaries).
 */
export async function test_api_admin_update_notification_preference_for_any_member(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });

  // 4. Login as member (overwrite JWT on connection)
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // 5. Member creates notification preference
  const prefCreate: IPolEcoBoardNotificationPreference.ICreate = {
    member_id: typia.random<string & tags.Format<"uuid">>(), // may be ignored by backend, usually set from session
    event_type: "reply",
    channel: "email",
    opt_in: true,
  };
  const notifPref = await api.functional.polEcoBoard.member.notificationPreferences.create(connection, {
    body: prefCreate,
  });
  typia.assert(notifPref);

  // 6. Login again as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 7. Admin updates the notification preference
  const updateFields: IPolEcoBoardNotificationPreference.IUpdate = {
    opt_in: false,
    channel: "sms",
  };
  const updated = await api.functional.polEcoBoard.admin.notificationPreferences.update(connection, {
    notificationPreferenceId: notifPref.id,
    body: updateFields,
  });
  typia.assert(updated);

  // 8. Validate that the updates were applied
  TestValidator.equals("preference id unchanged")(updated.id)(notifPref.id);
  TestValidator.equals("member id unchanged")(updated.member_id)(notifPref.member_id);
  TestValidator.equals("event_type unchanged")(updated.event_type)(notifPref.event_type);
  TestValidator.equals("channel updated")(updated.channel)(updateFields.channel);
  TestValidator.equals("opt_in updated")(updated.opt_in)(updateFields.opt_in);
  TestValidator.predicate("updated_at advanced")(new Date(updated.updated_at).getTime() > new Date(notifPref.updated_at).getTime());
}

