import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardModeratorBoardAssignment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorBoardAssignment";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that a moderator can retrieve their own moderator-board assignment by ID,
 * including correct authorization, error handling for non-existent/unauthorized
 * assignments, and setup via full business workflow.
 *
 * This test ensures both the normal and boundary-case behavior for the endpoint,
 * validating that moderator-board assignments are retrievable only for authorized
 * moderators and that error/forbidden is returned for invalid IDs or unauthorized attempts.
 *
 * Step-by-step process:
 * 1. Register a moderator, saving their moderatorId and credential details.
 * 2. Register and login an admin.
 * 3. Admin creates a new board category.
 * 4. Admin creates a new board in the created category.
 * 5. Admin creates a moderator-board assignment for the moderator and board (save assignmentId).
 * 6. Moderator logs in (get JWT via setHeaders.Authorization).
 * 7. Moderator fetches their moderator-board assignment by ID -> verify full record is returned and matches the assignmentId.
 * 8. Fetch a random/non-existent assignmentId as moderator -> confirm error (TestValidator.error / forbidden or not found).
 * 9. Register a second moderator and ensure they cannot fetch the first moderator's assignment.
 */
export async function test_api_moderator_board_assignment_get_success_invalid_forbidden(
  connection: api.IConnection,
) {
  // 1. Register a moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "StrongPass123!";
  const moderatorSignup = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: RandomGenerator.name(),
      consent_status: "v1",
    },
  });
  typia.assert(moderatorSignup);

  // 2. Register an admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPass321!";
  const adminSignup = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminSignup);

  // 3. Login as admin
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminLogin);

  // 4. Admin creates a board category
  const categoryCreate = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.paragraph()(2).replace(/\./g, "").slice(0, 30),
      description: RandomGenerator.content()()(2).slice(0, 80),
      display_order: 1,
    },
  });
  typia.assert(categoryCreate);

  // 5. Admin creates a board in the new category
  const boardCreate = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: categoryCreate.id,
      name: RandomGenerator.name(),
      code: RandomGenerator.alphaNumeric(10).toLowerCase(),
      description: RandomGenerator.paragraph()(1).slice(0, 80),
      is_public: true,
      is_archived: false,
      display_order: 1,
    },
  });
  typia.assert(boardCreate);

  // 6. Admin assigns moderator to board
  const assignmentCreate = await api.functional.polEcoBoard.admin.moderatorBoardAssignments.create(connection, {
    body: {
      pol_eco_board_moderator_id: moderatorSignup.moderatorId,
      pol_eco_board_board_id: boardCreate.id,
      assigned_by_admin_id: null,
      assigned_at: new Date().toISOString(),
      ended_at: null,
      role_transfer_log: "Initial assignment",
    },
  });
  typia.assert(assignmentCreate);

  // 7. Login as moderator
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: { email: moderatorEmail, password: moderatorPassword },
  });
  typia.assert(moderatorLogin);

  // 8. Moderator fetches their assignment by ID
  const assignment = await api.functional.polEcoBoard.moderator.moderatorBoardAssignments.at(connection, {
    moderatorBoardAssignmentId: assignmentCreate.id,
  });
  typia.assert(assignment);
  TestValidator.equals("assignment id matches")(assignment.id)(assignmentCreate.id);
  TestValidator.equals("moderator id matches")(assignment.pol_eco_board_moderator_id)(moderatorSignup.moderatorId);
  TestValidator.equals("board id matches")(assignment.pol_eco_board_board_id)(boardCreate.id);

  // 9. Attempt to fetch a random/non-existent assignmentId as moderator and confirm error
  await TestValidator.error("random assignment id not found/forbidden")(
    async () =>
      await api.functional.polEcoBoard.moderator.moderatorBoardAssignments.at(connection, {
        moderatorBoardAssignmentId: typia.random<string & tags.Format<"uuid">>(),
      }),
  );

  // 10. Register a second moderator and ensure they can't access the first moderator's assignment
  const secondModeratorEmail = typia.random<string & tags.Format<"email">>();
  const secondModeratorPassword = "AnotherPass456!";
  const secondModeratorSignup = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: secondModeratorEmail,
      password: secondModeratorPassword,
      display_name: RandomGenerator.name(),
      consent_status: "v1",
    },
  });
  typia.assert(secondModeratorSignup);

  // Login as second moderator
  const secondModeratorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: secondModeratorEmail,
      password: secondModeratorPassword,
    },
  });
  typia.assert(secondModeratorLogin);

  await TestValidator.error("unauthorized assignment access")(
    async () =>
      await api.functional.polEcoBoard.moderator.moderatorBoardAssignments.at(connection, {
        moderatorBoardAssignmentId: assignmentCreate.id,
      }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validates moderator-only access to full comment vote details, and correct permission error for non-moderators.
 *
 * This test ensures that:
 *  - A moderator can fetch all audit details for a specific vote on a comment, with full referential and field integrity.
 *  - The endpoint enforces moderator-only access (403/permission error for ordinary members).
 *
 * Steps:
 * 1. Register and login a moderator; store the Bearer token.
 * 2. Register and login a member; store Bearer token and identity.
 * 3. Member creates a post (injected category_id/title/body).
 * 4. Member adds a comment to the post.
 * 5. Member upvotes or downvotes the comment.
 * 6. Moderator fetches vote detail by (commentId, voteId) and verifies full properties and referential integrity.
 * 7. Member attempts same fetch; expect authorization error.
 */
export async function test_api_comment_vote_detail_moderator_success_and_permission(connection: api.IConnection) {
  // 1. Register moderator and store credentials/token
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "testPassword!1";
  const moderatorDisplayName = RandomGenerator.name();
  const moderatorConsent = "privacy_v1";

  const moderatorRegister = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: moderatorConsent,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorRegister);

  // 2. Login as moderator (refresh token)
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(moderatorLogin);
  const moderatorAuth = moderatorLogin.setHeaders.Authorization;

  // Save current header state for restoration
  const originalAuth = connection.headers && "Authorization" in connection.headers ? connection.headers.Authorization : undefined;

  // 3. Register a new member and login
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "testMemberPW2!";
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  const memberLogin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberLogin);
  const memberAuth = memberLogin.setHeaders.Authorization;

  // 4. Member creates a post
  connection.headers = {
    ...connection.headers,
    Authorization: memberAuth,
  };
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(15),
      body: RandomGenerator.content()()(50),
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 5. Member creates a comment
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(10),
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment);

  // 6. Member votes on the comment
  const vote = await api.functional.polEcoBoard.member.comments.votes.create(connection, {
    commentId: comment.id,
    body: { vote_value: 1 } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(vote);

  // 7. Switch to moderator credentials
  connection.headers = {
    ...connection.headers,
    Authorization: moderatorAuth,
  };

  // 8. Moderator fetches vote details
  const detail = await api.functional.polEcoBoard.moderator.comments.votes.at(connection, {
    commentId: comment.id,
    voteId: vote.id,
  });
  typia.assert(detail);
  TestValidator.equals("commentId match")(detail.comment_id)(comment.id);
  TestValidator.equals("vote id match")(detail.id)(vote.id);
  TestValidator.equals("vote value")(detail.vote_value)(vote.vote_value);
  TestValidator.equals("voter member id")(detail.voter_member_id)(vote.voter_member_id);
  TestValidator.predicate("created_at is ISO string")(
    !!detail.created_at && typeof detail.created_at === "string" && !isNaN(Date.parse(detail.created_at))
  );

  // 9. Switch back to member
  connection.headers = {
    ...connection.headers,
    Authorization: memberAuth,
  };
  // 10. Attempt to fetch vote (should fail with error)
  await TestValidator.error("permission error for non-moderator")(async () => {
    await api.functional.polEcoBoard.moderator.comments.votes.at(connection, {
      commentId: comment.id,
      voteId: vote.id,
    });
  });

  // Restore header, handling required assignment
  if (originalAuth !== undefined) {
    connection.headers = {
      ...connection.headers,
      Authorization: originalAuth,
    };
  } else {
    const { Authorization, ...rest } = connection.headers ?? {};
    connection.headers = rest;
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * E2E test for the comment voting business flow on the polEcoBoard platform.
 *
 * - Validates that a registered and logged-in member can upvote/downvote a comment not written by themselves.
 * - Tests business logic constraints: a member cannot vote twice on the same comment, or vote on their own comment.
 *
 * Steps:
 *   1. Register memberA (the voter), and login to get access.
 *   2. Register memberB (the content author), and login to get memberB's access.
 *   3. As memberB, create a post and add a comment (target comment).
 *   4. As memberA, login and upvote (vote_value=1) the comment (should succeed).
 *   5. As memberA, try to upvote the same comment again (should fail due to business rule for duplicate voting).
 *   6. As memberB, attempt to vote on their own comment (should fail).
 *   7. (Not testing banned scenario, as there is no such API capability in provided material).
 *
 * The test validates success, duplicate prevention, and self-vote prevention via type assertions and expected thrown errors.
 */
export async function test_api_comment_vote_create_valid_and_duplicate_prevented(
  connection: api.IConnection,
) {
  // 1. Register memberA (the voter)
  const memberA_email: string = typia.random<string & tags.Format<"email">>();
  const memberA_password: string = typia.random<string & tags.Format<"password">>();
  const memberA_signup = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberA_email,
      password: memberA_password,
    } satisfies IMemberAuthenticationMemberSignUp
  });
  typia.assert(memberA_signup);

  // 2. Register memberB (the author)
  const memberB_email: string = typia.random<string & tags.Format<"email">>();
  const memberB_password: string = typia.random<string & tags.Format<"password">>();
  const memberB_signup = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberB_email,
      password: memberB_password,
    } satisfies IMemberAuthenticationMemberSignUp
  });
  typia.assert(memberB_signup);

  // 3. Login as memberB to create a post and comment
  const memberB_login = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberB_email,
      password: memberB_password,
    },
  });
  typia.assert(memberB_login);

  // Create post as memberB
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.paragraph()(30),
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // Create comment as memberB
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(5),
      parent_comment_id: null,
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment);

  // 4. Login as memberA to upvote the comment
  const memberA_login = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberA_email,
      password: memberA_password,
    },
  });
  typia.assert(memberA_login);

  // Upvote with memberA (should succeed)
  const vote1 = await api.functional.polEcoBoard.member.comments.votes.create(connection, {
    commentId: comment.id,
    body: {
      vote_value: 1,
    } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(vote1);
  TestValidator.equals("vote is correctly for this comment")(vote1.comment_id)(comment.id);
  TestValidator.equals("vote type is upvote")(vote1.vote_value)(1);

  // Try duplicate upvote (should fail)
  await TestValidator.error("duplicate vote should not be allowed")(
    async () => {
      await api.functional.polEcoBoard.member.comments.votes.create(connection, {
        commentId: comment.id,
        body: {
          vote_value: 1,
        } satisfies IPolEcoBoardVote.ICreate,
      });
    },
  );

  // 5. As memberB, try to vote their own comment (should fail)
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberB_email,
      password: memberB_password,
    },
  });
  await TestValidator.error("author cannot vote on own comment")(
    async () => {
      await api.functional.polEcoBoard.member.comments.votes.create(connection, {
        commentId: comment.id,
        body: {
          vote_value: 1,
        } satisfies IPolEcoBoardVote.ICreate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Test that a member can update their own vote on a comment (changing from upvote to downvote, or vice versa) within the allowed business rule update window.
 *
 * Business context:
 * - Only the member who originally cast a vote may update it, and only within a set time window (if one exists; exact window is business-rule dependent and not spec-exposed here).
 * - Update attempts outside this window, or by other members, must be rejected with an error (forbidden or out-of-period).
 *
 * Steps:
 * 1. Register and login as Member A (voter)
 * 2. Create a Post with required fields (category, title, body)
 * 3. Create a Comment on that post
 * 4. Cast initial vote (e.g. upvote = 1) on the comment as Member A
 * 5. Update the vote to the opposite value (e.g. downvote = -1) within presumed update window
 *    - Validate response reflects new vote_value, voter_member_id unchanged, and correct linkage to comment_id
 * 6. Attempt vote update after expiry by simulating after period or using a different member, and ensure it fails
 *
 * Notes:
 * - As the update window period is not spec-exposed, we cannot genuinely advance time, but can check error when trying as a different member.
 * - Audit trail validation would need read endpoints, but we check returned data and correct error behavior for this spec.
 */
export async function test_api_comment_vote_update_by_owner_and_update_window(connection: api.IConnection) {
  // 1. Register and login as Member A
  const memberAEmail = typia.random<string & tags.Format<"email">>();
  const memberAPassword = typia.random<string & tags.Format<"password">>();
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberAEmail,
      password: memberAPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberAEmail,
      password: memberAPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // 2. Create a Post as Member A
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.paragraph()(50),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. Create Comment on the Post
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(15),
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment);

  // 4. Cast initial vote (upvote)
  const vote = await api.functional.polEcoBoard.member.comments.votes.create(connection, {
    commentId: comment.id,
    body: {
      vote_value: 1,
    } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(vote);
  TestValidator.equals("vote value up")(vote.vote_value)(1);

  // 5. Update the vote to -1 (downvote) as owner
  const updated = await api.functional.polEcoBoard.member.comments.votes.update(connection, {
    commentId: comment.id,
    voteId: vote.id,
    body: { vote_value: -1 } satisfies IPolEcoBoardVote.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("vote value now downvote")(updated.vote_value)(-1);
  TestValidator.equals("voter unchanged")(updated.voter_member_id)(vote.voter_member_id);
  TestValidator.equals("linked to comment")(updated.comment_id)(comment.id);

  // 6. Register Member B (attacker), try to update Member A's vote (forbidden error expected)
  const memberBEmail = typia.random<string & tags.Format<"email">>();
  const memberBPassword = typia.random<string & tags.Format<"password">>();
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberBEmail,
      password: memberBPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberBEmail,
      password: memberBPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  TestValidator.error("cannot update another's vote")(
    () => api.functional.polEcoBoard.member.comments.votes.update(connection, {
      commentId: comment.id,
      voteId: vote.id,
      body: { vote_value: 1 } satisfies IPolEcoBoardVote.IUpdate,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
