import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * E2E test covering business policy for vote deletion on comments in PolEcoBoard.
 *
 * This test validates the following workflow:
 * 1. Register and login as a member (vote owner)
 * 2. Create a post and a comment, then cast a vote as the owner
 * 3. Delete (retract) the vote as the owner
 * 4. Confirm the vote cannot be queried or is excluded from vote tallies (by attempting repeated deletion)
 * 5. Register/login as a second (non-owner) member
 * 6. Attempt vote deletion as non-owner and confirm forbidden/authorization failure
 * 7. [Optional/Best effort] Attempts to delete after already deleted (should always error)
 *
 * Business constraints:
 * - Use only the provided SDK functions and DTOs
 * - Results are checked via error handling since votes have no direct query endpoint
 */
export async function test_api_comment_vote_delete_owner_and_policy_checks(
  connection: api.IConnection,
) {
  // 1. Register and login as vote owner
  const voterEmail = typia.random<string & tags.Format<"email">>();
  const voterPassword = typia.random<string & tags.Format<"password">>();
  const signUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: voterEmail,
      password: voterPassword,
    },
  });
  typia.assert(signUpResult);

  const signInResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: voterEmail,
      password: voterPassword,
    },
  });
  typia.assert(signInResult);

  // 2. Create a post for commenting context
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: "Vote policy test post " + typia.random<string>(),
      body: "This is to test vote deletion. " + typia.random<string>(),
      tag_ids: [],
      attachments: [],
    },
  });
  typia.assert(post);

  // 3. Create a comment
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: "Comment for vote deletion policy " + typia.random<string>(),
    },
  });
  typia.assert(comment);

  // 4. Owner: Cast an upvote
  const vote = await api.functional.polEcoBoard.member.comments.votes.create(connection, {
    commentId: comment.id,
    body: {
      vote_value: 1,
    },
  });
  typia.assert(vote);
  TestValidator.equals("vote linked to comment")((vote.comment_id ?? ""))(comment.id);
  TestValidator.equals("vote value is upvote")(vote.vote_value)(1);

  // 5. Owner deletes vote
  await api.functional.polEcoBoard.member.comments.votes.erase(connection, {
    commentId: comment.id,
    voteId: vote.id,
  });

  // 6. Attempt repeated deletion as owner (should fail)
  await TestValidator.error("cannot delete already-deleted vote")(
    async () => {
      await api.functional.polEcoBoard.member.comments.votes.erase(connection, {
        commentId: comment.id,
        voteId: vote.id,
      });
    },
  );

  // 7. Register/login as another member (non-owner)
  const otherEmail = typia.random<string & tags.Format<"email">>();
  const otherPassword = typia.random<string & tags.Format<"password">>();
  const otherSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: otherEmail,
      password: otherPassword,
    },
  });
  typia.assert(otherSignUp);
  const otherSignIn = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: otherEmail,
      password: otherPassword,
    },
  });
  typia.assert(otherSignIn);

  // 8. Non-owner attempts vote delete (should error)
  await TestValidator.error("non-owner cannot delete owner vote")(
    async () => {
      await api.functional.polEcoBoard.member.comments.votes.erase(connection, {
        commentId: comment.id,
        voteId: vote.id,
      });
    },
  );
}

