  TestValidator.equals("rationale matches")(moderationActionFetched.rationale)(moderationAction.rationale);
  TestValidator.equals("outcome matches")(moderationActionFetched.outcome)(moderationAction.outcome);
  TestValidator.equals("created_at is present")(typeof moderationActionFetched.created_at === "string")(true);
  TestValidator.equals("updated_at is present")(typeof moderationActionFetched.updated_at === "string")(true);
