import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Test the update of a moderation action's mutable properties by a properly authenticated moderator.
 *
 * This test confirms that an authenticated moderator can modify fields such as 'status', 'rationale', or 'outcome' for an existing moderation action, reflecting typical moderation workflow corrections or decisions.
 *
 * Business Context:
 * Moderators may need to update moderation actions as new information arrives, mistakes are corrected, or workflows advance (such as from 'pending' to 'completed').
 * All updates must be audit-logged and restricted to mutable fields.
 *
 * Steps:
 * 1. Register a moderator account.
 * 2. Log in as the newly created moderator to get authentication (token automatically handled).
 * 3. Create a moderation action using valid report, operator_id, status, rationale, outcome, and required fields.
 * 4. Update the moderation action with new values for one or more mutable fields (status/rationale/outcome), using the moderationActionId of the just-created action.
 * 5. Confirm response reflects the updated fields while immutable fields remain unchanged.
 * 6. Optionally, perform a negative test by attempting to update immutable fields (not implementable if API does not allow).
 * 7. Validate that audit trails/logs are properly recorded (if accessible; otherwise, validate updated business state).
 */
export async function test_api_update_moderation_action_success(connection: api.IConnection) {
  // 1. Register a moderator
  const modEmail = typia.random<string & tags.Format<"email">>();
  const modPassword = "TestP@ssword1";
  const modDisplayName = RandomGenerator.name();
  const registrationResponse = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: modEmail,
      password: modPassword,
      display_name: modDisplayName,
      consent_status: "consented"
    } satisfies IPolEcoBoardModeratorRegistration.ICreate
  });
  typia.assert(registrationResponse);
  const operator_id = registrationResponse.moderatorId;

  // 2. Log in as moderator (token handled in connection)
  const loginResponse = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: modEmail,
      password: modPassword
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });
  typia.assert(loginResponse);
  TestValidator.equals("operator_id matches")(loginResponse.moderatorId)(registrationResponse.moderatorId);

  // 3. Create a new moderation action
  const report_id = typia.random<string & tags.Format<"uuid">>();
  const action_type = "remove";
  const target_type = "post";
  const initial_status = "pending";
  const rationale = "Initial rationale for moderation";
  const outcome = "none";
  const moderationAction = await api.functional.polEcoBoard.moderator.moderationActions.create(connection, {
    body: {
      report_id,
      operator_id,
      action_type,
      target_type,
      status: initial_status,
      rationale,
      outcome
    } satisfies IPolEcoBoardModerationAction.ICreate
  });
  typia.assert(moderationAction);

  // 4. Update the moderation action (e.g., status/rationale/outcome)
  const updated_status = "completed";
  const updated_rationale = "Action completed after appeal review.";
  const updated_outcome = "accepted";
  const updatedModerationAction = await api.functional.polEcoBoard.moderator.moderationActions.update(connection, {
    moderationActionId: moderationAction.id,
    body: {
      status: updated_status,
      rationale: updated_rationale,
      outcome: updated_outcome
    } satisfies IPolEcoBoardModerationAction.IUpdate
  });
  typia.assert(updatedModerationAction);

  // 5. Validate updates
  TestValidator.equals("status updated")(updatedModerationAction.status)(updated_status);
  TestValidator.equals("rationale updated")(updatedModerationAction.rationale)(updated_rationale);
  TestValidator.equals("outcome updated")(updatedModerationAction.outcome)(updated_outcome);
  // Immutable fields remain unchanged
  TestValidator.equals("report_id unchanged")(updatedModerationAction.report_id)(moderationAction.report_id);
  TestValidator.equals("operator_id unchanged")(updatedModerationAction.operator_id)(moderationAction.operator_id);
  TestValidator.equals("action_type unchanged")(updatedModerationAction.action_type)(moderationAction.action_type);
  TestValidator.equals("target_type unchanged")(updatedModerationAction.target_type)(moderationAction.target_type);
  // Updated timestamp is later than or equal to previous
  TestValidator.predicate("updated_at after created_at")(
    new Date(updatedModerationAction.updated_at) >= new Date(moderationAction.updated_at)
  );
}

