import type { IPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardReport";

/**
 * Validate failure cases for post reporting: ensure unauthenticated users cannot submit reports and
 * schema or business validation is enforced for report reason codes/descriptions.
 *
 * This test covers two failure branches for post report submissions:
 * 1. Guest (unauthenticated) users must not be able to report posts. Upon attempting a report submission
 *    with no authentication, a 401 (or 403) error must be thrown.
 * 2. When authenticated, attempts to report a post with invalid inputs — such as missing or invalid reason_code,
 *    or empty/too-long reason_description — should be rejected with validation errors by the API.
 *
 * Business context:
 * - Only members may report posts; moderation relies on strict input schemas for reports.
 * - Reason codes must match allowed values; blank or garbage should be rejected. Descriptions that are excessively long
 *   or missing as required must trigger errors.
 *
 * Workflow:
 * 1. Create a member post through the normal endpoint (setup prerequisite, must be authenticated).
 * 2. Attempt to report that post (using the new post ID) as an unauthenticated user and validate error behavior.
 * 3. Authenticate (become a valid member user).
 * 4. Attempt to submit a report with missing reason_code: expect schema error.
 * 5. Attempt with an obviously invalid reason_code (e.g. 'invalid_code'): expect validation error.
 * 6. Attempt with a too-long reason_description: expect validation error.
 * 7. Optionally, attempt valid report (should succeed for completeness, but main focus is on validation failures).
 */
export async function test_api_member_post_report_submission_unauthenticated_and_validation(
  connection: api.IConnection,
) {
  // 1. Create a member post (authentication required)
  const postInput: IPolEcoBoardPost.ICreate = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.alphaNumeric(16),
    body: RandomGenerator.paragraph()(15),
    tag_ids: null,
    attachments: null,
  };
  // Create post as authenticated member
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: postInput,
  });
  typia.assert(post);
  // Post ID for reporting
  const postId = post.id;

  // 2. Attempt post report as unauthenticated user (simulate by clearing auth header)
  //    Should throw 401/403
  const unauthConnection = { ...connection, headers: { ...connection.headers } };
  delete unauthConnection.headers["Authorization"];
  TestValidator.error("guest should not submit report")(
    async () =>
      await api.functional.polEcoBoard.member.posts.reports.create(unauthConnection, {
        postId,
        body: {
          reason_code: "spam", // Assume 'spam' is valid but won't test validity here
          reason_description: "Reported as spam.",
          post_id: postId,
          comment_id: null,
        } satisfies IPolEcoBoardReport.ICreate,
      })
  );

  // 3. Re-authenticate as member (not needed if prior login is preserved)

  // 4. Attempt report missing reason_code (schema error: code required)
  TestValidator.error("missing reason_code triggers schema error")(
    async () =>
      await api.functional.polEcoBoard.member.posts.reports.create(connection, {
        postId,
        body: {
          // Intentionally empty string to trigger server validation error
          reason_code: "", 
          reason_description: "Insufficient code.",
          post_id: postId,
          comment_id: null,
        } satisfies IPolEcoBoardReport.ICreate,
      })
  );

  // 5. Attempt report with invalid reason_code
  TestValidator.error("invalid reason_code triggers business validation error")(
    async () =>
      await api.functional.polEcoBoard.member.posts.reports.create(connection, {
        postId,
        body: {
          reason_code: "invalid_code", // Not an approved business value
          reason_description: "Purposefully invalid reason code.",
          post_id: postId,
          comment_id: null,
        } satisfies IPolEcoBoardReport.ICreate,
      })
  );

  // 6. Attempt report with too-long reason_description
  TestValidator.error("reason_description > 400 chars triggers validation error")(
    async () =>
      await api.functional.polEcoBoard.member.posts.reports.create(connection, {
        postId,
        body: {
          reason_code: "spam", // Use plausible good value
          reason_description: RandomGenerator.alphaNumeric(500), // Exceed 400-char limit
          post_id: postId,
          comment_id: null,
        } satisfies IPolEcoBoardReport.ICreate,
      })
  );

  // 7. (Optional) Submit valid report (should succeed; for full coverage)
  const validReport = await api.functional.polEcoBoard.member.posts.reports.create(connection, {
    postId,
    body: {
      reason_code: "spam", // Use plausible valid value
      reason_description: "Obvious spam post, violating forum guidelines.",
      post_id: postId,
      comment_id: null,
    } satisfies IPolEcoBoardReport.ICreate,
  });
  typia.assert(validReport);
  TestValidator.equals("report post_id matches")(validReport.post_id)(postId);
}

