import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E test for an admin fetching the full edit/audit history of a post.
 *
 * Business context:
 * - Only admins (or authorized roles) may access revision audit trails.
 * - Verifies all business audit fields, edge cases (empty history), and authorization enforcement.
 *
 * Test steps:
 * 1. Register admin and acquire admin session.
 * 2. Register a member account and create a post as member.
 * 3. Generate multiple edits for the member's post (simulating a rich edit history).
 * 4. As admin, fetch full edit/audit history and verify returned data and pagination.
 * 5. Test all edit history business metadata fields.
 * 6. Test audit filtering (by editor) and sorting/pagination.
 * 7. Check result for post with no edits.
 * 8. Confirm that unauthenticated/faulty session is denied.
 */
export async function test_api_post_edit_history_admin_fetch(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });

  // 2. Login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });

  // 3. Register member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const memberDisplayName = RandomGenerator.name();
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: memberDisplayName,
      consent_status: "v1"
    } satisfies IPolEcoBoardMember.ICreate
  });
  typia.assert(member);

  // 4. Login as member
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    } satisfies IMemberAuthenticationMemberSignIn
  });

  // 5. Create post as member
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const postTitle = RandomGenerator.paragraph()(12);
  const postBody = RandomGenerator.content()()(36);
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: postTitle,
      body: postBody
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);

  // 6. Create several post edits
  const editSnapshots: IPolEcoBoardPostEdit[] = [];
  for (let i = 0; i < 4; ++i) {
    const edit = await api.functional.polEcoBoard.member.posts.postEdits.createEdit(connection, {
      postId: post.id,
      body: {
        edit_body: RandomGenerator.content()()(36 + i * 5),
        edit_reason: `Revision #${i+1}`
      } satisfies IPolEcoBoardPostEdit.ICreate
    });
    typia.assert(edit);
    editSnapshots.push(edit);
  }

  // Switch back to admin session before admin APIs
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });

  // 7. Fetch edit history: happy path (all records, full audit fields)
  const page = await api.functional.polEcoBoard.admin.posts.postEdits.searchEditHistory(connection, {
    postId: post.id,
    body: {
      page: 1,
      limit: 20
    } satisfies IPolEcoBoardPostEdit.IRequest
  });
  typia.assert(page);
  TestValidator.equals("edit count matches")(page.data.length)(editSnapshots.length);
  // Ensure all expected audit snapshot fields are present and valid
  TestValidator.predicate("edit audits valid")(page.data.every(edit => (
    typeof edit.id === "string" &&
    typeof edit.post_id === "string" &&
    typeof edit.editor_member_id === "string" &&
    typeof edit.edit_body === "string" &&
    typeof edit.created_at === "string"
  )));

  // 8. Filtering by editor_member_id
  const filtered = await api.functional.polEcoBoard.admin.posts.postEdits.searchEditHistory(connection, {
    postId: post.id,
    body: {
      editor_member_id: member.id
    } satisfies IPolEcoBoardPostEdit.IRequest
  });
  typia.assert(filtered);
  TestValidator.equals("all filtered by member")(filtered.data.every(e => e.editor_member_id === member.id))(true);

  // 9. Sorting by created_at descending
  const sorted = await api.functional.polEcoBoard.admin.posts.postEdits.searchEditHistory(connection, {
    postId: post.id,
    body: {
      order_by: "created_at",
      order_dir: "desc"
    } satisfies IPolEcoBoardPostEdit.IRequest
  });
  typia.assert(sorted);
  for(let j = 1; j < sorted.data.length; ++j) {
    TestValidator.predicate("sorted desc")(sorted.data[j-1].created_at >= sorted.data[j].created_at);
  }

  // 10. No edits: create a new post, fetch should return empty data
  const newPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(12),
      body: RandomGenerator.content()()(36)
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(newPost);
  const empty = await api.functional.polEcoBoard.admin.posts.postEdits.searchEditHistory(connection, {
    postId: newPost.id,
    body: {} satisfies IPolEcoBoardPostEdit.IRequest
  });
  typia.assert(empty);
  TestValidator.equals("empty edit history")(empty.data.length)(0);

  // 11. Unauthorized: fake admin token
  const fakeConn = { ...connection, headers: { ...connection.headers, Authorization: "Bearer invalid-token" } };
  await TestValidator.error("admin unauthorized access fails")(async () => {
    await api.functional.polEcoBoard.admin.posts.postEdits.searchEditHistory(fakeConn, {
      postId: post.id,
      body: {} satisfies IPolEcoBoardPostEdit.IRequest
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPostEdit";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validates that a post author (member) can fetch the full detail of a post edit on their own post.
 *
 * This test covers the full member workflow for edit detail retrieval and validates all historical edit info and access control via author login.
 *
 * Steps:
 * 1. Register a new member to serve as the post author.
 * 2. Log in as that member and obtain a valid session.
 * 3. Create a new post – category_id is populated with a valid random UUID, as category fetch APIs are unavailable.
 * 4. Record an edit to the post, providing a new edit_body and edit_reason.
 * 5. Fetch the edit detail by its ID as the post author.
 * 6. Assert that the returned edit object contains correct and complete information:
 *    - editor_member_id matches the logged-in member
 *    - post_id matches the created post
 *    - edit_body and edit_reason match what was submitted
 *    - created_at is a non-empty ISO string
 *
 * Note: Negative tests for non-author (moderator/admin) permission are not possible here due to lack of such flows in the supplied API. This test covers only author access control.
 */
export async function test_api_post_edit_detail_member_access(connection: api.IConnection) {
  // 1. Register a new member as post author
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(16);
  const displayName = RandomGenerator.name();
  const consentStatus = "v1.0";
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email,
      password_hash: password,
      display_name: displayName,
      consent_status: consentStatus,
      profile_image_uri: null,
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. Log in as member (auth token made available in connection)
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // 3. Create a new post
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const postTitle = RandomGenerator.paragraph()(1);
  const postBody = RandomGenerator.content()()();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: postTitle,
      body: postBody,
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Create an edit for the post
  const editBody = postBody + " (updated)";
  const editReason = RandomGenerator.paragraph()(1);
  const postEdit = await api.functional.polEcoBoard.member.posts.postEdits.createEdit(connection, {
    postId: post.id,
    body: {
      edit_body: editBody,
      edit_reason: editReason,
    } satisfies IPolEcoBoardPostEdit.ICreate,
  });
  typia.assert(postEdit);

  // 5. Fetch the detail for this edit by post author
  const detail = await api.functional.polEcoBoard.member.posts.postEdits.atEdit(connection, {
    postId: post.id,
    postEditId: postEdit.id,
  });
  typia.assert(detail);

  // 6. Business/data assertions
  TestValidator.equals("editor_member_id matches author")(detail.editor_member_id)(member.id);
  TestValidator.equals("post_id matches")(detail.post_id)(post.id);
  TestValidator.equals("edit_body matches")(detail.edit_body)(editBody);
  TestValidator.equals("edit_reason matches")(detail.edit_reason)(editReason);
  TestValidator.predicate("created_at present and not empty")(typeof detail.created_at === "string" && detail.created_at.length > 0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPostEdit";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate forbidden access to post edit history for non-authors.
 *
 * Ensures that a regular member (not the post's author and with no admin/moderator privileges)
 * receives a permission denied error when attempting to access the edit detail of another
 * member's post via the protected endpoint. This confirms backend enforcement of RBAC.
 *
 * Business scenario walkthrough:
 * 1. Register a member to act as the post author (authorMember).
 * 2. Author logs in successfully.
 * 3. Author creates a new board post in a random category.
 * 4. Author submits an edit to their own post.
 * 5. Register a second member (nonAuthorMember).
 * 6. Second member logs in successfully (no moderator/admin privileges).
 * 7. Second member attempts to fetch the post edit detail using the protected endpoint.
 * 8. Assert that the request is rejected (403 forbidden) due to lacking permissions.
 */
export async function test_api_post_edit_detail_member_permission_denied_non_author(
  connection: api.IConnection,
) {
  // 1. Register first member (author)
  const authorEmail = typia.random<string & tags.Format<"email">>();
  const authorPassword = "testPassword123!";
  const author: IPolEcoBoardMember = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: authorEmail,
      password_hash: authorPassword,
      display_name: RandomGenerator.name(),
      consent_status: "v1-consent",
      profile_image_uri: null,
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(author);

  // 2. Login as author
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: authorEmail,
      password: authorPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // 3. Author creates a post
  const post: IPolEcoBoardPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Author creates a post edit
  const postEdit: IPolEcoBoardPostEdit = await api.functional.polEcoBoard.member.posts.postEdits.createEdit(connection, {
    postId: post.id,
    body: {
      edit_body: RandomGenerator.content()()(),
      edit_reason: "Initial post correction.",
    } satisfies IPolEcoBoardPostEdit.ICreate,
  });
  typia.assert(postEdit);

  // 5. Register second member (not the author, not privileged)
  const member2Email = typia.random<string & tags.Format<"email">>();
  const member2Password = "testPassword456!";
  const member2: IPolEcoBoardMember = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: member2Email,
      password_hash: member2Password,
      display_name: RandomGenerator.name(),
      consent_status: "v1-consent",
      profile_image_uri: null,
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member2);

  // 6. Login as second member
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: member2Email,
      password: member2Password,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // 7. Attempt forbidden post edit detail request as non-author (should fail with 403)
  await TestValidator.error("non-author cannot access another member's post edit detail")(
    async () => {
      await api.functional.polEcoBoard.member.posts.postEdits.atEdit(connection, {
        postId: post.id,
        postEditId: postEdit.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPostEdit";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate that a moderator can access detailed information of any post edit for audit and compliance review, even when not the editor or post author.
 *
 * This ensures moderators have full visibility into post edit histories, regardless of the editing actor or original author, in line with business audit and compliance requirements.
 *
 * Test steps:
 *   1. Register a new moderator.
 *   2. Log in as this moderator; capture authentication state.
 *   3. Register a normal member account (distinct from moderator).
 *   4. Log in as the member to create a post and then create an edit snapshot for that post.
 *   5. Switch authentication to moderator session.
 *   6. Retrieve post edit detail using the moderator privileged endpoint.
 *   7. Validate that the retrieved edit includes the correct editor, content, reason, and timestamps, confirming full access to audit-relevant fields.
 *   8. Attempt to fetch a post edit detail using a non-existent edit ID and verify proper error response (permission enforcement).
 */
export async function test_api_post_edit_detail_moderator_access(connection: api.IConnection) {
  // 1. Register a new moderator
  const modEmail = typia.random<string & tags.Format<"email">>();
  const modPassword = RandomGenerator.alphaNumeric(12);
  const modDisplayName = RandomGenerator.name();
  const modConsent = "policy_v1";
  const moderatorReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: modEmail,
      password: modPassword,
      display_name: modDisplayName,
      consent_status: modConsent,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorReg);

  // 2. Log in as moderator
  const modLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: modEmail,
      password: modPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(modLogin);

  // 3. Register normal member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberRawPassword = RandomGenerator.alphaNumeric(12);
  const memberPasswordHash = memberRawPassword as string; // Assume raw password is accepted as hash for test
  const memberDisplayName = RandomGenerator.name();
  const memberConsent = "policy_v1";
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPasswordHash,
      display_name: memberDisplayName,
      profile_image_uri: null,
      consent_status: memberConsent,
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // 4. Log in as member, create post, create post edit
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberRawPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  // Category ID is required; for test use random UUID
  const postCategoryId = typia.random<string & tags.Format<"uuid">>();
  const postTitle = RandomGenerator.paragraph()(1, 2).substring(0, 120); // Max 120 chars by business rules
  const postBody = RandomGenerator.content()()(10, 1000);
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: postCategoryId,
      title: postTitle,
      body: postBody,
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // Create an edit for the post
  const editReason = "Typo correction for audit test";
  const editBody = postBody + " - edit";
  const edit = await api.functional.polEcoBoard.member.posts.postEdits.createEdit(connection, {
    postId: post.id,
    body: {
      edit_body: editBody,
      edit_reason: editReason,
    } satisfies IPolEcoBoardPostEdit.ICreate,
  });
  typia.assert(edit);

  // 5. Switch authentication back to moderator
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: modEmail,
      password: modPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });

  // 6. Retrieve post edit detail using the moderator-privileged endpoint
  const fetchedEdit = await api.functional.polEcoBoard.moderator.posts.postEdits.atEdit(connection, {
    postId: post.id,
    postEditId: edit.id,
  });
  typia.assert(fetchedEdit);
  // 7. Validate audit-relevant detail access
  TestValidator.equals("edit id matches")(fetchedEdit.id)(edit.id);
  TestValidator.equals("edit post id matches")(fetchedEdit.post_id)(post.id);
  TestValidator.equals("edit editor member id matches")(fetchedEdit.editor_member_id)(member.id);
  TestValidator.equals("edit body matches")(fetchedEdit.edit_body)(editBody);
  TestValidator.equals("edit reason matches")(fetchedEdit.edit_reason)(editReason);
  TestValidator.predicate("edit created_at is ISO date")(
    !isNaN(Date.parse(fetchedEdit.created_at))
  );
  // Permission: Moderator can view any post edit

  // 8. Attempt to fetch non-existent edit (simulate with random UUID)
  const nonExistentPostEditId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("accessing non-existent post edit should fail")(async () => {
    await api.functional.polEcoBoard.moderator.posts.postEdits.atEdit(connection, {
      postId: post.id,
      postEditId: nonExistentPostEditId,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPostEdit";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validates that an admin account can retrieve full details for any post edit using admin privileges.
 *
 * Business context:
 *   - Admin accounts must have unrestricted read access to all post edit records, regardless of editor or post author.
 *     This is essential for audit, compliance, and moderation. The test simulates the entire workflow:
 *     admin registration/login, member registration/login, post creation, post edit, and admin query of post edit detail, including negative case.
 *
 * Test steps:
 *   1. Register a new admin account and log in, acquiring full system permissions.
 *   2. Register a standard member and log in.
 *   3. As the member, create a post (article).
 *   4. As the member, submit a post edit (revision) to that post.
 *   5. Switch back to the admin session, query the post edit record by postId/postEditId, and validate the data is correct.
 *   6. Attempt to query a non-existent postEditId as admin and validate that an error is thrown (negative path).
 */
export async function test_api_post_edit_detail_admin_access(connection: api.IConnection) {
  // 1. Admin registration
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Admin login
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Member registration
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const memberDisplayName = RandomGenerator.name();
  const memberConsent = "v1";
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: memberDisplayName,
      consent_status: memberConsent,
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // 4. Member login
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // 5. Member creates a post
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const postTitle = RandomGenerator.paragraph(1)();
  const postBody = RandomGenerator.content()()();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: postTitle,
      body: postBody,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 6. Member submits an edit (revision)
  const editReason = "First revision for test.";
  const postEdit = await api.functional.polEcoBoard.member.posts.postEdits.createEdit(connection, {
