import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validates the hard deletion (permanent removal) of an incident record as a super-admin (admin privilege enforcement and audit required).
 *
 * This function tests the following workflow and controls:
 *
 * 1. Register and login as an admin (super-admin privilege).
 * 2. Create an incident as the admin to ensure a valid target exists.
 * 3. Delete the incident by its unique incidentId.
 * 4. Confirm the incident is deleted (e.g., attempting to delete again should error, or it can no longer be referenced).
 * 5. Ensure compliance and audit requirements (deletion action is permitted only for admins, mandatory audit trail/log).
 * 6. Validate forbidden and error cases:
 *    - Deletion of non-existent incident (should error)
 *    - Deletion of already deleted incident (should error)
 *    - Attempt by non-admin/unauthenticated user (should error)
 *
 * Key business rules:
 * - Only admins may perform this operation.
 * - Each deletion must be logged for compliance/audit (cannot be checked directly with current SDK; assumed to be server-side enforced).
 * - Hard-delete is final (no recovery).
 */
export async function test_api_incident_delete_hard_delete_and_permission_controls(connection: api.IConnection) {
  // 1. Register a super-admin/admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Login as admin (sets Authorization header on connection)
  const signInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResp);

  // 3. Create an incident
  const createIncidentResp = await api.functional.polEcoBoard.admin.incidents.create(connection, {
    body: {
      incident_code: `TEST_${Date.now()}`,
      category: "OUTAGE",
      status: "OPEN",
      description: "Test incident for deletion",
      detected_at: new Date().toISOString(),
    } satisfies IPolEcoBoardIncident.ICreate,
  });
  typia.assert(createIncidentResp);
  const incidentId = createIncidentResp.id;

  // 4. Delete the incident (hard delete)
  await api.functional.polEcoBoard.admin.incidents.erase(connection, {
    incidentId,
  });

  // 5. Try to delete the same incident again (should error)
  await TestValidator.error("double delete fails")(() =>
    api.functional.polEcoBoard.admin.incidents.erase(connection, { incidentId })
  );

  // 6. Try to delete a random (non-existent) incident (should error)
  await TestValidator.error("delete non-existent incident fails")(() =>
    api.functional.polEcoBoard.admin.incidents.erase(connection, {
      incidentId: typia.random<string & tags.Format<"uuid">>(),
    })
  );

  // 7. Attempt to delete as non-admin/unauthenticated user
  const connectionNoAuth: api.IConnection = {
    ...connection,
    headers: {},
  };
  await TestValidator.error("delete with no auth fails")(() =>
    api.functional.polEcoBoard.admin.incidents.erase(connectionNoAuth, {
      incidentId,
    })
  );
  // Note: Explicit audit/compliance log validation is not implementable (API does not expose log access); assumed enforced by server.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMaintenanceWindow } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMaintenanceWindow";
import type { IPageIPolEcoBoardMaintenanceWindow } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardMaintenanceWindow";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate search, filter, pagination, and permission on maintenance window listing as admin.
 *
 * Test ensures the complete workflow for maintenance window search as an administrator:
 * - Admin registration and login flow covers setup and authentication handling.
 * - Multiple maintenance windows are created with variance in code, time, and description for realistic test data coverage.
 * - The search endpoint is validated for: all-records (no filter), filter by window_code, by expected_impact text, and by time range.
 * - Pagination and edge cases like empty results and permission denial for unauthenticated requests are verified.
 * - Invalid argument handling (such as negative page and too large limit) ensures schema robustness and error handling.
 *
 * Step-by-step process:
 * 1. Register a new admin with unique email/password.
 * 2. Login as admin account for valid authentication.
 * 3. Create several maintenance windows with varying codes, times, impact descriptors.
 * 4. Perform search queries: no filters, filter by code, by expected_impact substring, and by time range.
 * 5. Force pagination (limit=1) to check multi-page navigation.
 * 6. Apply a nonsense filter for empty results test.
 * 7. Pass invalid arguments (negative page/index, excessive limit) for schema error handling.
 * 8. Attempt access with no JWT (unauthenticated) to check access denied behavior.
 */
export async function test_api_maintenance_window_search_filter_pagination(connection: api.IConnection) {
  // 1. Register a new admin
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: { email, password } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as the new admin (JWT Authorization header is set)
  await api.functional.auth.admin.login.signIn(connection, {
    body: { email, password } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create distinct maintenance windows
  const now = new Date();
  const created: IPolEcoBoardMaintenanceWindow[] = [];
  for (let i = 0; i < 3; ++i) {
    // Each window gets a unique code and staggered date ranges
    const mw = await api.functional.polEcoBoard.admin.maintenanceWindows.create(connection, {
      body: {
        window_code: `MAINT_${now.getFullYear()}${now.getMonth() + 1}${now.getDate()}_${i}`,
        start_time: new Date(now.getTime() + i * 24 * 3600 * 1000).toISOString(),
        end_time: new Date(now.getTime() + (i + 1) * 24 * 3600 * 1000).toISOString(),
        expected_impact: i % 2 === 0 ? "service degradation" : "platform offline",
        notified_at: null,
      } satisfies IPolEcoBoardMaintenanceWindow.ICreate,
    });
    typia.assert(mw);
    created.push(mw);
  }

  // 4. Search: all records (no filters)
  const search1 = await api.functional.polEcoBoard.admin.maintenanceWindows.search(connection, {
    body: {} satisfies IPolEcoBoardMaintenanceWindow.IRequest,
  });
  typia.assert(search1);
  TestValidator.predicate("all created windows should be present")(created.every(c => search1.data.some(d => d.id === c.id)));
  TestValidator.predicate("pagination info available")(!!search1.pagination && typeof search1.pagination.pages === "number");

  // 5. Search: filter by window_code
  const codeToFilter = created[1].window_code;
  const search2 = await api.functional.polEcoBoard.admin.maintenanceWindows.search(connection, {
    body: { window_code: codeToFilter } satisfies IPolEcoBoardMaintenanceWindow.IRequest,
  });
  typia.assert(search2);
  TestValidator.equals("should return one matching code")(search2.data.length)(1);
  TestValidator.equals("window_code matches")(search2.data[0].window_code)(codeToFilter);

  // 6. Search: filter by expected_impact substring
  const search3 = await api.functional.polEcoBoard.admin.maintenanceWindows.search(connection, {
    body: { expected_impact: "degradation" } satisfies IPolEcoBoardMaintenanceWindow.IRequest,
  });
  typia.assert(search3);
  TestValidator.predicate("should find at least one matching expected_impact")(search3.data.some(w => w.expected_impact.includes("degradation")));

  // 7. Search: time range filtering
  const timeFrom = created[1].start_time;
  const timeTo = created[2].end_time!;
  const search4 = await api.functional.polEcoBoard.admin.maintenanceWindows.search(connection, {
    body: { start_time_from: timeFrom, start_time_to: timeTo } satisfies IPolEcoBoardMaintenanceWindow.IRequest,
  });
  typia.assert(search4);
  TestValidator.predicate("all results within requested time range")(search4.data.every(w => w.start_time >= timeFrom && w.start_time <= timeTo));

  // 8. Pagination test: limit=1, page 1 and then next page if available
  const search5 = await api.functional.polEcoBoard.admin.maintenanceWindows.search(connection, {
    body: { page: 1, limit: 1 } satisfies IPolEcoBoardMaintenanceWindow.IRequest,
  });
  typia.assert(search5);
  TestValidator.equals("result count for page 1")(search5.data.length)(1);
  TestValidator.equals("page is 1")(search5.pagination.current)(1);
  if (search5.pagination.pages > 1) {
    const search5b = await api.functional.polEcoBoard.admin.maintenanceWindows.search(connection, {
      body: { page: 2, limit: 1 } satisfies IPolEcoBoardMaintenanceWindow.IRequest,
    });
    typia.assert(search5b);
    TestValidator.equals("page is 2")(search5b.pagination.current)(2);
    TestValidator.equals("count page 2")(search5b.data.length)(1);
  }

  // 9. Empty result scenario: filter with a nonsense code
  const search6 = await api.functional.polEcoBoard.admin.maintenanceWindows.search(connection, {
    body: { window_code: "NON_EXIST_CODE" } satisfies IPolEcoBoardMaintenanceWindow.IRequest,
  });
  typia.assert(search6);
  TestValidator.equals("should have no matching records")(search6.data.length)(0);

  // 10. Invalid argument: page negative / excessive limit (must use as any for negative test)
  await TestValidator.error("page negative error")(async () => {
    await api.functional.polEcoBoard.admin.maintenanceWindows.search(connection, {
      body: { page: -1 } as any,
    });
  });
  await TestValidator.error("limit too large error")(async () => {
    await api.functional.polEcoBoard.admin.maintenanceWindows.search(connection, {
      body: { limit: 99999 } as any,
    });
  });

  // 11. Unauthenticated access: remove JWT and verify 401/denied
  const unauthConn = { ...connection, headers: { ...connection.headers } };
  delete unauthConn.headers.Authorization;
  await TestValidator.error("should fail without auth")(async () => {
    await api.functional.polEcoBoard.admin.maintenanceWindows.search(unauthConn, {
