/**
 * Validate moderator access to board history detail API.
 *
 * Tests the ability of a moderator to fetch full details of a board change history by boardHistoryId.
 * Covers the following workflow:
 * 1. Register and login an admin (creates source data for board histories)
 * 2. Register and login a moderator (for API permission context)
 * 3. Admin creates a category
 * 4. Admin creates a board within that category
 * 5. Admin creates a board history record for the board
 * 6. Moderator fetches the boardHistoryId and checks field composition
 * 7. Moderator attempts to fetch a random/nonexistent and (if possible) deleted ID, verifies correct permission/error behaviour
 *
 * This test ensures the permission matrix and business workflow are enforced, with all object references and rationale visible to moderators.
 */
export async function test_api_board_history_get_detail_as_moderator(connection: api.IConnection) {
  // 1. Register and login admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 2. Register and login moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = RandomGenerator.alphaNumeric(12);
  const moderatorDisplayName = RandomGenerator.name();
  const moderatorConsentStatus = "accepted_v1";
  await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: moderatorConsentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });

  // 3. Admin creates a category
  // Switch back to admin (login again to set admin token)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      description: RandomGenerator.paragraph()(),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);

  // 4. Admin creates a board within the category
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.alphabets(12),
      code: RandomGenerator.alphaNumeric(10).toLowerCase(),
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 5. Admin creates a board history record for the board
  const history = await api.functional.polEcoBoard.admin.boardHistories.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      previous_category_id: null,
      new_category_id: category.id,
      actor_admin_id: null, // Could set adminId if available; left null for path compatibility
      actor_moderator_id: null,
      change_type: "reassignment",
      change_reason: RandomGenerator.paragraph()(),
      changed_at: new Date().toISOString() as string & tags.Format<"date-time">,
    } satisfies IPolEcoBoardBoardHistory.ICreate,
  });
  typia.assert(history);

  // 6. Moderator fetches boardHistoryId (login again as moderator)
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  const fetched = await api.functional.polEcoBoard.moderator.boardHistories.at(connection, {
    boardHistoryId: history.id,
  });
  typia.assert(fetched);
  TestValidator.equals("boardHistoryId matches")(fetched.id)(history.id);
  TestValidator.equals("board id matches")(fetched.pol_eco_board_board_id)(board.id);
  TestValidator.equals("new category matches")(fetched.new_category_id)(category.id);
  TestValidator.predicate("change_reason is present")(typeof fetched.change_reason === "string" && fetched.change_reason.length > 0);

  // 7. Moderator fetches a non-existent boardHistoryId (random UUID): expect not found or error
  const randomBoardHistoryId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("non-existent boardHistoryId should fail")(async () => {
    await api.functional.polEcoBoard.moderator.boardHistories.at(connection, {
      boardHistoryId: randomBoardHistoryId,
    });
  });
  // Edge: Try fetch of deleted (not implemented here -- no API to delete; would do same as random if supported)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardBoardStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoardStatus";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate the ability for a moderator to soft-delete (archive) a board status event record for a discussion board.
 *
 * Business rationale:
 * - Moderators should be able to archive (soft-delete) board status events for compliance and operational reversibility, but only on events they have privileges for.
 * - System must strictly mark the record as deleted (set `deleted_at`) without removing from the audit trail.
 * - Subsequent deletion attempts for the same or nonexistent events must raise errors.
 *
 * Step-by-step process:
 * 1. Register a new admin and login to allow privileged category/board creation.
 * 2. As admin: Create a new category and a board in that category.
 * 3. Register a moderator and login as that moderator.
 * 4. As moderator: Create a board status event for that board.
 * 5. Soft-delete the status event (main action).
 * 6. Verify deletion by checking:
 *    a) Second delete call fails (already deleted)
 *    b) Deleting a random nonexistent status also fails
 */
export async function test_api_board_status_soft_delete_by_moderator(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "adminPass123!";
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Admin login (to authorize board/category creation)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create a new category
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      description: RandomGenerator.alphaNumeric(30),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);

  // 4. Create a board under this category
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.alphabets(10),
      code: RandomGenerator.alphaNumeric(10).toLowerCase(),
      description: RandomGenerator.alphaNumeric(25),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 5. Register a moderator
  const modEmail = typia.random<string & tags.Format<"email">>();
  const modPassword = "modPass123!";
  const modDisplayName = RandomGenerator.alphabets(8);
  await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: modEmail,
      password: modPassword,
      display_name: modDisplayName,
      consent_status: "accepted-latest-tos",
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });

  // 6. Moderator login
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: modEmail,
      password: modPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });

  // 7. Moderator creates a board status event (archived)
  const status = await api.functional.polEcoBoard.moderator.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      actor_moderator_id: null, // Provided by JWT; only moderator can act here
      actor_admin_id: null,
      status_type: "archived",
      effective_at: new Date().toISOString(),
      reason: "Setup for soft-delete test.",
    } satisfies IPolEcoBoardBoardStatus.ICreate,
  });
  typia.assert(status);

  // 8. Invoke soft-delete (archive) as moderator
  await api.functional.polEcoBoard.moderator.boardStatuses.erase(connection, {
    boardStatusId: status.id,
  });

  // 9. Attempt to delete again should fail (already deleted)
  await TestValidator.error("already deleted / double delete")(() =>
    api.functional.polEcoBoard.moderator.boardStatuses.erase(connection, {
      boardStatusId: status.id,
    })
  );

  // 10. Attempt to delete a random/unknown boardStatusId should fail
  await TestValidator.error("delete nonexistent boardStatusId")(() =>
    api.functional.polEcoBoard.moderator.boardStatuses.erase(connection, {
      boardStatusId: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardBoardStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoardStatus";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Verify admin-driven soft-deletion of board status events and compliance with audit and retention business rules.
 *
 * This test ensures that an admin user can soft-delete (archive) a board status event and that business logic behaves as expected:
 *
 * 1. Registers and logs in as an admin, yielding privileged session.
 * 2. Creates a category and a discussion board as prerequisites.
 * 3. Records a new board status event (with this admin as the actor).
 * 4. Issues DELETE for the new status event (should archive via deleted_at—not physical removal).
 * 5. Checks that deleted_at has been set (by making additional status event, verifying new event not affected, and comparing outcomes).
 * 6. Attempts duplicate deletion on the same status id (should yield a business error).
 * 7. Attempts deletion of a non-existent boardStatusId (should yield a not-found/business error).
 *
 * Note: Non-admin actor simulation is omitted, as user/moderator auth APIs are unavailable in current E2E surface.
 */
export async function test_api_board_status_soft_delete_by_admin(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Login as admin to ensure token set (redundant if signUp sets, but double-check for strictness)
  const signInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResp);

  // 3. Create a category
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(2),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);

  // 4. Create a board in that category
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.paragraph()(1),
      code: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()(2),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 5. Create a board status event (admin as actor)
  const boardStatus = await api.functional.polEcoBoard.admin.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      actor_admin_id: null, // Will be system-resolved based on token
      status_type: "visible",
      effective_at: new Date().toISOString(),
      reason: RandomGenerator.paragraph()(),
    } satisfies IPolEcoBoardBoardStatus.ICreate,
  });
  typia.assert(boardStatus);
  TestValidator.equals("not deleted initially")(boardStatus.deleted_at)(null);

  // 6. Soft-delete the board status event
  await api.functional.polEcoBoard.admin.boardStatuses.erase(connection, {
    boardStatusId: boardStatus.id,
  });

  // 7. Confirm status is now deleted (simulate by making new status, ensure old id not re-used, etc.)
  // Since we can't query the deleted record, create another status to show system allows others
  const boardStatusAfter = await api.functional.polEcoBoard.admin.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      actor_admin_id: null,
      status_type: "locked",
      effective_at: new Date().toISOString(),
      reason: RandomGenerator.paragraph()(),
    } satisfies IPolEcoBoardBoardStatus.ICreate,
  });
  typia.assert(boardStatusAfter);
  TestValidator.notEquals("new status has new id")(boardStatusAfter.id)(boardStatus.id);

  // 8. Edge: Try deleting already-deleted record (should error)
  await TestValidator.error("re-delete yields error")(async () => {
    await api.functional.polEcoBoard.admin.boardStatuses.erase(connection, {
      boardStatusId: boardStatus.id,
    });
  });

  // 9. Edge: Try deleting random/non-existent id (should error)
  await TestValidator.error("delete random id fails")(async () => {
    await api.functional.polEcoBoard.admin.boardStatuses.erase(connection, {
      boardStatusId: typia.random<string & tags.Format<"uuid">>()
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
