import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Comprehensive E2E test for board status creation as moderator, including business rules
 * and permission/error validation for the polEcoBoard system.
 *
 * This function validates:
 * 1. Successful board status creation by an authenticated moderator with valid data (follows correct registration and login, references a real board)
 * 2. Validation errors for required fields and invalid status_type
 * 3. Attempt to reference a non-existent board (should fail)
 * 4. Forbidden/unauthorized usage by unauthenticated user
 */
export async function test_api_board_status_creation_by_moderator_with_validation_and_permission_errors(connection: api.IConnection) {
  // Step 1: Register a new moderator and extract id/token
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorRegRes = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: "SecretPassword123!",
      display_name: RandomGenerator.name(),
      consent_status: "v1.0-policy-accepted",
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorRegRes);

  // Step 2: Login as moderator (simulates real flow, ensures JWT in connection)
  const moderatorLoginRes = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: "SecretPassword123!",
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(moderatorLoginRes);
  const moderatorId = moderatorLoginRes.moderatorId;

  // Step 3: Create a board (admin)
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.alphaNumeric(8),
      code: RandomGenerator.alphaNumeric(8).toLowerCase(),
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // Step 4: As moderator, create a valid board status event
  const now = new Date().toISOString();
  const statusPayload = {
    pol_eco_board_board_id: board.id,
    actor_moderator_id: moderatorId,
    status_type: "locked",
    effective_at: now,
    reason: "Testing board lock by moderator.",
  } satisfies IPolEcoBoardBoardStatus.ICreate;
  const createdStatus = await api.functional.polEcoBoard.moderator.boardStatuses.create(connection, {
    body: statusPayload,
  });
  typia.assert(createdStatus);
  TestValidator.equals("board id matches")(createdStatus.pol_eco_board_board_id)(board.id);
  TestValidator.equals("status type matches")(createdStatus.status_type)(statusPayload.status_type);

  // Step 5: Validation for invalid status_type
  await TestValidator.error("invalid status_type should be rejected")(async () =>
    api.functional.polEcoBoard.moderator.boardStatuses.create(connection, {
      body: {
        pol_eco_board_board_id: board.id,
        actor_moderator_id: moderatorId,
        status_type: "notarealstatus" as any, // will fail at runtime
        effective_at: now,
        reason: "Invalid status_type.",
      } as any,
    })
  );

  // Step 6: Missing optional reason (should succeed)
  const statusNoReason = await api.functional.polEcoBoard.moderator.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      actor_moderator_id: moderatorId,
      status_type: "open",
      effective_at: now,
      // reason omitted
    } satisfies IPolEcoBoardBoardStatus.ICreate,
  });
  typia.assert(statusNoReason);
  TestValidator.equals("board id matches for no reason")(statusNoReason.pol_eco_board_board_id)(board.id);

  // Step 7: Reference non-existent board
  await TestValidator.error("referencing non-existent board should be rejected")(async () =>
    api.functional.polEcoBoard.moderator.boardStatuses.create(connection, {
      body: {
        pol_eco_board_board_id: typia.random<string & tags.Format<"uuid">>(),
        actor_moderator_id: moderatorId,
        status_type: "locked",
        effective_at: now,
        reason: "Non-existent board reference.",
      } satisfies IPolEcoBoardBoardStatus.ICreate,
    })
  );

  // Step 8: Attempt forbidden/unauthenticated usage: call with base (unauthenticated) connection
  // Use the original base connection object for this call (before any token is set)
  await TestValidator.error("unauthorized should be forbidden")(async () =>
    api.functional.polEcoBoard.moderator.boardStatuses.create(connection, {
      body: statusPayload,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
