/**
 * Test updating details of a board status event by a moderator (PUT /polEcoBoard/moderator/boardStatuses/{boardStatusId}).
 *
 * This test validates multiple business cases for board status event updates:
 *
 * 1. Successfully update an existing status event by an authorized moderator
 * 2. Attempt update with invalid or missing fields (should fail)
 * 3. Attempt update after allowed edit window (should fail if window is enforced)
 * 4. Update of a deleted (soft-deleted) or non-existent event (should fail)
 * 5. Update attempt by unauthorized (non-moderator) actor (should fail)
 *
 * Steps:
 * - Register and login as a new moderator
 * - Create a board status event for a random board as this moderator
 * - Successfully update the status event using valid inputs (expect audit fields changed)
 * - Try to update with missing required fields (should error)
 * - (If allowed edit window: update after the window expires)
 * - Try to update a deleted status event (first soft-delete, then try update; expect error)
 * - Try updating a non-existent boardStatusId (expect error)
 * - Try updating as unauthorized (simulate by removing Authorization or using invalid token)
 */
export async function test_api_board_status_update_by_moderator_with_state_and_permission_validation(
  connection: api.IConnection,
) {
  // 1. Register a new moderator
  const moderatorReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestModPass1!",
      display_name: RandomGenerator.name(),
      consent_status: "v1/2024-consent",
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorReg);
  const moderatorEmail = moderatorReg.email;
  const moderatorPassword = "TestModPass1!";

  // 2. Login as the registered moderator (confirm token is set)
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(moderatorLogin);

  // 3. Create a board status event with this moderator
  const polEcoBoardBoardId = typia.random<string & tags.Format<"uuid">>();
  const createBoardStatus = await api.functional.polEcoBoard.moderator.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: polEcoBoardBoardId,
      actor_moderator_id: moderatorLogin.moderatorId,
      status_type: "visible",
      effective_at: new Date().toISOString(),
      reason: "Initial status set by moderator",
    } satisfies IPolEcoBoardBoardStatus.ICreate,
  });
  typia.assert(createBoardStatus);
  const boardStatusId = createBoardStatus.id;

  // 4. Successful update of the board status event
  const updateStatus1 = await api.functional.polEcoBoard.moderator.boardStatuses.update(connection, {
    boardStatusId,
    body: {
      status_type: "locked",
      reason: "Board locked for moderation review",
      actor_moderator_id: moderatorLogin.moderatorId,
    } satisfies IPolEcoBoardBoardStatus.IUpdate,
  });
  typia.assert(updateStatus1);
  TestValidator.equals("board status id match")(updateStatus1.id)(boardStatusId);
  TestValidator.equals("status type updated")(updateStatus1.status_type)("locked");
  TestValidator.equals("reason updated")(updateStatus1.reason)("Board locked for moderation review");
  TestValidator.equals("actor moderator id updated")(updateStatus1.actor_moderator_id)(moderatorLogin.moderatorId);

  // 5. Error: update with invalid (illegal status_type)
  await TestValidator.error("invalid status_type should fail")(async () => {
    await api.functional.polEcoBoard.moderator.boardStatuses.update(connection, {
      boardStatusId,
      body: {
        status_type: "non-existent-status" as any,
        actor_moderator_id: moderatorLogin.moderatorId,
      } as any,
    });
  });

  // 6. Error: update a non-existent boardStatusId
  const fakeBoardStatusId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("update with non-existent boardStatusId should fail")(async () => {
    await api.functional.polEcoBoard.moderator.boardStatuses.update(connection, {
      boardStatusId: fakeBoardStatusId,
      body: {
        status_type: "locked",
        reason: "Testing non-existent",
        actor_moderator_id: moderatorLogin.moderatorId,
      } satisfies IPolEcoBoardBoardStatus.IUpdate,
    });
  });

  // 7. Error: update as non-moderator (no Authorization) - Remove token, expect error
  const noAuthConnection = { ...connection, headers: { ...connection.headers, Authorization: "" } };
  await TestValidator.error("update as non-moderator should fail")(async () => {
    await api.functional.polEcoBoard.moderator.boardStatuses.update(noAuthConnection, {
      boardStatusId,
      body: {
        status_type: "visible",
        reason: "Unauthorized update attempt",
      } satisfies IPolEcoBoardBoardStatus.IUpdate,
    });
  });
}

