import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate update failure of a maintenance window when the start time is after the end time (invalid window).
 *
 * This test simulates the business scenario where an admin attempts to update a maintenance window entry with logically invalid times, violating the platform rule that the window start cannot be after its end. The function ensures validation logic is enforced and the record remains unchanged upon error.
 *
 * Test procedure:
 * 1. Register an admin account (unique email/password).
 * 2. Login as this admin to acquire a valid session/token.
 * 3. Create a new maintenance window with valid data to obtain a valid maintenanceWindowId.
 * 4. Attempt to update the created maintenance window, setting the start_time to a value after the end_time (invalid window).
 * 5. Assert that a validation error (runtime error) is correctly thrown, and the window record is not modified as a result of the invalid request.
 */
export async function test_api_maintenance_window_update_invalid_time_window(
  connection: api.IConnection,
) {
  // 1. Register an admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResult = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResult);

  // 2. Login as admin (session/token handled automatically)
  const signInResult = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResult);

  // 3. Create a valid maintenance window
  const now = new Date();
  const start_time = new Date(now.getTime() + 60 * 60 * 1000).toISOString();
  const end_time = new Date(now.getTime() + 2 * 60 * 60 * 1000).toISOString();
  const createResult = await api.functional.polEcoBoard.admin.maintenanceWindows.create(connection, {
    body: {
      window_code: `MAINT_${now.toISOString().replace(/[-:T.]/g, "").slice(0,12)}`,
      start_time,
      end_time,
      expected_impact: "Expected downtime for system upgrade.",
    } satisfies IPolEcoBoardMaintenanceWindow.ICreate,
  });
  typia.assert(createResult);

  // 4. Attempt update: start_time after end_time (should fail)
  const invalid_start = new Date(now.getTime() + 3 * 60 * 60 * 1000).toISOString();
  const invalid_end = new Date(now.getTime() + 2 * 60 * 60 * 1000).toISOString(); // end before start

  // Test that update throws validation error
  await TestValidator.error("should fail when start_time is after end_time")(() =>
    api.functional.polEcoBoard.admin.maintenanceWindows.update(connection, {
      maintenanceWindowId: createResult.id,
      body: {
        start_time: invalid_start,
        end_time: invalid_end,
      } satisfies IPolEcoBoardMaintenanceWindow.IUpdate,
    })
  );

  // (Optional) Confirm record not updated - omitted as the API contract may not let us confirm due to no get/read function provided.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
