import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardServiceMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardServiceMetric";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate successful creation of a service metric by an authenticated admin.
 *
 * This test simulates the full admin workflow for creating a KPI/service metric record in the PolEcoBoard system API.
 *
 * Steps:
 * 1. Register a new admin user with unique credentials.
 * 2. Log in as the new admin to initialize the authentication context.
 * 3. Create a service metric via POST /polEcoBoard/admin/serviceMetrics, using a unique metric_code and a valid time window. Set only the integer value field (value_int), leaving value_double null.
 * 4. Verify that the returned metric matches the input and adheres to the contract. Assert correct value type assignment.
 * 5. Attempt to create a duplicate metric with the exact same code and window; ensure this fails due to business rule enforcement.
 * 6. Create a second, unrelated metric with exactly the same window but a different code. This time, set only the value_double field, with value_int null. Validate correct value type and API contract.
 */
export async function test_api_service_metric_create_success(connection: api.IConnection) {
  // 1. Register admin user for authentication
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(12);
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Log in to establish JWT/session for subsequent requests
  const signInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResp);

  // 3. Create the first service metric (integer variant)
  // Generate a unique code, and a discrete hourly window
  const now = new Date();
  const metricWindowStart: string =
    new Date(now.getFullYear(), now.getMonth(), now.getDate(), 0, 0, 0, 0).toISOString();
  const metricWindowEnd: string =
    new Date(now.getFullYear(), now.getMonth(), now.getDate(), 1, 0, 0, 0).toISOString();
  const metricCode1: string = `test_metric_code_${RandomGenerator.alphaNumeric(6)}`;
  const metricCreateInput1: IPolEcoBoardServiceMetric.ICreate = {
    metric_code: metricCode1,
    metric_window_start: metricWindowStart,
    metric_window_end: metricWindowEnd,
    value_int: typia.random<number & tags.Type<"int32">>(),
    value_double: null,
    notes: RandomGenerator.paragraph()(),
  };
  const metric1 = await api.functional.polEcoBoard.admin.serviceMetrics.create(
    connection,
    { body: metricCreateInput1 },
  );
  typia.assert(metric1);

  // 4. Assert returned record matches input and correct type fields
  TestValidator.equals("metric_code")(metric1.metric_code)(metricCreateInput1.metric_code);
  TestValidator.equals("metric_window_start")(metric1.metric_window_start)(metricCreateInput1.metric_window_start);
  TestValidator.equals("metric_window_end")(metric1.metric_window_end)(metricCreateInput1.metric_window_end);
  TestValidator.equals("value_int")(metric1.value_int)(metricCreateInput1.value_int);
  TestValidator.equals("value_double")(metric1.value_double)(null);
  TestValidator.equals("notes")(metric1.notes)(metricCreateInput1.notes);

  // 5. Attempt duplicate code+window (should fail uniqueness rule)
  await TestValidator.error("Duplicate metric_code+window should fail")(
    () => api.functional.polEcoBoard.admin.serviceMetrics.create(
      connection,
      { body: metricCreateInput1 },
    ),
  );

  // 6. Create a second metric (floating-point variant, same window different code)
  const metricCode2: string = `test_metric_code_${RandomGenerator.alphaNumeric(6)}`;
  const metricCreateInput2: IPolEcoBoardServiceMetric.ICreate = {
    metric_code: metricCode2,
    metric_window_start: metricWindowStart,
    metric_window_end: metricWindowEnd,
    value_int: null,
    value_double: Math.random() * 1_000,
    notes: RandomGenerator.paragraph()(),
  };
  const metric2 = await api.functional.polEcoBoard.admin.serviceMetrics.create(
    connection,
    { body: metricCreateInput2 },
  );
  typia.assert(metric2);
  TestValidator.equals("metric_code")(metric2.metric_code)(metricCreateInput2.metric_code);
  TestValidator.equals("metric_window_start")(metric2.metric_window_start)(metricCreateInput2.metric_window_start);
  TestValidator.equals("metric_window_end")(metric2.metric_window_end)(metricCreateInput2.metric_window_end);
  TestValidator.equals("value_int")(metric2.value_int)(null);
  TestValidator.equals("value_double")(metric2.value_double)(metricCreateInput2.value_double);
  TestValidator.equals("notes")(metric2.notes)(metricCreateInput2.notes);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPageIPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardBoard";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test the admin board search API for advanced filtering, pagination, and permission enforcement.
 *
 * This function simulates a full workflow for an admin searching boards, using all supported filters and pagination mechanisms, with checks for correct record retrieval, schema, and authorization.
 * It also verifies correct enforcement of admin-only protection, and covers many edge cases including no-result circumstances and invalid filters.
 *
 * Steps:
 * 1. Register an admin account and log in to get auth credentials (token set via SDK `connection` headers).
 * 2. Create two board categories (catA, catB) via admin API.
 * 3. Create four boards: two in catA, two in catB, with deliberately different codes/names/public/archive/displayOrder values to test filter/sorting behaviors.
 * 4. For each supported filter (category, code, name, is_public, is_archived, display_order):
 *    - Call the search API with only that filter and validate only expected boards are returned.
 * 5. Test with multiple filters combined (e.g., catA + is_public=false).
 * 6. Use pagination (limit, page) to verify correct record slicing (page 1, 2, etc.).
 * 7. Try invalid category UUID and confirm empty result (no crash).
 * 8. Try code/name partial match and confirm correct records.
 * 9. Try invalid pagination values (page=0, limit=0, limit>100) and check for proper failure or validation error.
 * 10. As a negative case, clear admin tokens from the connection and attempt board search; assert that unauthorized error or access denied occurs.
 * 11. For every search result, typia.assert() each record and check key fields (category linkage, schema, etc).
 */
export async function test_api_board_search_with_filters_and_pagination(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(10);
  await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword },
  });
  // 2. Login admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword },
  });

  // 3. Create categories
  const catA = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      display_order: 1,
      description: "Category A",
    },
  });
  const catB = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      display_order: 2,
      description: "Category B",
    },
  });

  // 4. Create boards in different categories & with varied properties
  const boards: IPolEcoBoardBoard[] = [];
  boards.push(await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: catA.id,
      name: "Board 1A",
      code: "board1a_code",
      description: null,
      is_public: true,
      is_archived: false,
      display_order: 3,
    },
  }));
  boards.push(await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: catA.id,
      name: "Board 2A",
      code: "board2a_unique",
      description: "desc2A",
      is_public: false,
      is_archived: true,
      display_order: 4,
    },
  }));
  boards.push(await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: catB.id,
      name: "Board 1B",
      code: "board1b_code",
      description: null,
      is_public: false,
      is_archived: false,
      display_order: 5,
    },
  }));
  boards.push(await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: catB.id,
      name: "Board 2B",
      code: "board2b_search",
      description: "desc2B",
      is_public: true,
      is_archived: true,
      display_order: 6,
    },
  }));

  // 5. Filtering and paging checks

  // By category id
  let result = await api.functional.polEcoBoard.admin.boards.search(connection, {
    body: { pol_eco_board_category_id: catA.id },
  });
  typia.assert(result);
  TestValidator.equals("catA boards count")(result.data.length)(2);
  for (const b of result.data) TestValidator.equals("cat id")(b.pol_eco_board_category_id)(catA.id);

  // By code (exact match)
  result = await api.functional.polEcoBoard.admin.boards.search(connection, {
    body: { code: "board2b_search" },
  });
  typia.assert(result);
  TestValidator.equals("code boards")(result.data.length)(1);
  TestValidator.equals("code check")(result.data[0].code)("board2b_search");

  // By name (partial/substring)
  result = await api.functional.polEcoBoard.admin.boards.search(connection, {
    body: { name: "Board 1" },
  });
  typia.assert(result);
  TestValidator.equals("by name includes")(result.data.length)(2);
  for (const b of result.data) TestValidator.predicate("name includes 'Board 1'")(b.name.includes("Board 1"));

  // is_public filter
  result = await api.functional.polEcoBoard.admin.boards.search(connection, {
    body: { is_public: false },
  });
  typia.assert(result);
  for (const b of result.data) TestValidator.equals("is_public false")(b.is_public)(false);

  // is_archived filter
  result = await api.functional.polEcoBoard.admin.boards.search(connection, {
    body: { is_archived: true },
  });
  typia.assert(result);
  for (const b of result.data) TestValidator.equals("is_archived true")(b.is_archived)(true);

  // display_order filter
  result = await api.functional.polEcoBoard.admin.boards.search(connection, {
    body: { display_order: 6 },
  });
  typia.assert(result);
  TestValidator.equals("display_order count")(result.data.length)(1);
  TestValidator.equals("display_order value")(result.data[0].display_order)(6);

  // Combined filters
  result = await api.functional.polEcoBoard.admin.boards.search(connection, {
    body: {
      pol_eco_board_category_id: catA.id,
      is_public: true,
    },
  });
  typia.assert(result);
  TestValidator.equals("catA + is_public true count")(result.data.length)(1);
  TestValidator.equals("combined filter match")(result.data[0].name)("Board 1A");

  // Pagination (limit 2, page 2)
  result = await api.functional.polEcoBoard.admin.boards.search(connection, {
    body: { limit: 2, page: 2 },
  });
  typia.assert(result);
  TestValidator.equals("page limit")(result.pagination.limit)(2);
  TestValidator.equals("pagination current")(result.pagination.current)(2);
  // total records, pages should reflect count
  TestValidator.equals("pagination total")(result.pagination.records)(4);
  TestValidator.equals("pagination pages")(result.pagination.pages)(2);

  // Invalid category (should return 0 results, not an error)
  result = await api.functional.polEcoBoard.admin.boards.search(connection, {
    body: { pol_eco_board_category_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(result);
  TestValidator.equals("invalid category = 0")(result.data.length)(0);

  // Invalid pagination values (page=0: probably validation error)
  await TestValidator.error("page=0 throws")(() => api.functional.polEcoBoard.admin.boards.search(connection, {
    body: { page: 0 },
  }));
  // limit=0
  await TestValidator.error("limit=0 throws")(() => api.functional.polEcoBoard.admin.boards.search(connection, {
    body: { limit: 0 },
  }));
  // limit>100
  await TestValidator.error("limit>100 throws")(() => api.functional.polEcoBoard.admin.boards.search(connection, {
    body: { limit: 101 },
  }));

  // 6. Permission enforcement: access denied if not an admin
  // simulate by removing Authorization from connection headers
  const noAuthConn: api.IConnection = { ...connection, headers: { ...connection.headers, Authorization: "" } };
  await TestValidator.error("no-auth fails")(() => api.functional.polEcoBoard.admin.boards.search(noAuthConn, {
    body: {},
  }));

  // Schema validation for search results
  result = await api.functional.polEcoBoard.admin.boards.search(connection, {
    body: {},
  });
  typia.assert(result);
  for (const b of result.data) {
    TestValidator.predicate("id is uuid")(typeof b.id === "string" && b.id.length > 0);
    TestValidator.predicate("cat id is uuid")(typeof b.pol_eco_board_category_id === "string");
    TestValidator.predicate("display_order is int")(typeof b.display_order === "number");
    // Check all board data can be matched to real categories
    TestValidator.predicate("category exists")([catA.id, catB.id].includes(b.pol_eco_board_category_id));
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validates the retrieval of a discussion board's full details by boardId for admin users.
 *
 * This test ensures:
 * 1. Category and board can be created through the admin workflow.
 * 2. Authenticated admin can retrieve board by its id and receives all required business fields.
 * 3. Retrieving with a non-existent boardId yields not-found error.
 * 4. Retrieving with an invalid UUID returns a validation error.
 * 5. Attempting access as non-admin yields a forbidden error.
 */
export async function test_api_board_detail_retrieval_by_id(connection: api.IConnection) {
  // Step 1: Register a new admin and login to obtain valid admin session.
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestAdmin1!";
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // Step 2: Create a new category to associate with the board.
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: `Economics ${typia.random<number & tags.Type<"int32">>()}`,
      description: "Discussion about Economics",
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);

  // Step 3: Create a new board under this category.
  const boardCreateData: IPolEcoBoardBoard.ICreate = {
    pol_eco_board_category_id: category.id,
    name: `Global Finance Board ${typia.random<number & tags.Type<"int32">>()}`,
    code: `finance_${typia.random<number & tags.Type<"int32">>()}`,
    description: "Discussions on international finance and policies.",
    is_public: true,
    is_archived: false,
    display_order: typia.random<number & tags.Type<"int32">>(),
  };
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: boardCreateData,
  });
  typia.assert(board);

  // Step 4: Retrieve the board details as admin by id.
  const fetched = await api.functional.polEcoBoard.admin.boards.at(connection, {
    boardId: board.id,
  });
  typia.assert(fetched);
  TestValidator.equals("id matches")(fetched.id)(board.id);
  TestValidator.equals("category link matches")(fetched.pol_eco_board_category_id)(category.id);
  TestValidator.equals("name matches")(fetched.name)(boardCreateData.name);
  TestValidator.equals("code matches")(fetched.code)(boardCreateData.code);
  TestValidator.equals("description matches")(fetched.description)(boardCreateData.description);
  TestValidator.equals("is_public matches")(fetched.is_public)(boardCreateData.is_public);
  TestValidator.equals("is_archived matches")(fetched.is_archived)(boardCreateData.is_archived);
  TestValidator.equals("display order")(fetched.display_order)(boardCreateData.display_order);
  TestValidator.predicate("created_at is ISO string")(!!Date.parse(fetched.created_at));
  TestValidator.predicate("updated_at is ISO string")(!!Date.parse(fetched.updated_at));

  // Step 5: Negative - try non-existent boardId (valid UUID, not in DB)
  const nonExistBoardId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("not found for missing boardId")(() =>
    api.functional.polEcoBoard.admin.boards.at(connection, {
      boardId: nonExistBoardId,
    })
  );

  // Step 6: Negative - try with invalid UUID format
  TestValidator.error("validation error for bad UUID")(() =>
    api.functional.polEcoBoard.admin.boards.at(connection, {
      boardId: "bad-uuid-format" as any,
    })
  );

  // Step 7: Negative - try access as unauthenticated (non-admin)
  // Use the base connection object (without admin login) to simulate a non-admin user
  TestValidator.error("forbidden for non-admin")(() =>
    api.functional.polEcoBoard.admin.boards.at({ ...connection }, { boardId: board.id })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validates creation of polEcoBoard boards by an admin, covering success and failure cases.
 *
 * Business context: Only authenticated admins can create boards, which must belong to a valid category. Board creation is tightly controlled: name and code must be unique, fields must honor validation constraints, and only authorized users may perform this operation. This ensures correct community structure and platform governance.
 *
 * Steps:
 * 1. Register & log in an admin to get privileges
 * 2. Create a valid board category
 * 3. Create a board with all valid fields, verify output matches input/constraints
 * 4. Try to create a board with a non-existent categoryId (should error)
 * 5. Try to create a board with duplicate name or code (should error)
 * 6. Try to create a board with invalid required fields or field values (should error)
 * 7. Try creation as non-admin (should error)
 */
export async function test_api_board_creation_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Register & log in admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(14);
  const adminReg = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminReg);
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // 2. Create valid category
  const catInput: IPolEcoBoardCategory.ICreate = {
    name: RandomGenerator.alphabets(10),
    description: RandomGenerator.paragraph()(24),
    display_order: typia.random<number & tags.Type<"int32">>(),
  };
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, { body: catInput });
  typia.assert(category);

  // 3. Valid board creation
  const boardInput: IPolEcoBoardBoard.ICreate = {
    pol_eco_board_category_id: category.id,
    name: RandomGenerator.alphabets(14),
    code: RandomGenerator.alphaNumeric(10).toLowerCase(),
    description: RandomGenerator.paragraph()(80),
    is_public: true,
    is_archived: false,
    display_order: typia.random<number & tags.Type<"int32">>(),
  };
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, { body: boardInput });
  typia.assert(board);
  // Validate fields
  TestValidator.equals("categoryId")(board.pol_eco_board_category_id)(boardInput.pol_eco_board_category_id);
  TestValidator.equals("name")(board.name)(boardInput.name);
  TestValidator.equals("code")(board.code)(boardInput.code);
  TestValidator.equals("description")(board.description)(boardInput.description);
  TestValidator.equals("is_public")(board.is_public)(boardInput.is_public);
  TestValidator.equals("is_archived")(board.is_archived)(boardInput.is_archived);
  TestValidator.equals("display_order")(board.display_order)(boardInput.display_order);
  TestValidator.predicate("has id")(!!board.id && typeof board.id === "string" && board.id.length > 0);
  TestValidator.predicate("created_at is ISO")(!!board.created_at && typeof board.created_at === "string");
  TestValidator.predicate("updated_at is ISO")(!!board.updated_at && typeof board.updated_at === "string");

  // 4. Invalid categoryId
  const badCatBoardInput: IPolEcoBoardBoard.ICreate = {
    ...boardInput,
    pol_eco_board_category_id: typia.random<string & tags.Format<"uuid">>(),
  };
  await TestValidator.error("non-existent categoryId should fail")(async () => {
    await api.functional.polEcoBoard.admin.boards.create(connection, {
      body: badCatBoardInput,
    });
  });

  // 5. Duplicate name/code (must both violate uniqueness constraint)
  // Duplicate name
  const dupNameInput: IPolEcoBoardBoard.ICreate = {
    ...boardInput,
    code: RandomGenerator.alphaNumeric(10).toLowerCase(),
  };
  await TestValidator.error("duplicate name should fail")(async () => {
    await api.functional.polEcoBoard.admin.boards.create(connection, { body: dupNameInput });
  });
  // Duplicate code
  const dupCodeInput: IPolEcoBoardBoard.ICreate = {
    ...boardInput,
    name: RandomGenerator.alphabets(14),
  };
  await TestValidator.error("duplicate code should fail")(async () => {
    await api.functional.polEcoBoard.admin.boards.create(connection, { body: dupCodeInput });
  });

  // 6. Field-level input errors
  // Name too short
  const tooShortName: IPolEcoBoardBoard.ICreate = {
    ...boardInput,
    name: "A",
    code: RandomGenerator.alphaNumeric(10).toLowerCase(),
  };
  await TestValidator.error("name too short")(async () => {
    await api.functional.polEcoBoard.admin.boards.create(connection, { body: tooShortName });
  });
  // Code invalid format (uppercase)
  const invalidCode: IPolEcoBoardBoard.ICreate = {
    ...boardInput,
    code: RandomGenerator.alphabets(10).toUpperCase(),
    name: RandomGenerator.alphabets(14),
  };
  await TestValidator.error("invalid code format")(async () => {
    await api.functional.polEcoBoard.admin.boards.create(connection, { body: invalidCode });
  });
  // Missing description (allowed: optional)
  const noDesc: IPolEcoBoardBoard.ICreate = {
    ...boardInput,
    description: undefined,
  };
  const noDescRes = await api.functional.polEcoBoard.admin.boards.create(connection, { body: noDesc });
  typia.assert(noDescRes);

  // 7. Non-admin (simulate by clearing headers)
  const anonConn = { ...connection, headers: {} };
  await TestValidator.error("non-admin create forbidden")(async () => {
    await api.functional.polEcoBoard.admin.boards.create(anonConn, { body: boardInput });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E test for updating a discussion board (admin privilege required)
 *
 * This test function validates the update operation on a discussion board, focusing on:
 * - Admin registration and login for authorization
 * - Category and board creation for prerequisites
 * - Updating the board with valid data (success)
 * - Uniqueness and reference constraint violations (failures)
 * - Permission enforcement and not-found logic
 *
 * Steps:
 * 1. Register and sign in as admin
 * 2. Create two categories
 * 3. Create a board in the first category
 * 4. Update the board with valid data: switch to 2nd category, change name/code, etc.
 * 5. Confirm response updates
 * 6. Attempt to update with duplicate name/code (should fail)
 * 7. Attempt to update with invalid category id (should fail)
 * 8. Attempt to update with missing required fields (should fail)
 * 9. Attempt to update with a non-existent boardId (should fail/not found)
 * 10. Attempt to update as non-admin (should fail/permission error)
 */
export async function test_api_board_update_success_and_failure_cases(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create two categories
  const category1 = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(10),
      description: "Category for success update",
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category1);

  const category2 = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(10),
      description: "Category for switch during update",
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category2);

  // 4. Create a board in category1
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category1.id,
      name: RandomGenerator.alphaNumeric(8),
      code: RandomGenerator.alphaNumeric(8).toLowerCase(),
      description: "Test board for update e2e",
      is_public: true,
      is_archived: false,
      display_order: 1,
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 5. Update the board with new info (SUCCESS)
  const updatedName = board.name + "-updated";
  const updatedCode = board.code + "_u";
  const updateRes = await api.functional.polEcoBoard.admin.boards.update(connection, {
    boardId: board.id,
    body: {
      pol_eco_board_category_id: category2.id,
      name: updatedName,
      code: updatedCode,
      description: "Updated description",
      is_public: false,
      is_archived: true,
      display_order: 2,
    } satisfies IPolEcoBoardBoard.IUpdate,
  });
  typia.assert(updateRes);
  TestValidator.equals("update pol_eco_board_category_id")(updateRes.pol_eco_board_category_id)(category2.id);
  TestValidator.equals("update name")(updateRes.name)(updatedName);
  TestValidator.equals("update code")(updateRes.code)(updatedCode);
  TestValidator.equals("update description")(updateRes.description)("Updated description");
  TestValidator.equals("is_public")(updateRes.is_public)(false);
  TestValidator.equals("is_archived")(updateRes.is_archived)(true);
  TestValidator.equals("display_order")(updateRes.display_order)(2);

  // 6. Attempt to update board using a duplicate name and duplicate code (should FAIL on uniqueness)
  const secondBoard = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category2.id,
      name: RandomGenerator.alphaNumeric(7) + "_b2",
      code: RandomGenerator.alphaNumeric(8).toLowerCase() + "_b2",
      description: "Second board for duplication",
      is_public: true,
      is_archived: false,
      display_order: 3,
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(secondBoard);

  // Try duplicate name:
  await TestValidator.error("duplicate board name should fail")(async () => {
    await api.functional.polEcoBoard.admin.boards.update(connection, {
      boardId: secondBoard.id,
      body: {
        name: updatedName, // Same as board1's new name
      } satisfies IPolEcoBoardBoard.IUpdate,
    });
  });
  // Try duplicate code:
  await TestValidator.error("duplicate board code should fail")(async () => {
    await api.functional.polEcoBoard.admin.boards.update(connection, {
      boardId: secondBoard.id,
      body: {
        code: updatedCode, // Same as board1's new code
      } satisfies IPolEcoBoardBoard.IUpdate,
    });
  });

  // 7. Attempt to update with invalid categoryId (referential integrity)
  const invalidCatId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("invalid category id for update should fail")(async () => {
    await api.functional.polEcoBoard.admin.boards.update(connection, {
      boardId: board.id,
      body: {
        pol_eco_board_category_id: invalidCatId,
      } satisfies IPolEcoBoardBoard.IUpdate,
    });
  });

  // 8. Attempt update with missing required fields (should fail)
  // Since all IUpdate fields are optional, simulate no-op or illogical update
  await TestValidator.error("empty update should fail")(async () => {
    await api.functional.polEcoBoard.admin.boards.update(connection, {
      boardId: board.id,
      body: {}, // No fields set
    });
  });

  // 9. Attempt to update a non-existent boardId
  const fakeBoardId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("updating non-existent board should fail")(async () => {
    await api.functional.polEcoBoard.admin.boards.update(connection, {
      boardId: fakeBoardId,
      body: {
        name: "should-not-work",
      } satisfies IPolEcoBoardBoard.IUpdate,
    });
  });

  // 10. Attempt update as a non-admin (should fail on permission)
  // Simulate by creating new random connection without admin tokens
  // If possible, clear the Authorization header
  const connection2: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error("non-admin update should fail")(async () => {
    await api.functional.polEcoBoard.admin.boards.update(connection2, {
      boardId: board.id,
      body: {
        description: "illegal update by non-admin"
      } satisfies IPolEcoBoardBoard.IUpdate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardBoard";
