import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test the soft delete (archive) of a board and edge cases as an admin.
 *
 * This test ensures that when an admin soft deletes a board:
 *   - The 'deleted_at' field of the board is set, and the board is excluded from active listings, but retained for audit/restoration.
 *   - Attempting to delete a non-existing board or already deleted board returns appropriate errors.
 *   - Attempts to delete with insufficient permissions fail (non-admin/unauthed test is included).
 *   - If board cannot be deleted due to business constraints (e.g. referenced in a mandatory workflow), deletion is blocked.
 *   - All actions are fully audited by API contract.
 *
 * Test Steps:
 * 1. Register a new admin and login to obtain an authenticated session.
 * 2. Create a new board category (required for board creation).
 * 3. Create a new board within that category.
 * 4. Soft delete the created board and verify operation succeeded (repeat GET is not available so rely on success and DTO).
 * 5. Attempt to soft delete again (should error: already deleted/non-existent).
 * 6. Attempt to delete a random, likely non-existent board id (should error: not found).
 * 7. [Edge] Attempt the same delete as an unauthenticated/non-admin user (expect error/forbidden).
 * 8. [Business] If supported by the API, attempt to delete a board that is referenced in a mandatory workflow (should fail due to constraint; not implemented if workflow/references are not modeled in fixtures).
 */
export async function test_api_board_soft_delete_and_edge_cases(connection: api.IConnection) {
  // 1. Register and login admin
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const password = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  const loginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password } satisfies IPolEcoBoardAdminAuth.SignIn
  });
  typia.assert(loginResp);

  // 2. Create category
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.paragraph()(2),
      description: RandomGenerator.paragraph()(),
      display_order: typia.random<number & tags.Type<'int32'>>()
    } satisfies IPolEcoBoardCategory.ICreate
  });
  typia.assert(category);

  // 3. Create board
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.paragraph()(2),
      code: RandomGenerator.alphaNumeric(10).toLowerCase(),
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<'int32'>>()
    } satisfies IPolEcoBoardBoard.ICreate
  });
  typia.assert(board);

  // 4. Soft delete
  await api.functional.polEcoBoard.admin.boards.erase(connection, {
    boardId: board.id
  });

  // 5. Attempt soft delete again (should error)
  await TestValidator.error('Deleting already-deleted board should fail')(async () => {
    await api.functional.polEcoBoard.admin.boards.erase(connection, {
      boardId: board.id
    });
  });

  // 6. Attempt delete with random id (should error)
  await TestValidator.error('Deleting non-existent board should fail')(async () => {
    await api.functional.polEcoBoard.admin.boards.erase(connection, {
      boardId: typia.random<string & tags.Format<'uuid'>>()
    });
  });

  // 7. Attempt delete as unauthenticated user (should error)
  const { Authorization, ...restHeaders } = connection.headers ?? {};
  const unauthConnection = { ...connection, headers: restHeaders };
  await TestValidator.error('Deleting as unauthenticated should fail')(async () => {
    await api.functional.polEcoBoard.admin.boards.erase(unauthConnection, {
      boardId: board.id
    });
  });

  // 8. [Business] Cannot implement mandatory workflow reference constraint without further API
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotification";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test viewing a notification as a moderator and validate success, not-found, and forbidden flows.
 *
 * This test verifies that:
 * - A moderator can view their own notification assigned by an admin and all metadata matches
 * - Unauthorized access by non-owners or with invalid IDs is correctly handled (not-found, forbidden)
 * - Appropriate role-based authentication is set before each API call
 * - System privacy boundaries are respected and no sensitive information leaks occur
 *
 * Test Steps:
 * 1. Register a new moderator and assert their registration fields
 * 2. Log in as that moderator, storing JWT for subsequent requests
 * 3. Register and log in as new admin, storing JWT for admin-privileged notification creation
 * 4. Create a notification targeting the moderator using the admin API and assert returned data
 * 5. Switch back to moderator session and successfully fetch the notification, validating all fields
 * 6. Attempt to fetch a notification with a random (nonexistent) UUID, expect not-found error
 * 7. Register/log in a different moderator and, as that user, attempt to fetch the notification belonging to the first moderator, expecting forbidden error
 */
export async function test_api_moderator_notification_access_success_and_failure(connection: api.IConnection) {
  // 1. Register a new moderator
  const moderatorEmail = typia.random<string & tags.Format<'email'>>();
  const moderatorPassword = 'moder@Pass123';
  const moderatorDisplayName = RandomGenerator.name();
  const consentStatus = '2025-privacy-v1';

  const moderatorReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: consentStatus,
    },
  });
  typia.assert(moderatorReg);
  TestValidator.equals('moderator email')(moderatorReg.email)(moderatorEmail);

  // 2. Moderator log in, get JWT for session
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  typia.assert(moderatorLogin);
  TestValidator.equals('moderator login email')(moderatorLogin.email)(moderatorEmail);
  // Store JWT for this moderator session
  const moderatorHeaders = {
    ...connection.headers,
    Authorization: moderatorLogin.setHeaders.Authorization,
  };

  // 3. Register and log in as admin for notification creation
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = 'admin@PolEco123';
  await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPassword },
  });
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword },
  });
  const adminHeaders = {
    ...connection.headers,
    Authorization: adminLogin.setHeaders.Authorization,
  };

  // 4. Create notification for the moderator
  const notificationInput = {
    recipient_member_id: moderatorReg.moderatorId,
    event_type: 'moderation_action',
    status: 'pending',
  } satisfies IPolEcoBoardNotification.ICreate;
  const notification = await api.functional.polEcoBoard.admin.notifications.create(
    { ...connection, headers: adminHeaders },
    { body: notificationInput },
  );
  typia.assert(notification);
  TestValidator.equals('recipient_member_id')(notification.recipient_member_id)(moderatorReg.moderatorId);
  TestValidator.equals('event_type')(notification.event_type)('moderation_action');
  TestValidator.equals('status')(notification.status)('pending');

  // 5. Fetch the notification via the moderator session
  const fetched = await api.functional.polEcoBoard.moderator.notifications.at(
    { ...connection, headers: moderatorHeaders },
    { notificationId: notification.id },
  );
  typia.assert(fetched);
  TestValidator.equals('notification id')(fetched.id)(notification.id);
  TestValidator.equals('recipient_member_id')(fetched.recipient_member_id)(moderatorReg.moderatorId);

  // 6. Try to fetch a missing notification (random uuid)
  const randomMissingId = typia.random<string & tags.Format<'uuid'>>();
  TestValidator.error('fetching non-existent notification')(() =>
    api.functional.polEcoBoard.moderator.notifications.at(
      { ...connection, headers: moderatorHeaders },
      { notificationId: randomMissingId },
    ),
  );

  // 7. Register and log in as another moderator, attempt to access the notification of the first moderator (forbidden)
  const otherModEmail = typia.random<string & tags.Format<'email'>>();
  const otherModPassword = 'otherModPass1';
  const otherModDisplayName = RandomGenerator.name();
  await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: otherModEmail,
      password: otherModPassword,
      display_name: otherModDisplayName,
      consent_status: consentStatus,
    },
  });
  const otherModLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: { email: otherModEmail, password: otherModPassword },
  });
  const otherModHeaders = {
    ...connection.headers,
    Authorization: otherModLogin.setHeaders.Authorization,
  };
  TestValidator.error('forbidden: notification is not owned by other moderator')(() =>
    api.functional.polEcoBoard.moderator.notifications.at(
      { ...connection, headers: otherModHeaders },
      { notificationId: notification.id },
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotification";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate comprehensive admin notification access and permission boundaries.
 *
 * This scenario verifies that an admin can retrieve individual notification events by their UUID, with all business and delivery metadata, and receives correct error responses in boundary or unauthorized cases.
 *
 * Step-by-step process:
 * 1. Register a new admin with random unique email and valid password
 * 2. Log in as this admin to obtain session credentials
 * 3. Create several notification events as the admin using randomized values:
 *    - Use unique member UUIDs as recipients
 *    - Randomize event types and status fields
 * 4. Retrieve each created notification by its ID via the admin get-by-id endpoint:
 *    - Verify that all mandatory and expected fields (id, recipient_member_id, status, event_type, timestamps, etc.) are present and correct
 *    - Confirm returned record matches the created data (for at least one notification)
 * 5. Test error path for invalid notification ID:
 *    - Attempt to fetch a notification with a random (nonexistent) UUID
 *    - Assert that an error is thrown (not found/unauthorized)
 * * (Cannot test cross-admin boundary error since notifications are not scoped to admin but to recipient_member_id, but can ensure only existing records are fetched)
 */
export async function test_api_admin_notification_access_comprehensive(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Login as admin
  const signInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResp);

  // 3. Create several notifications
  const notificationInputs: IPolEcoBoardNotification.ICreate[] = ArrayUtil.repeat(3)(() => {
    return {
      recipient_member_id: typia.random<string & tags.Format<"uuid">>(),
      event_type: RandomGenerator.pick([
        "reply",
        "moderation_action",
        "report",
        "announcement",
        "test_event_type"
      ]),
      status: RandomGenerator.pick(["pending", "delivered", "failed"]),
      attempt_count: typia.random<number & tags.Type<"int32">>(),
      provider_id: Math.random() < 0.5 ? typia.random<string & tags.Format<"uuid">>() : null,
      related_object_id: Math.random() < 0.5 ? typia.random<string & tags.Format<"uuid">>() : null,
    } satisfies IPolEcoBoardNotification.ICreate;
  });

  const notifications: IPolEcoBoardNotification[] = [];
  for (const input of notificationInputs) {
    const notif = await api.functional.polEcoBoard.admin.notifications.create(connection, { body: input });
    typia.assert(notif);
    notifications.push(notif);
  }

  // 4. Retrieve each notification by ID, checking returned metadata
  for (const notif of notifications) {
    const fetched = await api.functional.polEcoBoard.admin.notifications.at(connection, { notificationId: notif.id });
    typia.assert(fetched);
    // Confirm must-have fields match
    TestValidator.equals("notification id")(fetched.id)(notif.id);
    TestValidator.equals("recipient_member_id")(fetched.recipient_member_id)(notif.recipient_member_id);
    TestValidator.equals("event_type")(fetched.event_type)(notif.event_type);
    TestValidator.equals("status")(fetched.status)(notif.status);
    // Check existence of optional fields (no value comparison; just that they exist as allowed by schema)
    TestValidator.predicate("created_at is present")(typeof fetched.created_at === "string");
    TestValidator.predicate("updated_at is present")(typeof fetched.updated_at === "string");
  }

  // (Edge case) - for at least the first notification, check the whole object matches (except for generated timestamps)
  const origin = notifications[0];
  const fetchedOrigin = await api.functional.polEcoBoard.admin.notifications.at(connection, { notificationId: origin.id });
