  TestValidator.equals("event_type matches")(notification.event_type)(validEventType);
  TestValidator.equals("status matches")(notification.status)(validStatus);
  TestValidator.predicate("id assigned, UUID")(typeof notification.id === "string" && notification.id.length > 0);

  // 4. Missing required: recipient_member_id
  await TestValidator.error("missing recipient_member_id should fail")(async () => {
    return api.functional.polEcoBoard.admin.notifications.create(connection, {
      body: {
        event_type: validEventType,
        status: validStatus,
      } as any,
    });
