import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotification";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E test for updating a notification as a member, validating proper authorization and input validation.
 *
 * This test verifies that a regular member can update their own notification's mutable fields, and that proper permission and input validation is enforced for edge cases and business rules.
 *
 * Steps:
 * 1. Register a new member account for the notification recipient.
 * 2. Log in as the member to obtain a session (JWT authorization header).
 * 3. Register a new admin account and log in as admin for notification creation privilege.
 * 4. As admin, create a notification for the member (to be updated in the test).
 * 5. As the member, update mutable fields of the notification (status, attempt_count, delivered_at, etc.) and verify the update succeeds, response structure is correct, and audit trail (timestamps/fields) are updated.
 * 6. Attempt to update a notification not belonging to the member and verify permission is denied.
 * 7. Attempt to update with an unsupported status and verify input validation fails.
 */
export async function test_api_member_notification_update_authorization_and_validation(
  connection: api.IConnection,
) {
  // 1. Register a new member (recipient)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "StrongPW!" + typia.random<string & tags.MinLength<2>>();
  const memberSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberSignUp);

  // 2. Log in as member to obtain Authorization header
  const memberLogIn = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberLogIn);

  // 3. Register and log in as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "VeryStrongPW!" + typia.random<string & tags.MinLength<4>>();
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  const adminLogIn = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLogIn);

  // 4. As admin, create notification for member
  // recipient_member_id is not available from memberSignUp response, so create a UUID for target
  const recipientMemberId = typia.random<string & tags.Format<"uuid">>();
  const notification = await api.functional.polEcoBoard.admin.notifications.create(connection, {
    body: {
      recipient_member_id: recipientMemberId,
      event_type: "reply",
      status: "pending",
      attempt_count: 0,
    } satisfies IPolEcoBoardNotification.ICreate,
  });
  typia.assert(notification);

  // 5. Switch context to member (simulate by setting Authorization header)
  connection.headers = {
    ...connection.headers,
    Authorization: memberLogIn.setHeaders.Authorization,
  };

  // Prepare an update payload for mutable fields
  const updateBody: IPolEcoBoardNotification.IUpdate = {
    status: "delivered",
    attempt_count: 1,
    delivered_at: new Date().toISOString(),
    last_attempted_at: new Date().toISOString(),
  };

  // 6. Update the notification as the member (should succeed)
  const updatedNotification = await api.functional.polEcoBoard.member.notifications.update(connection, {
    notificationId: notification.id,
    body: updateBody,
  });
  typia.assert(updatedNotification);
  TestValidator.equals("status updated")(updatedNotification.status)(updateBody.status);
  TestValidator.equals("attempt_count updated")(updatedNotification.attempt_count)(updateBody.attempt_count);

  // 7. Attempt to update a notification not belonging to the member (should fail)
  const otherNotification = await api.functional.polEcoBoard.admin.notifications.create(connection, {
    body: {
      recipient_member_id: typia.random<string & tags.Format<"uuid">>(),
      event_type: "reply",
      status: "pending",
      attempt_count: 0,
    } satisfies IPolEcoBoardNotification.ICreate,
  });
  typia.assert(otherNotification);
  TestValidator.error("cannot update notification not belonging to member")(
    async () => {
      await api.functional.polEcoBoard.member.notifications.update(connection, {
        notificationId: otherNotification.id,
        body: { status: "delivered" },
      });
    },
  );

  // 8. Attempt to update with unsupported status (should fail)
  TestValidator.error("invalid status enumeration fails")(
    async () => {
      await api.functional.polEcoBoard.member.notifications.update(connection, {
        notificationId: notification.id,
        body: { status: "INVALID_STATUS" },
      });
    },
  );

  // 9. Skipped: event_type is not allowed to be updated via IUpdate (not present in DTO), so not tested for type safety.
}

