 *
 * This test covers the following flows and edge cases:
 *
 * 1. Register and login as a moderator (to obtain JWT for protected endpoint).
 * 2. Register and login as an admin.
 * 3. Admin creates a notification targeted at the registered moderator (using moderator's ID as recipient).
 * 4. As the moderator, update fields allowed by IPolEcoBoardNotification.IUpdate on their own notification (status, attempt_count, timestamps, provider_id).
 * 5. Verify that all allowed changes persist (fields are updated, status changes are reflected, and modified state is visible in response).
 * 6. Attempt as this moderator to update a notification that belongs to a different user—should reject (authorization failure).
 * 7. Attempt to update their own notification with an invalid status code (business logic error), expect error.
 * 8. For each update, check that 'updated_at' changes after modification for audit traceability.
 *
 * Coverage:
 * - Field change: status, attempt_count, timestamps (allowed fields)
 * - Unauthorized update: other user's notification
 * - Invalid status update (application error)
 */
export async function test_api_moderator_notification_update_success_and_failure(
  connection: api.IConnection,
) {
  // 1. Register moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "M0d3rat0rP@ss1";
  const moderatorDisplayName = RandomGenerator.name();
  const moderatorConsentStatus = "2025-v1-privacy";

  const moderatorReg = await api.functional.auth.moderator.register.signUp(
    connection,
    {
      body: {
        email: moderatorEmail,
        password: moderatorPassword,
        display_name: moderatorDisplayName,
        consent_status: moderatorConsentStatus,
      },
    },
  );
  typia.assert(moderatorReg);
  const moderatorId = moderatorReg.moderatorId;

  // 2. Login as moderator (initial authentication, token will be updated when switching roles)
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });

  // 3. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Adm1nP@ssw0rd1";
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  // 4. Admin login
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 5. Admin creates a notification assigned to the moderator
  const notificationCreate = await api.functional.polEcoBoard.admin.notifications.create(connection, {
    body: {
      recipient_member_id: moderatorId,
      event_type: "moderation_action",
      status: "pending",
      provider_id: null,
      related_object_id: null,
      attempt_count: 0,
    },
  });
  typia.assert(notificationCreate);
  TestValidator.equals("created notification recipient")(
    notificationCreate.recipient_member_id,
  )(moderatorId);
  const notificationId = notificationCreate.id;

  // 6. Switch to moderator account for update test
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });

  // 7. Update allowed fields as moderator
  const updateBody = {
    status: "delivered",
    attempt_count: 1,
    last_attempted_at: new Date().toISOString(),
    delivered_at: new Date().toISOString(),
    provider_id:
      notificationCreate.provider_id ||
      typia.random<string & tags.Format<"uuid">>(),
  } satisfies IPolEcoBoardNotification.IUpdate;
  const updated = await api.functional.polEcoBoard.moderator.notifications.update(
    connection,
    {
      notificationId,
      body: updateBody,
    },
  );
  typia.assert(updated);
  // 8. Validate allowed field changes persist
  TestValidator.equals("updated status")(updated.status)(updateBody.status);
  TestValidator.equals("updated attempt_count")(updated.attempt_count)(
    updateBody.attempt_count,
  );
  TestValidator.equals("updated last_attempted_at")(updated.last_attempted_at)(
    updateBody.last_attempted_at,
  );
  TestValidator.equals("updated delivered_at")(updated.delivered_at)(
    updateBody.delivered_at,
  );
  TestValidator.equals("updated provider_id")(updated.provider_id)(
    updateBody.provider_id,
  );
  TestValidator.predicate("updated_at changed")(
    new Date(updated.updated_at).getTime() >
      new Date(notificationCreate.updated_at).getTime(),
  );

  // 9. Attempt to update someone else's notification (should fail)
  // Admin login again
  await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword },
  });
  const foreignMemberId = typia.random<string & tags.Format<"uuid">>();
  const foreignNotification =
    await api.functional.polEcoBoard.admin.notifications.create(connection, {
      body: {
        recipient_member_id: foreignMemberId,
        event_type: "moderation_action",
        status: "pending",
        provider_id: null,
        related_object_id: null,
        attempt_count: 0,
      },
    });
  typia.assert(foreignNotification);

  // Switch back to moderator
  await api.functional.auth.moderator.login.signIn(connection, {
    body: { email: moderatorEmail, password: moderatorPassword },
  });
  await TestValidator.error(
    "cannot update notification belonging to other member",
  )(async () => {
    await api.functional.polEcoBoard.moderator.notifications.update(
      connection,
      {
        notificationId: foreignNotification.id,
        body: { status: "delivered" },
      },
    );
  });

  // 10. Attempt to update own notification with invalid status (should error)
  await TestValidator.error("cannot update with invalid status")(async () => {
    await api.functional.polEcoBoard.moderator.notifications.update(
      connection,
      {
        notificationId,
        body: { status: "not_a_valid_status" },
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardAccountAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAccountAudit";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that an admin can update allowed metadata fields (such as context or compliance note)
 * of an existing account audit record as required by compliance procedures.
 *
 * Business Context:
 *  - PolEcoBoard administrators are required to create comprehensive audit records for sensitive account actions (creation, updates, privilege escalation, banning, etc.).
 *  - There are regulatory and compliance needs to allow post-hoc updates of certain mutable fields (e.g., supplemental action_metadata or corrected status) by privileged admin users only.
 *  - Audit objects have immutable and mutable fields, and all modifications are required to be logged and returned in the object.
 *
 * Test Steps:
 * 1. Register a new admin using a business-valid email and a strong password
 * 2. Login as that admin to obtain an authenticated session (tokens are injected into the connection)
 * 3. Create a new audit record for a target account action – populating actor/target, action_type, metadata, etc.
 * 4. Use that audit record's id to update metadata and status fields with new values
 * 5. Validate that the response reflects the changed data, but other fields remain unchanged
 */
export async function test_api_account_audit_update_success_admin_auth(
  connection: api.IConnection,
) {
  // 1. Register a new admin with unique email/password
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12); // 12+ char, strong
  const signUpRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email,
      password,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpRes);

  // 2. Login as the new admin to get tokens for privileged calls (not strictly necessary if signup issues tokens, but for safety & replayability)
  const signInRes = await api.functional.auth.admin.login.signIn(connection, {
    body: { email, password } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInRes);

  // 3. Create a new account audit record as the admin
  const actor_id = typia.random<string & tags.Format<"uuid">>();
  const target_account_id = typia.random<string & tags.Format<"uuid">>();
  const initialAudit = await api.functional.polEcoBoard.admin.accountAudits.create(connection, {
    body: {
      action_type: "role_transition",
      actor_id,
      target_account_id,
      action_metadata: "Initial registration context for audit test.",
      event_source: "api-test-suite",
      status: "success",
      occurred_at: new Date().toISOString(),
    } satisfies IPolEcoBoardAccountAudit.ICreate,
  });
  typia.assert(initialAudit);

  // 4. Update metadata and status for the account audit record
  const updateBody = {
    action_metadata: "Added compliance review note.",
    status: "pending",
  } satisfies IPolEcoBoardAccountAudit.IUpdate;
  const updatedAudit = await api.functional.polEcoBoard.admin.accountAudits.update(connection, {
    accountAuditId: initialAudit.id,
    body: updateBody,
  });
  typia.assert(updatedAudit);

  // 5. Validate - fields have been updated as expected, other fields remain unchanged
  TestValidator.equals("action_metadata updated")(updatedAudit.action_metadata)(updateBody.action_metadata);
  TestValidator.equals("status updated")(updatedAudit.status)(updateBody.status);
  TestValidator.equals("immutable fields unchanged")(updatedAudit.id)(initialAudit.id);
  TestValidator.equals("action_type unchanged")(updatedAudit.action_type)(initialAudit.action_type);
  TestValidator.equals("actor_id unchanged")(updatedAudit.actor_id)(initialAudit.actor_id);
  TestValidator.equals("target_account_id unchanged")(updatedAudit.target_account_id)(initialAudit.target_account_id);
  TestValidator.equals("event_source unchanged")(updatedAudit.event_source)(initialAudit.event_source);
  TestValidator.equals("occurred_at unchanged")(updatedAudit.occurred_at)(initialAudit.occurred_at);
  TestValidator.equals("created_at unchanged")(updatedAudit.created_at)(initialAudit.created_at);
}

