/**
 * Validate that a moderator only sees board statuses for boards they are assigned to.
 *
 * This test establishes a minimal workflow for moderator-scoped access:
 * 1. Register a new moderator and log in to retrieve authentication/headers.
 * 2. Create a board category (admin capability).
 * 3. Create a board assigned to the new board category.
 * 4. Assign the registered moderator to that board.
 * 5. As the assigned moderator, create a board status event (e.g., lock, archive).
 * 6. Run the boardStatuses search patch as the moderator and verify:
 *    - Only statuses from boards where the moderator is assigned are shown.
 *    - Filtering by board id, moderator id, and status_type works as expected.
 *    - (Negative) Statuses from unassigned boards are not visible to this moderator.
 */
export async function test_api_moderator_board_statuses_search_with_assigned_boards_only(
  connection: api.IConnection,
) {
  // 1. Register moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "Mod!23_" + RandomGenerator.alphaNumeric(8);
  const moderatorDisplayName = RandomGenerator.name();
  const consent_status = "v1.2024-terms-consent";
  const regResp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status,
    },
  });
  typia.assert(regResp);
  TestValidator.equals("emailed moderator matches")(regResp.email)(moderatorEmail);
  connection.headers = { ...(connection.headers || {}), ...regResp.setHeaders };

  // 1b. Log in separately to confirm login flow works and tokens are refreshed
  const loginResp = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  typia.assert(loginResp);
  TestValidator.equals("login moderator id matches registered")(loginResp.moderatorId)(regResp.moderatorId);
  connection.headers = { ...(connection.headers || {}), ...loginResp.setHeaders };

  // 2. Create a board category (admin action)
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(12),
      description: "Test category for moderator/boardStatuses E2E",
      display_order: typia.random<number & tags.Type<"int32">>(),
    },
  });
  typia.assert(category);

  // 3. Create a board in the category (admin action)
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.alphabets(10),
      code: RandomGenerator.alphaNumeric(10).toLowerCase(),
      description: "Test board for assignment",
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    },
  });
  typia.assert(board);

  // 4. Assign moderator to board as admin
  const assignment = await api.functional.polEcoBoard.admin.moderatorBoardAssignments.create(connection, {
    body: {
      pol_eco_board_moderator_id: regResp.moderatorId,
      pol_eco_board_board_id: board.id,
      assigned_by_admin_id: null,
      assigned_at: new Date().toISOString(),
      ended_at: null,
      role_transfer_log: "E2E moderator assignment for privilege scope",
    },
  });
  typia.assert(assignment);
  TestValidator.equals("assign-to-board moderator matches")(assignment.pol_eco_board_moderator_id)(regResp.moderatorId);
  TestValidator.equals("assign-to-board matches")(assignment.pol_eco_board_board_id)(board.id);

  // 5. As moderator, create a board status (e.g., open)
  const boardStatus = await api.functional.polEcoBoard.moderator.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      actor_moderator_id: regResp.moderatorId,
      actor_admin_id: null,
      status_type: "open",
      effective_at: new Date().toISOString(),
      reason: "Initial board open for testing",
    },
  });
  typia.assert(boardStatus);
  TestValidator.equals("status board matches")(boardStatus.pol_eco_board_board_id)(board.id);
  TestValidator.equals("actor moderator matches")(boardStatus.actor_moderator_id)(regResp.moderatorId);
  TestValidator.equals("status_type is open")(boardStatus.status_type)("open");

  // 6. Search for boardStatuses as moderator for assigned board
  const searchResp = await api.functional.polEcoBoard.moderator.boardStatuses.search(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      actor_moderator_id: regResp.moderatorId,
      status_type: "open",
      effective_after: null,
      effective_before: null,
      page: 1,
      limit: 10,
      orderBy: "created_at",
      orderDirection: "desc",
    },
  });
  typia.assert(searchResp);
  TestValidator.predicate("search returns relevant records")(Array.isArray(searchResp.data) && searchResp.data.length >= 1);
  // Ensure all returned boardStatus summaries are for assigned board and moderator
  for (const summary of searchResp.data) {
    TestValidator.equals("status_type is open")(summary.status_type)("open");
    TestValidator.equals("search - board matches")(summary.pol_eco_board_board_id)(board.id);
  }
  TestValidator.equals("first search record matches created status by moderator")(searchResp.data[0].id)(boardStatus.id);

  // 7. (Negative case) Create another board, status, but DO NOT assign moderator to this new board
  const otherBoard = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.alphabets(8),
      code: RandomGenerator.alphaNumeric(9).toLowerCase(),
      description: "Board with no assignment",
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    },
  });
  typia.assert(otherBoard);
  const otherStatus = await api.functional.polEcoBoard.moderator.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: otherBoard.id,
      actor_moderator_id: regResp.moderatorId,
      actor_admin_id: null,
      status_type: "locked",
      effective_at: new Date().toISOString(),
      reason: "Other board, not assigned",
    },
  });
  typia.assert(otherStatus);
  // Now, search on otherBoard.id (should show at least the status if privilege not enforced, none if enforced)
  const negativeSearch = await api.functional.polEcoBoard.moderator.boardStatuses.search(connection, {
    body: {
      pol_eco_board_board_id: otherBoard.id,
      actor_moderator_id: regResp.moderatorId,
