import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * E2E test for member post creation in polEcoBoard.
 *
 * Validates:
 * 1. Successful creation of a post with all required valid fields (category, title, body)
 * 2. Failure when required fields are missing (title/content/category) - limited to runtime errors only
 * 3. Creation with boundary values (title/content at their minimum and maximum lengths)
 * 4. Failure when invalid/non-existent category is used
 *
 * Covers authentication, dependency category creation, and checks for business logic and validation errors.
 */
export async function test_api_member_post_creation_valid_and_invalid_data(connection: api.IConnection) {
  // 0. Register and log in as a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPw = typia.random<string & tags.Format<"password">>();
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPw,
    },
  });
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPw,
    },
  });

  // 1. Create a valid board category as admin (using current connection)
  const categoryName = "Category-" + RandomGenerator.alphaNumeric(8);
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: categoryName,
      description: "Test category for board post E2E",
      display_order: 1,
    },
  });
  typia.assert(category);

  // 2. --- Post creation: Success case ---
  const validTitle = RandomGenerator.alphabets(15); // Between 10 and 120 chars
  const validBody = RandomGenerator.alphabets(30); // Between 10 and 10,000 chars
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: validTitle,
      body: validBody,
    },
  });
  typia.assert(post);
  TestValidator.equals("category")(post.category_id)(category.id);
  TestValidator.equals("title")(post.title)(validTitle);
  TestValidator.equals("body")(post.body)(validBody);

  // 3. --- Post creation: Boundary field values ---
  // Title min (10 chars)
  const minTitle = RandomGenerator.alphabets(10);
  const postMinTitle = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: minTitle,
      body: validBody,
    },
  });
  typia.assert(postMinTitle);
  TestValidator.equals("title min")(postMinTitle.title)(minTitle);

  // Title max (120 chars)
  const maxTitle = RandomGenerator.alphabets(120);
  const postMaxTitle = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: maxTitle,
      body: validBody,
    },
  });
  typia.assert(postMaxTitle);
  TestValidator.equals("title max")(postMaxTitle.title)(maxTitle);

  // Body min (10 chars)
  const minBody = RandomGenerator.alphabets(10);
  const postMinBody = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: validTitle,
      body: minBody,
    },
  });
  typia.assert(postMinBody);
  TestValidator.equals("body min")(postMinBody.body)(minBody);

  // Body max (10,000 chars)
  const maxBody = RandomGenerator.alphabets(10000);
  const postMaxBody = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: validTitle,
      body: maxBody,
    },
  });
  typia.assert(postMaxBody);
  TestValidator.equals("body max")(postMaxBody.body)(maxBody);

  // 4. --- Post creation: Invalid/non-existent category ---
  const fakeCategoryId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("invalid category fails")(() =>
    api.functional.polEcoBoard.member.posts.create(connection, {
      body: {
        category_id: fakeCategoryId,
        title: validTitle,
        body: validBody,
      },
    })
  );
}

