import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validates post editing window enforcement for members on polEcoBoard.
 *
 * This test ensures that:
 * 1. A member can update their own post's title and content within the allowed edit window (the happy path)
 * 2. Editing the same post after the permitted window has expired is denied by the API
 *
 * Steps performed:
 * 1. Register a new member and obtain credentials
 * 2. Log in as that member to ensure authenticated context
 * 3. Create a new board category as admin (needed for post submission)
 * 4. Log back in as the member for post creation
 * 5. Create a post in the category as the member
 * 6. Immediately update the post's title and content (should succeed)
 * 7. Attempt to update the post again simulating time passage past the edit window (should yield error)
 *
 * Both the successful and failed update attempts are asserted.
 */
export async function test_api_member_post_update_owner_and_edit_window(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = typia.random<string & tags.Format<"password">>();
  const signUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  typia.assert(signUpResult);

  // 2. Log in as the member
  const signInResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  typia.assert(signInResult);

  // 3. Create a board category as admin
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(10),
      description: RandomGenerator.paragraph()(),
      display_order: 1,
    },
  });
  typia.assert(category);

  // 4. Re-authenticate as member to ensure context
  const signInResult2 = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  typia.assert(signInResult2);

  // 5. Create a post as the member in the category
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(15),
      body: RandomGenerator.content()()(100),
    },
  });
  typia.assert(post);

  // 6. Immediately update post title/body (within allowed window)
  const updatedPost = await api.functional.polEcoBoard.member.posts.update(connection, {
    postId: post.id,
    body: {
      title: RandomGenerator.paragraph()(16),
      body: RandomGenerator.content()()(110),
    },
  });
  typia.assert(updatedPost);

  // 7. Simulate expiry of edit window - in E2E, we just assert an error occurs
  await TestValidator.error("edit after window should be denied")(async () => {
    await api.functional.polEcoBoard.member.posts.update(connection, {
      postId: post.id,
      body: {
        title: RandomGenerator.paragraph()(17),
        body: RandomGenerator.content()()(120),
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Ensure that only the author of a polEcoBoard post can update their own post.
 *
 * This test verifies the authorization mechanism for post editing - specifically, it asserts that a member (Member B) cannot update a post originally authored by another member (Member A).
 *
 * Step-by-step process:
 * 1. Register Member A (the original post author) with a unique email and password.
 * 2. Log in as Member A to obtain authentication credentials/token.
 * 3. Register a category as an admin (required for post creation context).
 * 4. As Member A, create a new post under the freshly created category.
 * 5. Register Member B (will attempt the unauthorized update).
 * 6. Log in as Member B to obtain Member B auth credentials/token.
 * 7. As Member B, attempt to update Member A's post by changing the title and/or body.
 * 8. Confirm that this operation fails with an authorization/forbidden error (using TestValidator.error). Member B must not be able to update posts they do not own.
 *
 * This test ensures robust business rule enforcement regarding post ownership and edit permissions.
 */
export async function test_api_member_post_update_forbidden_on_non_owner(connection: api.IConnection) {
  // 1. Register Member A
  const emailA = typia.random<string & tags.Format<'email'>>();
  const passwordA = typia.random<string & tags.Format<'password'>>();
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: emailA,
      password: passwordA,
    },
  });

  // 2. Login as Member A
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: emailA,
      password: passwordA,
    },
  });

  // 3. Register category as admin
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: 'Test Category ' + Math.random().toString(36).slice(2, 8),
      description: 'Category for forbidden update test',
      display_order: Math.floor(Math.random()*1000),
    },
  });
  typia.assert(category);

  // 4. Create post as Member A
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: 'Initial Title',
      body: 'Initial body content of the post for forbidden update test.',
    },
  });
  typia.assert(post);

  // 5. Register Member B
  const emailB = typia.random<string & tags.Format<'email'>>();
  const passwordB = typia.random<string & tags.Format<'password'>>();
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: emailB,
      password: passwordB,
    },
  });

  // 6. Login as Member B
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: emailB,
      password: passwordB,
    },
  });

  // 7. Attempt to update Member A's post as Member B
  TestValidator.error("Non-owner member cannot update another user's post")(async () => {
    await api.functional.polEcoBoard.member.posts.update(connection, {
      postId: post.id,
      body: {
        title: 'Unauthorized Update Attempt',
        body: 'This should not succeed.',
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Verify that a moderator can update any board post, regardless of authorship or time window constraints.
 *
 * This test ensures:
 * 1. Moderators have permissions to edit posts authored by other members.
 * 2. Moderator can update a post even after the member edit window has expired.
 * 3. Update is successful (result reflects new title/body).
 *
 * Steps:
 * 1. Create a board category as prerequisite using the admin endpoint.
 * 2. Register and login as a member.
 * 3. Member creates a new post in that category.
 * 4. Register and login as a moderator.
 * 5. Moderator updates the member's post (title/body).
 * 6. Confirm the update succeeded and important fields are correct.
 */
export async function test_api_moderator_post_update_any_post_edit(
  connection: api.IConnection,
) {
  // 1. Create a board category
  const categoryInput = {
    name: `cat_${RandomGenerator.alphabets(6)}`,
    description: RandomGenerator.paragraph()(1),
    display_order: typia.random<number & tags.Type<"int32">>(),
  } satisfies IPolEcoBoardCategory.ICreate;
  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: categoryInput,
  });
  typia.assert(category);

  // 2. Register and login as a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  const memberSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberSignUp);
  // Login (authorization header set in connection)
  const memberSignIn = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberSignIn);

  // 3. Member creates a post
  const postInput = {
    category_id: category.id,
    title: `A member's original title ${RandomGenerator.alphabets(4)}`,
    body: RandomGenerator.paragraph()(2),
  } satisfies IPolEcoBoardPost.ICreate;
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: postInput,
  });
  typia.assert(post);

  // 4. Register and login as a moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = RandomGenerator.alphaNumeric(15);
  const moderatorDisplayName = `Mod_${RandomGenerator.alphabets(5)}`;
  const moderatorSignUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: "CONSENT_VERSION_2025",
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorSignUp);
  const moderatorSignIn = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(moderatorSignIn);

  // 5. Moderator updates the member's post
  const updatedTitle = `Updated by moderator ${RandomGenerator.alphabets(4)}`;
  const updatedBody = RandomGenerator.paragraph()(3);
  const updatedPost = await api.functional.polEcoBoard.moderator.posts.update(connection, {
    postId: post.id,
    body: {
      title: updatedTitle,
      body: updatedBody,
    } satisfies IPolEcoBoardPost.IUpdate,
  });
  typia.assert(updatedPost);

  // 6. Confirm the update succeeded
  TestValidator.equals("title updated")(updatedPost.title)(updatedTitle);
  TestValidator.equals("body updated")(updatedPost.body)(updatedBody);
  TestValidator.notEquals("updated_at changed")(updatedPost.updated_at)(post.updated_at);
  TestValidator.equals("author unchanged")(updatedPost.author_member_id)(post.author_member_id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Test an authorized moderator's attempt to update a post using a non-existent postId.
 *
 * This test ensures the system correctly enforces not found (404) error semantics and prevents unauthorized post updates—an essential security and integrity requirement for a content board.
 *
 * **Test Overview and Steps:**
 * 1. Register a new moderator account
 * 2. Log in as this moderator to obtain and apply authentication context
 * 3. Attempt to update a post with a random UUID (guaranteed absent from the system)
 * 4. Assert that an error is thrown (ideally HttpError 404 Not Found) and no data is returned
 *
 * By explicitly verifying the negative case (invalid postId), we ensure business-critical security: only valid, existing posts can be updated via moderator API routes, with clear error reporting for invalid resources.
 */
export async function test_api_moderator_post_update_invalid_postid(connection: api.IConnection) {
  // 1. Register a new moderator
  const email = typia.random<string & tags.Format<"email">>();
  const password = "TestPassword123!";
  const displayName = RandomGenerator.name();
  const registerResp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email,
      password,
      display_name: displayName,
      consent_status: "v1-policy-accepted",
    }
  });
  typia.assert(registerResp);

  // 2. Login as the new moderator (establishes bearer token)
  const loginResp = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email,
      password,
    }
  });
  typia.assert(loginResp);

  // 3. Attempt update on a random, guaranteed-nonexistent postId
  const nonExistentPostId = typia.random<string & tags.Format<"uuid">>();
  const updateBody: IPolEcoBoardPost.IUpdate = {
    title: "Should not update",
    body: "This update should never succeed.",
    tag_ids: null,
    attachments: null,
  };

  // 4. Assert update fails with error (ideally NotFound)
  await TestValidator.error("update on non-existent post should throw error")(async () => {
    await api.functional.polEcoBoard.moderator.posts.update(connection, {
      postId: nonExistentPostId,
      body: updateBody,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
