/**
 * Validate that non-admin users (regular members) are not allowed to update authentication sessions via the admin-only endpoint.
 *
 * This test ensures the following business rule:
 * - Only admin users may update authentication sessions via /polEcoBoard/admin/authSessions/{authSessionId}
 * - Non-admin users (regular members) must be strictly denied.
 *
 * Scenario Workflow:
 * 1. Register a new member to simulate a regular user
 * 2. Login as this member (simulate real-world access token flow)
 * 3. Register an admin user to ensure a valid authentication session exists to target
 * 4. As the regular member, attempt to update (PUT) an admin-protected auth session (supplying a sessionId)
 * 5. Confirm that the operation fails with an error, verifying privilege barriers are enforced
 *
 * Step-by-step Process:
 * 1. Member Registration: Create a unique regular member email/account
 * 2. Member Login: Authenticate and ensure user context updates connection token
 * 3. Admin Registration: Provision a separate admin account to guarantee an auth session resource for testing
 * 4. Unauthorized Update Attempt: While authenticated as the member, call the admin update endpoint, expect failure
 * 5. Validate the error is properly thrown by the SDK for non-admin users
 *
 * Notes:
 * - Since the SDK's admin registration result only returns setHeaders (tokens), the sessionId for targeting must be generated as a random UUID for testing rejection behavior (in a real test system, you would query the actual session table or cross-reference a known session).
 * - This test does NOT validate specific error types/messages, only that a permission error occurs for non-admin updates.
 */
export async function test_api_auth_session_update_unauthorized(connection: api.IConnection) {
  // 1. Register a new regular member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = typia.random<string & tags.Format<"password">>();
  const signUpResult = await api.functional.auth.member.register.signUp(connection, {
