import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardRoleTransition } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardRoleTransition";
import type { IPageIPolEcoBoardRoleTransition } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardRoleTransition";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Verify searching of role transition records as an admin using multiple filters and pagination.
 *
 * This test ensures that an admin can query the role transition records with various filters (such as affected account, destination role, status, and date range) and receive correct results, including accurate pagination. Both positive and negative filter cases are validated.
 *
 * Steps:
 * 1. Register a new admin account (this becomes the approver for role transitions).
 * 2. Login as that admin.
 * 3. Create a new role transition (e.g., promote a unique member to moderator) with distinct IDs for the admin and affected user.
 * 4. Search transitions using filters:
 *    a. By affected account (should return this transition).
 *    b. By destination_role and status (should return this transition).
 *    c. By status only (should include this transition among possible others).
 *    d. By an invalid/non-matching account (should NOT return this transition).
 *    e. By requested_after/requested_before covering the time window (should include/exclude as expected).
 *    f. By origin_role (should return this transition).
 * 5. Check pagination by querying with page=1, limit=1 and validate response shape.
 */
export async function test_api_role_transition_search_success(
  connection: api.IConnection,
) {
  // 1. Register a new admin account for search authorization
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Login as the admin to receive session tokens
  const loginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(loginResp);

  // 3. Create a new role transition record with distinct IDs
  const affectedAccountId = typia.random<string & tags.Format<"uuid">>();
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString() as string & tags.Format<"date-time">;
  const transition: IPolEcoBoardRoleTransition = await api.functional.polEcoBoard.admin.roleTransitions.create(connection, {
    body: {
      account_id: affectedAccountId,
      approved_by_admin_id: adminId, // Simulate a real admin approval
      origin_role: "member",
      destination_role: "moderator",
      reason: "E2E promotion",
      status: "completed",
      requested_at: now,
    } satisfies IPolEcoBoardRoleTransition.ICreate,
  });
  typia.assert(transition);

  // 4a. Search by affected account (should find the transition)
  const byAccount = await api.functional.polEcoBoard.admin.roleTransitions.search(connection, {
    body: {
      account_id: affectedAccountId,
    } satisfies IPolEcoBoardRoleTransition.IRequest,
  });
  typia.assert(byAccount);
  TestValidator.predicate("at least one result for affected user")(
    byAccount.data.some(tr => tr.id === transition.id),
  );

  // 4b. Search by destination_role and status
  const byDestRole = await api.functional.polEcoBoard.admin.roleTransitions.search(connection, {
    body: {
      destination_role: "moderator",
      status: "completed",
    } satisfies IPolEcoBoardRoleTransition.IRequest,
  });
  typia.assert(byDestRole);
  TestValidator.predicate("result includes transition by destination_role")(
    byDestRole.data.some(tr => tr.id === transition.id),
  );

  // 4c. Search by status only
  const byStatus = await api.functional.polEcoBoard.admin.roleTransitions.search(connection, {
    body: {
      status: "completed",
    } satisfies IPolEcoBoardRoleTransition.IRequest,
  });
  typia.assert(byStatus);
  TestValidator.predicate("result includes transition by status")(
    byStatus.data.some(tr => tr.id === transition.id),
  );

  // 4d. Search by non-matching account (should NOT return our transition)
  const byInvalidAccount = await api.functional.polEcoBoard.admin.roleTransitions.search(connection, {
    body: {
      account_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IPolEcoBoardRoleTransition.IRequest,
  });
  typia.assert(byInvalidAccount);
  TestValidator.predicate("transition not found with wrong account_id")(
    byInvalidAccount.data.every(tr => tr.id !== transition.id),
  );

  // 4e. Search with date range: should include the transition
  const byDateRange = await api.functional.polEcoBoard.admin.roleTransitions.search(connection, {
    body: {
      requested_after: new Date(Date.now() - 1000 * 60 * 10).toISOString() as string & tags.Format<"date-time">, // 10 min ago
      requested_before: new Date(Date.now() + 1000 * 60 * 10).toISOString() as string & tags.Format<"date-time">, // 10 min in future
    } satisfies IPolEcoBoardRoleTransition.IRequest,
  });
  typia.assert(byDateRange);
  TestValidator.predicate("date range should include transition")(
    byDateRange.data.some(tr => tr.id === transition.id),
  );

  // 4f. Search by origin_role (should return the transition)
  const byOriginRole = await api.functional.polEcoBoard.admin.roleTransitions.search(connection, {
    body: {
      origin_role: "member",
    } satisfies IPolEcoBoardRoleTransition.IRequest,
  });
  typia.assert(byOriginRole);
  TestValidator.predicate("origin_role includes transition")(
    byOriginRole.data.some(tr => tr.id === transition.id),
  );

  // 5. Pagination check: should return the correct structure for limit/1
  const paged = await api.functional.polEcoBoard.admin.roleTransitions.search(connection, {
    body: {
      page: 1,
      limit: 1,
      status: "completed",
    } satisfies IPolEcoBoardRoleTransition.IRequest,
  });
  typia.assert(paged);
  TestValidator.equals("pagination limit")(paged.pagination.limit)(1);
  TestValidator.predicate("returned data has at most 1 row")(paged.data.length <= 1);
}

