    approved_by_admin_id: typia.random<string & tags.Format<"uuid">>(),
    origin_role: "member",
    destination_role: "moderator",
    reason: "Promotion to moderator for outstanding contribution.",
    status: "pending",
    requested_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const createResp = await api.functional.polEcoBoard.admin.roleTransitions.create(connection, {
    body: roleTransitionPayload,
  });
