/**
 * Validates member access and comprehensive filters for comment edit history endpoint.
 *
 * This test covers a member's ability to:
 * 1. Register and log in.
 * 2. Create a post and a comment.
 * 3. Retrieve comment edit history — should be empty for a new comment.
 * 4. Perform and verify two edits (with all audit data).
 * 5. Search/history retrieval with pagination (limit=1), ensuring order/data.
 * 6. Use history filters (editor_member_id).
 * 7. Attempt forbidden access (another member cannot see other's history).
 * 8. Test not-found case (nonexistent comment).
 *
 * The function also validates type contracts and error modes, using typia and TestValidator throughout.
 */
export async function test_api_comment_edit_history_member_access_and_filters(connection: api.IConnection) {
  // 1. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "test-password1!";
  const displayName = RandomGenerator.name();
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword, // For E2E, accept plain as mock hash.
      display_name: displayName,
      consent_status: "agreed",
    },
  });
  typia.assert(member);
  // 2. Login
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  // 3. Create a post
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(12),
      body: RandomGenerator.content()(20)(),
    },
  });
  typia.assert(post);
  // 4. Create a comment
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(25),
    },
  });
  typia.assert(comment);
  // 5. Retrieve edit history (should be empty)
  let editsPage = await api.functional.polEcoBoard.member.posts.comments.commentEdits.search(connection, {
    postId: post.id,
    commentId: comment.id,
    body: {},
  });
  typia.assert(editsPage);
  TestValidator.equals("empty edit history")(editsPage.data.length)(0);
  // 6. Edit the comment twice
  const editBodies = [RandomGenerator.content()(30)(), RandomGenerator.content()(31)()];
  for (const body of editBodies) {
    const updated = await api.functional.polEcoBoard.member.posts.comments.update(connection, {
      postId: post.id,
      commentId: comment.id,
      body: { body },
    });
    typia.assert(updated);
    TestValidator.equals("body after edit")(updated.body)(body);
  }
  // 7. Full edit history; check contents, audit, filters; expect two records (oldest first)
  editsPage = await api.functional.polEcoBoard.member.posts.comments.commentEdits.search(connection, {
    postId: post.id,
    commentId: comment.id,
    body: {},
  });
  typia.assert(editsPage);
  TestValidator.equals("edit revision count")(editsPage.data.length)(editBodies.length);
  for (let i = 0; i < editsPage.data.length; ++i) {
    TestValidator.equals(`history[${i}].editor_member_id`)(editsPage.data[i].editor_member_id)(member.id);
    TestValidator.equals(`history[${i}].edit_body`)(editsPage.data[i].edit_body)(editBodies[i]);
    TestValidator.predicate(`history[${i}].created_at is ISO string`)(/\d{4}-\d{2}-\d{2}T/.test(editsPage.data[i].created_at));
  }
  // 8. Pagination: limit=1; verify only first edit shown
  const paged1 = await api.functional.polEcoBoard.member.posts.comments.commentEdits.search(connection, {
    postId: post.id,
    commentId: comment.id,
    body: { limit: 1 },
  });
  typia.assert(paged1);
  TestValidator.equals("pagination - one result")(paged1.data.length)(1);
  TestValidator.equals("pagination - correct edit body")(paged1.data[0].edit_body)(editBodies[0]);
  // 9. Editor filter: only return edits by current member
  const filtered = await api.functional.polEcoBoard.member.posts.comments.commentEdits.search(connection, {
    postId: post.id,
    commentId: comment.id,
    body: { editor_member_id: member.id },
  });
  typia.assert(filtered);
  TestValidator.equals("filter by editor")(filtered.data.length)(editBodies.length);
  // 10. Register and login as a different member
  const member2Email = typia.random<string & tags.Format<"email">>();
  const member2Password = "other-password2!";
  await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: member2Email,
      password_hash: member2Password,
      display_name: RandomGenerator.name(),
      consent_status: "agreed",
    },
  });
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: member2Email,
      password: member2Password,
    },
  });
  // 11. Forbidden: try to view original member's comment history
  await TestValidator.error("forbidden for non-owner")(async () => {
    await api.functional.polEcoBoard.member.posts.comments.commentEdits.search(connection, {
      postId: post.id,
      commentId: comment.id,
      body: {},
    });
  });
  // 12. Not found case: random comment id
  await TestValidator.error("not found: random comment id")(async () => {
    await api.functional.polEcoBoard.member.posts.comments.commentEdits.search(connection, {
      postId: post.id,
      commentId: typia.random<string & tags.Format<"uuid">>(),
      body: {},
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
