/**
 * Validate that admin can retrieve details of any comment on any post, including regular, flagged, and deleted comments (to the extent possible with available APIs), and receives correct errors on missing/unauthorized comment combinations.
 *
 * ## Business Context
 * Admins are responsible for audit, moderation, and compliance across all posts and comments. This test ensures that the privileged GET endpoint for comment detail provides all business, moderation, and audit fields for any given comment.
 *
 * ## Steps:
 * 1. Register a new admin account with a unique email and password.
 * 2. Login as admin, acquiring a session for authenticated, privileged requests.
 * 3. Create a new post for the comment to attach to (as allowed by the current authentication context).
 * 4. Create a new comment under the created post using the member comment creation API.
 * 5. Retrieve the comment as admin using the privileged detail endpoint, confirming all audit/metadata fields (id, post_id, author_member_id, flagged, deleted_at, etc.) and check population of correct values (including nulls and booleans where appropriate).
 * 6. Attempt to access a non-existent commentId under the real post, expect a not-found error.
 * 7. Attempt to access a real comment under a non-existent postId, expect a not-found or forbidden error.
 * 8. Attempt to access a real comment under an unrelated, valid postId, expect forbidden/not-found error.
 */
export async function test_api_admin_comment_detail_view_and_access_errors(connection: api.IConnection) {
  // 1. Register a new admin (admin role required for privileged comment access)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpRes);

  // 2. Login as admin
  const signInRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInRes);
  // The SDK should update connection.headers.Authorization after login

  // 3. Create a post (as admin or as member if required; only member create API is available)
  // NOTE: No member registration API provided, so this is performed in the admin session.
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const postTitle = RandomGenerator.paragraph()(15);
  const postBody = RandomGenerator.content()(100)();
  const createdPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: postTitle,
      body: postBody,
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(createdPost);

  // 4. Create a comment under the post (same authentication context)
  const commentBody = RandomGenerator.paragraph()(8);
  const createdComment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: createdPost.id,
    body: {
      body: commentBody,
      parent_comment_id: null
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(createdComment);

  // 5. Retrieve the comment as admin (should include all moderation/audit fields)
  const adminComment = await api.functional.polEcoBoard.admin.posts.comments.at(connection, {
    postId: createdPost.id,
    commentId: createdComment.id,
  });
  typia.assert(adminComment);
  TestValidator.equals("body matches")(adminComment.body)(createdComment.body);
  TestValidator.equals("flagged - should be false for new comment")(adminComment.flagged)(false);
  TestValidator.equals("deleted_at - should be null for active comment")(adminComment.deleted_at)(null);
  TestValidator.equals("post_id matches")(adminComment.post_id)(createdPost.id);
  TestValidator.equals("id matches")(adminComment.id)(createdComment.id);
  TestValidator.predicate("author_member_id populated")(typeof adminComment.author_member_id === "string" && adminComment.author_member_id.length > 0);
  TestValidator.predicate("created_at populated")(typeof adminComment.created_at === "string" && adminComment.created_at.length > 0);
  TestValidator.predicate("updated_at populated")(typeof adminComment.updated_at === "string" && adminComment.updated_at.length > 0);

  // 6. Error: request with non-existent commentId
  const randomCommentId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("should fail for non-existent commentId")(async () =>
    await api.functional.polEcoBoard.admin.posts.comments.at(connection, {
      postId: createdPost.id,
      commentId: randomCommentId
    })
  );

  // 7. Error: request with non-existent postId
  const randomPostId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("should fail for non-existent postId")(async () =>
    await api.functional.polEcoBoard.admin.posts.comments.at(connection, {
      postId: randomPostId,
      commentId: createdComment.id
    })
  );

  // 8. Error: mismatched but valid postId and commentId (comment doesn't belong to post)
  const otherPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(12),
      body: RandomGenerator.content()(80)(),
      tag_ids: null,
      attachments: null
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(otherPost);
  TestValidator.error("should fail for mismatched post and comment")(async () =>
    await api.functional.polEcoBoard.admin.posts.comments.at(connection, {
      postId: otherPost.id,
      commentId: createdComment.id
    })
  );
}

