  const signInResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(signInResult);
  connection.headers = {
    ...connection.headers,
    Authorization: signInResult.setHeaders.Authorization,
  };

  // 3. Create post (category_id, title, body): use valid random values
  const postInput: IPolEcoBoardPost.ICreate = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.alphabets(20),
    body: RandomGenerator.alphabets(100),
  };
  const post = await api.functional.polEcoBoard.member.posts.create(connection, { body: postInput });
  typia.assert(post);

  // 4. Create top-level comment with valid body
  const commentInput: IPolEcoBoardComment.ICreate = {
    body: RandomGenerator.alphabets(25),
  };
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: commentInput,
  });
  typia.assert(comment);
  TestValidator.equals("post id matches on comment")(comment.post_id)(post.id);
  TestValidator.equals("parent_comment_id null for top-level")(comment.parent_comment_id)(null);
  TestValidator.equals("body matches on comment")(comment.body)(commentInput.body);

  // 5. Create reply by setting parent_comment_id
  const replyInput: IPolEcoBoardComment.ICreate = {
    body: RandomGenerator.alphabets(50),
    parent_comment_id: comment.id,
  };
  const reply = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: replyInput,
  });
  typia.assert(reply);
  TestValidator.equals("parent_comment_id on reply")(reply.parent_comment_id)(comment.id);
  TestValidator.equals("body matches on reply")(reply.body)(replyInput.body);

  // 6. Attempt comment with invalid/empty body (too short)
  await TestValidator.error("body too short should fail")(async () =>
    api.functional.polEcoBoard.member.posts.comments.create(connection, {
      postId: post.id,
      body: { body: "h" },
    })
  );

  // 7. Attempt comment with body too long
  await TestValidator.error("body too long should fail")(async () =>
    api.functional.polEcoBoard.member.posts.comments.create(connection, {
      postId: post.id,
      body: { body: "x".repeat(1001) },
    })
  );

  // 8. Attempt reply with invalid parent_comment_id
  await TestValidator.error("invalid parent_comment_id should fail")(async () =>
    api.functional.polEcoBoard.member.posts.comments.create(connection, {
      postId: post.id,
      body: {
        body: RandomGenerator.alphabets(20),
        parent_comment_id: typia.random<string & tags.Format<"uuid">>(),
      },
    })
  );

  // 9. Remove Authorization header and attempt unauthenticated comment
  const unauthConn = { ...connection, headers: { ...connection.headers } };
  delete unauthConn.headers.Authorization;
  await TestValidator.error("unauthenticated comment should fail")(async () =>
    api.functional.polEcoBoard.member.posts.comments.create(unauthConn, {
      postId: post.id,
      body: { body: RandomGenerator.alphabets(10) },
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
