import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate that a moderator can create comments under any post, including posts that are flagged, locked, or archived if business rules permit moderator override.
 *
 * This includes positive cases (regular, flagged, locked, archived) and negative cases (deleted post or lock that blocks all).
 * Also verify proper audit records/metadata are present on the created comment.
 *
 * Steps:
 * 1. Register a moderator account
 * 2. Log in as moderator
 * 3. Create a regular post (as member, but since only moderator/member flows are available in this E2E, use moderator JWT)
 * 4. (Positive) Add comment to active/regular post as moderator (should succeed)
 * 5. (Positive) Set post status to 'locked' and add comment as moderator (should succeed due to privileged override)
 * 6. (Positive) Set post status to 'archived' and add comment as moderator (should succeed if permitted)
 * 7. (Negative) Try to add comment to a deleted/nonexistent post as moderator (should fail)
 * 8. (Negative) If business rules supported a non-overridable lock type, test block (skipped as not present)
 * 9. After each successful comment, assert audit data: audit trail fields set, author is moderator, correct postId, etc.
 */
export async function test_api_moderator_create_comment_with_privileged_post_access(connection: api.IConnection) {
  // 1. Register moderator
  const moderatorEmail = typia.random<string & tags.Format<'email'>>();
  const moderatorPassword = "SuperStrongPassword1!";
  const moderatorDisplayName = RandomGenerator.name();
  const consentStatus = "v1";
  const registrationResp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(registrationResp);
  const moderatorId = registrationResp.moderatorId;

  // 2. Log in as moderator
  const loginResp = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(loginResp);
  TestValidator.equals("Moderator identity matches")(loginResp.moderatorId)(moderatorId);

  // 3. Create a test post as member (using moderator JWT because only moderator flows are available)
  const categoryId = typia.random<string & tags.Format<'uuid'>>();
  const postTitle = RandomGenerator.paragraph(1)();
  const postBody = RandomGenerator.content()(10, 20)();
  const postResp = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: postTitle,
      body: postBody,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(postResp);
  const postId = postResp.id;

  // 4. Add comment to regular/active post (should succeed)
  const commentBody1 = RandomGenerator.content()(5, 10)();
  const comment1 = await api.functional.polEcoBoard.moderator.posts.comments.create(connection, {
    postId,
    body: { body: commentBody1 } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment1);
  TestValidator.equals("Regular: comment post_id matches")(comment1.post_id)(postId);
  TestValidator.equals("Regular: moderator authored")(comment1.author_member_id)(loginResp.moderatorId);
  TestValidator.predicate("Audit trail: created_at present")(typeof comment1.created_at === "string");
  TestValidator.predicate("Audit trail: updated_at present")(typeof comment1.updated_at === "string");
  TestValidator.predicate("Flagged field is boolean")(typeof comment1.flagged === "boolean");

  // 5. Set post status to 'locked' and add comment as moderator (should succeed due to moderator privilege)
  const lockStatus = await api.functional.polEcoBoard.admin.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: postId,
      actor_moderator_id: moderatorId,
      status_type: "locked",
      effective_at: new Date().toISOString(),
      reason: "Test lock as moderator",
    } satisfies IPolEcoBoardBoardStatus.ICreate,
  });
  typia.assert(lockStatus);

  const commentBody2 = RandomGenerator.content()(5, 10)();
  const comment2 = await api.functional.polEcoBoard.moderator.posts.comments.create(connection, {
    postId,
    body: { body: commentBody2 } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment2);
  TestValidator.equals("Locked: comment post_id matches")(comment2.post_id)(postId);
  TestValidator.equals("Locked: moderator authored")(comment2.author_member_id)(loginResp.moderatorId);
  TestValidator.predicate("Locked: created_at tz")(typeof comment2.created_at === "string");
  TestValidator.predicate("Locked: updated_at tz")(typeof comment2.updated_at === "string");
  TestValidator.predicate("Locked: flagged boolean")(typeof comment2.flagged === "boolean");

  // 6. Set post status to 'archived' and add comment as moderator (should succeed if software allows)
  const archiveStatus = await api.functional.polEcoBoard.admin.boardStatuses.create(connection, {
    body: {
      pol_eco_board_board_id: postId,
      actor_moderator_id: moderatorId,
      status_type: "archived",
      effective_at: new Date().toISOString(),
      reason: "Test archive as moderator",
    } satisfies IPolEcoBoardBoardStatus.ICreate,
  });
  typia.assert(archiveStatus);

  const commentBody3 = RandomGenerator.content()(5, 10)();
  const comment3 = await api.functional.polEcoBoard.moderator.posts.comments.create(connection, {
    postId,
    body: { body: commentBody3 } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment3);
  TestValidator.equals("Archived: comment post_id matches")(comment3.post_id)(postId);
  TestValidator.equals("Archived: moderator authored")(comment3.author_member_id)(loginResp.moderatorId);
  TestValidator.predicate("Archived: created_at tz")(typeof comment3.created_at === "string");
  TestValidator.predicate("Archived: updated_at tz")(typeof comment3.updated_at === "string");
  TestValidator.predicate("Archived: flagged boolean")(typeof comment3.flagged === "boolean");

  // 7. Try to comment on a deleted/nonexistent post as moderator (should fail)
  const deletedOrRandomPostId = typia.random<string & tags.Format<'uuid'>>();
  await TestValidator.error("Should not allow comment on deleted/nonexistent post")(async () => {
    await api.functional.polEcoBoard.moderator.posts.comments.create(connection, {
      postId: deletedOrRandomPostId,
      body: { body: RandomGenerator.content()(5, 10)() } satisfies IPolEcoBoardComment.ICreate,
    });
  });

  // 8. No API for non-overridable lock/block, so cannot test extra lock type.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardReport";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate admin ability to update a post report in polEcoBoard.
 *
 * This test performs and verifies the full workflow for admin report moderation:
 *  1. Register a member.
 *  2. Register a new admin account.
 *  3. Login as admin for authorization to update the report.
 *  4. Login as member for post/report flows.
 *  5. Member creates a post.
 *  6. Member reports the post.
 *  7. Switch to admin, update the report (change reason/code/notes).
 *  8. Validate that the update is applied and that only a privileged user can perform this.
 *
 * Steps require session switching via Authorization headers (from returned setHeaders), to mimic real authentication transitions between member/admin.
 */
export async function test_api_post_report_update_admin_happy_path(connection: api.IConnection) {
  // 1. Register a member user
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = typia.random<string & tags.Format<"password">>();
  const memberReg = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    }
  });
  typia.assert(memberReg);
  connection.headers = { ...connection.headers, ...memberReg.setHeaders };

  // 2. Register an admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Admin!E2EPass2025";
  const adminReg = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    }
  });
  typia.assert(adminReg);

  // 3. Login as admin to fetch Authorization JWT for admin API
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    }
  });
  typia.assert(adminLogin);
  connection.headers = { ...connection.headers, ...adminLogin.setHeaders };

  // 4. Switch back to member session for post/report
  const memberReAuth = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    }
  });
  typia.assert(memberReAuth);
  connection.headers = { ...connection.headers, ...memberReAuth.setHeaders };

  // 5. Member creates a new post
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "E2E: Test post for admin report update",
      body: "Automated E2E test post content for admin update path."
    }
  });
  typia.assert(post);

  // 6. Member reports the new post
  const report = await api.functional.polEcoBoard.member.posts.reports.create(connection, {
    postId: post.id,
    body: {
      reason_code: "abuse",
      reason_description: "Flagged for moderation in E2E admin test.",
      post_id: post.id,
      comment_id: null
    }
  });
  typia.assert(report);

  // 7. Switch to admin session for updating the report
  connection.headers = { ...connection.headers, ...adminLogin.setHeaders };

  // Perform update: change reason and moderation notes
  const updatedReason = "hate";
  const updatedDescription = "Moderation complete: test admin updated this report.";
  const updated = await api.functional.polEcoBoard.admin.posts.reports.update(connection, {
    postId: post.id,
    reportId: report.id,
    body: {
      reason_code: updatedReason,
      reason_description: updatedDescription
    }
  });
  typia.assert(updated);

  // 8. Validate update
  TestValidator.equals("reason_code updated")(updated.reason_code)(updatedReason);
  TestValidator.equals("description updated")(updated.reason_description)(updatedDescription);
  TestValidator.equals("report id")(updated.id)(report.id);
  TestValidator.equals("post id")(updated.post_id)(report.post_id);
}

