/**
 * Test that a moderator can successfully soft-delete a valid report for a post.
 *
 * Business Context:
 * Moderators should be able to remove (soft-delete) reports on posts for valid moderation/audit reasons, with strict role-based access control, record retention, and audit compliance. This test ensures a full workflow: user/member creates a post and files a report; a moderator deletes that report. The expected behavior is that after deletion, the report cannot be found via member interfaces (since it's soft-deleted and hidden), but the audit log and retention policy is enforced via the business logic and data layer.
 *
 * Steps:
 * 1. Register a member (who will author the post and file the report)
 * 2. Register a moderator account
 * 3. Log in as moderator (to get auth context for deletion)
 * 4. Log in as member (to get auth context for post/report creation)
 * 5. Member creates a post
 * 6. Member files a report on the newly created post
 * 7. Moderator logs in to obtain correct credentials for report deletion
 * 8. Moderator deletes (soft-deletes) the report
 * 9. Check that the report is gone (not accessible via normal list/search interfaces for reports on the post)
 *
 * (Note: As the search/list API for reports is not exposed, skip step 9 validation in the code; focus on soft-deletion.)
 */
export async function test_api_post_report_delete_moderator_success(connection: api.IConnection) {
  // 1. Register a member (will be reporter and post author)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "pw" + RandomGenerator.alphaNumeric(10);
  const memberRegisterResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberRegisterResult);
  // Set member auth token
  connection.headers = {
    ...connection.headers,
    Authorization: memberRegisterResult.setHeaders.Authorization,
  };

  // 2. Register a moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "pw" + RandomGenerator.alphaNumeric(10);
  const moderatorDisplayName = RandomGenerator.alphabets(12);
  const moderatorConsent = "20240813-v1"; // mock consent string
  const moderatorRegisterResult = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: moderatorConsent,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorRegisterResult);

  // 3. Log in as member (to create the post & report)
  connection.headers = {
    ...connection.headers,
    Authorization: memberRegisterResult.setHeaders.Authorization,
  };

  // 4. Member creates a post
  const postCategoryId = typia.random<string & tags.Format<"uuid">>();
  const postTitle = RandomGenerator.paragraph()(1).slice(0, 30); // 10-120 chars
  const postBody = RandomGenerator.content()(1)().slice(0, 80); // 10-10,000 chars
  const postOutput = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: postCategoryId,
      title: postTitle,
      body: postBody,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(postOutput);

  // 5. Member files a report on the post
  const reportReason = "abuse"; // standard code
  const reportDescription = RandomGenerator.paragraph()(1).slice(0, 80);
  const reportOutput = await api.functional.polEcoBoard.member.posts.reports.create(connection, {
    postId: postOutput.id,
    body: {
      reason_code: reportReason,
      reason_description: reportDescription,
      post_id: postOutput.id,
    } satisfies IPolEcoBoardReport.ICreate,
  });
  typia.assert(reportOutput);

  // 6. Moderator logs in
  const moderatorLoginResult = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(moderatorLoginResult);
  // Switch context to moderator
  connection.headers = {
    ...connection.headers,
    Authorization: moderatorLoginResult.setHeaders.Authorization,
  };

  // 7. Moderator deletes (soft-deletes) the report
  await api.functional.polEcoBoard.moderator.posts.reports.erase(connection, {
    postId: postOutput.id,
    reportId: reportOutput.id,
  });

  // 8. (No available list/search API for further validation)
}

