import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardTag";
import type { IPageIPolEcoBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for searching and paginating tags in the polEcoBoard module.
 *
 * Business Context:
 * - This test ensures that the tag search endpoint returns appropriate results for various search input scenarios.
 * - The endpoint supports searching by tag name or slug, regular/general search, pagination (page/limit), and should handle empty/invalid queries gracefully.
 *
 * Test Workflow/Steps:
 * 1. Perform an unfiltered query (empty body), expecting all tags paginated.
 * 2. Filter search by partial tag name: simulate user typing for autocomplete/filter -- expect returned tags contain the substring.
 * 3. Filter by exact slug, expecting (if a tag with that slug exists) at most 1 record with matching slug or empty result.
 * 4. Paginated listing: query with page/limit and verify correct pagination and data batch length.
 * 5. Edge case: search by a name/slug that does not exist, expect empty data list.
 * 6. Edge case: query with invalid pagination (e.g. page=0, limit=1000) to verify error or fallback to valid defaults.
 *
 * Each step validates type correctness and major business expectations like data count, contents, and pagination info.
 */
export async function test_api_tag_search_pagination_and_filters(connection: api.IConnection) {
  // 1. Unfiltered: Empty body (all tags, first page)
  const unfiltered = await api.functional.polEcoBoard.tags.search(connection, { body: {} });
  typia.assert(unfiltered);
  TestValidator.predicate("at least 0 tags returned")(Array.isArray(unfiltered.data));

  // If there are any tags, capture a sample for later
  const someTag = unfiltered.data.length > 0 ? unfiltered.data[0] : undefined;

  // 2. Filter by partial tag name (if available)
  if (someTag && someTag.name.length >= 2) {
    const partial = someTag.name.slice(0, 2);
    const filteredName = await api.functional.polEcoBoard.tags.search(connection, { body: { name: partial } });
    typia.assert(filteredName);
    TestValidator.predicate("tags should contain name substring")(
      filteredName.data.every(t => t.name.includes(partial))
    );
  }

  // 3. Filter by exact slug
  if (someTag) {
    const filteredSlug = await api.functional.polEcoBoard.tags.search(connection, { body: { slug: someTag.slug } });
    typia.assert(filteredSlug);
    TestValidator.predicate("all tags have exact slug")(
      filteredSlug.data.every(t => t.slug === someTag.slug)
    );
    if (filteredSlug.data.length > 0) {
      TestValidator.equals("filtered slug returns one record")(filteredSlug.data[0].slug)(someTag.slug);
    }
  }

  // 4. Pagination test: page=2, limit=1 (meaningful only if there are >=2)
  if (unfiltered.data.length > 1) {
    const paginated = await api.functional.polEcoBoard.tags.search(connection, { body: { page: 2, limit: 1 } });
    typia.assert(paginated);
    TestValidator.equals("limit respected")(paginated.data.length)(1);
    TestValidator.equals("current page")(paginated.pagination.current)(2);
  }

  // 5. Edge: Nonexistent tag name
  const noResult = await api.functional.polEcoBoard.tags.search(connection, { body: { name: "nonexistent-auto-be-test-tag" } });
  typia.assert(noResult);
  TestValidator.equals("no data for nonexistent tag")(noResult.data.length)(0);

  // 6. Edge: Invalid pagination (page=0, limit=1000)
  const invalidPage = await api.functional.polEcoBoard.tags.search(connection, { body: { page: 0, limit: 1000 } });
  typia.assert(invalidPage);
  TestValidator.predicate("page >= 1")(invalidPage.pagination.current >= 1);
  TestValidator.predicate("limit reasonable")(invalidPage.pagination.limit <= 100);
}

