  TestValidator.equals("session_anon_id matches")(fetchedEvent.session_anon_id)(createInput.session_anon_id);
  TestValidator.equals("user_role matches")(fetchedEvent.user_role)(createInput.user_role);
  TestValidator.equals("event_details matches")(fetchedEvent.event_details)(createInput.event_details);
  TestValidator.equals("region matches")(fetchedEvent.region)(createInput.region);
  TestValidator.equals("created_at matches")(fetchedEvent.created_at)(createInput.created_at);

  // 5. Negative: fetch with invalid analyticsEventId
  await TestValidator.error("should not find event for random analyticsEventId")(
    () => api.functional.polEcoBoard.admin.analyticsEvents.at(connection, {
      analyticsEventId: typia.random<string & tags.Format<"uuid">>(),
    }),
  );

  // 6. Negative: unauthorized request
  // Remove credentials
  const unauthConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthorized user cannot access event details")(
    () => api.functional.polEcoBoard.admin.analyticsEvents.at(unauthConnection, {
      analyticsEventId: createdEvent.id,
    }),
  );
