  // 3. Create a well-formed analytics event
  const eventBody = {
    event_type: "page_view",
    session_anon_id: RandomGenerator.alphaNumeric(32),
    user_role: "admin",
    event_details: JSON.stringify({ url: "/dashboard", ref: "test-suite" }),
