import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAppeal";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that admin can successfully hard-delete an appeal record and that errors are thrown for invalid or repeat deletions.
 *
 * Business context: Appeal deletions are highly privileged, require admin access, and must not quietly fail. Auditable and compliance-critical for moderation review lifecycles.
 *
 * Step-by-step process:
 * 1. Register a new admin user (to get a unique admin with fresh credentials).
 * 2. Login as the above admin (to get a privileged, authenticated session).
 * 3. Create a moderation action (required because appeals always reference an existing moderation decision).
 * 4. Create an appeal linked to the moderation action and this admin as the appellant.
 * 5. Delete the appeal by its id using the admin endpoint, expecting a successful hard delete with no result.
 * 6. Attempt to delete the same appeal again and verify a proper error is returned (already deleted or not found).
 * 7. Attempt to delete a random/nonexistent UUID and check for a not-found error response.
 */
export async function test_api_appeal_deletion_success_and_error_handling(
  connection: api.IConnection,
) {
  // 1. Register a new admin user (unique and strong credentials)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin (to ensure auth/session is set for privileged calls)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create a moderation action (with unique synthetic IDs, since the system doesn't expose real user/admin IDs directly here)
  const fakeAdminId = typia.random<string & tags.Format<"uuid">>();
  const fakeReportId = typia.random<string & tags.Format<"uuid">>();
  const moderationAction = await api.functional.polEcoBoard.admin.moderationActions.create(connection, {
    body: {
      report_id: fakeReportId,
      operator_id: fakeAdminId,
      action_type: "remove",
      target_type: "post",
      status: "completed",
      rationale: "Spam post removed for policy violation.",
      outcome: "removed",
    } satisfies IPolEcoBoardModerationAction.ICreate,
  });
  typia.assert(moderationAction);

  // 4. Create appeal targeting the above moderation action, as this admin
  const appeal = await api.functional.polEcoBoard.admin.appeals.create(connection, {
    body: {
      moderation_action_id: moderationAction.id,
      appellant_id: fakeAdminId,
      reason: "Dispute moderation removal -- requesting review.",
      status: "pending",
    } satisfies IPolEcoBoardAppeal.ICreate,
  });
  typia.assert(appeal);

  // 5. Delete the appeal (should succeed, hard delete, no result)
  await api.functional.polEcoBoard.admin.appeals.erase(connection, {
    appealId: appeal.id,
  });

  // 6. Try to delete the same appeal again (should throw error)
  await TestValidator.error("delete already deleted appeal")(() =>
    api.functional.polEcoBoard.admin.appeals.erase(connection, {
      appealId: appeal.id,
    })
  );

  // 7. Try to delete a nonexistent/invalid appealId
  await TestValidator.error("delete nonexistent appeal")(() =>
    api.functional.polEcoBoard.admin.appeals.erase(connection, {
      appealId: typia.random<string & tags.Format<"uuid">>()
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotification";
import type { IPageIPolEcoBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardNotification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate search, filtering, pagination, and permission enforcement for the member notifications list API (PATCH /polEcoBoard/member/notifications).
 *
 * This test ensures members can query their own notifications with correct filtering/pagination and that privacy and permission are enforced:
 *   - Only the member’s own notifications are returned (no leaks)
 *   - Filter fields (event_type, status, date range) work
 *   - Pagination is applied as requested (limit/page)
 *   - Unauthorized use (missing/invalid token or wrong role) is denied
 *
 * Steps:
 * 1. Register a new member
 * 2. Login and retain Authorization header/token
 * 3. Create multiple notifications for this member (with varying event_type and status)
 * 4. As the member, query all notifications, and then filtered queries:
 *      • By event_type
 *      • By status
 *      • By created_from/created_to (date range)
 *      • Use pagination limit/page
 *      For each: check that only matching notifications for this member are returned
 * 5. Attempt to query notifications without auth, and assert forbidden/unauthorized
 */
export async function test_api_notification_search_member_success_and_permission(connection: api.IConnection) {
  // Step 1: Register a new member
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.Format<"password">>();

  const regResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password,
    },
  });
  typia.assert(regResult);
  const bearer = regResult.setHeaders.Authorization;
  TestValidator.predicate("got JWT after registration")(typeof bearer === "string" && bearer.startsWith("Bearer "));
  // Use this for requests as the member
  const memberConn = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: bearer,
    },
  };

  // Step 2: Login as member and confirm token
  const loginResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password,
    },
  });
  typia.assert(loginResult);
  const loginBearer = loginResult.setHeaders.Authorization;
  TestValidator.predicate("got JWT from login")(typeof loginBearer === "string" && loginBearer.startsWith("Bearer "));
  const authedConn = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: loginBearer,
    },
  };

  // Step 3: Create various notification events for this member (omit 'channel' from ICreate)
  // Simulate event_type/status variety
  const testNotiData = [
    { event_type: "reply", status: "pending" },
    { event_type: "admin_notice", status: "delivered" },
    { event_type: "system_announce", status: "delivered" },
    { event_type: "moderation_action", status: "failed" },
  ];
  // Get recipient_member_id: we don't have a direct memberId. Instead, we must retrieve the member id by creating a notification and then reading it back using filters.

  let memberId: string | undefined;
  let firstNotificationId: string | undefined;
  const createdNotis: IPolEcoBoardNotification[] = [];
  // Create first notification and retrieve id
  const firstNoti = await api.functional.polEcoBoard.admin.notifications.create(connection, {
    body: {
      recipient_member_id: typia.random<string & tags.Format<"uuid">>(),
      event_type: testNotiData[0].event_type,
      status: testNotiData[0].status,
      attempt_count: 0,
    },
  });
  typia.assert(firstNoti);
  createdNotis.push(firstNoti);
  memberId = firstNoti.recipient_member_id;
  firstNotificationId = firstNoti.id;

  // Create rest for same recipient_member_id
  for (const d of testNotiData.slice(1)) {
    const result = await api.functional.polEcoBoard.admin.notifications.create(connection, {
      body: {
        recipient_member_id: memberId,
        event_type: d.event_type,
        status: d.status,
        attempt_count: 0,
      },
    });
    typia.assert(result);
    createdNotis.push(result);
  }

  // Step 4: Search/Filter - all, then by event_type, status, date, paginated
  // All notifications
  const allResp = await api.functional.polEcoBoard.member.notifications.index(authedConn, { body: {} });
  typia.assert(allResp);
  TestValidator.predicate("all notifications for memberId only")(allResp.data.every((n) => n.recipient_member_id === memberId));
  // By event_type
  for (const d of testNotiData) {
    const resp = await api.functional.polEcoBoard.member.notifications.index(authedConn, {
      body: { event_type: d.event_type },
    });
    typia.assert(resp);
    TestValidator.predicate(`notifications filtered by event_type='${d.event_type}' only`)(resp.data.every((n) => n.event_type === d.event_type && n.recipient_member_id === memberId));
  }
  // By status
  for (const d of testNotiData) {
    const resp = await api.functional.polEcoBoard.member.notifications.index(authedConn, {
      body: { status: d.status },
    });
    typia.assert(resp);
    TestValidator.predicate(`notifications filtered by status='${d.status}' only`)(resp.data.every((n) => n.status === d.status && n.recipient_member_id === memberId));
  }
  // Date/time range
  const now = new Date();
  const oneDayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);
  const dateResp = await api.functional.polEcoBoard.member.notifications.index(authedConn, {
    body: {
      created_from: oneDayAgo.toISOString(),
      created_to: now.toISOString(),
    },
  });
  typia.assert(dateResp);
  TestValidator.predicate("all notifications fall within created_from/to")(dateResp.data.every((n) => {
    const created = new Date(n.created_at);
    return created >= oneDayAgo && created <= now && n.recipient_member_id === memberId;
  }));
  // Pagination
  const pagedResp = await api.functional.polEcoBoard.member.notifications.index(authedConn, {
    body: { limit: 2, page: 1 },
  });
  typia.assert(pagedResp);
  TestValidator.equals("pagination respects limit")(pagedResp.data.length)(2);
  TestValidator.equals("pagination meta reflects limit")(pagedResp.pagination.limit)(2);

  // Step 5: Permission/Privacy: Try query with no auth (should be denied)
  await TestValidator.error("unauthenticated call forbidden")(async () => {
    await api.functional.polEcoBoard.member.notifications.index(connection, { body: {} });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotification";
import type { IPageIPolEcoBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardNotification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate moderator notification search, filtering, and access control for polEcoBoard.
 *
 * This test verifies that a moderator can search for their own notifications as well as for a member user, using advanced filtering and pagination options. It also ensures that permission boundaries, invalid query handling, and token-based access control are enforced.
 *
 * Step-by-step workflow:
 * 1. Register a new moderator (unique email and display_name), consents to platform terms
 * 2. Log in as that moderator and save moderatorId/token
 * 3. Register a member account and log them in
 * 4. As admin (using moderator role), create notifications for both moderator and member
 * 5. As moderator, search for all notifications for self using PATCH /polEcoBoard/moderator/notifications (recipient_member_id filter: self)
 * 6. Search notifications for the member using recipient_member_id filter
 * 7. Assert matching notifications are returned for each actor
 * 8. Apply filters (status, event_type) and assert filtering works
 * 9. Test pagination by limit=1 and check results
 * 10. Test unauthorized: member attempts moderator endpoint, expect error
 * 11. Test invalid/expired token behavior
 * 12. Test invalid filter payload causes error
 */
export async function test_api_notification_search_moderator_scope_and_access_control(connection: api.IConnection) {
  // 1. Register moderator
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorPassword: string = "Moderator#1234";
  const moderatorDisplayName: string = RandomGenerator.name();
  const moderatorConsent: string = "current_terms_v1";
  const moderatorSignUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: moderatorConsent,
    },
  });
  typia.assert(moderatorSignUp);
  const moderatorId = moderatorSignUp.moderatorId;
  const moderatorToken = moderatorSignUp.setHeaders.Authorization;

  // 2. Login as moderator (check login/identity)
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  typia.assert(moderatorLogin);
  TestValidator.equals("moderator login id matches sign up")(moderatorLogin.moderatorId)(moderatorId);

  // Set connection for moderator
  connection.headers = { ...connection.headers, Authorization: moderatorToken };

  // 3. Register member (unique email/password)
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberPassword: string = "Member#12345";
  const memberSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  typia.assert(memberSignUp);
  const memberToken = memberSignUp.setHeaders.Authorization;

  // 4. Login as member to acquire real session
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });

  // 5. As admin/moderator, create notifications for self and member
  // Self notification
  const notifSelf = await api.functional.polEcoBoard.admin.notifications.create(connection, {
    body: {
      recipient_member_id: moderatorId,
      event_type: "moderation_action",
      status: "delivered",
    },
  });
  typia.assert(notifSelf);

  // Member notification
  // Use same logic as before, but with correct member id
  const notifMember = await api.functional.polEcoBoard.admin.notifications.create(connection, {
    body: {
      recipient_member_id: memberEmail === moderatorEmail ? typia.random<string & tags.Format<"uuid">>() : memberSignUp.setHeaders.Authorization,
      event_type: "admin_notice",
      status: "pending",
    },
  });
  typia.assert(notifMember);
  const memberId = notifMember.recipient_member_id;

  // 6. Search all notifications for moderator (self)
  const selfSearch = await api.functional.polEcoBoard.moderator.notifications.index(connection, {
    body: { recipient_member_id: moderatorId },
  });
  typia.assert(selfSearch);
  TestValidator.predicate("self notification present")(!!selfSearch.data.find((n) => n.id === notifSelf.id));

  // 7. Search notifications for member using recipient_member_id filter
  const memberSearch = await api.functional.polEcoBoard.moderator.notifications.index(connection, {
    body: { recipient_member_id: memberId },
  });
  typia.assert(memberSearch);
  TestValidator.predicate("member notification present")(!!memberSearch.data.find((n) => n.id === notifMember.id));

  // 8. Filtering: status
  const statusSearch = await api.functional.polEcoBoard.moderator.notifications.index(connection, {
    body: { status: "pending" },
  });
  typia.assert(statusSearch);
  TestValidator.predicate("pending notification present")(statusSearch.data.some((n) => n.status === "pending"));

  // Filtering: event_type
  const typeSearch = await api.functional.polEcoBoard.moderator.notifications.index(connection, {
    body: { event_type: "moderation_action" },
  });
  typia.assert(typeSearch);
  TestValidator.predicate("moderation_action notification present")(typeSearch.data.some((n) => n.event_type === "moderation_action"));

  // 9. Pagination: limit=1
  const paged = await api.functional.polEcoBoard.moderator.notifications.index(connection, {
    body: { limit: 1 },
  });
  typia.assert(paged);
  TestValidator.equals("one item page limit")(paged.data.length)(1);
  TestValidator.predicate("pagination fields")(typeof paged.pagination.current === "number" && typeof paged.pagination.pages === "number");

  // 10. Unauthorized: member tries to access moderator notifications endpoint
  connection.headers = { ...connection.headers, Authorization: memberToken };
  TestValidator.error("member cannot access moderator endpoint")(async () => {
    await api.functional.polEcoBoard.moderator.notifications.index(connection, {
      body: {},
    });
  });

  // 11. Expired or invalid token
  connection.headers = { ...connection.headers, Authorization: "Bearer invalidtoken" };
  TestValidator.error("invalid token denied")(async () => {
    await api.functional.polEcoBoard.moderator.notifications.index(connection, {
      body: { recipient_member_id: moderatorId },
    });
  });

  // 12. Invalid filter criteria (nonexistent status)
  connection.headers = { ...connection.headers, Authorization: moderatorToken };
  TestValidator.error("invalid filter fails")(async () => {
    await api.functional.polEcoBoard.moderator.notifications.index(connection, {
      body: { status: "not-a-real-status" },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotification";
import type { IPageIPolEcoBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardNotification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E test for administrative notification search, filtering, audit, and permission boundaries.
 *
 * Validates:
 * - Admin can list/search all notifications, with delivery/audit metadata for any user
 * - Filtering by recipient, event_type, status, time window, as well as pagination/sorting
 * - Audit/permission boundaries: only admins may access; others are denied
 * - Error handling for malformed queries (bad uuid, invalid page/limit)
 *
 * Steps:
 * 1. Register and log in as admin (set session)
 * 2. Register member and moderator recipients
 * 3. Create cross-role notifications (variation of event_types/status)
 * 4. Full search with no filter (check all fields/visibility)
 * 5. Filtering by recipient, event_type, and status
 * 6. Filtering by created_at windows
 * 7. Pagination with limit/page checks
 * 8. Negative: non-admin search deny
 * 9. Negative: error with invalid params
 */
export async function test_api_notification_search_admin_privileged_audit_and_filtering(connection: api.IConnection) {
  // 1. Admin registration
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPw = RandomGenerator.alphaNumeric(10);
  const adminReg = await api.functional.auth.admin.register.signUp(connection, {
    body: { email: adminEmail, password: adminPw } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminReg);

  // 2. Admin login (cred store in session)
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPw } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLogin);
  const adminConnection: api.IConnection = { ...connection, headers: { ...(connection.headers ?? {}), Authorization: adminLogin.setHeaders.Authorization } };

  // 3. Member registration (need id from JWT sub field)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPw = RandomGenerator.alphaNumeric(10);
  const memberReg = await api.functional.auth.member.register.signUp(connection, {
    body: { email: memberEmail, password: memberPw } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberReg);
  const memberToken = memberReg.setHeaders.Authorization.replace(/^Bearer /, "");
  const memberId = JSON.parse(atob(memberToken.split(".")[1])).sub as string;

  // 4. Moderator registration
  const modEmail = typia.random<string & tags.Format<"email">>();
  const modPw = RandomGenerator.alphaNumeric(12);
  const modReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: modEmail,
      password: modPw,
      display_name: RandomGenerator.name(),
      consent_status: "1",
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(modReg);
  const moderatorId = modReg.moderatorId;

  // 5. Create notifications for each user (member, moderator)
  const now = new Date();
  const eventTypes = ["reply", "moderation_action", "admin_notice"];
  const statuses = ["pending", "delivered"];
  const allRecipients = [memberId, moderatorId];
  const allNotes: IPolEcoBoardNotification[] = [];
  for (const rec of allRecipients) {
    for (const eventType of eventTypes) {
      for (const status of statuses) {
        const note = await api.functional.polEcoBoard.admin.notifications.create(adminConnection, {
          body: {
            recipient_member_id: rec,
            event_type: eventType,
            status,
            attempt_count: Math.floor(Math.random() * 3) + 1,
            related_object_id: typia.random<string & tags.Format<"uuid">>(),
            provider_id: Math.random() > 0.5 ? typia.random<string & tags.Format<"uuid">>() : null,
          } satisfies IPolEcoBoardNotification.ICreate,
        });
        typia.assert(note);
        allNotes.push(note);
      }
    }
  }

  // Admin notification to member (simulate self note)
  const adminSelfNote = await api.functional.polEcoBoard.admin.notifications.create(adminConnection, {
    body: {
      recipient_member_id: memberId,
      event_type: "admin_notice",
      status: "pending",
      attempt_count: 1,
      related_object_id: typia.random<string & tags.Format<"uuid">>(),
      provider_id: null,
    } satisfies IPolEcoBoardNotification.ICreate,
  });
  typia.assert(adminSelfNote);

  // 6. List all notifications (no filter, as admin)
  let results = await api.functional.polEcoBoard.admin.notifications.index(adminConnection, {
    body: {} satisfies IPolEcoBoardNotification.IRequest,
  });
  typia.assert(results);
  TestValidator.predicate("admin sees all notifications")(results.data.length >= allNotes.length);
  for (const note of results.data) {
    TestValidator.predicate("id present")(!!note.id);
    TestValidator.predicate("recipient present")(!!note.recipient_member_id);
    TestValidator.predicate("event_type present")(!!note.event_type);
    TestValidator.predicate("status present")(!!note.status);
    TestValidator.predicate("attempt_count >= 1")(note.attempt_count >= 1);
    TestValidator.predicate("created_at valid")(!!note.created_at);
    TestValidator.predicate("updated_at valid")(!!note.updated_at);
  }

  // 7. Filter by recipient
  for (const rec of allRecipients) {
    const filtered = await api.functional.polEcoBoard.admin.notifications.index(adminConnection, {
      body: { recipient_member_id: rec } satisfies IPolEcoBoardNotification.IRequest,
    });
    typia.assert(filtered);
    for (const n of filtered.data) {
      TestValidator.equals("recipient matches")(n.recipient_member_id)(rec);
    }
  }

  // 8. Filter by event_type
  for (const eventType of eventTypes) {
    const filtered = await api.functional.polEcoBoard.admin.notifications.index(adminConnection, {
      body: { event_type: eventType } satisfies IPolEcoBoardNotification.IRequest,
    });
    typia.assert(filtered);
    for (const n of filtered.data) {
      TestValidator.equals("event_type matches")(n.event_type)(eventType);
    }
  }

  // 9. Filter by status
  for (const status of statuses) {
    const filtered = await api.functional.polEcoBoard.admin.notifications.index(adminConnection, {
      body: { status } satisfies IPolEcoBoardNotification.IRequest,
    });
    typia.assert(filtered);
    for (const n of filtered.data) {
      TestValidator.equals("status matches")(n.status)(status);
    }
  }

  // 10. Date/time boundary filter
  const dates = allNotes.map(n => new Date(n.created_at));
  const minCreated = new Date(Math.min(...dates.map(d => d.valueOf()))).toISOString();
  const maxCreated = new Date(Math.max(...dates.map(d => d.valueOf()))).toISOString();
  const dateFilterRes = await api.functional.polEcoBoard.admin.notifications.index(adminConnection, {
    body: { created_from: minCreated, created_to: maxCreated } satisfies IPolEcoBoardNotification.IRequest,
  });
  typia.assert(dateFilterRes);
  TestValidator.predicate("date filter returns records")(dateFilterRes.data.length > 0);
  for (const n of dateFilterRes.data) {
    TestValidator.predicate("created_at in range")(n.created_at >= minCreated && n.created_at <= maxCreated);
  }

  // 11. Pagination - limit 1, page 1 and 2
  const page1 = await api.functional.polEcoBoard.admin.notifications.index(adminConnection, {
    body: { limit: 1, page: 1 } satisfies IPolEcoBoardNotification.IRequest,
  });
  typia.assert(page1);
  const page2 = await api.functional.polEcoBoard.admin.notifications.index(adminConnection, {
    body: { limit: 1, page: 2 } satisfies IPolEcoBoardNotification.IRequest,
  });
  typia.assert(page2);
  TestValidator.notEquals("page 1 and 2 results differ")(page1.data[0]?.id)(page2.data[0]?.id);

  // 12. Permission test: member tries admin search
  const memberConnection: api.IConnection = { ...connection, headers: { ...(connection.headers ?? {}), Authorization: memberReg.setHeaders.Authorization } };
  await TestValidator.error("non-admin denied notification search")(async () => {
    await api.functional.polEcoBoard.admin.notifications.index(memberConnection, {
      body: {} satisfies IPolEcoBoardNotification.IRequest,
    });
  });

  // 13. Invalid parameter: bad uuid, negative page/limit
  await TestValidator.error("bad UUID for recipient")(async () => {
    await api.functional.polEcoBoard.admin.notifications.index(adminConnection, {
      body: { recipient_member_id: "bad-uuid-value" as any } as any,
    });
  });
  await TestValidator.error("negative page/limit")(async () => {
    await api.functional.polEcoBoard.admin.notifications.index(adminConnection, {
      body: { limit: -1, page: -2 } as any,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotification";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate authorization and business logic for retrieving notification details by notificationId.
 *
 * Ensures that only the owning member can access their notification, enforces robust authentication boundaries,
 * verifies full field presence/audit metadata, and checks that access is denied for other users or missing/not-found/invalid tokens.
 *
 * Steps:
 * 1. Register Member A (notification recipient)
 * 2. Log in as Member A, store token
 * 3. As Member A, trigger admin notification creation targeting Member A
 * 4. Fetch notification details as owner and check all relevant fields
 * 5. Register and log in as Member B
 * 6. Attempt to fetch Member A's notification as Member B (should get denied)
 * 7. Attempt to fetch a random non-existent notificationId (should error)
 * 8. Invalidate Member A's token and ensure fetch fails (auth enforced)
 */
export async function test_api_notification_detail_member_authorization_and_audit(
  connection: api.IConnection
) {
  // 1. Register Member A
  const memberAEmail = typia.random<string & tags.Format<"email">>();
  const memberAPassword = typia.random<string & tags.Format<"password">>();
  const signUpA = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberAEmail,
      password: memberAPassword,
    },
  });
  typia.assert(signUpA);

  // 2. Log in as Member A and store the token
  const signInA = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberAEmail,
      password: memberAPassword,
    },
  });
  typia.assert(signInA);
  const memberAToken = signInA.setHeaders.Authorization;

  // 3. As Member A (token), create notification for Member A (simulate admin/system event)
  const memberAConn = { ...connection, headers: { ...(connection.headers ?? {}), Authorization: memberAToken } };
  const notification = await api.functional.polEcoBoard.admin.notifications.create(memberAConn, {
    body: {
      recipient_member_id: typia.random<string & tags.Format<"uuid">>(),
      provider_id: null,
      event_type: "reply",
      status: "pending",
      attempt_count: 0,
    },
  });
  typia.assert(notification);

  // 4. As Member A, fetch notification details and verify all fields are present/correct
  const output = await api.functional.polEcoBoard.member.notifications.at(memberAConn, {
    notificationId: notification.id,
  });
  typia.assert(output);
  TestValidator.equals("recipient match")(output.recipient_member_id)(notification.recipient_member_id);
  TestValidator.equals("event type")(output.event_type)(notification.event_type);
  TestValidator.equals("status")(output.status)(notification.status);
  TestValidator.equals("attempt count")(output.attempt_count)(notification.attempt_count);
  TestValidator.predicate("created_at format and presence")(typeof output.created_at === "string" && output.created_at.length > 0);
  TestValidator.predicate("updated_at format and presence")(typeof output.updated_at === "string" && output.updated_at.length > 0);

  // 5. Register and log in as Member B
  const memberBEmail = typia.random<string & tags.Format<"email">>();
  const memberBPassword = typia.random<string & tags.Format<"password">>();
  const signUpB = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberBEmail,
      password: memberBPassword,
    },
  });
  typia.assert(signUpB);

  const signInB = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberBEmail,
      password: memberBPassword,
    },
  });
  typia.assert(signInB);
  const memberBToken = signInB.setHeaders.Authorization;
  const memberBConn = { ...connection, headers: { ...(connection.headers ?? {}), Authorization: memberBToken } };

  // 6. Attempt to fetch Member A's notification as Member B
  await TestValidator.error("authorization - only owner can fetch notification")(() =>
    api.functional.polEcoBoard.member.notifications.at(memberBConn, { notificationId: notification.id })
  );

  // 7. Attempt to fetch a random non-existent notificationId
  await TestValidator.error("not-found - nonexistent notificationId")(() =>
    api.functional.polEcoBoard.member.notifications.at(memberBConn, { notificationId: typia.random<string & tags.Format<"uuid">>() })
  );

  // 8. Invalidate Member A's token and ensure auth enforcement
  const invalidConn = { ...connection, headers: { ...(connection.headers ?? {}), Authorization: "Bearer.invalid.token" } };
  await TestValidator.error("auth - invalid session token blocks access")(() =>
    api.functional.polEcoBoard.member.notifications.at(invalidConn, { notificationId: notification.id })
  );
}

