/**
 * Test logical deletion of a role transition record by admin.
 *
 * 1. Register a new admin account for authorization.
 * 2. Log in as the admin to obtain JWT authorization for protected endpoints.
 * 3. Create a member user to serve as the subject for a role transition.
 * 4. Create a new role transition for this member (e.g., promote to moderator), using a test admin/member id as the approver.
 * 5. Use the delete endpoint to logically remove (soft delete) the role transition by its unique ID.
 * 6. Attempt to delete the same role transition again and confirm an appropriate error occurs (e.g., not found or already deleted).
 * 7. Attempt to delete a randomly generated (non-existent) role transition ID and confirm an error is returned.
 *
 * Validates: admin authentication control; role transition creation; logical deletion by admin; appropriate error signaling for deletion of missing/invalid/previously deleted records.
 */
export async function test_api_role_transition_deletion_success_and_not_found(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin to acquire JWT for authentication
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberDisplayName = RandomGenerator.name();
  const member: IPolEcoBoardMember = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: RandomGenerator.alphaNumeric(32),
      display_name: memberDisplayName,
      consent_status: "agree-v1",
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // 4. Create role transition for that member (use member.id as approver test value for coverage)
  const roleTransition: IPolEcoBoardRoleTransition = await api.functional.polEcoBoard.admin.roleTransitions.create(connection, {
    body: {
      account_id: member.id,
      approved_by_admin_id: member.id, // For test, use member.id as dummy admin id
      origin_role: "member",
      destination_role: "moderator",
      reason: "Promotion for moderation",
      status: "completed",
      requested_at: new Date().toISOString(),
    } satisfies IPolEcoBoardRoleTransition.ICreate,
  });
  typia.assert(roleTransition);

  // 5. Delete the role transition by id
  await api.functional.polEcoBoard.admin.roleTransitions.erase(connection, {
    roleTransitionId: roleTransition.id,
  });

  // 6. Attempt to delete same (already deleted) role transition again - must error
  await TestValidator.error("deletion of already deleted returns error")(
    async () => {
      await api.functional.polEcoBoard.admin.roleTransitions.erase(connection, {
        roleTransitionId: roleTransition.id,
      });
    },
  );

  // 7. Attempt to delete a completely non-existent role transition
  await TestValidator.error("deletion of non-existent ID returns error")(
    async () => {
      await api.functional.polEcoBoard.admin.roleTransitions.erase(connection, {
        roleTransitionId: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
