import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardTag";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate error handling and permission enforcement for admin tag deletion.
 *
 * This test verifies two core business rules for tag deletion:
 *   1. Deleting a tag with an invalid (non-existent or already deleted) tagId returns a not found error.
 *   2. Attempting deletion without admin authentication (or with missing/insufficient permissions) returns a forbidden error.
 *
 * **Business context:**
 *   Tag taxonomy integrity is enforced by requiring strictly authorized admin credentials for all tag management operations. This ensures only privileged users can mutate the tag dataset, and robust error responses prevent information leakage and privilege escalation.
 *
 * **Test steps:**
 *   1. Register a system admin (to enable tag creation/deletion permissions)
 *   2. Login as that admin (to acquire JWT and session)
 *   3. Create a new unique tag and save its tagId
 *   4. Delete the created tag as admin (successful path to prep for error case)
 *   5. Attempt to delete the same tagId again (should yield not found error)
 *   6. Attempt to delete a truly random (never-valid) tagId (should yield not found error)
 *   7. Attempt to delete a tagId (from a fresh, new tag) with missing/invalid admin token (should yield forbidden error)
 *      - This step simulates an unauthenticated or unauthorized request
 */
export async function test_api_tag_deletion_not_found_and_permission_errors(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Login as admin to establish session
  const signInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResp);

  // 3. Create a tag
  const uniqueTag = {
    name: RandomGenerator.alphaNumeric(12),
    slug: RandomGenerator.alphaNumeric(12).toLowerCase(),
    description: RandomGenerator.alphaNumeric(32),
  } satisfies IPolEcoBoardTag.ICreate;
  const tag = await api.functional.polEcoBoard.admin.tags.create(connection, { body: uniqueTag });
  typia.assert(tag);

  // 4. Delete the created tag (should succeed as preparation)
  await api.functional.polEcoBoard.admin.tags.erase(connection, { tagId: tag.id });

  // 5. Attempt to delete same tag again (should yield not found error)
  await TestValidator.error("delete already-deleted tag yields not found error")(
    async () => {
      await api.functional.polEcoBoard.admin.tags.erase(connection, { tagId: tag.id });
    },
  );

  // 6. Attempt to delete a truly random tagId (should yield not found error)
  const fakeTagId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("delete never-existing tag yields not found error")(
    async () => {
      await api.functional.polEcoBoard.admin.tags.erase(connection, { tagId: fakeTagId });
    },
  );

  // 7. Create a new tag for forbidden test
  const tag2 = await api.functional.polEcoBoard.admin.tags.create(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(13),
      slug: RandomGenerator.alphaNumeric(13).toLowerCase(),
      description: RandomGenerator.alphaNumeric(20),
    } satisfies IPolEcoBoardTag.ICreate,
  });
  typia.assert(tag2);

  // Simulate missing/invalid authentication: deliberately remove admin session
  const unauthConnection = { ...connection, headers: { ...connection.headers } };
  delete unauthConnection.headers["Authorization"];

  // 8. Attempt to delete tag2 without authentication (should yield forbidden error)
  await TestValidator.error("unauthenticated tag deletion is forbidden")(
    async () => {
      await api.functional.polEcoBoard.admin.tags.erase(unauthConnection, { tagId: tag2.id });
    },
  );
}

