import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that an admin can retrieve a paginated, filtered list of votes on a comment for moderation and audit purposes.
 *
 * This test exercises the full moderation/audit workflow:
 * 1. Register and log in as admin to acquire privileged access for comment vote search.
 * 2. Register and log in as a member who will create a post, add a comment, and vote.
 * 3. The member creates a post in a randomly chosen category (using a random UUID for the test).
 * 4. The member adds a top-level comment to the post.
 * 5. The member casts an upvote for the comment.
 * 6. Re-authenticate as the admin and search votes on that comment using the admin API, with a paginated request (limit=10, page=1).
 * 7. Confirm that the vote is returned and the details (vote value, voter, comment id) are correct.
 * 8. Additionally, test filtering by voter_member_id and vote_value, and verify pagination/limit enforcement.
 * 9. Check that filtering for an unmatching vote_value (downvote) yields an empty result array.
 */
export async function test_api_comment_votes_search_admin_access(connection: api.IConnection) {
  // 1. Register and log in as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignUp
  });
  typia.assert(adminSignUpResp);

  const adminSignInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });
  typia.assert(adminSignInResp);

  // 2. Register and log in as member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const memberSignUpResp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    } satisfies IMemberAuthenticationMemberSignUp
  });
  typia.assert(memberSignUpResp);

  const memberSignInResp = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    } satisfies IMemberAuthenticationMemberSignIn
  });
  typia.assert(memberSignInResp);

  // 3. Member creates a post
  const category_id = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id,
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.paragraph()(20)
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);

  // 4. Member adds a comment
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(6)
    } satisfies IPolEcoBoardComment.ICreate
  });
  typia.assert(comment);

  // 5. Member casts an upvote for the comment
  const vote = await api.functional.polEcoBoard.member.comments.votes.create(connection, {
    commentId: comment.id,
    body: {
      vote_value: 1
    } satisfies IPolEcoBoardVote.ICreate
  });
  typia.assert(vote);

  // 6. Re-login as admin for vote searching
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword
    } satisfies IPolEcoBoardAdminAuth.SignIn
  });

  // 7. Admin searches votes for the comment (pagination, page=1, limit=10)
  const voteSearchResp = await api.functional.polEcoBoard.admin.comments.votes.search(connection, {
    commentId: comment.id,
    body: { comment_id: comment.id, limit: 10, page: 1 } satisfies IPolEcoBoardVote.IRequest
  });
  typia.assert(voteSearchResp);

  // 8. Validate that the vote info is present and accurate
  TestValidator.equals("returned vote count")(voteSearchResp.data.length)(1);
  const v = voteSearchResp.data[0];
  TestValidator.equals("comment id matches")(v.comment_id)(comment.id);
  TestValidator.equals("vote value matches")(v.vote_value)(1);

  // 9. Test filtering by voter_member_id should return the vote
  const filterByVoterResp = await api.functional.polEcoBoard.admin.comments.votes.search(connection, {
    commentId: comment.id,
    body: {
      comment_id: comment.id,
      voter_member_id: v.voter_member_id,
      limit: 10,
      page: 1
    } satisfies IPolEcoBoardVote.IRequest
  });
  typia.assert(filterByVoterResp);
  TestValidator.equals("filter by voter - count")(filterByVoterResp.data.length)(1);
  TestValidator.equals("voter matches")(filterByVoterResp.data[0].voter_member_id)(v.voter_member_id);

  // 10. Check filter by negative vote_value yields zero results
  const downvoteResp = await api.functional.polEcoBoard.admin.comments.votes.search(connection, {
    commentId: comment.id,
    body: { comment_id: comment.id, vote_value: -1, limit: 10, page: 1 } satisfies IPolEcoBoardVote.IRequest
  });
  typia.assert(downvoteResp);
  TestValidator.equals("no downvotes")(downvoteResp.data.length)(0);
}

