import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate successful updating of a moderation action record by an authenticated admin.
 *
 * This test ensures that the privileged admin workflow for updating an existing moderation action operates correctly from end to end. It validates authentication enforcement, business logic (field mutability), and correct reporting of updated values, including timestamp changes for auditing/compliance.
 *
 * Step-by-step process:
 * 1. Register a new admin using unique email and strong password
 * 2. Login as admin to issue JWT/set session
 * 3. Create a new moderation action (distinct business references)
 * 4. Update the moderation action's status, rationale, and outcome fields
 * 5. Confirm the API returns updated fields and that updated_at timestamp advances
 */
export async function test_api_admin_moderation_action_update_successful(connection: api.IConnection) {
  // 1. Register a new admin with unique email and strong password
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12); // minimum 8 chars
  const signUpOutput = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpOutput);

  // 2. Login as admin to get/set JWT session
  const signInOutput = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInOutput);

  // 3. Create a moderation action record (as admin)
  const reportId = typia.random<string & tags.Format<"uuid">>();
  const operatorId = typia.random<string & tags.Format<"uuid">>(); // In reality, should be the admin ID. No fetch in API, so generate.
  const createActionBody: IPolEcoBoardModerationAction.ICreate = {
    report_id: reportId,
    operator_id: operatorId,
    action_type: "warn",
    target_type: "post",
    status: "pending",
    rationale: "Initial warning for policy violation.",
    outcome: "accepted",
  };
  const moderationAction = await api.functional.polEcoBoard.admin.moderationActions.create(connection, {
    body: createActionBody,
  });
  typia.assert(moderationAction);

  // 4. Prepare and execute update of action (status, rationale, outcome)
  const updatedStatus = "completed";
  const updatedRationale = "Case reviewed and completed.";
  const updatedOutcome = "resolved";
  const updateActionBody: IPolEcoBoardModerationAction.IUpdate = {
    status: updatedStatus,
    rationale: updatedRationale,
    outcome: updatedOutcome,
  };
  const updatedAction = await api.functional.polEcoBoard.admin.moderationActions.update(connection, {
    moderationActionId: moderationAction.id,
    body: updateActionBody,
  });
  typia.assert(updatedAction);

  // 5. Assert updated fields/consistency & timestamps
  TestValidator.equals("status updated")(updatedAction.status)(updatedStatus);
  TestValidator.equals("rationale updated")(updatedAction.rationale)(updatedRationale);
  TestValidator.equals("outcome updated")(updatedAction.outcome)(updatedOutcome);
  TestValidator.predicate("updated_at changed")(updatedAction.updated_at !== moderationAction.updated_at);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
