/**
 * Validate that non-admin (member) users are forbidden from updating moderation actions via the admin update endpoint.
 *
 * Business context:
 * Moderation actions can only be modified by users with sufficient authority (admin/moderator). General members/members are not allowed to perform such updates. This test confirms that backend RBAC checks are robust and prevent privilege escalation or abuse via the moderation action update API.
 *
 * Step-by-step process:
 * 1. Register a member using random credentials (non-admin role).
 * 2. As the default authorized (admin) user, create a moderation action (to provide a valid target for update).
 * 3. Log in as the member to receive their JWT and apply it to the connection (token switching is handled by the SDK).
 * 4. As the member, attempt to update the moderation action.
 * 5. Validate the result: The API must reject the update, enforcing a permission/authorization error, and not leak or change moderation data.
 */
export async function test_api_admin_moderation_action_update_permission_denied(
  connection: api.IConnection
) {
  // 1. Register a member (non-admin)
  const email: string = typia.random<string & tags.Format<"email">>();
  const password: string = "P@ssw0rd!";
  const signupRes = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email,
      password
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(signupRes);

  // 2. Create a moderation action as admin/root
  const moderationAction = await api.functional.polEcoBoard.admin.moderationActions.create(connection, {
    body: {
      report_id: typia.random<string & tags.Format<"uuid">>(),
      operator_id: typia.random<string & tags.Format<"uuid">>(),
      action_type: "remove",
      target_type: "post",
      status: "pending",
      rationale: "E2E test: RBAC check for update",
      outcome: "under_review",
    } satisfies IPolEcoBoardModerationAction.ICreate,
  });
  typia.assert(moderationAction);

  // 3. Log in as the member (token replaced in-place in connection)
  const loginRes = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(loginRes);

  // 4. Attempt forbidden update as member
  await TestValidator.error("member update forbidden")(async () => {
    await api.functional.polEcoBoard.admin.moderationActions.update(connection, {
      moderationActionId: moderationAction.id,
      body: {
        status: "completed",
        rationale: "Member escalation attempt",
        outcome: "escalated",
      } satisfies IPolEcoBoardModerationAction.IUpdate,
    });
  });
}

