  // 6. Attempt to update with an excessively long rationale (should be rejected if limited)
  await TestValidator.error("update with excessive rationale length")(
    () => api.functional.polEcoBoard.admin.moderationActions.update(connection, {
      moderationActionId: moderationAction.id,
      body: {
        rationale: RandomGenerator.alphaNumeric(2000),
