import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardModerationAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAudit";
import type { IPageIPolEcoBoardModerationAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardModerationAudit";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test searching moderation audit logs for a moderation action as an admin (end-to-end, with pagination).
 *
 * Simulates realistic admin compliance/audit workflow:
 *   1. Register and login as a new admin.
 *   2. Create a moderation action (using admin id for operator).
 *   3. Create multiple audits for that moderation action (using admin id for auditor).
 *   4. Search audits via PATCH endpoint with pagination/filter params.
 *   5. Assert results return correct audit records, belonging to the correct moderationActionId, pagination structure is logical, and all field linkages are correct.
 *
 * Business rationale: Ensures only authorized admin can retrieve moderation action audit logs, confirms audit data consistency and that admin-facing reporting endpoints satisfy compliance/auditability needs. Also validates correct pagination structure.
 */
export async function test_api_admin_moderation_action_audit_search_success(connection: api.IConnection) {
  // Step 1: Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);

  const signUpResult = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResult);

  // Step 2: Log in as this admin (updates connection with JWT for protected endpoints)
  const signInResult = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResult);

  // The admin id for operator/auditor linkage is not returned by signup/login
  // We'll simulate it by generating a uuid for operator_id and use it throughout (in real world, would derive from context/session/jwt/userinfo API)
  const adminId = typia.random<string & tags.Format<"uuid">>();

  // Step 3: Create a moderation action
  const reportId = typia.random<string & tags.Format<"uuid">>();
  const actionProps = {
    report_id: reportId,
    operator_id: adminId,
    action_type: "edit",
    target_type: "post",
    status: "completed",
    rationale: RandomGenerator.paragraph()(),
    outcome: "accepted",
  } satisfies IPolEcoBoardModerationAction.ICreate;
  const moderationAction = await api.functional.polEcoBoard.admin.moderationActions.create(connection, {
    body: actionProps,
  });
  typia.assert(moderationAction);
  TestValidator.equals("moderationAction.operator_id should match adminId")(moderationAction.operator_id)(adminId);

  // Step 4: Create up to 3 audits for this moderation action
  const auditInputs = ArrayUtil.repeat(3)(i => {
    const preState = JSON.stringify({ status: "pending", updated_at: new Date(Date.now() - 1000 * (2 - i)).toISOString() });
    const postState = JSON.stringify({ status: "completed", updated_at: new Date(Date.now() - 1000 * (2 - i - 1)).toISOString() });
    return {
      moderation_action_id: moderationAction.id,
      auditor_id: adminId,
      pre_state_snapshot: preState,
      post_state_snapshot: postState,
      reason: `Audit rationale ${i + 1}`,
    } satisfies IPolEcoBoardModerationAudit.ICreate;
  });

  const audits: IPolEcoBoardModerationAudit[] = [];
  for (const auditInput of auditInputs) {
    const audit = await api.functional.polEcoBoard.admin.moderationActions.audits.create(connection, {
      moderationActionId: moderationAction.id,
      body: auditInput,
    });
    typia.assert(audit);
    TestValidator.equals("audit.moderation_action_id matches")(audit.moderation_action_id)(moderationAction.id);
    TestValidator.equals("audit.auditor_id matches")(audit.auditor_id)(adminId);
    audits.push(audit);
  }

  // Step 5: Search audits for this moderation action using PATCH (test basic and paginated retrieval)
  const searchBody: IPolEcoBoardModerationAudit.IRequest = {
    moderation_action_id: moderationAction.id,
    page: 1,
    limit: 2, // force pagination
  };

  const page1 = await api.functional.polEcoBoard.admin.moderationActions.audits.search(connection, {
    moderationActionId: moderationAction.id,
    body: searchBody,
  });
  typia.assert(page1);

  TestValidator.equals("pagination.current == 1")(page1.pagination.current)(1);
  TestValidator.equals("pagination.limit == 2")(page1.pagination.limit)(2);
  TestValidator.predicate(`page1.data audits correspond to moderationActionId; got: ${page1.data.map(a=>a.moderation_action_id).join(",")}`)
    (page1.data.every(a => a.moderation_action_id === moderationAction.id));
  TestValidator.predicate(`All returned audits auditorId == adminId`)
    (page1.data.every(a => a.auditor_id === adminId));
  TestValidator.equals("pagination.records")
    (page1.pagination.records)
    (audits.length);
  TestValidator.equals("pagination.pages")
    (page1.pagination.pages)
    (Math.ceil(audits.length / 2));

  // If more than limit, test page 2
  if (audits.length > 2) {
    const page2 = await api.functional.polEcoBoard.admin.moderationActions.audits.search(connection, {
      moderationActionId: moderationAction.id,
      body: {
        moderation_action_id: moderationAction.id,
        page: 2,
        limit: 2,
      },
    });
    typia.assert(page2);
    TestValidator.equals("pagination.current == 2")(page2.pagination.current)(2);
    TestValidator.equals("pagination.limit == 2")(page2.pagination.limit)(2);
    TestValidator.predicate(`page2.data audits correspond to moderationActionId; got: ${page2.data.map(a=>a.moderation_action_id).join(",")}`)
      (page2.data.every(a => a.moderation_action_id === moderationAction.id));
    TestValidator.predicate(`All returned audits auditorId == adminId`)
      (page2.data.every(a => a.auditor_id === adminId));
  }

  // Edge case: No access without admin token (skipped, as no non-admin context available in test)
}

