import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardNotificationPreference";
import type { IPageIPolEcoBoardNotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardNotificationPreference";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate that a moderator user can search for their own notification preferences using pagination and filter options.
 *
 * Test steps:
 * 1. Register a new moderator using the registration endpoint (capture email/password for login).
 * 2. Login as this moderator and ensure Authorization header is set for subsequent authenticated calls.
 * 3. Create a set of diverse notification preferences for this moderator, using various event_type/channel/opt_in combos, via the POST endpoint.
 * 4. Use the PATCH endpoint to search for preferences, varying parameters for:
 *    a. No filters (returns all for the moderator, paginated)
 *    b. Filter by event_type (one of those created above)
 *    c. Filter by channel (one of those created above)
 *    d. Filter by opt_in status (true/false)
 *    e. Pagination: request small limit & page through results, test edge case (results at boundaries)
 * 5. Validate for each search:
 *    - Only notification preferences for this moderator account are returned (member_id matches moderatorId)
 *    - All result records match the search filter
 *    - Pagination metadata reflects the correct number of total records (as can be confirmed from the created set)
 */
export async function test_api_moderator_notification_preference_search_by_self(connection: api.IConnection) {
  // 1. Register a new moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = RandomGenerator.alphaNumeric(10);
  const moderatorDisplayName = RandomGenerator.name();
  const consentStatus = "v1-policy-agree";

  const registration = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(registration);
  const moderatorId = registration.moderatorId;

  // 2. Log in as this moderator
  const login = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(login);

  // 3. Create diverse notification preferences
  const eventTypes = ["reply", "moderation_action", "new_topic", "system_alert"];
  const channels = ["email", "push", "in_app", "sms"];
  const optInMatrix = [true, false];
  // Total: 4*4*2 = 32 notification preferences
  const createdPrefs: IPolEcoBoardNotificationPreference[] = [];
  for (const event_type of eventTypes) {
    for (const channel of channels) {
      for (const opt_in of optInMatrix) {
        const pref = await api.functional.polEcoBoard.moderator.notificationPreferences.create(connection, {
          body: {
            member_id: moderatorId,
            event_type,
            channel,
            opt_in
          } satisfies IPolEcoBoardNotificationPreference.ICreate,
        });
        typia.assert(pref);
        createdPrefs.push(pref);
      }
    }
  }
  TestValidator.equals("created preference count")(createdPrefs.length)(eventTypes.length * channels.length * optInMatrix.length);
  // Used for later filter count checks

  // 4a. Search: No filters (all for moderator, paginated)
  const searchAll = await api.functional.polEcoBoard.moderator.notificationPreferences.search(connection, {
    body: {
      page: 1,
      limit: 32,
    } satisfies IPolEcoBoardNotificationPreference.IRequest,
  });
  typia.assert(searchAll);
  // Validate all returned records are for this moderator
  for (const pref of searchAll.data)
    TestValidator.equals("all prefs belong to moderator")(pref.member_id)(moderatorId);
  // Validate full set was returned
  TestValidator.equals("all prefs returned")(searchAll.data.length)(createdPrefs.length);
  TestValidator.equals("pagination records")(searchAll.pagination.records)(createdPrefs.length);

  // 4b. Search by event_type
  for (const eventType of eventTypes) {
    const filteredByEvent = createdPrefs.filter(x => x.event_type === eventType);
    const searchByEvent = await api.functional.polEcoBoard.moderator.notificationPreferences.search(connection, {
      body: {
        event_type: eventType,
        page: 1,
        limit: 32,
      } satisfies IPolEcoBoardNotificationPreference.IRequest,
    });
    typia.assert(searchByEvent);
    TestValidator.equals(`event_type '${eventType}' filter count`)(searchByEvent.data.length)(filteredByEvent.length);
    for (const pref of searchByEvent.data) {
      TestValidator.equals("event_type matches")(pref.event_type)(eventType);
      TestValidator.equals("member_id matches")(pref.member_id)(moderatorId);
    }
  }

  // 4c. Search by channel
  for (const channel of channels) {
    const filteredByChannel = createdPrefs.filter(x => x.channel === channel);
    const searchByChannel = await api.functional.polEcoBoard.moderator.notificationPreferences.search(connection, {
      body: {
        channel,
        page: 1,
        limit: 32,
      } satisfies IPolEcoBoardNotificationPreference.IRequest,
    });
    typia.assert(searchByChannel);
    TestValidator.equals(`channel '${channel}' filter count`)(searchByChannel.data.length)(filteredByChannel.length);
    for (const pref of searchByChannel.data) {
      TestValidator.equals("channel matches")(pref.channel)(channel);
      TestValidator.equals("member_id matches")(pref.member_id)(moderatorId);
    }
  }

  // 4d. Search by opt_in status
  for (const optIn of optInMatrix) {
    const filteredByOpt = createdPrefs.filter(x => x.opt_in === optIn);
    const searchByOpt = await api.functional.polEcoBoard.moderator.notificationPreferences.search(connection, {
      body: {
        opt_in: optIn,
        page: 1,
        limit: 32,
      } satisfies IPolEcoBoardNotificationPreference.IRequest,
    });
    typia.assert(searchByOpt);
    TestValidator.equals(`opt_in='${optIn}' filter count`)(searchByOpt.data.length)(filteredByOpt.length);
    for (const pref of searchByOpt.data) {
      TestValidator.equals("opt_in matches")(pref.opt_in)(optIn);
      TestValidator.equals("member_id matches")(pref.member_id)(moderatorId);
    }
  }

  // 4e. Pagination edge: page through with small limit, check for correct non-overlapping, correct union of all ids
  const pagedLimit = 5;
  const totalPages = Math.ceil(createdPrefs.length / pagedLimit);
  let allPagedIds: string[] = [];
  for (let page = 1; page <= totalPages; page++) {
    const pageResult = await api.functional.polEcoBoard.moderator.notificationPreferences.search(connection, {
      body: {
        page,
        limit: pagedLimit,
      } satisfies IPolEcoBoardNotificationPreference.IRequest,
    });
    typia.assert(pageResult);
    for (const pref of pageResult.data) {
      TestValidator.equals("member_id matches in paging")(pref.member_id)(moderatorId);
      // Ids must not repeat across pages
      TestValidator.predicate(`unique id in pages: ${pref.id}`)(!allPagedIds.includes(pref.id));
      allPagedIds.push(pref.id);
    }
  }
  // The union of paged ids must cover all
  TestValidator.equals("paged id union covers all")(allPagedIds.length)(createdPrefs.length);
  for (const id of allPagedIds)
    TestValidator.predicate(`id found in createdPrefs`)(createdPrefs.some(p => p.id === id));
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
