import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate admin's ability to view a specific comment report (detail view).
 *
 * Business Context:
 * Ensure that an admin user can retrieve the full detail of a filed report on a comment, including all audit/moderation/abuse fields. This verifies proper admin access, exposes sensitive fields for moderation review, and enforces correct permission boundaries — only admins may succeed; errors are thrown when misusing IDs or role.
 *
 * Steps:
 * 1. Register a new admin (and obtain credentials)
 * 2. Login as the admin (activates admin session/token)
 * 3. Create a post as a member (prereq for comment)
 * 4. Create a comment on the post (as member)
 * 5. File a report for the comment (as member)
 * 6. As the admin, fetch the report detail (expect success, all fields match what was filed in step 5)
 * 7. Attempt to fetch with an invalid reportId (expect error)
 * 8. Attempt to fetch with a mismatched commentId (expect error)
 * 9. Attempt to fetch report as a non-admin (wrong role or no token, expect error)
 */
export async function test_api_comment_report_detail_view_admin_role(connection: api.IConnection) {
  // Step 1: Register a new admin (unique credentials)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminRegisterOut = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminRegisterOut);

  // Step 2: Login as this admin (get valid token)
  const adminLoginOut = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLoginOut);

  // The connection now carries admin privileges for privileged requests

  // Step 3: Create a post as member (not possible to simulate real member auth in this context; but API accepts member actions if connection permits)
  // Fake a valid category_id for post (as schema allows any UUID here, and test is not about this logic)
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.paragraph()(50),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // Step 4: Create a comment on the post.
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(8),
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment);

  // Step 5: File a report against the comment
  const reportReason = "abuse";
  const reportDesc = RandomGenerator.paragraph()(10);
  const report = await api.functional.polEcoBoard.member.comments.reports.create(connection, {
    commentId: comment.id,
    body: {
      reason_code: reportReason,
      reason_description: reportDesc,
      comment_id: comment.id,
    } satisfies IPolEcoBoardReport.ICreate,
  });
  typia.assert(report);

  // Step 6: As admin, fetch the report detail by (commentId,reportId)
  const fetched = await api.functional.polEcoBoard.admin.comments.reports.at(connection, {
    commentId: comment.id,
    reportId: report.id,
  });
  typia.assert(fetched);
  // Validate all critical fields match
  TestValidator.equals("report id")(fetched.id)(report.id);
  TestValidator.equals("comment id")(fetched.comment_id)(report.comment_id);
  TestValidator.equals("reason_code")(fetched.reason_code)(report.reason_code);
  TestValidator.equals("reason_description")(fetched.reason_description)(report.reason_description);
  TestValidator.equals("reporter_member_id")(fetched.reporter_member_id)(report.reporter_member_id);
  TestValidator.equals("created_at")(fetched.created_at)(report.created_at);

  // Step 7: Try to fetch with non-existent reportId (should error)
  await TestValidator.error("not found reportId")(() =>
    api.functional.polEcoBoard.admin.comments.reports.at(connection, {
      commentId: comment.id,
      reportId: typia.random<string & tags.Format<"uuid">>(), // random unassociated report
    }),
  );

  // Step 8: Try to fetch same reportId, but mismatched/wrong commentId (should error)
  await TestValidator.error("mismatched commentId")(() =>
    api.functional.polEcoBoard.admin.comments.reports.at(connection, {
      commentId: typia.random<string & tags.Format<"uuid">>(), // wrong commentId
      reportId: report.id,
    }),
  );

  // Step 9: Try to fetch as non-admin (simulate by clearing connection.headers.Authorization)
  // Save old token, remove Authorization, try API, restore
  const oldAuth = connection.headers?.Authorization;
  if (connection.headers) delete connection.headers.Authorization;
  await TestValidator.error("forbidden for non-admin")(() =>
    api.functional.polEcoBoard.admin.comments.reports.at(connection, {
      commentId: comment.id,
      reportId: report.id,
    }),
  );
  // Restore admin token
  if (connection.headers && oldAuth) connection.headers.Authorization = oldAuth;
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPageIPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * E2E test for member role advanced post search with filtering and pagination.
 *
 * This test validates that a registered, logged-in member can retrieve a filtered, paginated list of post summaries using the /polEcoBoard/member/posts API. It focuses on verifying that only accessible posts (not flagged/deleted unless policy allows) are returned, pagination metadata is correct, and business logic such as visibility and filtering is enforced.
 *
 * Steps:
 * 1. Register a new member using the /polEcoBoard/members endpoint with unique account details.
 * 2. Log in as that member using /auth/member/login with their email and password to obtain the API access token (Authorization header is set automatically on the connection object).
 * 3. Perform a search for posts (via /polEcoBoard/member/posts) with various pagination and filter criteria (category, keywords, tags, date, active/unflagged status).
 * 4. Validate the response: ensure the returned posts are limited to those the member should see, response includes correct pagination metadata, and all filter criteria are respected.
 *    - Specially check that flagged or deleted posts are not included (unless policy or permissions change in the future).
 *    - Use multiple filters and paging options: valid results with data, no results for out-of-bounds pages, and empty result set when filters exclude all posts.
 * 5. Validate edge cases (empty result, exceeding page bounds, and only active/unflagged posts shown).
 */
export async function test_api_post_search_member_role_success_filter_pagination(connection: api.IConnection) {
  // 1. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  const memberDisplayName = RandomGenerator.name();
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: memberDisplayName,
      profile_image_uri: null,
      consent_status: "v1.0"
    } satisfies IPolEcoBoardMember.ICreate
  });
  typia.assert(member);

  // 2. Login as the created member
  const login = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword
    } satisfies IMemberAuthenticationMemberSignIn
  });
  typia.assert(login);

  // 3. Perform post search with various filter and pagination criteria
  // --- Round 1: Default (most permissive) search, expect only non-flagged/non-deleted posts
  const searchFilters = {
    page: 1,
    limit: 10,
    flagged: false,
    deleted: false,
    order_by: "created_at",
    order_dir: "desc",
    with_tags: false
  } satisfies IPolEcoBoardPost.IRequest;

  const page1 = await api.functional.polEcoBoard.member.posts.search(connection, {
    body: searchFilters,
  });
  typia.assert(page1);

  TestValidator.equals("pagination.limit")(page1.pagination.limit)(10);
  TestValidator.equals("pagination.current")(page1.pagination.current)(1);
  TestValidator.predicate("pagination pages >= 1")(page1.pagination.pages >= 1);

  for (const summary of page1.data) {
    TestValidator.equals("flagged is false for all returned posts")(summary.flagged)(false);
  }

  // --- Round 2: Edge case - Request page outside of range (should return empty array with correct pagination)
  const outOfBoundsPage = (page1.pagination.pages || 1) + 1;
  const outOfBoundsFilters = { ...searchFilters, page: outOfBoundsPage } satisfies IPolEcoBoardPost.IRequest;
  const emptyPage = await api.functional.polEcoBoard.member.posts.search(connection, {
    body: outOfBoundsFilters,
  });
  typia.assert(emptyPage);
  TestValidator.equals("empty result set for out-of-bounds page")(emptyPage.data.length)(0);

  // --- Round 3: Keyword search with unlikely string (should return empty array)
  const keyword = `unlikely_keyword_${RandomGenerator.alphaNumeric(10)}`;
  const keywordFilters = { ...searchFilters, search: keyword } satisfies IPolEcoBoardPost.IRequest;
  const keywordPage = await api.functional.polEcoBoard.member.posts.search(connection, {
    body: keywordFilters,
  });
  typia.assert(keywordPage);
  TestValidator.equals("empty result for unmatched keyword")(keywordPage.data.length)(0);
}

