 *
 * Workflow:
 * 1. Register a new admin.
 * 2. Login as the registered admin to obtain credentials.
 * 3. Using authenticated admin connection, create a third-party audit log with valid payload (all required fields, valid formats).
 * 4. Assert successful response. Validate the returned log data matches input and correct metadata is present (e.g. id is uuid, created_at is ISO8601, etc).
 * 5. Attempt creation with missing required fields (such as omitting provider_key) and invalid field formats to verify validation handling (should return error).
 * 6. Attempt creation as an unauthenticated (non-admin) user; assert permission error (should not allow creation).
 */
export async function test_api_third_party_audit_log_creation_success_and_validation_error(connection: api.IConnection) {
  // 1. Register admin (get random unique admin email & password, ensure password satisfies minLength 8)
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = RandomGenerator.alphaNumeric(12); // between 8-128 chars
  const adminSignUpResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUpResponse);

  // 2. Login as the just-registered admin to establish a privileged session
  const adminLoginResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLoginResponse);

  // 3. Create a valid audit log as admin
  const auditLogPayload = {
    provider_key: 'google',
    event_type: 'api_call',
    event_payload: JSON.stringify({ query: 'user_auth', result: 'success' }),
    result_code: 'success',
    correlation_id: typia.random<string & tags.Format<'uuid'>>(),
  } satisfies IPolEcoBoardThirdPartyAuditLog.ICreate;

  const createdLog = await api.functional.polEcoBoard.admin.thirdPartyAuditLogs.create(connection, {
    body: auditLogPayload,
  });
  typia.assert(createdLog);
  TestValidator.equals('provider_key')(createdLog.provider_key)('google');
  TestValidator.equals('event_type')(createdLog.event_type)('api_call');
  TestValidator.equals('result_code')(createdLog.result_code)('success');
  TestValidator.equals('event_payload')(createdLog.event_payload)(auditLogPayload.event_payload);
  TestValidator.predicate('created_at ISO8601')(!!Date.parse(createdLog.created_at));
  TestValidator.predicate('id is uuid')(/^[0-9a-fA-F-]{36}$/.test(createdLog.id));

  // 4. Try creating an audit log with missing required field (provider_key missing)
  await TestValidator.error('missing required provider_key')(async () => {
    const invalidPayload = {
      // provider_key is missing
      event_type: 'auth_flow_start',
      event_payload: JSON.stringify({ step: 1 }),
      result_code: 'failure',
    } as unknown as IPolEcoBoardThirdPartyAuditLog.ICreate;
    await api.functional.polEcoBoard.admin.thirdPartyAuditLogs.create(connection, {
      body: invalidPayload,
    });
  });

  // 5. Try creating an audit log with invalid event_payload (should be string but passing an object)
  await TestValidator.error('invalid event_payload type')(async () => {
