import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardAuditTrail } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAuditTrail";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate admin can successfully update an existing audit trail record (for permissible fields only).
 *
 * Business context:
 * Platform requires immutable regulatory audit trails for compliance. Certain metadata (e.g., context/note) can be appended by admin for correction/comment, but most fields must remain immutable and cannot be changed. All such updates themselves must generate their own immutable audit entries.
 *
 * Process overview:
 * 1. Register a new admin account (provides a unique admin email and password, stores JWT)
 * 2. Login as the newly registered admin (obtain session/JWT, connection headers updated)
 * 3. Create a new audit trail record as this admin (must provide required ICreate content)
 * 4. Update the audit trail record using the update endpoint, changing permissible fields (context/note)
 * 5. Check that returned audit trail record reflects updated permissible fields (context changed), but immutable fields (action type, performed_by_id, etc.) are unchanged
 * 6. Confirm (as much as possible with available APIs) that an audit trail for the update itself was generated, or that the returned record is compliant
 */
export async function test_api_audit_trail_update_successful_admin(connection: api.IConnection) {
  // 1. Register a new admin account
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as the new admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create a new audit trail record as this admin
  const auditCreateInput: IPolEcoBoardAuditTrail.ICreate = {
    action_type: "CONFIG_CHANGE",
    performed_by_id: typia.random<string & tags.Format<"uuid">>(),
    target_resource: typia.random<string>(),
    audit_context: "Initial audit entry for compliance.",
    recorded_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const originalRecord = await api.functional.polEcoBoard.admin.auditTrails.create(connection, {
    body: auditCreateInput,
  });
  typia.assert(originalRecord);

  // 4. Update the audit trail - only updating permissible metadata (context)
  const updatedContext = "Updated context note for compliance.";
  const updated = await api.functional.polEcoBoard.admin.auditTrails.update(connection, {
    auditTrailId: originalRecord.id,
    body: {
      audit_context: updatedContext,
    } satisfies IPolEcoBoardAuditTrail.IUpdate,
  });
  typia.assert(updated);

  // 5. Validate that the record is updated as expected
  TestValidator.equals("audit_context was updated")(updated.audit_context)(updatedContext);
  TestValidator.equals("action_type immutable")(updated.action_type)(originalRecord.action_type);
  TestValidator.equals("performed_by_id immutable")(updated.performed_by_id)(originalRecord.performed_by_id);
  TestValidator.equals("target_resource immutable")(updated.target_resource)(originalRecord.target_resource);
  TestValidator.equals("recorded_at immutable")(updated.recorded_at)(originalRecord.recorded_at);

  // updated_at should reflect the update and be after or equal to created_at
  TestValidator.predicate("updated_at should be >= created_at")(
    updated.updated_at >= updated.created_at,
  );

  // 6. (If more API endpoints existed: Confirm a new audit entry for this update was added)
  // For now, only validate as much as allowed by public API response
}

