/**
 * Validate search, pagination, and filtering of incidents as an admin.
 *
 * This test ensures that incident search functionality for admins correctly supports:
 * - Registration and authentication of an admin account for access
 * - Creation of multiple incident records with varying categories/statuses/codes
 * - Pagination metadata (total records, page size, page numbers are accurate)
 * - Filtering by incident_code, category, and status
 * - Correct data shape and all incidents are non-deleted
 * - Paging and data distinction across result pages
 *
 * Step-by-step process:
 * 1. Register a new admin account with unique credentials
 * 2. Login as that admin to obtain Authorization
 * 3. Create multiple incidents with diverse fields (category/status/code/detected_at)
 * 4. Search for all incidents (limit 2, page 1); verify pagination and field correctness
 * 5. Search incidents filtered by code (expect 1 result with exact match)
 * 6. Search incidents filtered by status (all returned must match given status)
 * 7. Search incidents filtered by category (all returned must match given category)
 * 8. Search for next page (page 2); verify correct records and non-overlap
 * 9. Assert data types/fields for all records using typia.assert
 */
export async function test_api_incident_search_pagination_and_filters(connection: api.IConnection) {
  // 1. Register new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
