/**
 * Validates admin vote search, with pagination and filtering, for a specific post in polEcoBoard.
 *
 * This test covers the full admin workflow for reviewing votes on a post with various filters and paginated result handling.
 *
 * Steps:
 * 1. Register a new admin account and log in (admin authentication context)
 * 2. Register two member accounts and log in both (to generate different voter_member_id)
 * 3. Member 1 creates a post under a random category
 * 4. Member 1 upvotes the post
 * 5. Member 2 downvotes the post
 * 6. Additional votes from extra members for pagination
 * 7. Admin searches all votes for the post (no filter) and checks that all votes are returned and valid
 * 8. Admin filters by voter_member_id and vote_value to verify filtering
 * 9. Test pagination with low limit; validate coverage and non-overlap between pages
 */
export async function test_api_post_votes_admin_search_success_and_filters(connection: api.IConnection) {
  // --- 1. Register admin account ---
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(10);
  const adminSignUpResult = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUpResult);

  // --- 2. Log in as admin ---
  const adminSignInResult = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminSignInResult);

  // --- 3. Register Member 1 & log in ---
  const member1Email = typia.random<string & tags.Format<"email">>();
  const member1Password = RandomGenerator.alphaNumeric(10);
  const member1SignUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: member1Email,
      password: member1Password,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(member1SignUpResult);

  const member1SignInResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: member1Email,
      password: member1Password,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(member1SignInResult);

  // --- 4. Register Member 2 & log in ---
  const member2Email = typia.random<string & tags.Format<"email">>();
  const member2Password = RandomGenerator.alphaNumeric(10);
  const member2SignUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: member2Email,
      password: member2Password,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(member2SignUpResult);

  const member2SignInResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: member2Email,
      password: member2Password,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(member2SignInResult);

  // --- 5. Member 1 creates a post ---
  // Assume a random valid category UUID and no tags/attachments for simplicity
  const postCategoryId = typia.random<string & tags.Format<"uuid">>();
  const postTitle = RandomGenerator.paragraph()(15);
  const postBody = RandomGenerator.content()()(100);
  const createdPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: postCategoryId,
      title: postTitle,
      body: postBody,
      tag_ids: [],
      attachments: [],
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(createdPost);

  // For gathering correct voter_member_id values, retrieve member1's UUID from post author afterward
  const postId = createdPost.id;
  const authorId = createdPost.author_member_id;

  // --- 6. Member 1 (author) upvotes their post ---
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: member1Email,
      password: member1Password,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  const vote1 = await api.functional.polEcoBoard.member.posts.votes.create(connection, {
    postId,
    body: {
      vote_value: 1,
    } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(vote1);

  // --- 7. Member 2 downvotes the same post ---
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: member2Email,
      password: member2Password,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  const vote2 = await api.functional.polEcoBoard.member.posts.votes.create(connection, {
    postId,
    body: {
      vote_value: -1,
    } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(vote2);

  // --- 8. Create more voters for pagination (e.g., add 5 more upvotes and 3 more downvotes) ---
  const extraVoters: Array<{ email: string; password: string; vote_value: 1 | -1; vote_response?: IPolEcoBoardVote }> = [];
  for (let i = 0; i < 8; ++i) {
    const isUpvote = i < 5;
    const email = typia.random<string & tags.Format<"email">>();
    const password = RandomGenerator.alphaNumeric(10);
    // Register and login
    await api.functional.auth.member.register.signUp(connection, {
      body: { email, password } satisfies IMemberAuthenticationMemberSignUp,
    });
    await api.functional.auth.member.login.signIn(connection, {
      body: { email, password } satisfies IMemberAuthenticationMemberSignIn,
    });
    // Vote
    const vote = await api.functional.polEcoBoard.member.posts.votes.create(connection, {
      postId,
      body: { vote_value: isUpvote ? 1 : -1 } satisfies IPolEcoBoardVote.ICreate,
    });
    typia.assert(vote);
    extraVoters.push({ email, password, vote_value: isUpvote ? 1 : -1, vote_response: vote });
  }

  // Collect all voter_member_id and value for reference
  const allVotes: Array<{ voter_member_id: string; vote_value: 1 | -1 }> = [
    { voter_member_id: vote1.voter_member_id, vote_value: 1 },
    { voter_member_id: vote2.voter_member_id, vote_value: -1 },
    ...extraVoters.map(x => ({ voter_member_id: x.vote_response!.voter_member_id, vote_value: x.vote_value })),
  ];

  // Total upvotes/downvotes for later assertions
  const totalUpvotes = allVotes.filter(v => v.vote_value === 1).length;
  const totalDownvotes = allVotes.filter(v => v.vote_value === -1).length;
  const totalVotes = allVotes.length;

  // --- 9. Switch to admin by logging in again ---
  await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // --- 10. Admin searches all votes for the post (no filters) ---
  const searchAll = await api.functional.polEcoBoard.admin.posts.votes.search(connection, {
    postId,
    body: { post_id: postId } satisfies IPolEcoBoardVote.IRequest,
  });
  typia.assert(searchAll);
  TestValidator.equals("total vote count")(searchAll.pagination.records)(totalVotes);
  // All votes accounted for
  const returnedVoters = searchAll.data.map((v) => v.voter_member_id);
  for (const { voter_member_id } of allVotes) {
    TestValidator.predicate(`Vote present for voter ${voter_member_id}`)(returnedVoters.includes(voter_member_id));
  }
  // All vote values are valid
  for (const v of searchAll.data) {
    TestValidator.predicate("Vote value must be either 1 or -1")(v.vote_value === 1 || v.vote_value === -1);
  }

  // --- 11. Filter by voter_member_id (pick one with upvote) ---
  const upvoters = allVotes.filter(v => v.vote_value === 1);
  if (upvoters.length > 0) {
    const voterToCheck = upvoters[0].voter_member_id;
    const searchByVoter = await api.functional.polEcoBoard.admin.posts.votes.search(connection, {
      postId,
      body: { post_id: postId, voter_member_id: voterToCheck } satisfies IPolEcoBoardVote.IRequest,
    });
    typia.assert(searchByVoter);
    for (const r of searchByVoter.data) {
      TestValidator.equals("Filtered by voter_member_id")(r.voter_member_id)(voterToCheck);
    }
  }

  // --- 12. Filter by vote_value (-1) ---
  const searchDownvotes = await api.functional.polEcoBoard.admin.posts.votes.search(connection, {
    postId,
    body: { post_id: postId, vote_value: -1 } satisfies IPolEcoBoardVote.IRequest,
  });
  typia.assert(searchDownvotes);
  for (const r of searchDownvotes.data) {
    TestValidator.equals("Filtered by vote_value -1")(r.vote_value)(-1);
  }

  // --- 13. Test pagination: limit = 3 ---
  const limit = 3;
  const searchPage1 = await api.functional.polEcoBoard.admin.posts.votes.search(connection, {
    postId,
    body: { post_id: postId, page: 1, limit } satisfies IPolEcoBoardVote.IRequest,
  });
  typia.assert(searchPage1);
  TestValidator.equals("pagination: page 1 limit")(searchPage1.pagination.limit)(limit);
  const searchPage2 = await api.functional.polEcoBoard.admin.posts.votes.search(connection, {
    postId,
    body: { post_id: postId, page: 2, limit } satisfies IPolEcoBoardVote.IRequest,
  });
  typia.assert(searchPage2);
  TestValidator.equals("pagination: page 2 limit")(searchPage2.pagination.limit)(limit);
  // No overlap between page 1 and page 2
  const p1Ids = searchPage1.data.map(v => v.id);
  const p2Ids = searchPage2.data.map(v => v.id);
  for (const id of p1Ids) {
    TestValidator.predicate("Pagination non-overlap: page 1 and 2")(p2Ids.includes(id) === false);
  }
  // Total results from all pages (should match totalVotes)
  const pagedTotal = searchPage1.pagination.records;
  TestValidator.equals("Paged total equals all votes")(pagedTotal)(totalVotes);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate retrieval of a member's own vote on a post, and rejection of invalid or unauthorized accesses.
 *
 * This test covers the following flows:
 * 1. Register as a member (user A), and log in to get a connection with authentication.
 * 2. Create a new post as the logged-in member.
 * 3. Cast a vote (upvote or downvote) on the post as the logged-in member.
 * 4. Retrieve the vote just cast using its voteId and postId, and verify that all details match the cast vote.
 * 5. Try to retrieve a vote with a random/non-existent voteId on the same post; confirm error is thrown.
 * 6. Register and log in as a different member (user B).
 * 7. As user B, attempt to retrieve user A's vote; confirm permission denial or error is thrown.
 */
export async function test_api_post_vote_member_retrieve_own_vote_success_and_errors(
  connection: api.IConnection,
) {
  // 1. Register user A
  const memberAEmail = typia.random<string & tags.Format<"email">>();
  const memberAPassword = typia.random<string & tags.Format<"password">>();
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberAEmail,
      password: memberAPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });

  // 2. Log in as user A
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberAEmail,
      password: memberAPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // 3. Create a post as user A
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: "Test Post for Vote Retrieval",
      body: "This is a post created to test retrieval of the member's own vote.",
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Cast a vote as user A
  const voteValue: 1 | -1 = RandomGenerator.pick([1, -1]);
  const vote = await api.functional.polEcoBoard.member.posts.votes.create(connection, {
    postId: post.id,
    body: {
      vote_value: voteValue,
    } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(vote);

  // 5. Retrieve the vote using postId and voteId, verify details
  const retrievedVote = await api.functional.polEcoBoard.member.posts.votes.at(connection, {
    postId: post.id,
    voteId: vote.id,
  });
  typia.assert(retrievedVote);
  TestValidator.equals("vote id matches")(retrievedVote.id)(vote.id);
  TestValidator.equals("post id matches")(retrievedVote.post_id)(post.id);
  TestValidator.equals("vote value matches")(retrievedVote.vote_value)(voteValue);

  // 6. Try to retrieve a non-existent vote (random voteId)
  await TestValidator.error("non-existent voteId returns error")(async () => {
    await api.functional.polEcoBoard.member.posts.votes.at(connection, {
      postId: post.id,
      voteId: typia.random<string & tags.Format<"uuid">>(),
    });
  });

  // 7. Register and log in as user B
  const memberBEmail = typia.random<string & tags.Format<"email">>();
  const memberBPassword = typia.random<string & tags.Format<"password">>();
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberBEmail,
      password: memberBPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberBEmail,
      password: memberBPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });

  // 8. As user B (now logged in), attempt to retrieve user A's vote
  await TestValidator.error("cannot access another member's vote")(async () => {
    await api.functional.polEcoBoard.member.posts.votes.at(connection, {
      postId: post.id,
      voteId: vote.id,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that an admin can retrieve any vote record by postId and voteId.
 *
 * Business context: This test ensures that admin-level API permissions allow retrieving any vote record for any post, regardless of the voting user. It must also confirm that non-admins cannot do so, and that proper error handling occurs for invalid identifiers.
 *
 * Steps:
 * 1. Register and login an admin account.
 * 2. Register and login two member accounts.
 * 3. As member1, create a post.
 * 4. As member1 and member2, each cast a vote on the post (cover both upvote/downvote).
 * 5. As admin, retrieve both votes using the admin endpoint and confirm full access/details for both votes.
 * 6. As admin, attempt to retrieve a non-existent vote and confirm error response occurs.
 * 7. As a regular member (non-admin), attempt to retrieve a vote using the admin endpoint and verify access is denied.
 */
export async function test_api_post_vote_admin_retrieve_any_vote_permissions(connection: api.IConnection) {
  // Helper functions for switching identity
  async function admin_register_and_login(email: string, password: string) {
    // Register
    const reg = await api.functional.auth.admin.register.signUp(connection, {
      body: { email, password } satisfies IPolEcoBoardAdminAuth.SignUp,
    });
    typia.assert(reg);
    // Login
    const login = await api.functional.auth.admin.login.signIn(connection, {
      body: { email, password } satisfies IPolEcoBoardAdminAuth.SignIn,
    });
    typia.assert(login);
    // Set token
    connection.headers = { ...(connection.headers ?? {}), Authorization: login.setHeaders.Authorization };
  }

  async function member_register_and_login(email: string, password: string) {
    const reg = await api.functional.auth.member.register.signUp(connection, {
      body: { email, password } satisfies IMemberAuthenticationMemberSignUp,
    });
    typia.assert(reg);
    // Login
    const login = await api.functional.auth.member.login.signIn(connection, {
      body: { email, password } satisfies IMemberAuthenticationMemberSignIn,
    });
    typia.assert(login);
    connection.headers = { ...(connection.headers ?? {}), Authorization: login.setHeaders.Authorization };
  }

  // 1. Register and login an admin
  const admin_email = typia.random<string & tags.Format<"email">>();
  const admin_password = RandomGenerator.alphaNumeric(12);
  await admin_register_and_login(admin_email, admin_password);

  // 2. Register and login two members
  const member1_email = typia.random<string & tags.Format<"email">>();
  const member2_email = typia.random<string & tags.Format<"email">>();
  const member1_password = RandomGenerator.alphaNumeric(12);
  const member2_password = RandomGenerator.alphaNumeric(12);

  await member_register_and_login(member1_email, member1_password);
  // Keep to get author_member_id of member1
  // 3. As member1, create a post
  const category_id = typia.random<string & tags.Format<"uuid">>(); // Use random category_id
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.paragraph()(2),
      // Optionals left blank
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);
  // Save member1 id to confirm in votes later
  const member1_id = post.author_member_id;

  // 4. As member1, cast a vote (upvote)
  const vote1 = await api.functional.polEcoBoard.member.posts.votes.create(connection, {
    postId: post.id,
    body: { vote_value: 1 } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(vote1);

  // As member2, log in and cast a vote (downvote)
  await member_register_and_login(member2_email, member2_password);
  const vote2 = await api.functional.polEcoBoard.member.posts.votes.create(connection, {
    postId: post.id,
    body: { vote_value: -1 } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(vote2);
  const member2_id = vote2.voter_member_id;

  // 5. As admin, log in and retrieve both votes
  await admin_register_and_login(admin_email, admin_password);
  for (const vote of [vote1, vote2]) {
    const found = await api.functional.polEcoBoard.admin.posts.votes.at(connection, {
      postId: post.id,
      voteId: vote.id,
    });
    typia.assert(found);
    // All fields match expected
    TestValidator.equals("vote id matches")(found.id)(vote.id);
    TestValidator.equals("post id")(found.post_id)(post.id);
    TestValidator.equals("vote value")(found.vote_value)(vote.vote_value);
    TestValidator.equals("voter")(typeof found.voter_member_id)("string");
    TestValidator.equals("created_at present")(
      typeof found.created_at === "string" && !!found.created_at
    )(true);
  }

  // 6. As admin, try to get a non-existent vote id
  const invalid_vote_id = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("non-existent vote id returns error")(async () => {
    await api.functional.polEcoBoard.admin.posts.votes.at(connection, {
      postId: post.id,
      voteId: invalid_vote_id,
    });
  });

  // 7. As a non-admin (member1), attempt admin endpoint to read vote (should be denied)
  await member_register_and_login(member1_email, member1_password);
  TestValidator.error("non-admin forbidden to access admin vote endpoint")(async () => {
    await api.functional.polEcoBoard.admin.posts.votes.at(connection, {
      postId: post.id,
      voteId: vote1.id,
    });
  });
}

