  await TestValidator.error("Cannot upvote own post")(
    () => api.functional.polEcoBoard.member.posts.votes.create(connection, {
      postId: post.id,
      body: { vote_value: 1 },
    })
  );

  // 4. Register Member B
  const memberBEmail = typia.random<string & tags.Format<"email">>();
