/**
 * Validate admin password change success and incorrect current password error handling.
 *
 * This test ensures that (1) an authenticated administrator can successfully change their password, (2) all previous sessions are invalidated after the password change (requiring new authentication), and (3) incorrect old password results in the correct error response. This protects security policy and confirms both business logic and error handling pathways.
 *
 * Steps:
 * 1. Register a new admin account using a unique email/password
 * 2. Log in with the new credentials to establish an authenticated session
 * 3. Call the password change endpoint with the correct current password and an acceptable new password
 * 4. Verify password change is acknowledged, with all sessions revoked
 * 5. Confirm the admin cannot perform protected actions (attempt re-login using OLD password fails)
 * 6. Authenticate again with the new password (success)
 * 7. Attempt password change AGAIN but use incorrect current password and verify the expected error is returned
 */
export async function test_api_admin_change_password_success_and_invalid_current_password(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const initialPassword = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  const resSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: initialPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(resSignUp);

  // 2. Log in with initial password
  const resSignIn = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: initialPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(resSignIn);

  // 3. Change password using correct current password
  const newPassword = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  const resChangePassword = await api.functional.auth.admin.password.changePassword(connection, {
    body: {
      currentPassword: initialPassword,
      newPassword,
    } satisfies IPolEcoBoardAdminAuth.ChangePassword,
  });
  typia.assert(resChangePassword);
  TestValidator.equals("password_changed")(resChangePassword.status)("password_changed");

  // 4. Password updated, all sessions revoked. Login with OLD password should now fail.
  TestValidator.error("old password should not work after change")(async () => {
    await api.functional.auth.admin.login.signIn(connection, {
      body: { email: adminEmail, password: initialPassword } satisfies IPolEcoBoardAdminAuth.SignIn,
    });
  });

  // 5. Login with NEW password succeeds
  const resSignInAgain = await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: newPassword } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(resSignInAgain);

  // 6. Attempt to change password using incorrect current password
  const wrongOldPassword = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  TestValidator.error("invalid current password triggers error")(async () => {
    await api.functional.auth.admin.password.changePassword(connection, {
      body: {
        currentPassword: wrongOldPassword,
        newPassword: typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>(),
      } satisfies IPolEcoBoardAdminAuth.ChangePassword,
    });
  });
}

