/**
 * Validate that updating service settings with invalid data fails and does not mutate global configuration.
 *
 * This test ensures that the admin-only endpoint for updating polEcoBoard global settings enforces strict validation and business rules:
 * - Negative or zero values for number fields are rejected
 * - Out-of-bounds integer values are rejected
 * - Incorrect types (e.g. string instead of int for post length) are rejected
 * - Requests with extra/malformed fields are rejected
 * If any of these invalid updates are attempted, the API must not change the settings and should throw an error. After failed attempts, state must be unchanged.
 *
 * Steps:
 * 1. Register a new admin account
 * 2. Login as admin
 * 3. Fetch and store current service settings
 * 4. Try to update service settings with several invalid payloads:
 *    a) negative max_post_length
 *    b) extremely large max_comment_length
 *    c) wrong type (string for max_post_length)
 *    d) extra property `bad_field`
 *    e) zero data_retention_days
 * 5. Assert each update fails with an error
 * 6. Re-fetch service settings and verify no modifications occurred
 */
export async function test_api_service_settings_update_invalid_data(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Fetch and store the current service settings
  const oldSettings = await api.functional.polEcoBoard.admin.serviceSettings.at(connection);
  typia.assert(oldSettings);

  // 4a) Negative max_post_length
  await TestValidator.error("Negative max_post_length fails")(async () => {
    await api.functional.polEcoBoard.admin.serviceSettings.update(connection, {
      body: { max_post_length: -1 } as any // purposely invalid
    });
  });

  // 4b) Extremely large max_comment_length (int32 overflow)
  await TestValidator.error("int32 overflow max_comment_length fails")(async () => {
    await api.functional.polEcoBoard.admin.serviceSettings.update(connection, {
      body: { max_comment_length: 2147483648 } as any // int32 overflow on purpose
    });
  });

  // 4c) Wrong type -- string for max_post_length
  await TestValidator.error("String instead of int for max_post_length fails")(async () => {
    await api.functional.polEcoBoard.admin.serviceSettings.update(connection, {
      body: { max_post_length: "invalid_type" } as any
    });
  });

  // 4d) Extra property: should not be accepted
  await TestValidator.error("Extra field bad_field fails")(async () => {
    await api.functional.polEcoBoard.admin.serviceSettings.update(connection, {
      body: { bad_field: 1 } as any
    });
  });

  // 4e) Zero data_retention_days (should be positive)
  await TestValidator.error("Zero data_retention_days fails")(async () => {
    await api.functional.polEcoBoard.admin.serviceSettings.update(connection, {
      body: { data_retention_days: 0 } as any
    });
  });

  // 5. Fetch the settings again for comparison
  const newSettings = await api.functional.polEcoBoard.admin.serviceSettings.at(connection);
  typia.assert(newSettings);
  TestValidator.equals("Settings unchanged after failed updates")(newSettings)(oldSettings);
}

