import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPageIPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate admin retrieval, filtering, and pagination of discussion board categories.
 *
 * This test verifies correct behavior of the admin search endpoint for polEcoBoard categories:
 * 1. It covers the full admin flow from registration, login, category creation, to category search with advanced filters/pagination/ordering.
 * 2. Categories are created with unique names, descriptions, and display orders to validate filtering and sort orders reflect up-to-date data.
 * 3. The search endpoint is tested for:
 *    - Pagination correctness (with explicit limit and page)
 *    - Filtering on name and description (case-insensitive substring match)
 *    - Filtering on exact display_order
 *    - Presence and type accuracy of all fields in the response (id, name, description, display_order, created_at, updated_at)
 *    - Accurate pagination metadata
 *    - Correct ordering by display_order (ascending)
 * 4. Edge cases (empty result set, description null, multi-record per page, uniqueness constraints) are checked where feasible.
 */
export async function test_api_category_list_admin_success_and_filtering(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(signUpRes);

  // 2. Login as admin
  const signInRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(signInRes);

  // 3. Create several categories for filter/pagination
  const randomPrefix = RandomGenerator.alphabets(8);
  const categories: IPolEcoBoardCategory[] = [];
  for (let i = 0; i < 5; ++i) {
    const name = `${randomPrefix}-cat-${i}`;
    const description = i % 2 === 0 ? `Info-${randomPrefix}-${i}` : null;
    const display_order = i + 1;
    const res = await api.functional.polEcoBoard.admin.categories.create(connection, {
      body: {
        name,
        description,
        display_order,
      },
    });
    typia.assert(res);
    categories.push(res);
  }
  // Sort reference for display_order validation
  categories.sort((a, b) => a.display_order - b.display_order);

  // 4. Basic search: all categories, default page/limit
  const allSearch = await api.functional.polEcoBoard.admin.categories.search(connection, {
    body: {},
  });
  typia.assert(allSearch);
  // Ensure at least all test-created categories are present
  for (const cat of categories) {
    TestValidator.predicate(`Created category ${cat.name} is present`)(
      allSearch.data.some((x) => x.id === cat.id)
    );
  }

  // 5. Paginated search (limit 2)
  const paged = await api.functional.polEcoBoard.admin.categories.search(connection, {
    body: { page: 1, limit: 2 },
  });
  typia.assert(paged);
  TestValidator.equals('pagination limit')(paged.pagination.limit)(2);
  TestValidator.predicate('pagination page 1')(paged.pagination.current === 1);
  TestValidator.predicate('pagination data max 2')(paged.data.length <= 2);

  // 6. Filtering: by name substring (case-insensitive, using unique prefix)
  const nameQuery = randomPrefix.toLowerCase();
  const byName = await api.functional.polEcoBoard.admin.categories.search(connection, {
    body: { search: nameQuery },
  });
  typia.assert(byName);
  TestValidator.predicate('All results match name search')(byName.data.every(x => x.name.toLowerCase().includes(nameQuery)));
  // At least one result comes from the created set
  TestValidator.predicate('At least one searched by name is test data')(byName.data.some(x => categories.some(c => c.id === x.id)));

  // Query with non-existent substring: should yield 0 results
  const bogusName = 'ZZZ-NONMATCH-'+Math.random().toString(36).slice(2,8);
  const emptyByName = await api.functional.polEcoBoard.admin.categories.search(connection, {
    body: { search: bogusName },
  });
  typia.assert(emptyByName);
  TestValidator.equals('Non-existent name yields zero')(emptyByName.data.length)(0);

  // 7. Filtering: by exact display_order
  const specificOrder = categories[3].display_order;
  const byOrder = await api.functional.polEcoBoard.admin.categories.search(connection, {
    body: { display_order: specificOrder },
  });
  typia.assert(byOrder);
  TestValidator.equals('Display order match')(byOrder.data[0]?.display_order)(specificOrder);
  TestValidator.predicate('Order match is test data')(byOrder.data.some((x) => x.id === categories[3].id));

  // 8. Filtering: by description substring (case-insensitive, skip nulls)
  const nonNullDesc = categories.find(c => c.description);
  if (nonNullDesc && nonNullDesc.description) {
    const descQuery = nonNullDesc.description.slice(0, 4).toLowerCase();
    const byDesc = await api.functional.polEcoBoard.admin.categories.search(connection, {
      body: { description: descQuery },
    });
    typia.assert(byDesc);
    TestValidator.predicate('Description filter')(byDesc.data.every(x => (x.description ?? '').toLowerCase().includes(descQuery)));
    TestValidator.predicate('At least one desc search result is test data')(byDesc.data.some((x) => x.id === nonNullDesc.id));
  }

  // 9. Ordering by display_order should match reference
  const orderCheck = await api.functional.polEcoBoard.admin.categories.search(connection, {
    body: { limit: categories.length, search: randomPrefix },
  });
  typia.assert(orderCheck);
  const testSetReturned = orderCheck.data.filter((x) => categories.some((c) => c.id === x.id));
  const displayedOrders = testSetReturned.map(x => x.display_order);
  const sorted = [...displayedOrders].sort((a, b) => a - b);
  TestValidator.equals('Display order ascending')(displayedOrders)(sorted);

  // 10. All returned fields present/accurate for all categories in test set
  for (const sample of testSetReturned) {
    TestValidator.predicate('Field: id')(!!sample.id && typeof sample.id === 'string');
    TestValidator.predicate('Field: name')(!!sample.name && typeof sample.name === 'string');
    TestValidator.predicate('Field: display_order')(typeof sample.display_order === 'number');
    TestValidator.predicate('Field: created_at')(!!sample.created_at && typeof sample.created_at === 'string');
    TestValidator.predicate('Field: updated_at')(!!sample.updated_at && typeof sample.updated_at === 'string');
    TestValidator.predicate('Field: description')(
      typeof sample.description === 'string' || sample.description === null || sample.description === undefined
    );
  }

  // 11. Pagination metadata validity
  TestValidator.predicate('Total records ≥ categories')(orderCheck.pagination.records >= testSetReturned.length);
  TestValidator.predicate('Pages ≥ 1')(orderCheck.pagination.pages >= 1);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
