import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validates that only admin users can access the polEcoBoard category admin listing endpoint.
 *
 * This test covers three scenarios of access control:
 * 1. Access by a regular authenticated member
 * 2. Access by an authenticated moderator
 * 3. Access without authentication (no JWT provided)
 *
 * For both non-admin roles (member and moderator), registration and login are performed to obtain valid JWTs. After acquiring tokens, the test attempts to request the admin category listing using each credential type. Each attempt must fail with an authorization or authentication error, demonstrating correct permission enforcement. An unauthenticated request is made by stripping the Authorization header, which must also fail.
 *
 * Steps:
 * 1. Register and log in as a member
 * 2. Attempt admin category listing as member (expect forbidden/unauthorized error)
 * 3. Register and log in as a moderator
 * 4. Attempt admin category listing as moderator (expect forbidden/unauthorized error)
 * 5. Attempt admin category listing without any authentication header (expect authentication error)
 *
 * The test asserts that all non-admin access paths are strictly denied, and error responses are descriptive and actionable.
 */
export async function test_api_category_list_admin_auth_required_permission_denied(connection: api.IConnection) {
  // 1. Register member
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberPassword: string = typia.random<string & tags.Format<"password">>();
  const memberSignUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberSignUpResult);

  // 2. Login as member
  const memberSignInResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberSignInResult);

  // 3. Attempt admin category list as member (should fail)
  const memberHeaders = {
    ...(connection.headers ?? {}),
    Authorization: memberSignInResult.setHeaders.Authorization,
  };
  const memberConn = { ...connection, headers: memberHeaders };
  TestValidator.error("member access denied to admin endpoint")(async () => {
    await api.functional.polEcoBoard.admin.categories.search(memberConn, {
      body: {}, // Minimal valid request
    });
  });

  // 4. Register moderator
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorPassword: string = typia.random<string>();
  const moderatorDisplayName: string = RandomGenerator.name();
  const consentStatus: string = "policy-v1";
  const moderatorSignUpResult = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorSignUpResult);

  // 5. Login as moderator
  const moderatorSignInResult = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(moderatorSignInResult);

  // 6. Attempt admin category list as moderator (should fail)
  const moderatorHeaders = {
    ...(connection.headers ?? {}),
    Authorization: moderatorSignInResult.setHeaders.Authorization,
  };
  const moderatorConn = { ...connection, headers: moderatorHeaders };
  TestValidator.error("moderator access denied to admin endpoint")(async () => {
    await api.functional.polEcoBoard.admin.categories.search(moderatorConn, {
      body: {}, // Minimal valid request
    });
  });

  // 7. Attempt admin category list WITHOUT authentication (should fail)
  const noAuthHeaders = { ...((connection.headers ?? {})) };
  delete noAuthHeaders.Authorization;
  const noAuthConn = { ...connection, headers: noAuthHeaders };
  TestValidator.error("unauthenticated access denied to admin endpoint")(async () => {
    await api.functional.polEcoBoard.admin.categories.search(noAuthConn, {
      body: {}, // Minimal valid request
    });
  });
}

