/**
 * Test admin category creation and validation enforcement for polEcoBoard.
 *
 * Validates admin's ability to create new discussion board categories, enforcing business constraints:
 *   - Name: required, unique, 2–60 chars
 *   - Description: optional, string, max 255 chars
 *   - Display order: required, int32
 *
 * Workflow:
 * 1. Register a new admin with a unique business email/password
 * 2. Login as admin to enable privileged access
 * 3. Create a new category with valid data, verify all returned fields & system-generated UUID
 * 4. Attempt duplicate-name creation and verify uniqueness constraint is enforced (should fail)
 * 5. Validation error cases:
 *    a. Too-short name (1 char)
 *    b. Too-long name (>60 chars)
 *    c. Omitted name
 *    d. Excessively long description (>255 chars)
 *    e. Omitted display_order
 */
export async function test_api_category_creation_success_and_validation(connection: api.IConnection) {
  // 1. Admin registration
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(12);
  const signupResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signupResp);

  // 2. Admin login
  const loginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(loginResp);

  // 3. Create valid category
  const categoryData: IPolEcoBoardCategory.ICreate = {
    name: "EcoPolicy " + RandomGenerator.alphaNumeric(5),
    description: RandomGenerator.paragraph()(1, 3),
    display_order: typia.random<number & tags.Type<"int32">>(),
  };
  const created = await api.functional.polEcoBoard.admin.categories.create(connection, { body: categoryData });
  typia.assert(created);
  TestValidator.equals("category name matches")(created.name)(categoryData.name);
  TestValidator.predicate("category UUID format")(typeof created.id === "string" && /^[0-9a-f\-]{36}$/i.test(created.id));
  TestValidator.equals("category display order matches")(created.display_order)(categoryData.display_order);
  TestValidator.predicate("created_at present")(!!created.created_at && typeof created.created_at === "string");
  TestValidator.predicate("updated_at present")(!!created.updated_at && typeof created.updated_at === "string");

  // 4. Duplicate name (uniqueness violation)
  await TestValidator.error("duplicate name should fail")(async () => {
    await api.functional.polEcoBoard.admin.categories.create(connection, { body: { ...categoryData, display_order: categoryData.display_order + 1 } });
  });

  // 5a. Too-short name
  await TestValidator.error("name too short should fail")(async () => {
    await api.functional.polEcoBoard.admin.categories.create(connection, { body: { ...categoryData, name: "E", display_order: categoryData.display_order + 2 } });
  });

  // 5b. Too-long name >60 chars
  await TestValidator.error("name too long should fail")(async () => {
    await api.functional.polEcoBoard.admin.categories.create(connection, { body: { ...categoryData, name: RandomGenerator.alphaNumeric(61), display_order: categoryData.display_order + 3 } });
  });

  // 5c. Omitted name
  await TestValidator.error("omitted name should fail")(async () => {
    await api.functional.polEcoBoard.admin.categories.create(connection, { body: { display_order: categoryData.display_order + 4, description: "Missing name" } as IPolEcoBoardCategory.ICreate });
  });

  // 5d. Too-long description >255 chars
  await TestValidator.error("description too long should fail")(async () => {
    await api.functional.polEcoBoard.admin.categories.create(connection, { body: { ...categoryData, name: "EcoMaxDesc", description: RandomGenerator.alphaNumeric(256), display_order: categoryData.display_order + 5 } });
  });

  // 5e. Omitted display_order
  await TestValidator.error("omitted display_order should fail")(async () => {
    await api.functional.polEcoBoard.admin.categories.create(connection, { body: { ...categoryData, name: "EcoNoDispOrder" } as IPolEcoBoardCategory.ICreate });
  });
}

