    await api.functional.polEcoBoard.admin.categories.create(connection, {
      body: {
        name: categoryName, // duplicate
        description: RandomGenerator.paragraph()(1),
        display_order: typia.random<number & tags.Type<"int32">>(),
      } satisfies IPolEcoBoardCategory.ICreate,
