import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate updating categories as an admin, including error scenarios for uniqueness conflicts and partial updates.
 *
 * This test covers:
 * 1. Register and login as an admin user for API access.
 * 2. Creating two categories to provide context for unique constraint and partial update testing.
 * 3. Updating the first category (all fields) and verifying response reflects correct update values and updated_at timestamp.
 * 4. Uniqueness conflict: trying to update the second category's name to the (now-updated) first category's name should trigger an error.
 * 5. Partial update: updating only the description of the second category verifies that unchanged fields remain unaltered.
 */
export async function test_api_category_update_success_and_conflict(
  connection: api.IConnection
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword =
    "AdminPwd1!" + typia.random<string>().slice(0, 8); // At least 8 chars & some complexity
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as the admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create two categories for update/uniqueness scenarios
  const category1Input = {
    name: "Eco Economy " + typia.random<string>().slice(0, 6),
    description: "First eco category: " + typia.random<string>().slice(0, 10),
    display_order: typia.random<number & tags.Type<"int32">>(),
  } satisfies IPolEcoBoardCategory.ICreate;
  const category2Input = {
    name: "Eco Env " + typia.random<string>().slice(0, 6),
    description: "Second eco category: " + typia.random<string>().slice(0, 10),
    display_order: category1Input.display_order + 1,
  } satisfies IPolEcoBoardCategory.ICreate;

  const category1 = await api.functional.polEcoBoard.admin.categories.create(
    connection,
    { body: category1Input }
  );
  typia.assert(category1);
  const category2 = await api.functional.polEcoBoard.admin.categories.create(
    connection,
    { body: category2Input }
  );
  typia.assert(category2);

  // Save previous updated_at for later assertion
  const category1PrevUpdatedAt = category1.updated_at;

  // 4. Update the first category (all fields)
  const category1Update: IPolEcoBoardCategory.IUpdate = {
    name: category1.name + " Updated",
    description: (category1.description ?? "") + " (edited)",
    display_order: category1.display_order + 10,
  };
  const updatedCategory1 =
    await api.functional.polEcoBoard.admin.categories.update(connection, {
      categoryId: category1.id,
      body: category1Update,
    });
  typia.assert(updatedCategory1);
  TestValidator.notEquals("updated_at changed")(
    updatedCategory1.updated_at
  )(category1PrevUpdatedAt);
  TestValidator.equals("updated name")(
    updatedCategory1.name
  )(category1Update.name);
  TestValidator.equals("updated description")(
    updatedCategory1.description
  )(category1Update.description);
  TestValidator.equals("updated display_order")(
    updatedCategory1.display_order
  )(category1Update.display_order);

  // 5. Uniqueness conflict: try to update category 2's name to category1's (now updated) name
  await TestValidator.error("duplicate category name should fail")(
    async () => {
      await api.functional.polEcoBoard.admin.categories.update(connection, {
        categoryId: category2.id,
        body: {
          name: updatedCategory1.name,
        },
      });
    }
  );

  // 6. Partial update: just update the description of the second category
  const partialDescription = (category2.description ?? "") + " (partial update)";
  const partiallyUpdatedCategory2 =
    await api.functional.polEcoBoard.admin.categories.update(connection, {
      categoryId: category2.id,
      body: {
        description: partialDescription,
      },
    });
  typia.assert(partiallyUpdatedCategory2);
  TestValidator.equals("description updated")(
    partiallyUpdatedCategory2.description
  )(partialDescription);
  TestValidator.equals("name remains unchanged")(
    partiallyUpdatedCategory2.name
  )(category2.name);
  TestValidator.equals("display_order remains unchanged")(
    partiallyUpdatedCategory2.display_order
  )(category2.display_order);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCategory";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate error handling when attempting to update a board category (polEcoBoard) using a categoryId that does not exist or is malformed, as an administrator.
 *
 * Business context: Only authenticated admins can update a category. Admins must supply a valid category UUID, and any update attempt with a non-existent UUID should result in a not-found error, while a syntactically invalid ID should trigger validation errors.
 *
 * Steps:
 * 1. Register a new admin to ensure access (using unique random email/pass).
 * 2. Log in as that admin (to set tokens for privileged request).
 * 3. Try to update a category using a random UUID that does not exist in the system.
 *    - Expect a not-found error (HTTP 404 or similar), with a descriptive message.
 * 4. Try to update a category using an improperly formatted ID (not a UUID string, e.g. "wrong-id").
 *    - Expect a validation error, with an actionable message.
 * 5. Confirm that in both cases, no resource is updated, and proper error mechanisms are triggered.
 */
export async function test_api_category_update_not_found_and_invalid_id(connection: api.IConnection) {
  // 1. Register a new admin for access
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPass = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPass,
    },
  });

  // 2. Authenticate as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPass,
    },
  });

  // 3. Try to update with a non-existent (but valid) UUID
  const updateBody: IPolEcoBoardCategory.IUpdate = {
    name: "NonExistentCategory",
    description: "Trying update on nonexistent category.",
    display_order: 15,
  };
  const notFoundCategoryId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Should error for nonexistent categoryId")(
    async () => {
      await api.functional.polEcoBoard.admin.categories.update(connection, {
        categoryId: notFoundCategoryId,
        body: updateBody,
      });
    },
  );

  // 4. Try to update with a malformed categoryId (invalid format)
  // Type casting is required to bypass compile-time UUID format restriction for runtime validation testing
  await TestValidator.error("Should error for invalid categoryId format")(
    async () => {
      await api.functional.polEcoBoard.admin.categories.update(connection, {
        categoryId: "wrong-id" as any,
        body: updateBody,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
