/**
 * Validate successful deletion of board categories by admin, and enforce referential integrity so referenced categories cannot be removed.
 *
 * Test covers two main scenarios:
 * 1. Admin can delete a category that is not referenced by any boards (Should be removed successfully and no longer available).
 * 2. Attempting to delete a category that is referenced (by a board) must fail, with a clear error regarding referential integrity.
 *
 * Test steps:
 * 1. Register a new admin with unique email/password.
 * 2. Log in as that admin to have authentication/authorization for subsequent operations.
 * 3. Create the first category (standalone, not referenced).
 * 4. Delete the first category - Expect successful deletion (void response).
 * 5. Optionally, attempt to fetch or list categories and confirm it is not retrievable (would require an endpoint, but skip if unavailable).
 * 6. Create a second category (to be referenced).
 * 7. Create a board using the second category as parent association.
 * 8. Attempt to delete the second category - Expect error due to referential integrity (use TestValidator.error to confirm).
 */
export async function test_api_category_deletion_success_and_referential_integrity(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail: string = typia.random<string & tags.Format<'email'>>();
  const adminPassword: string = RandomGenerator.alphaNumeric(12);
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Log in as the newly registered admin
  const signInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResp);

  // 3. Create a category not referenced anywhere
  const categoryStandalone = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(16),
      description: RandomGenerator.paragraph()(),
      display_order: typia.random<number & tags.Type<'int32'>>()
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(categoryStandalone);

  // 4. Delete the standalone category
  await api.functional.polEcoBoard.admin.categories.erase(connection, {
    categoryId: categoryStandalone.id,
  });

  // 5. (Optional) If there were read/list endpoints, we would check category no longer exists (omitted)

  // 6. Create a second category to be referenced
  const categoryRef = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(16),
      description: RandomGenerator.paragraph()(),
      display_order: typia.random<number & tags.Type<'int32'>>()
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(categoryRef);

  // 7. Create a board in this category
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: categoryRef.id,
      name: RandomGenerator.alphaNumeric(12),
      code: RandomGenerator.alphaNumeric(8).toLowerCase(),
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<'int32'>>()
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 8. Attempt to delete the referenced category -> Expect error
  await TestValidator.error('deleting referenced category should fail')(async () => {
    await api.functional.polEcoBoard.admin.categories.erase(connection, {
      categoryId: categoryRef.id,
    });
  });
}

