  TestValidator.equals("file size")(loadedAttachment.file_size_bytes)(attachmentInput.file_size_bytes);
  TestValidator.equals("mime type")(loadedAttachment.mime_type)(attachmentInput.mime_type);
  TestValidator.equals("uri")(loadedAttachment.uri)(attachmentInput.uri);
  TestValidator.equals("deleted_at null")(loadedAttachment.deleted_at)(null);
}

