 * This test enforces privacy and access control by ensuring that only the authoring member (or authorized roles) can access their post's attachments.
 *
 * Step-by-step workflow:
 * 1. Register Member A (Author).
 * 2. Login as Member A (personal connection).
 * 3. Member A creates a post.
 * 4. Member A attaches a file to their post.
 * 5. Register Member B (another normal member).
 * 6. Login as Member B (personal connection).
 * 7. Member B attempts to retrieve the attachment from Member A's post using the attachment's ID.
 * 8. Confirm that the API returns a forbidden or not found error, blocking the access.
 */
export async function test_api_post_attachment_details_member_forbidden_on_others_post(connection: api.IConnection) {
  // 1. Register Member A
  const memberAEmail = typia.random<string & tags.Format<"email">>();
  const memberAPassword = typia.random<string & tags.Format<"password">>();
  const signUpA = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberAEmail,
      password: memberAPassword
    }
  });
  typia.assert(signUpA);

  // 2. Login as Member A
  const signInA = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberAEmail,
      password: memberAPassword
    }
  });
  typia.assert(signInA);
  // Set Authorization for Member A
  connection.headers = {
    ...connection.headers,
    ...signInA.setHeaders,
  };

  // 3. Member A creates a post
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const createdPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: "Test Attachment Privacy",
      body: "Checking forbidden access to attachments"
    }
  });
  typia.assert(createdPost);

  // 4. Member A attaches a file to their post
  const attachmentData: IPolEcoBoardAttachment.ICreate = {
    uri: "https://fileserver.example/test-file.txt",
    file_name: "test-file.txt",
    file_size_bytes: 241,
    mime_type: "text/plain"
  };
  const createdAttachment = await api.functional.polEcoBoard.member.posts.attachments.create(connection, {
    postId: createdPost.id,
    body: attachmentData,
  });
  typia.assert(createdAttachment);

  // 5. Register Member B
  const memberBEmail = typia.random<string & tags.Format<"email">>();
  const memberBPassword = typia.random<string & tags.Format<"password">>();
  const signUpB = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberBEmail,
      password: memberBPassword
    }
  });
  typia.assert(signUpB);

  // 6. Login as Member B
  const signInB = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberBEmail,
      password: memberBPassword
    }
  });
  typia.assert(signInB);
  connection.headers = {
    ...connection.headers,
    ...signInB.setHeaders,
  };

  // 7 & 8. Member B attempts to access Member A's attachment - must fail
  await TestValidator.error("Member B forbidden from accessing Member A's attachment")(
    async () => {
      await api.functional.polEcoBoard.member.posts.attachments.at(connection, {
        postId: createdPost.id,
        attachmentId: createdAttachment.id,
      });
    }
  );
}

