/**
 * Validate admin authentication session search with filters and pagination.
 *
 * This test ensures polEcoBoard admin session auditing behaves as expected:
 * - Registers a new admin account
 * - Simulates multiple login sessions from different devices (User-Agent headers)
 * - Uses the session search API to filter by member_id, status, provider, and with paging/limits
 * - Confirms results contain only matching sessions and that pagination/sorting is correct
 *
 * Steps:
 * 1. Register a new admin via /auth/admin/register
 * 2. Log in as the admin from three simulated User-Agent strings (creates three sessions)
 * 3. Search all sessions (should include all just generated sessions)
 * 4. Use search filters (member_id, status, provider), and verify match behaviors
 * 5. Test pagination by setting a small limit and checking output
 */
export async function test_api_admin_auth_session_search_with_filters(
  connection: api.IConnection,
) {
  // 1. Register a new admin account
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Log in via three different User-Agent headers (simulated devices/contexts)
  const userAgents = [
    'Mozilla/5.0 (iPad)',
    'Mozilla/5.0 (Windows NT 10.0)',
    'SessionTestBot/1.0',
  ];
  for (const ua of userAgents) {
    connection.headers = { ...(connection.headers ?? {}), 'User-Agent': ua };
    const loginResp = await api.functional.auth.admin.login.signIn(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
      } satisfies IPolEcoBoardAdminAuth.SignIn,
    });
    typia.assert(loginResp);
  }
  connection.headers = { ...(connection.headers ?? {}) };

  // 3. Fetch all admin auth sessions (should include our three generated)
  const allSessions = await api.functional.polEcoBoard.admin.authSessions.search(connection, {
    body: {} satisfies IPolEcoBoardAuthSession.IRequest,
  });
  typia.assert(allSessions);
  TestValidator.predicate('sessions were recorded')(allSessions.data.length >= 3);

  // 4. Filter by member_id: all returned sessions must have same member_id
  const testMemberId = allSessions.data[0]?.member_id;
  const byMemberId = await api.functional.polEcoBoard.admin.authSessions.search(connection, {
    body: {
      member_id: testMemberId,
    } satisfies IPolEcoBoardAuthSession.IRequest,
  });
  typia.assert(byMemberId);
  TestValidator.predicate('sessions have correct member_id')(byMemberId.data.every((s) => s.member_id === testMemberId));

  // 5. Filter by status = "active": sessions must not be revoked and not expired
  const byStatus = await api.functional.polEcoBoard.admin.authSessions.search(connection, {
    body: {
      member_id: testMemberId,
      status: 'active',
    } satisfies IPolEcoBoardAuthSession.IRequest,
  });
  typia.assert(byStatus);
  TestValidator.predicate('all sessions active')(byStatus.data.every((s) => !s.revoked_at && new Date(s.expires_at) > new Date()));

  // 6. Filter by provider ('native')
  const byProvider = await api.functional.polEcoBoard.admin.authSessions.search(connection, {
    body: {
      member_id: testMemberId,
      provider: 'native',
    } satisfies IPolEcoBoardAuthSession.IRequest,
  });
  typia.assert(byProvider);
  TestValidator.predicate('all sessions have native provider')(byProvider.data.every((s) => s.provider === 'native'));

  // 7. Pagination: set limit = 1
  const paged = await api.functional.polEcoBoard.admin.authSessions.search(connection, {
    body: {
      member_id: testMemberId,
      limit: 1,
    } satisfies IPolEcoBoardAuthSession.IRequest,
  });
  typia.assert(paged);
  TestValidator.equals('pagination limit')(paged.data.length)(1);
  TestValidator.equals('pagination.limit field')(paged.pagination.limit)(1);
  TestValidator.equals('pagination.current')(paged.pagination.current)(1);
}

