  TestValidator.equals("reason code updated")(updatedReport.reason_code)(updatedReason);
  TestValidator.equals("description updated")(updatedReport.reason_description)(updatedDescription);
  TestValidator.predicate("created_at unchanged or reasonable")(!!updatedReport.created_at);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
