import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate deletion of comment reports by author and admin with proper authorization enforcement.
 *
 * This workflow verifies that only the report author and an admin can delete (erase) a report on a board comment. Covers both positive cases (author, admin) and negative case (random user).
 *
 * Steps:
 * 1. Register a normal member (M1), who will be the report author.
 * 2. Login as M1 and create a post (P).
 * 3. Create a comment (C) on that post.
 * 4. File a report (R1) on the comment as M1.
 * 5. As M1 (the report author), delete the report R1 and validate success (no error).
 * 6. Register a second member (M2) and login as M2. Re-create a report (R2) on comment C as M2 for next steps and ensure it exists.
 * 7. Register an admin member (A), login as admin. As admin, delete the report R2 and validate deletion is allowed (no error).
 * 8. (Negative authorization) Register a fresh member (M3), login as M3, and attempt to delete a report authored by M2. Confirm error is thrown (only author or admin can delete).
 *
 * Validations:
 * - Both the author and admin can delete the report successfully.
 * - Other users are forbidden from deletion.
 * - Each API step receives a valid response and all data is type-safe.
 */
export async function test_api_comment_report_delete_by_author_or_admin(
  connection: api.IConnection,
) {
  // 1. Register M1 (report author)
  const m1_email = typia.random<string & tags.Format<"email">>();
  const m1_password = typia.random<string & tags.Format<"password">>();
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: m1_email,
      password: m1_password,
    },
  });
  // 2. Login as M1
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: m1_email,
      password: m1_password,
    },
  });

  // 3. Create a post (random category)
  const category_id = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id,
      title: RandomGenerator.paragraph()(12),
      body: RandomGenerator.content()(50)(),
    },
  });
  typia.assert(post);

  // 4. Create a comment
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(7),
    },
  });
  typia.assert(comment);

  // 5. File report R1 as M1
  const report1 = await api.functional.polEcoBoard.member.comments.reports.create(connection, {
    commentId: comment.id,
    body: {
      reason_code: "abuse",
      reason_description: "Spam content.",
      comment_id: comment.id,
    },
  });
  typia.assert(report1);

  // 6. Delete report R1 as author (should succeed)
  await api.functional.polEcoBoard.member.comments.reports.erase(connection, {
    commentId: comment.id,
    reportId: report1.id,
  });

  // 7. Register M2
  const m2_email = typia.random<string & tags.Format<"email">>();
  const m2_password = typia.random<string & tags.Format<"password">>();
  await api.functional.auth.member.register.signUp(connection, {
    body: { email: m2_email, password: m2_password },
  });
  // Login as M2
  await api.functional.auth.member.login.signIn(connection, {
    body: { email: m2_email, password: m2_password },
  });

  // 8. File report R2 as M2
  const report2 = await api.functional.polEcoBoard.member.comments.reports.create(connection, {
    commentId: comment.id,
    body: {
      reason_code: "spam",
      reason_description: "Unrelated advertising.",
      comment_id: comment.id,
    },
  });
  typia.assert(report2);

  // 9. Register admin (A)
  const admin_email = typia.random<string & tags.Format<"email">>();
  const admin_password = typia.random<string & tags.Format<"password">>();
  await api.functional.auth.member.register.signUp(connection, {
    body: { email: admin_email, password: admin_password },
  });
  // Login as admin
  await api.functional.auth.member.login.signIn(connection, {
    body: { email: admin_email, password: admin_password },
  });
  // (In an actual business scenario, an admin role assignment would occur here—omitted due to lack of API)

  // 10. Delete report R2 as admin
  await api.functional.polEcoBoard.member.comments.reports.erase(connection, {
    commentId: comment.id,
    reportId: report2.id,
  });

  // 11. Register M3
  const m3_email = typia.random<string & tags.Format<"email">>();
  const m3_password = typia.random<string & tags.Format<"password">>();
  await api.functional.auth.member.register.signUp(connection, {
    body: { email: m3_email, password: m3_password },
  });
  // Login as M3
  await api.functional.auth.member.login.signIn(connection, {
    body: { email: m3_email, password: m3_password },
  });

  // 12. Try to delete R2 as M3 (should fail/throw)
  await TestValidator.error("non-author non-admin cannot delete report")(() =>
    api.functional.polEcoBoard.member.comments.reports.erase(connection, {
      commentId: comment.id,
      reportId: report2.id,
    })
  );
}

