/**
 * Validates that a member who is neither the author of a report nor an admin is forbidden from deleting the report for a comment.
 *
 * Business context:
 *  - Only the member who originally filed a report on a comment, or an admin, may erase (delete) that report.
 *  - Any other member must be denied access, and the API must return an error (forbidden/unauthorized).
 *
 * Test workflow:
 * 1. Register and log in as Member A, who will author both the comment and the report
 * 2. Create a new post (as Member A)
 * 3. Add a comment to the newly created post (as Member A)
 * 4. File a report on the above comment (as Member A)
 * 5. Register and log in as Member B, who is unrelated to the above actions
 * 6. As Member B, attempt to delete (erase) Member A's report, which must fail with an authorization error
 *
 * Each step is validated, and the API's business permission check for deletion is asserted via TestValidator.error.
 */
export async function test_api_comment_report_delete_forbidden_for_non_owner_member(
  connection: api.IConnection,
) {
  // Step 1: Register Member A
  const memberAEmail = typia.random<string & tags.Format<"email">>();
  const memberAPassword = typia.random<string & tags.Format<"password">>();
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberAEmail,
      password: memberAPassword,
    },
  });

  // Step 2: Login as Member A
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberAEmail,
      password: memberAPassword,
    },
  });

  // Step 3: Create a post as Member A
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.alphabets(15),
      body: RandomGenerator.paragraph()(),
      tag_ids: null,
      attachments: null,
    },
  });
  typia.assert(post);

  // Step 4: Add a comment to the post
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(comment);

  // Step 5: Member A files a report on the comment
  const report = await api.functional.polEcoBoard.member.comments.reports.create(connection, {
    commentId: comment.id,
    body: {
      reason_code: "abuse",
      reason_description: "E2E forbidden test by Member A",
      post_id: null,
      comment_id: comment.id,
    },
  });
  typia.assert(report);

  // Step 6: Register Member B
  const memberBEmail = typia.random<string & tags.Format<"email">>();
  const memberBPassword = typia.random<string & tags.Format<"password">>();
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberBEmail,
      password: memberBPassword,
    },
  });

  // Step 7: Login as Member B
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberBEmail,
      password: memberBPassword,
    },
  });

  // Step 8: Attempt to delete Member A's report as Member B (should get forbidden error)
  await TestValidator.error("only author or admin may erase comment report")(
    () =>
      api.functional.polEcoBoard.member.comments.reports.erase(connection, {
        commentId: comment.id,
        reportId: report.id,
      }),
  );
}

