import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate advanced search and filtering of appeal records with admin privileges.
 *
 * Business context:
 * - Admins must be able to search and filter appeals using key fields, and view sensitive information such as rationale and reviewer identity.
 * - This test ensures that only admins can see full appeal details and that filtering and paging logic behaves as expected for real compliance/reporting use.
 *
 * Test workflow:
 * 1. Register and log in as a new admin (provision test admin credentials).
 * 2. Create several distinct appeals as admin, each with unique filterable properties.
 * 3. Test advanced search by using /polEcoBoard/admin/appeals PATCH with filters on appellant_id, status, and outcome.
 * 4. Validate paged results and that all sensitive data is visible (since admin).
 * 5. Confirm filtering works: matching (positive) and non-matching (negative) scenarios.
 */
export async function test_api_appeal_search_admin_role_advanced_filtering(
  connection: api.IConnection,
) {
  // 1. Register a new admin account
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Log in as this admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create three appeals, each with unique appellant_id, status, and outcome
  const APPEAL_STATUSES = ["pending", "in_review", "resolved"];
  const APPEAL_OUTCOMES = ["approved", "denied", "escalated"];
  const createdAppeals: IPolEcoBoardAppeal[] = [];
  for (let i = 0; i < 3; i++) {
    const appealInput = {
      moderation_action_id: typia.random<string & tags.Format<'uuid'>>(),
      appellant_id: typia.random<string & tags.Format<'uuid'>>(),
      reason: `Appeal for ${APPEAL_STATUSES[i]}`,
      status: APPEAL_STATUSES[i],
    } satisfies IPolEcoBoardAppeal.ICreate;
    const appeal = await api.functional.polEcoBoard.admin.appeals.create(connection, {
      body: appealInput,
    });
    typia.assert(appeal);
    // Simulate non-pending statuses: set outcome to a known value (status likely determines outcome in real workflow)
    // The outcome may be set server-side on creation by business rules; this test uses created data as baseline
    createdAppeals.push(appeal);
  }

  // 4. Use PATCH /polEcoBoard/admin/appeals with filters
  {
    // Use the 2nd created appeal for filter checks
    const basis = createdAppeals[1];
    const filter = {
      appellant_id: basis.appellant_id,
      status: basis.status,
      outcome: basis.outcome,
    } satisfies IPolEcoBoardAppeal.IRequest;
    const page = await api.functional.polEcoBoard.admin.appeals.index(connection, {
      body: filter,
    });
    typia.assert(page);
    TestValidator.predicate("at least one match")(page.data.length >= 1);
    // Validate that each returned appeal in result matches all filter properties, and sensitive fields are visible
    for (const item of page.data) {
      TestValidator.equals("appellant_id match")(item.appellant_id)(basis.appellant_id);
      TestValidator.equals("status match")(item.status)(basis.status);
      // For admin, sensitive fields like reason and reviewer_admin_id are visible
      TestValidator.predicate("sensitive field - reason present")(typeof item.reason === "string");
      // reviewer_admin_id is optional, but should be visible as key (even if null)
      if ("reviewer_admin_id" in item) {
        // property exists, OK
      }
    }
  }
  // 5. Search with a filter that cannot possibly match (negative test)
  const fakeOutcome = "nonexistent_outcome";
  const emptyPage = await api.functional.polEcoBoard.admin.appeals.index(connection, {
    body: { outcome: fakeOutcome },
  });
  typia.assert(emptyPage);
  TestValidator.equals("no matches")(emptyPage.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAppeal";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate moderator can view complete detail of a specific appeal record.
 *
 * This test covers the full flow of moderator-based privileged appeal inspection on the platform:
 * 1. Register a new moderator (with unique random email)
 * 2. Login as that moderator to obtain authentication
 * 3. Create an appeal (using moderator as appellant) referencing a random moderation action ID
 * 4. Retrieve the appeal by its ID through the moderator GET endpoint
 *
 * Validations:
 * - Successful retrieval and detail inspection for authorized moderator
 * - All permissible fields are present: audit/identity, rationale, timeline, moderation and workflow state, etc.
 * - Response does not include admin-only/sensitive fields beyond moderator scope
 * - All data returned (moderation_action_id, appellant_id, reviewer_admin_id, etc) matches the appeal record created
 * - Business logic is enforced per role: moderator sees all mod fields, not admin-only
 */
export async function test_api_appeal_detail_view_moderator_success(connection: api.IConnection) {
  // 1. Register a new moderator
  const email = typia.random<string & tags.Format<"email">>();
  const password = "P@ssw0rd1234";
  const displayName = RandomGenerator.name();
  const consentStatus = "accepted-v1"; // assuming business-consent string
  const registration = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email,
      password,
      display_name: displayName,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(registration);

  // 2. Login as the new moderator (to set proper Authorization, in case the registration token is not re-used)
  const login = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email,
      password,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(login);

  // 3. Create an appeal as the moderator
  // NOTE: moderation_action_id should be a new, valid UUID. We create a random one for test isolation.
  const moderationActionId = typia.random<string & tags.Format<"uuid">>();
  const appealReason = RandomGenerator.paragraph()();
  const createdAppeal = await api.functional.polEcoBoard.moderator.appeals.create(connection, {
    body: {
      moderation_action_id: moderationActionId,
      appellant_id: registration.moderatorId,
      reason: appealReason,
      status: "pending", // typical initial status
    } satisfies IPolEcoBoardAppeal.ICreate,
  });
  typia.assert(createdAppeal);

  // 4. Fetch the appeal detail as a moderator
  const appealFetched = await api.functional.polEcoBoard.moderator.appeals.at(connection, {
    appealId: createdAppeal.id,
  });
  typia.assert(appealFetched);

  // 5. Validate all expected fields match and access is correct
  TestValidator.equals("id matches")(appealFetched.id)(createdAppeal.id);
  TestValidator.equals("moderation_action_id matches")(appealFetched.moderation_action_id)(moderationActionId);
  TestValidator.equals("appellant_id matches")(appealFetched.appellant_id)(registration.moderatorId);
  TestValidator.equals("reason matches")(appealFetched.reason)(appealReason);
  TestValidator.equals("status matches")(appealFetched.status)(createdAppeal.status);
  // reviewer_admin_id and outcome may be null on creation: validate types but not strict values

  // Audit and timeline fields present
  TestValidator.predicate("created_at is ISO string")(typeof appealFetched.created_at === "string");
  TestValidator.predicate("updated_at is ISO string")(typeof appealFetched.updated_at === "string");
  // No direct leak of admin-only/superuser fields (we can't check for non-existent output; just validate allowed properties)
  // deleted_at may be null or undefined
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Test that a moderator can successfully upvote and downvote posts and that duplicate voting is prevented.
 *
 * Business context:
 *   - Moderators curate content by voting on posts for platform health and rule enforcement.
 *   - Each moderator can vote once per post (upvote or downvote), and cannot vote twice or change their vote by recasting.
 *   - Only member accounts can author posts; moderators must be registered and logged in to vote.
 *
 * This E2E test validates:
 *   1. Moderator account registration with consent and display name
 *   2. Moderator login (credentials set in connection headers)
 *   3. Member registration and login
 *   4. Member post creation (using valid random category uuid)
 *   5. Moderator can upvote (+1) on a post, and duplicate upvotes are rejected
 *   6. Moderator cannot downvote the same post after upvoting (one vote per post per moderator)
 *   7. Moderator can downvote (-1) a different post, and duplicate downvotes/upvotes on same post are rejected
 *   8. All major responses are type-asserted and business rules, including error cases, are enforced
 *
 * Steps:
 *   1. Register and login a new moderator with random email and display name
 *   2. Register and login a member
 *   3. Member creates first post (for upvote)
 *   4. Switch to moderator, upvote the post, verify response
 *   5. Attempt duplicate upvote and then a downvote on the same post — both must fail
 *   6. Member creates a second post
 *   7. Moderator downvotes the new post, verify response
 *   8. Attempt duplicate downvote and then an upvote on the second post — both must fail
 */
export async function test_api_post_vote_creation_moderator_success(connection: api.IConnection) {
  // 1. Register moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "moderatorPass1102!";
  const moderatorDisplayName = RandomGenerator.name();
  const moderatorConsent = "test-consent-version";
  const moderatorSignUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: moderatorConsent,
    },
  });
  typia.assert(moderatorSignUp);

  // 2. Log in as moderator
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  typia.assert(moderatorLogin);

  // 3. Register and login member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "memberPass1102$";
  const memberSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword as string & tags.Format<"password">,
    },
  });
  typia.assert(memberSignUp);

  const memberLogin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword as string & tags.Format<"password">,
    },
  });
  typia.assert(memberLogin);

  // 4. Member creates post1
  const categoryId1 = typia.random<string & tags.Format<"uuid">>();
  const postTitle1 = RandomGenerator.paragraph()(15, 30).substring(0, 30); // min 10, max 30
  const postBody1 = RandomGenerator.content()()(80, 250).substring(0, 250); // min 10, max 250
  const post1 = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId1,
      title: postTitle1,
      body: postBody1,
    },
  });
  typia.assert(post1);

  // 5. Switch to moderator, upvote post1
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  const voteUp = await api.functional.polEcoBoard.moderator.posts.votes.create(connection, {
    postId: post1.id,
    body: { vote_value: 1 },
  });
  typia.assert(voteUp);
  TestValidator.equals("vote linked to post1 - upvote")(voteUp.post_id)(post1.id);
  TestValidator.equals("vote_value = 1")(voteUp.vote_value)(1);

  // 6. Try duplicate upvote (should fail)
  await TestValidator.error("duplicate upvote rejected")(() =>
    api.functional.polEcoBoard.moderator.posts.votes.create(connection, {
      postId: post1.id,
      body: { vote_value: 1 },
    })
  );
  // 7. Try downvote on already upvoted post (should also fail)
  await TestValidator.error("switch vote from up to down disallowed")(() =>
    api.functional.polEcoBoard.moderator.posts.votes.create(connection, {
      postId: post1.id,
      body: { vote_value: -1 },
    })
  );

  // 8. Member creates post2
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword as string & tags.Format<"password">,
    },
  });
  const categoryId2 = typia.random<string & tags.Format<"uuid">>();
  const postTitle2 = RandomGenerator.paragraph()(15, 30).substring(0, 30);
  const postBody2 = RandomGenerator.content()()(80, 250).substring(0, 250);
  const post2 = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId2,
      title: postTitle2,
      body: postBody2,
    },
  });
  typia.assert(post2);

  // 9. Switch back to moderator, downvote post2
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  const voteDown = await api.functional.polEcoBoard.moderator.posts.votes.create(connection, {
    postId: post2.id,
    body: { vote_value: -1 },
  });
  typia.assert(voteDown);
  TestValidator.equals("vote linked to post2 - downvote")(voteDown.post_id)(post2.id);
  TestValidator.equals("vote_value = -1")(voteDown.vote_value)(-1);

  // 10. Duplicate downvote (should fail)
  await TestValidator.error("duplicate downvote rejected")(() =>
    api.functional.polEcoBoard.moderator.posts.votes.create(connection, {
      postId: post2.id,
      body: { vote_value: -1 },
    })
  );
  // 11. Try upvote on already downvoted post2 (should fail)
  await TestValidator.error("switch vote from down to up disallowed")(() =>
    api.functional.polEcoBoard.moderator.posts.votes.create(connection, {
      postId: post2.id,
      body: { vote_value: 1 },
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardVote";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test that an admin can upvote and downvote any existing post, enforcing all relevant business rules.
 *
 * Business context:
 * Admins may cast upvotes (1) or downvotes (-1) on posts they do not author, as part of board moderation and engagement analytics. The system must forbid duplicate voting (multiple upvotes/downvotes by same admin on the same post) and must prevent voting on one's own authored post if this logic is enforced for admins.
 *
 * Test workflow:
 * 1. Register and login as an admin user. Save email/password for switching sessions as needed.
 * 2. Register a member user and login as member.
 * 3. Create a valid post as the member user.
 * 4. Switch back to admin session (re-login as admin to ensure header/state).
 * 5. Submit an upvote (vote_value = 1) on the post as admin.
 *    - Assert success, response is a valid vote with value +1 and matches post id.
 * 6. Submit a downvote (vote_value = -1) on the same post as admin (which business logic may treat as a distinct vote, or may convert the vote).
 *    - Assert success or business logic as expected. Response is a valid vote with value -1 if the action is allowed, or enforced business logic error.
 * 7. Attempt to upvote or downvote again on the same post as admin (should be forbidden; assert error).
 * 8. (Optional) If admin authors a post themselves, attempt to vote on it; assert forbidden if business rule applies.
 */
export async function test_api_post_vote_creation_admin_success(connection: api.IConnection) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // 2. Login as admin
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // 3. Register member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const memberSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberSignUp);

  // 4. Login as member
  const memberLogin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberLogin);

  // 5. Member creates a post
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const postCreate = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()()(15),
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(postCreate);
  const postId = postCreate.id;

  // 6. Re-login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 7. Cast upvote as admin
  const upvote = await api.functional.polEcoBoard.admin.posts.votes.create(connection, {
    postId,
    body: {
      vote_value: 1,
    } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(upvote);
  TestValidator.equals("upvote: matches postId")(upvote.post_id)(postId);
  TestValidator.equals("upvote: admin voted")(upvote.vote_value)(1);

  // 8. Cast downvote as admin
  const downvote = await api.functional.polEcoBoard.admin.posts.votes.create(connection, {
    postId,
    body: {
      vote_value: -1,
    } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(downvote);
  TestValidator.equals("downvote: matches postId")(downvote.post_id)(postId);
  TestValidator.equals("downvote: admin downvoted")(downvote.vote_value)(-1);

  // 9. Attempt duplicate upvote as admin should fail
  await TestValidator.error("duplicate upvote forbidden")(async () => {
    await api.functional.polEcoBoard.admin.posts.votes.create(connection, {
      postId,
      body: {
        vote_value: 1,
      } satisfies IPolEcoBoardVote.ICreate,
    });
  });

  // 10. Attempt duplicate downvote as admin should fail
  await TestValidator.error("duplicate downvote forbidden")(async () => {
    await api.functional.polEcoBoard.admin.posts.votes.create(connection, {
      postId,
      body: {
        vote_value: -1,
      } satisfies IPolEcoBoardVote.ICreate,
    });
  });

  // 11. (Optional/Edge) Admin tries to post and vote on own post (if not forbidden, this step can be skipped)
  const adminPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()(10),
      body: RandomGenerator.content()()(15),
      tag_ids: null,
      attachments: null,
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(adminPost);
  await TestValidator.error("admin voting on own post forbidden")(async () => {
    await api.functional.polEcoBoard.admin.posts.votes.create(connection, {
      postId: adminPost.id,
      body: {
        vote_value: 1,
      } satisfies IPolEcoBoardVote.ICreate,
    });
  });
}

