  // 8. MemberB attempts to update memberA's vote (should fail with error)
  await TestValidator.error("memberB cannot update memberA's vote")(
    async () => {
      await api.functional.polEcoBoard.member.posts.votes.update(connection, {
        postId: post.id,
        voteId: vote.id,
        body: {
          vote_value: 1,
        } satisfies IPolEcoBoardVote.IUpdate,
      });
    },
  );

  // 9. (Omitted: simulate time passing beyond update window, unless supported)
}

