import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E test to validate that an admin can update any vote on any post per business rules and error conditions.
 *
 * Business context:
 * - Admins can update any vote on any post, regardless of who owns the vote.
 * - Ownership (voter_member_id) must not change during an update.
 * - Proper audit: update operates using correct postId and voteId; not changing vote author.
 * - System must return appropriate errors if attempting to update a mismatched postId/voteId or non-existent vote.
 *
 * Steps:
 * 1. Register and login as an admin
 * 2. Register and login as a member
 * 3. Member creates a post
 * 4. Member votes on their own post
 * 5. Admin logs in, updates the vote successfully (ownership unchanged)
 * 6. Try to update a non-existent vote (should fail)
 * 7. Try to update a valid vote for a mismatched post (should fail)
 */
export async function test_api_post_vote_update_by_admin_success_and_ownership_error(connection: api.IConnection) {
  // 1. Register and login as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUpResp);

  const adminLoginResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLoginResp);

  // 2. Register and login as member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const memberSignUpResp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberSignUpResp);

  const memberLoginResp = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberLoginResp);

  // 3. Member creates a post
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryId,
      title: RandomGenerator.paragraph()(typia.random<number & tags.Type<"int32"> & tags.Minimum<10> & tags.Maximum<25>>()),
      body: RandomGenerator.content()()(typia.random<number & tags.Type<"int32"> & tags.Minimum<30> & tags.Maximum<80>>()),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Member votes on their own post
  const originalVote = await api.functional.polEcoBoard.member.posts.votes.create(connection, {
    postId: post.id,
    body: {
      vote_value: 1,
    } satisfies IPolEcoBoardVote.ICreate,
  });
  typia.assert(originalVote);

  // 5. Re-login as admin before update test
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 6. Update the vote as admin (success case)
  const updatedVote = await api.functional.polEcoBoard.admin.posts.votes.update(connection, {
    postId: post.id,
    voteId: originalVote.id,
    body: {
      vote_value: -1,
    } satisfies IPolEcoBoardVote.IUpdate,
  });
  typia.assert(updatedVote);
  TestValidator.equals("vote id should remain unchanged")(updatedVote.id)(originalVote.id);
  TestValidator.equals("should remain same post")(updatedVote.post_id)(post.id);
  TestValidator.equals("admin changed vote value")(-1)(updatedVote.vote_value);
  TestValidator.equals("admin cannot change voter")(updatedVote.voter_member_id)(originalVote.voter_member_id);

  // 7. Try updating non-existent voteId (must fail)
  const nonexistentVoteId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("update of non-existent vote should fail")(async () => {
    await api.functional.polEcoBoard.admin.posts.votes.update(connection, {
      postId: post.id,
      voteId: nonexistentVoteId,
      body: {
        vote_value: 1,
      } satisfies IPolEcoBoardVote.IUpdate,
    });
  });

  // 8. Try updating with mismatched postId (must fail)
  const mismatchedPostId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("mismatched postId should fail")(async () => {
    await api.functional.polEcoBoard.admin.posts.votes.update(connection, {
      postId: mismatchedPostId,
      voteId: originalVote.id,
      body: {
        vote_value: 1,
      } satisfies IPolEcoBoardVote.IUpdate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
