 *
 * Steps:
 * 1. Register a unique admin (random email, strong password) for isolation.
 * 2. Login as admin to set proper authorization headers.
 * 3. Create a new board category via admin endpoint
 * 4. Create a new board referencing the created category
 * 5. Create a board history event (initial assignment, using test session as actor_admin)
 * 6. Retrieve the specific board history (by UUID) and assert properties match creation
 * 7. Validate all relevant entity field values are as expected.
 */
export async function test_api_board_history_detail_admin_access_success(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
