import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E: Ensure that an admin user can create a board history record when moving a board from one category to another.
 *
 * Business context:
 * This test verifies administrative workflow for maintaining board organizational lineage and audit compliance. Changing a board's category is a typical structural event that must be traceable by board history. This ensures regulatory, operational, and referential data integrity within the polEcoBoard platform.
 *
 * Step-by-step process:
 * 1. Register a new admin (unique email and secure password)
 * 2. Login as the new admin to establish authentication context
 * 3. Create two unique board categories: the source and the destination for the migration
 * 4. Create a board in the source category
 * 5. Move the board by creating a board history change event (type: 'reassignment', admin-acted)
 * 6. Validate correct creation and business/audit integrity of the returned board history record:
 *    - Referential integrity of all IDs
 *    - change_type and change_reason as expected
 *    - Audit trail date fields are valid RFC3339 timestamps
 *    - Only the actor_admin_id is populated, actor_moderator_id remains null
 */
export async function test_api_board_history_create_admin_success(connection: api.IConnection) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResponse);

  // 2. Login as the new admin
  const signInResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResponse);

  // 3. Create two categories for transfer scenario
  const cat1 = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: "Category " + RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(cat1);

  const cat2 = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: "Category " + RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(cat2);

  TestValidator.notEquals("Categories must be unique")(cat1.id)(cat2.id);

  // 4. Create a board in the source category
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: cat1.id,
      name: "Board " + RandomGenerator.alphaNumeric(8),
      code: ("code_" + RandomGenerator.alphaNumeric(10).toLowerCase()),
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);
  TestValidator.equals("Board's category matches cat1")(board.pol_eco_board_category_id)(cat1.id);

  // 5. Create board history: move board from cat1 to cat2 by admin
  const now = new Date().toISOString();
  const reason = RandomGenerator.paragraph()();
  const boardHistory = await api.functional.polEcoBoard.admin.boardHistories.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      previous_category_id: cat1.id,
      new_category_id: cat2.id,
      actor_admin_id: null, // let backend resolve admin identification
      actor_moderator_id: null, // not set, this is an admin action
      change_type: "reassignment",
      change_reason: reason,
      changed_at: now,
    } satisfies IPolEcoBoardBoardHistory.ICreate,
  });
  typia.assert(boardHistory);

  // 6. Validation: Board history record correctness
  TestValidator.equals("Board history board ID")(boardHistory.pol_eco_board_board_id)(board.id);
  TestValidator.equals("Previous category")(boardHistory.previous_category_id)(cat1.id);
  TestValidator.equals("New category")(boardHistory.new_category_id)(cat2.id);
  TestValidator.equals("Change type")(boardHistory.change_type)("reassignment");
  TestValidator.equals("Change reason")(boardHistory.change_reason)(reason);
  TestValidator.equals("Moderator actor id must be null")(boardHistory.actor_moderator_id)(null);
  TestValidator.predicate("Valid ISO8601 changed_at")(!!Date.parse(boardHistory.changed_at));
  TestValidator.predicate("Valid ISO8601 created_at")(!!Date.parse(boardHistory.created_at));
  TestValidator.predicate("Valid ISO8601 updated_at")(!!Date.parse(boardHistory.updated_at));
  TestValidator.equals("Audit referential - board id")(boardHistory.pol_eco_board_board_id)(board.id);
  // actor_admin_id should be present and well formed: string or null, but for admin creation, it should be set
  TestValidator.predicate("Admin id format if set")(boardHistory.actor_admin_id === null || (typeof boardHistory.actor_admin_id === "string" && boardHistory.actor_admin_id.length > 0));
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
