import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate moderator updating a board history event (change rationale or event details).
 *
 * Business context:
 * A moderator must be able to update an existing board history record with a new rationale or change type for an organizational event (e.g., archive, reassignment). The integrity of the audit log must be maintained, and only permitted fields may be changed by the moderator.
 *
 * Steps:
 * 1. Register as a moderator to gain credentials.
 * 2. Login as moderator to obtain JWT and authenticated session.
 * 3. Create two categories to support board transitions.
 * 4. Create a board, using category1 as parent.
 * 5. Create a board history event (change_type: 'reassignment', previous_category_id=cat1, new_category_id=cat2).
 * 6. Update the board history event's rationale and change_type using moderator privileges with a new timestamp.
 * 7. Assert all updated fields reflect the mutation, unchanged fields remain correct, and system audit fields are properly advanced.
 */
export async function test_api_board_history_update_moderator_success(connection: api.IConnection) {
  // 1. Register moderator account
  const mod_email = typia.random<string & tags.Format<"email">>();
  const regResult = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: mod_email,
      password: "TestPassword123!",
      display_name: RandomGenerator.name(),
      consent_status: "accepted-2025-01",
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(regResult);
  // Overwrite the authorization header using registration setHeaders
  connection.headers = {
    ...(connection.headers ?? {}),
    ...regResult.setHeaders,
  };

  // 2. Login as moderator to enforce session
  const loginResult = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: mod_email,
      password: "TestPassword123!",
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(loginResult);
  connection.headers = {
    ...connection.headers,
    ...loginResult.setHeaders,
  };

  // 3. Create two board categories
  const cat1 = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: "TestCat-" + RandomGenerator.alphabets(6),
      description: RandomGenerator.paragraph()(),
      display_order: 1,
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(cat1);

  const cat2 = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: "TestCat-2-" + RandomGenerator.alphabets(6),
      description: RandomGenerator.paragraph()(),
      display_order: 2,
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(cat2);

  // 4. Create board in category1
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: cat1.id,
      name: "Board-" + RandomGenerator.alphabets(8),
      code: "board_code_" + RandomGenerator.alphaNumeric(6),
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: 11,
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 5. Create a board history event (cat1 → cat2, reassignment)
  const nowIso = new Date().toISOString();
  const boardHistory = await api.functional.polEcoBoard.moderator.boardHistories.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      previous_category_id: cat1.id,
      new_category_id: cat2.id,
      actor_moderator_id: regResult.moderatorId,
      change_type: "reassignment",
      change_reason: "Initial reassignment for moderation test.",
      changed_at: nowIso,
    } satisfies IPolEcoBoardBoardHistory.ICreate,
  });
  typia.assert(boardHistory);

  // 6. Update rationale (and type), to new value, new time
  const newRationale = "Moderator-supplied update rationale.";
  const newChangedAt = new Date(Date.now() + 60000).toISOString();
  const newType = "archive";
  const updateResult = await api.functional.polEcoBoard.moderator.boardHistories.update(connection, {
    boardHistoryId: boardHistory.id,
    body: {
      change_type: newType,
      change_reason: newRationale,
      actor_moderator_id: regResult.moderatorId,
      changed_at: newChangedAt,
    } satisfies IPolEcoBoardBoardHistory.IUpdate,
  });
  typia.assert(updateResult);

  // 7. Validation: updated fields & unchanged linkage
  TestValidator.equals("boardHistoryId unchanged")(updateResult.id)(boardHistory.id);
  TestValidator.equals("change_reason updated")(updateResult.change_reason)(newRationale);
  TestValidator.equals("change_type updated")(updateResult.change_type)(newType);
  TestValidator.equals("changed_at updated")(updateResult.changed_at)(newChangedAt);
  TestValidator.equals("actor_moderator_id remains")(updateResult.actor_moderator_id)(regResult.moderatorId);
  TestValidator.equals("new_category_id unchanged")(updateResult.new_category_id)(cat2.id);
  TestValidator.equals("previous_category_id unchanged")(updateResult.previous_category_id)(cat1.id);
  TestValidator.equals("pol_eco_board_board_id unchanged")(updateResult.pol_eco_board_board_id)(board.id);
  TestValidator.predicate("updated_at advanced")(updateResult.updated_at > boardHistory.updated_at);
  TestValidator.equals("created_at unchanged")(updateResult.created_at)(boardHistory.created_at);
}

