/**
 * Validate that an admin can update an existing board history record with new change details.
 *
 * This test simulates the following business workflow:
 * 1. Admin registration (with unique email/password)
 * 2. Admin login (to issue tokens for privileged endpoints)
 * 3. Creation of two required board categories (for board/boardHistory linkage)
 * 4. Board creation (under the first category)
 * 5. Board history creation (for that board, using both categories)
 * 6. Update of the boardHistory record (change rationale text and change_type)
 * 7. Assertion that the response reflects the updated values.
 */
export async function test_api_board_history_update_admin_success(connection: api.IConnection) {
  // 1. Register a new admin (unique email/password per run)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignupOut = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignupOut);

  // 2. Login as admin to get fresh token (session enforced)
  const adminLoginOut = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLoginOut);

  // 3. Create two board categories (to allow category transitions in board history)
  const category1 = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
      display_order: 1,
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category1);
  const category2 = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphabets(8),
      description: RandomGenerator.paragraph()(),
      display_order: 2,
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category2);

  // 4. Create a new board under category1.
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category1.id,
      name: RandomGenerator.alphabets(10),
      code: RandomGenerator.alphaNumeric(10).toLowerCase(),
      description: RandomGenerator.paragraph()(),
      is_public: true,
      is_archived: false,
      display_order: 1,
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 5. Create a board history linking the board between the two categories
  const creationTime = new Date().toISOString();
  const boardHistory = await api.functional.polEcoBoard.admin.boardHistories.create(connection, {
    body: {
      pol_eco_board_board_id: board.id,
      previous_category_id: category1.id,
      new_category_id: category2.id,
      actor_admin_id: null,
      change_type: "reassignment",
      change_reason: "Initial assignment to new category.",
      changed_at: creationTime,
    } satisfies IPolEcoBoardBoardHistory.ICreate,
  });
  typia.assert(boardHistory);

  // 6. Update the board history: mutate change_type and change_reason
  const updateTime = new Date(Date.now() + 10000).toISOString();
  const updatedReason = "Category reassignment was due to organizational workflow automation.";
  const updatedChangeType = "archive";
  const boardHistoryUpdated = await api.functional.polEcoBoard.admin.boardHistories.update(connection, {
    boardHistoryId: boardHistory.id,
    body: {
      change_type: updatedChangeType,
      change_reason: updatedReason,
      actor_admin_id: null,
      changed_at: updateTime,
    } satisfies IPolEcoBoardBoardHistory.IUpdate,
  });
  typia.assert(boardHistoryUpdated);

  // 7. Assert record fields reflect update
  TestValidator.equals("change type mutated")(boardHistoryUpdated.change_type)(updatedChangeType);
  TestValidator.equals("rationale updated")(boardHistoryUpdated.change_reason)(updatedReason);
  TestValidator.equals("changed_at updated")(boardHistoryUpdated.changed_at)(updateTime);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
