import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that an admin cannot update a non-existent board history record.
 *
 * Context:
 * Admins in polEcoBoard can update board history records for organizational, compliance, or audit reasons. However, update operations must respond with a meaningful error if the boardHistoryId does not correspond to any real record. This ensures proper feedback for potential UI bugs, user error, or malicious manipulation attempts.
 *
 * This test simulates the full privileged workflow: registering a new admin, logging in as that admin, and then using a random UUID as the boardHistoryId to attempt an update. Since the ID does not exist, the update API should reject the request, and the client should receive an error (ideally HTTP 404) with a clear code/message indicating absent record.
 *
 * Test Steps:
 * 1. Register a new admin account (unique email/password).
 * 2. Login as that admin (to set connection headers).
 * 3. Attempt to update a board history record using a random UUID for boardHistoryId and a valid-looking update body.
 * 4. Assert that the operation throws an error, confirming not-found logic is enforced.
 */
export async function test_api_board_history_update_admin_invalid_record(
  connection: api.IConnection,
) {
  // 1. Register as a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResponse);

  // 2. Login with new admin credentials
  const signInResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResponse);

  // 3. Try to update board history with random non-existent ID
  const randomBoardHistoryId = typia.random<string & tags.Format<"uuid">>();
  const updateBody: IPolEcoBoardBoardHistory.IUpdate = {
    // All fields supplied validly. change_type is a required enum.
    change_type: RandomGenerator.pick([
      "reassignment",
      "merge",
      "split",
      "archive",
      "ownership_transfer",
    ]),
    change_reason: RandomGenerator.paragraph()(),
    // Optional fields actor_admin_id and actor_moderator_id set explicitly to null,
    // which is permitted per schema; alternatively, they could be omitted.
    actor_admin_id: null,
    actor_moderator_id: null,
    changed_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };

  // 4. Ensure this throws a not-found error (error structure/content is not inspected, only error thrown)
  await TestValidator.error("update on non-existent board history should fail")(
    async () =>
      api.functional.polEcoBoard.admin.boardHistories.update(connection, {
        boardHistoryId: randomBoardHistoryId,
        body: updateBody,
      }),
  );
}

