/**
 * Validate that a moderator can access details of a notification failure record by ID.
 *
 * This tests the role-based access control and data retrieval for notification failure details,
 * ensuring a successfully registered/logged-in moderator can access a compliance/audit record.
 *
 * Steps:
 * 1. Register a new moderator with unique random credentials/consent.
 * 2. Log in as this moderator, establishing a session/authorization context.
 * 3. Insert a known notification failure record via the admin interface for target test data.
 * 4. Using the moderator session, request the detail for this failure by ID.
 * 5. Assert all business, technical, and audit fields are present and correct (including nullables).
 *
 * This ensures E2E correctness for moderator role access, resource retrieval, and audit field population.
 */
export async function test_api_notification_failure_detail_access_by_moderator(
  connection: api.IConnection,
) {
  // 1. Register a new moderator with unique credentials
  const moderatorEmail: string = typia.random<string & tags.Format<"email">>();
  const moderatorPassword: string = "SecurePassword123!";
  const displayName: string = RandomGenerator.name();
  const consentStatus: string = "v1.0-policy-accepted";

  const moderatorRegistration = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: displayName,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(moderatorRegistration);
  TestValidator.equals("registered email")(moderatorRegistration.email)(moderatorEmail);
  TestValidator.equals("display_name")(moderatorRegistration.display_name)(displayName);

  // 2. Log in as the moderator
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(moderatorLogin);
  TestValidator.equals("login email")(moderatorLogin.email)(moderatorEmail);

  // 3. Create a notification failure record as test data
  const notificationId: string = typia.random<string & tags.Format<"uuid">>();
  const providerId: string = typia.random<string & tags.Format<"uuid">>();
  const now: string = new Date().toISOString();
  const failureCreate: IPolEcoBoardNotificationFailure.ICreate = {
    notification_id: notificationId,
    provider_id: providerId,
    failure_code: "provider_timeout",
    failure_message: "Timeout occurred in external notification provider.",
    occurred_at: now,
    resolution_status: "pending",
  };
  const createdFailure = await api.functional.polEcoBoard.admin.notificationFailures.create(connection, {
    body: failureCreate,
  });
  typia.assert(createdFailure);
  TestValidator.equals("failure code")(createdFailure.failure_code)(failureCreate.failure_code);
  TestValidator.equals("notification_id")(createdFailure.notification_id)(failureCreate.notification_id);

  // 4. Moderator retrieves notification failure detail by ID
  const detail = await api.functional.polEcoBoard.moderator.notificationFailures.at(connection, {
    notificationFailureId: createdFailure.id,
  });
  typia.assert(detail);

  // 5. Validate all key and audit fields are as expected
  TestValidator.equals("id")(detail.id)(createdFailure.id);
  TestValidator.equals("notification_id")(detail.notification_id)(failureCreate.notification_id);
  TestValidator.equals("provider_id")(detail.provider_id)(failureCreate.provider_id);
  TestValidator.equals("failure_code")(detail.failure_code)(failureCreate.failure_code);
  TestValidator.equals("failure_message")(detail.failure_message)(failureCreate.failure_message);
  TestValidator.equals("resolution_status")(detail.resolution_status)(failureCreate.resolution_status);
  TestValidator.predicate("occurred_at present")(!!detail.occurred_at);
  TestValidator.predicate("created_at present")(!!detail.created_at);
  TestValidator.predicate("updated_at present")(!!detail.updated_at);
  TestValidator.predicate("deleted_at present or null")(typeof detail.deleted_at === "string" || detail.deleted_at === null || detail.deleted_at === undefined);
}

