/**
 * Validate that an admin can access details of a notification failure record by ID.
 *
 * This test simulates the complete workflow where:
 * 1. An admin registers via the API and receives an authentication token.
 * 2. The admin logs in (to verify authentication flow and token correctness).
 * 3. The admin creates a notification failure entry, which generates a unique failure record in the system.
 * 4. The admin then requests the detail for the newly created notification failure entry using its notificationFailureId.
 * 5. The test asserts that:
 *    - The GET request is authorized (does not throw an error).
 *    - The returned detail matches the data of the created notification failure (all relevant fields are equal).
 *    - All technical and business attributes are supplied in the response, as required for troubleshooting.
 *
 * This test covers admin authentication, notification failure record creation, and full read-access permissions over notification failure detail endpoints.
 */
export async function test_api_notification_failure_detail_access_by_admin(connection: api.IConnection) {
  // 1. Register new admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();

  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin for authentication and to set session token
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Prepare notification failure record input
  const notificationFailureInput: IPolEcoBoardNotificationFailure.ICreate = {
    notification_id: typia.random<string & tags.Format<"uuid">>(),
    provider_id: typia.random<string & tags.Format<"uuid">>(),
    failure_code: "ERR_TEST_CODE",
    failure_message: "Test notification delivery failed for troubleshooting validation.",
    occurred_at: new Date().toISOString(),
    resolution_status: "pending",
  };

  // 4. Create a notification failure record
  const createdFailure = await api.functional.polEcoBoard.admin.notificationFailures.create(connection, {
    body: notificationFailureInput,
  });
  typia.assert(createdFailure);

  // 5. Fetch the detail by notificationFailureId as admin
  const detail = await api.functional.polEcoBoard.admin.notificationFailures.at(connection, {
    notificationFailureId: createdFailure.id,
  });
  typia.assert(detail);

  // 6. Validate that returned detail matches the created record (business/technical fields)
  TestValidator.equals("notification_id")(detail.notification_id)(notificationFailureInput.notification_id);
  TestValidator.equals("provider_id")(detail.provider_id ?? null)(notificationFailureInput.provider_id ?? null);
  TestValidator.equals("failure_code")(detail.failure_code)(notificationFailureInput.failure_code);
  TestValidator.equals("failure_message")(detail.failure_message)(notificationFailureInput.failure_message);
  TestValidator.equals("occurred_at")(detail.occurred_at)(notificationFailureInput.occurred_at);
  TestValidator.equals("resolution_status")(detail.resolution_status)(notificationFailureInput.resolution_status);
  // The following fields are system-generated (created_at, updated_at, deleted_at)
  TestValidator.predicate("created_at is ISO string")(!!Date.parse(detail.created_at));
  TestValidator.predicate("updated_at is ISO string")(!!Date.parse(detail.updated_at));
  TestValidator.equals("deleted_at is null")(detail.deleted_at ?? null)(null);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
