 *
 * This test ensures the full workflow for a privileged admin creating a notification failure event in the compliance/audit system. It covers authentication, business data requirements, and response auditing.
 *
 * Steps:
 * 1. Register a new admin using a unique email and strong password.
 * 2. Log in as that admin (ensuring token storage for authenticated requests).
 * 3. Prepare a realistic payload for notification failure creation, referencing a valid notification_id and relevant failure metadata.
 * 4. Call the notification failure create API as authenticated admin.
 * 5. Validate that the response returns a unique notification failure id, business/audit fields are properly set, and no fields are missing or null (unless allowed).
 * 6. All payload requirements and permission checks are validated; the created object must match type expectations and have properly set audit fields.
 */
export async function test_api_notification_failure_creation_by_admin(connection: api.IConnection) {
  // 1. Register a new admin (unique email, strong password)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Log in as the registered admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Prepare notification failure creation input (simulate notification_id, etc.)
  const createInput: IPolEcoBoardNotificationFailure.ICreate = {
    notification_id: typia.random<string & tags.Format<"uuid">>(),
    provider_id: typia.random<boolean>()
      ? typia.random<string & tags.Format<"uuid">>()
      : null,
    failure_code: RandomGenerator.alphabets(6),
    failure_message: RandomGenerator.paragraph()(),
    occurred_at: new Date().toISOString(),
    resolution_status: RandomGenerator.pick([
      "pending",
      "resolved",
      "permanent_failure",
      "diagnosing",
    ]),
  } satisfies IPolEcoBoardNotificationFailure.ICreate;

  // 4. Call API to create notification failure
  const output = await api.functional.polEcoBoard.admin.notificationFailures.create(connection, {
    body: createInput,
  });
  typia.assert(output);

  // 5. Check required business/audit fields are present and correct
  TestValidator.equals("notification id matches")(output.notification_id)(createInput.notification_id);
  TestValidator.equals("failure code matches")(output.failure_code)(createInput.failure_code);
  TestValidator.equals("failure message matches")(output.failure_message)(createInput.failure_message);
  TestValidator.equals("occurred_at matches")(output.occurred_at)(createInput.occurred_at);
  TestValidator.equals("resolution_status matches")(output.resolution_status)(createInput.resolution_status);

  // 6. Validate presence and format of audit fields
  TestValidator.predicate("id generated and is uuid")(
    typeof output.id === "string" &&
      output.id.length >= 30 &&
      output.id.includes("-")
  );
  TestValidator.predicate("created_at is ISO8601 date")(
    !isNaN(Date.parse(output.created_at))
  );
  TestValidator.predicate("updated_at is ISO8601 date")(
    !isNaN(Date.parse(output.updated_at))
  );
}

