    body: { email, password },
  });
  typia.assert(signUpResult);

  // 2. Log in as that member
  const signInResult = await api.functional.auth.member.login.signIn(connection, {
    body: { email, password },
  });
  typia.assert(signInResult);

  // 3. Create a board post (category UUID syntactically valid; title/body follow business constraints)
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Test post for forbidden late-delete",
      body: "This post is created to check enforcement of the late-delete business window.",
      tag_ids: null, // Explicit null for optional array fields
      attachments: null, // Explicit null for optional array fields
    },
  });
  typia.assert(post);

  // 4. Attempt to soft delete after (simulated) allowed window; actual time passage can't be simulated in E2E
  await TestValidator.error("delete is forbidden after window")(async () => {
    await api.functional.polEcoBoard.member.posts.erase(connection, { postId: post.id });
  });
}

