/**
 * Validates business rule enforcement for updating appeals with invalid status/outcome values or when locked/finalized.
 *
 * This test covers rejection of appeal updates in the following scenarios:
 *  - Setting an invalid status value not allowed by appeal workflow
 *  - Setting a forbidden/invalid outcome value
 *  - Attempting to update an appeal which is locked/finalized
 * The test performs full prerequisite flow for a realistic context and checks errors are returned.
 *
 * Steps:
 * 1. Register a new admin account
 * 2. Login as that admin (for future API admin calls)
 * 3. Register a regular member account
 * 4. Login as that member (persist authentication for correct permission)
 * 5. Create a test moderation action (member or admin as operator, valid fields)
 * 6. Initiate an appeal referencing this moderation action (as member)
 * 7. Re-authenticate as admin (JWT token should set connection to admin mode)
 * 8. Try updating the appeal with:
 *     a) An invalid status (e.g., gibberish or unsupported string)
 *     b) An invalid outcome (e.g., gibberish or unsupported outcome code)
 *     c) Try locking the appeal and then attempt another update as a finalized record
 * Each of steps 8a–8c should fail with an error (i.e., business logic enforcement or validation error).
 *
 * This test ensures that:
 *   - Status values and outcome codes are strictly checked
 *   - Finalized/locked appeals cannot be updated further
 *   - Proper error codes/responses are returned for invalid modifications
 */
export async function test_api_appeal_update_admin_invalid_status(connection: api.IConnection) {
  // 1. Register a new admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 2. Login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 3. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(14);
  const memberDisplayName = RandomGenerator.name();
  const consentStatus = RandomGenerator.alphaNumeric(5);
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: memberDisplayName,
      consent_status: consentStatus,
    },
  });
  typia.assert(member);

  // 4. Login as member
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });

  // 5. Create a moderation action (simulate report_id as random UUID)
  const reportId = typia.random<string & tags.Format<"uuid">>();
  const action = await api.functional.polEcoBoard.moderator.moderationActions.create(connection, {
    body: {
      report_id: reportId,
      operator_id: member.id,
      action_type: "remove",
      target_type: "post",
      status: "completed",
      rationale: RandomGenerator.paragraph()(60),
      outcome: "accepted",
    },
  });
  typia.assert(action);

  // 6. Create an appeal
  const appeal = await api.functional.polEcoBoard.member.appeals.create(connection, {
    body: {
      moderation_action_id: action.id,
      appellant_id: member.id,
      reason: RandomGenerator.paragraph()(40),
      status: "pending",
    },
  });
  typia.assert(appeal);

  // 7. Switch back to admin (for admin appeal update)
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });

  // 8a. Attempt update with an invalid status
  await TestValidator.error("update with invalid status should fail")(async () => {
    await api.functional.polEcoBoard.admin.appeals.update(connection, {
      appealId: appeal.id,
      body: {
        status: "not-a-real-status",
      },
    });
  });

