  await TestValidator.error("update with invalid outcome should fail")(async () => {
    await api.functional.polEcoBoard.admin.appeals.update(connection, {
      appealId: appeal.id,
      body: {
        status: "in_review", // assume valid, outcome is invalid
        outcome: "not-a-real-outcome",
      },
    });
  });

  // 8c. Finalize the appeal, then try to further update (simulate as if resolved, then try to update)
  const finalizedAppeal = await api.functional.polEcoBoard.admin.appeals.update(connection, {
    appealId: appeal.id,
    body: {
      status: "resolved",
      outcome: "approved",
    },
  });
  typia.assert(finalizedAppeal);

  // Now try to update again - this should fail since the appeal is finalized/locked
  await TestValidator.error("update finalized appeal should fail")(async () => {
    await api.functional.polEcoBoard.admin.appeals.update(connection, {
      appealId: appeal.id,
      body: {
        status: "pending",
      },
    });
  });
}

