import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardModerationAudit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAudit";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate the deletion of moderation audit records and test access control.
 *
 * Business context:
 * - Only admin accounts may delete moderation audit records.
 * - Deleting an audit that is already deleted or does not exist must result in a not-found error.
 * - Attempts by non-admins must be denied with a proper error (permission denied/unauthorized).
 *
 * Test steps:
 * 1. Register and log in as a new admin (password of at least 8 chars).
 * 2. Create a moderation action (required for audit association).
 * 3. Create an audit record for that moderation action.
 * 4. Delete the audit as admin (success case).
 * 5. Verify that re-deletion of the same audit fails (not found).
 * 6. Attempt audit deletion as non-admin (simulate by using a connection without admin Authorization header).
 * 7. Attempt deletion with a random non-existent auditId, expect not found error.
 */
export async function test_api_moderation_audit_delete_success_and_access_control(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const registerRes = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(registerRes);

  // 2. Log in as admin to set Authorization for privileged requests
  const loginRes = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(loginRes);
  // Authorization header is now set for subsequent privileged API calls

  // 3. Create a moderation action (the parent for the audit)
  const actionInput = {
    report_id: typia.random<string & tags.Format<"uuid">>(),
    operator_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: RandomGenerator.alphabets(8),
    target_type: RandomGenerator.alphabets(6),
    status: "pending",
    rationale: RandomGenerator.paragraph()(),
    outcome: "accepted",
  } satisfies IPolEcoBoardModerationAction.ICreate;
  const moderationAction = await api.functional.polEcoBoard.admin.moderationActions.create(
    connection,
    { body: actionInput },
  );
  typia.assert(moderationAction);

  // 4. Create an audit associated with the moderation action
  const auditInput = {
    moderation_action_id: moderationAction.id,
    auditor_id: moderationAction.operator_id,
    pre_state_snapshot: JSON.stringify(moderationAction),
    post_state_snapshot: JSON.stringify(moderationAction),
    reason: RandomGenerator.content()()(),
  } satisfies IPolEcoBoardModerationAudit.ICreate;
  const moderationAudit = await api.functional.polEcoBoard.admin.moderationActions.audits.create(
    connection,
    {
      moderationActionId: moderationAction.id,
      body: auditInput,
    },
  );
  typia.assert(moderationAudit);

  // 5. Successfully delete the audit as admin
  await api.functional.polEcoBoard.admin.moderationActions.audits.erase(
    connection,
    { moderationActionId: moderationAction.id, auditId: moderationAudit.id },
  );

  // 6. Try to delete the audit again (must fail with not found)
  await TestValidator.error("second delete of same audit must fail")(
    async () => {
      await api.functional.polEcoBoard.admin.moderationActions.audits.erase(
        connection,
        { moderationActionId: moderationAction.id, auditId: moderationAudit.id },
      );
    },
  );

  // 7. Attempt deletion as non-admin (simulate by removing admin Authorization header)
  const anonConnection = { ...connection, headers: {} } satisfies api.IConnection;
  await TestValidator.error("non-admin/unauthenticated cannot delete audit")(
    async () => {
      await api.functional.polEcoBoard.admin.moderationActions.audits.erase(
        anonConnection,
        { moderationActionId: moderationAction.id, auditId: moderationAudit.id },
      );
    },
  );

  // 8. Attempt to delete a non-existent audit under this moderation action
  await TestValidator.error("deleting random auditId fails")(
    async () => {
      await api.functional.polEcoBoard.admin.moderationActions.audits.erase(
        connection,
        {
          moderationActionId: moderationAction.id,
          auditId: typia.random<string & tags.Format<"uuid">>(),
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardSanction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardSanction";
import type { IPageIPolEcoBoardSanction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardSanction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate admin sanction search: filtering, access-control, and invalid-parameter handling.
 *
 * This test covers the workflow for listing/searching sanctions as an admin. It ensures that:
 * - Admin registration and authentication are correctly required and establish privilege.
 * - Multiple distinct moderation actions and sanctions are created for test data diversity.
 * - The search endpoint supports filtering by various criteria: status, type, user/member, moderation action, date-range, and pagination.
 * - Returned data honors each filter and includes correct pagination metadata.
 * - Invalid/malformed filters result in an appropriate validation error.
 * - Access control is enforced: only admins can search, attempts by non-admins or anonymous users are denied.
 *
 * Scenario Steps:
 * 1. Register an admin with a unique email/password for exclusive access.
 * 2. Log in as that admin to activate session/JWT.
 * 3. Create at least two moderation actions with different operator IDs and report IDs.
 * 4. For each moderation action, create sanctions with varied types, statuses, users, start/end times.
 * 5. Run search with no filters (should return all sanctions, paginated).
 * 6. Search by specific status (e.g., 'active'), specific sanction_type, and specific user.
 * 7. Search for a time range that only matches some sanctions.
 * 8. Use pagination (page, limit) and verify returned data & meta.
 * 9. Test invalid filters (bad field, wrong format) and expect validation errors.
 * 10. (Access) Try unauthorized search (not logged in or non-admin) and assert access denied.
 */
export async function test_api_sanction_search_admin_role_and_filters(connection: api.IConnection) {
  // 1. Register admin with unique credentials
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResponse);

  // 2. Log in as that admin
  const signInResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResponse);

  // 3. Create two moderation actions (pretend operator_id is admin's, distinct reports)
  const operatorId = typia.random<string & tags.Format<"uuid">>(); // can't get the admin id directly, so random
  const reportId1 = typia.random<string & tags.Format<"uuid">>();
  const reportId2 = typia.random<string & tags.Format<"uuid">>();

  const moderationAction1 = await api.functional.polEcoBoard.admin.moderationActions.create(connection, {
    body: {
      report_id: reportId1,
      operator_id: operatorId,
      action_type: "warn",
      target_type: "post",
      status: "completed",
      rationale: RandomGenerator.paragraph()(),
      outcome: "accepted",
    } satisfies IPolEcoBoardModerationAction.ICreate,
  });
  typia.assert(moderationAction1);

  const moderationAction2 = await api.functional.polEcoBoard.admin.moderationActions.create(connection, {
    body: {
      report_id: reportId2,
      operator_id: operatorId,
      action_type: "remove",
      target_type: "comment",
      status: "completed",
      rationale: RandomGenerator.paragraph()(),
      outcome: "accepted",
    } satisfies IPolEcoBoardModerationAction.ICreate,
  });
  typia.assert(moderationAction2);

  // 4. Create several sanctions for both actions, with distinct users/types/status/times
  const sanctionedUser1 = typia.random<string & tags.Format<"uuid">>();
  const sanctionedUser2 = typia.random<string & tags.Format<"uuid">>();
  const now = new Date();
  const inFuture = new Date(now.getTime() + 2 * 86400 * 1000); // +2 days
  const past = new Date(now.getTime() - 2 * 86400 * 1000); // -2 days

  // Sanction 1: Recent, active, type 'ban', user1
  const sanction1 = await api.functional.polEcoBoard.admin.sanctions.create(connection, {
    body: {
      moderation_action_id: moderationAction1.id,
      sanctioned_user_id: sanctionedUser1,
      sanction_type: "ban",
      status: "active",
      rationale: RandomGenerator.paragraph()(),
      start_at: now.toISOString(),
      end_at: inFuture.toISOString(),
    } satisfies IPolEcoBoardSanction.ICreate,
  });
  typia.assert(sanction1);

  // Sanction 2: Old, expired, type 'suspension', user2
  const sanction2 = await api.functional.polEcoBoard.admin.sanctions.create(connection, {
    body: {
      moderation_action_id: moderationAction2.id,
      sanctioned_user_id: sanctionedUser2,
      sanction_type: "suspension",
      status: "expired",
      rationale: RandomGenerator.paragraph()(),
      start_at: past.toISOString(),
      end_at: now.toISOString(),
    } satisfies IPolEcoBoardSanction.ICreate,
  });
  typia.assert(sanction2);

  // Sanction 3: warning, same user1, status 'active'
  const sanction3 = await api.functional.polEcoBoard.admin.sanctions.create(connection, {
    body: {
      moderation_action_id: moderationAction2.id,
      sanctioned_user_id: sanctionedUser1,
      sanction_type: "warning",
      status: "active",
      rationale: RandomGenerator.paragraph()(),
      start_at: now.toISOString(),
      end_at: inFuture.toISOString(),
    } satisfies IPolEcoBoardSanction.ICreate,
  });
  typia.assert(sanction3);

  // 5. Search with no filters - should return all
  {
    const result = await api.functional.polEcoBoard.admin.sanctions.search(connection, {
      body: {} satisfies IPolEcoBoardSanction.IRequest,
    });
    typia.assert(result);
    // Should include at least the sanctions just created
    const sanctionIds = [sanction1.id, sanction2.id, sanction3.id];
    const resultIds = result.data.map(s => s.id);
    for (const id of sanctionIds) {
      TestValidator.predicate(`result includes created sanction ${id}`)(resultIds.includes(id));
    }
    // Pagination meta present
    TestValidator.predicate("pagination object present")(!!result.pagination);
  }

  // 6. Filter by status, sanction_type, sanctioned_user_id
  {
    // Only active
    const result = await api.functional.polEcoBoard.admin.sanctions.search(connection, {
      body: {
        status: "active",
      } satisfies IPolEcoBoardSanction.IRequest,
    });
    typia.assert(result);
    for (const s of result.data) {
      TestValidator.equals("all active")(s.status)("active");
    }
    // Only ban
    const resultBan = await api.functional.polEcoBoard.admin.sanctions.search(connection, {
      body: {
        sanction_type: "ban",
      } satisfies IPolEcoBoardSanction.IRequest,
    });
    typia.assert(resultBan);
    for (const s of resultBan.data) {
      TestValidator.equals("all bans")(s.sanction_type)("ban");
    }
    // Only user1
    const resultUser1 = await api.functional.polEcoBoard.admin.sanctions.search(connection, {
      body: {
        sanctioned_user_id: sanctionedUser1,
      } satisfies IPolEcoBoardSanction.IRequest,
    });
    typia.assert(resultUser1);
    for (const s of resultUser1.data) {
      TestValidator.equals("user id")(s.sanctioned_user_id)(sanctionedUser1);
    }
  }

  // 7. Filter by moderation_action or by date range
  {
    // By moderation_action
    const result = await api.functional.polEcoBoard.admin.sanctions.search(connection, {
      body: {
        moderation_action_id: moderationAction2.id,
      } satisfies IPolEcoBoardSanction.IRequest,
    });
    typia.assert(result);
    for (const s of result.data) {
      TestValidator.equals("moderation_action_id matches")(s.moderation_action_id)(moderationAction2.id);
    }
    // By start_from and end_to
    const resultRange = await api.functional.polEcoBoard.admin.sanctions.search(connection, {
      body: {
        start_from: past.toISOString(),
        end_to: inFuture.toISOString(),
      } satisfies IPolEcoBoardSanction.IRequest,
    });
    typia.assert(resultRange);
    for (const s of resultRange.data) {
      TestValidator.predicate("start_at inside range")(
        new Date(s.start_at) >= past && new Date(s.start_at) <= inFuture
      );
    }
  }

  // 8. Pagination test
  {
    const result = await api.functional.polEcoBoard.admin.sanctions.search(connection, {
      body: {
        page: 1,
        limit: 2,
      } satisfies IPolEcoBoardSanction.IRequest,
    });
    typia.assert(result);
    TestValidator.equals("limit respected")(result.data.length)(Math.min(2, result.pagination.records));
    TestValidator.equals("page number")(result.pagination.current)(1);
    TestValidator.predicate("valid pages count")(result.pagination.pages >= 1);
  }

  // 9. Invalid filters (malformed uuid, bad status string, page too low)
  {
    // Bad format for UUID
    await TestValidator.error("malformed moderation_action_id triggers validation error")(
      async () => {
        await api.functional.polEcoBoard.admin.sanctions.search(connection, {
          body: {
            moderation_action_id: "not-a-uuid",
          } as any, // purposely wrong for runtime validation
        });
      },
    );
    // Page < 1, limit > 100
    await TestValidator.error("invalid pagination triggers validation")(
      async () => {
        await api.functional.polEcoBoard.admin.sanctions.search(connection, {
          body: {
            page: 0,
            limit: 1000,
          } as any,
        });
      }
    );
  }

  // 10. Access control check (simulate missing/invalid auth)
  {
    // Remove Authorization header
    const unauthConn = { ...connection, headers: { ...connection.headers } };
    delete unauthConn.headers["Authorization"];
    await TestValidator.error("unauthenticated search denied")(
      async () => {
        await api.functional.polEcoBoard.admin.sanctions.search(unauthConn, {
          body: {},
        });
      }
    );
    // Provide bogus Authorization header
    const invalidConn = { ...connection, headers: { ...connection.headers, Authorization: "Bearer BADTOKEN" } };
    await TestValidator.error("invalid token search denied")(
      async () => {
        await api.functional.polEcoBoard.admin.sanctions.search(invalidConn, {
          body: {},
        });
      }
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardSanction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardSanction";
import type { IPageIPolEcoBoardSanction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardSanction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Test that a moderator can search for sanctions within permitted scope, and that filtering, pagination, and status/type work as designed.
 *
 * 1. Register moderator
 * 2. Log in as moderator and verify identity
 * 3. Create moderation action
 * 4. Create a sanction for a test user
 * 5. Test all filter/search scenarios:
 *    - moderation_action_id filter
 *    - sanctioned_user_id filter
 *    - sanction_type/status filter
 *    - pagination (limit)
 *    - start_from/end_to (date window)
 * 6. Confirm scope control: unprivileged search yields no results
 * 7. Test error for bad status value
 * 8. Register a different moderator and confirm no access to prior moderator's sanctions
 */
export async function test_api_sanction_search_moderator_access_scope_and_filtering(
  connection: api.IConnection,
) {
  // 1. Register moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "TestP@ssw0rd1!";
  const moderatorSignUp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: RandomGenerator.name(),
      consent_status: "accepted-v1",
    },
  });
  typia.assert(moderatorSignUp);
  const moderatorId = moderatorSignUp.moderatorId;

  // 2. Log in as moderator and verify identity
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  typia.assert(moderatorLogin);
  TestValidator.equals("moderator ID matches")(moderatorLogin.moderatorId)(moderatorId);
  TestValidator.equals("moderator email matches")(moderatorLogin.email)(moderatorEmail);

  // 3. Create moderation action
  const moderationAction = await api.functional.polEcoBoard.moderator.moderationActions.create(connection, {
    body: {
      report_id: typia.random<string & tags.Format<"uuid">>(),
      operator_id: moderatorId,
      action_type: "remove",
      target_type: "post",
      status: "completed",
      rationale: "E2E test moderation action rationale",
      outcome: "accepted",
    },
  });
  typia.assert(moderationAction);
  TestValidator.equals("moderation action operator_id")(moderationAction.operator_id)(moderatorId);

  // 4. Create a sanction for a dummy user
  const sanctionedUserId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date();
  const sanction = await api.functional.polEcoBoard.moderator.sanctions.create(connection, {
    body: {
      moderation_action_id: moderationAction.id,
      sanctioned_user_id: sanctionedUserId,
      sanction_type: "ban",
      status: "active",
      rationale: "E2E test sanction rationale",
      start_at: now.toISOString(),
      end_at: new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString(),
    },
  });
  typia.assert(sanction);
  TestValidator.equals("sanction operator id via moderation action")(sanction.moderation_action_id)(moderationAction.id);
  TestValidator.equals("sanctioned user matches")(sanction.sanctioned_user_id)(sanctionedUserId);

  // 5a. Search by moderation_action_id
  const searchByAction = await api.functional.polEcoBoard.moderator.sanctions.search(connection, {
    body: { moderation_action_id: moderationAction.id },
  });
  typia.assert(searchByAction);
  TestValidator.predicate("search by moderation_action_id yields sanction")(
    searchByAction.data.some(s => s.id === sanction.id)
  );

  // 5b. Search by sanctioned_user_id
  const searchByUser = await api.functional.polEcoBoard.moderator.sanctions.search(connection, {
    body: { sanctioned_user_id: sanctionedUserId },
  });
  typia.assert(searchByUser);
  TestValidator.predicate("search by sanctioned_user_id yields sanction")(
    searchByUser.data.some(s => s.id === sanction.id)
  );

  // 5c. Search by sanction_type and status
  const searchByTypeAndStatus = await api.functional.polEcoBoard.moderator.sanctions.search(connection, {
    body: {
      sanction_type: "ban",
      status: "active",
    },
  });
  typia.assert(searchByTypeAndStatus);
  TestValidator.predicate("search by sanction_type/status yields sanction")(
    searchByTypeAndStatus.data.some(s => s.id === sanction.id)
  );

  // 5d. Pagination test (limit=1)
  const pagedResults = await api.functional.polEcoBoard.moderator.sanctions.search(connection, {
    body: { page: 1, limit: 1 },
  });
  typia.assert(pagedResults);
  TestValidator.equals("pagination limit=1")(pagedResults.data.length)(1);

  // 5e. Date range (start_from/end_to) — include 'end_to' property only if not null
  const dateRangeBody: { start_from: string } & { end_to?: string } = sanction.end_at != null
    ? { start_from: now.toISOString(), end_to: sanction.end_at }
    : { start_from: now.toISOString() };
  const searchByDateRange = await api.functional.polEcoBoard.moderator.sanctions.search(connection, {
    body: dateRangeBody,
  });
  typia.assert(searchByDateRange);
  TestValidator.predicate("search by date range yields sanction")(
    searchByDateRange.data.some(s => s.id === sanction.id)
  );

  // 6. Scope enforcement: unrelated moderation_action_id yields no results
  const unrelatedActionId = typia.random<string & tags.Format<"uuid">>();
  const unrelatedSearch = await api.functional.polEcoBoard.moderator.sanctions.search(connection, {
    body: { moderation_action_id: unrelatedActionId },
  });
  typia.assert(unrelatedSearch);
  TestValidator.predicate("unrelated moderation_action_id does not show sanction")(
    unrelatedSearch.data.every(s => s.id !== sanction.id)
  );

  // 7. Malformed filter: status with a value not in business list should error
  TestValidator.error("bad status value throws error")(() =>
    api.functional.polEcoBoard.moderator.sanctions.search(connection, {
      body: { status: "not-a-valid-status" },
    })
  );

  // 8. Create a different moderator, check cross-scope restriction
  const outsiderEmail = typia.random<string & tags.Format<"email">>();
  const outsiderPassword = "AnotherMod!2";
  const outsiderReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: outsiderEmail,
      password: outsiderPassword,
      display_name: RandomGenerator.name(),
      consent_status: "accepted-v1",
    },
  });
  typia.assert(outsiderReg);
  await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: outsiderEmail,
      password: outsiderPassword,
    },
  });
  const outsiderSearch = await api.functional.polEcoBoard.moderator.sanctions.search(connection, {
    body: { moderation_action_id: moderationAction.id },
  });
  typia.assert(outsiderSearch);
  TestValidator.predicate("outsider moderator cannot see created sanction")(
    !outsiderSearch.data.some(s => s.id === sanction.id)
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModerationAction";
import type { IPolEcoBoardSanction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardSanction";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that admin can retrieve the full details of a sanction by ID (with business compliance) and ensure proper permissions and not-found logic.
 *
 * Scenario steps:
 * 1. Register a new admin (using random unique credentials).
 * 2. Login as that admin for authorization/session.
 * 3. Create a moderation action (provides moderation_action_id).
 * 4. Create a valid sanction referencing the newly created moderation action and a target user (using random uuid for user).
 * 5. Retrieve the just-created sanction by its sanctionId as admin and validate all returned fields are present and business accurate (type, linkages, rationale, status, audit fields).
 * 6. Check access control by logging out (simulate no admin) or passing empty connection/headers and attempting to get the sanction detail - expect business error due to missing/invalid permissions.
 * 7. Attempt to fetch a sanction with a non-existent sanctionId (random UUID not used in system) - ensure the API returns not-found according to business error handling.
 * 8. Delete (soft delete) the sanction (simulate by directly setting the deleted_at field if possible, but if API not provided, skip actual deletion) and try to retrieve it, confirming the business error for accessing deleted sanctions or not-found semantics per API behavior.
 * (If soft/hard delete endpoint is not available, skip actual deletion step, but always check the not-found handler.)
