import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate that a moderator can update file attachment metadata on any post regardless of authorship.
 *
 * This test ensures the following end-to-end workflow aligns with business policy:
 *   1. Register a new moderator and login to obtain moderator session/context.
 *   2. Register a new regular member, then login as that member for post creation.
 *   3. Member creates a post, which will serve as the target for the test attachment.
 *   4. Member uploads/adds a file attachment to that post.
 *   5. Switch back to the moderator session: the moderator now updates the attachment's permitted mutable metadata (e.g., file_name, mime_type).
 *   6. Confirm the update via returned API response and assertions (direct audit/log review is not possible without suitable endpoints; business traceability is implied).
 *
 * This validates:
 *   • Moderator can update any permitted metadata on attachments, regardless of post author.
 *   • Only allowed fields are mutable; ID/author remain unchanged.
 *   • Response data reflects updated state after change.
 *
 * Implementation notes:
 *   • Only update those fields that are mutable as per IPolEcoBoardAttachment.IUpdate (file_name, mime_type).
 *   • Confirm update by comparing with prior values and submitted update object.
 *   • Use only the actual SDK endpoints and DTOs—no audit/log endpoints are assumed.
 */
export async function test_api_post_attachment_update_moderator_permissions(
  connection: api.IConnection,
) {
  // 1. Register and login a moderator
  const moderatorCredentials = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "P@ssw0rd123!",
    display_name: RandomGenerator.name(),
    consent_status: "accepted/2025-01-01"
  } satisfies IPolEcoBoardModeratorRegistration.ICreate;
  const moderatorRegister = await api.functional.auth.moderator.register.signUp(connection, { body: moderatorCredentials });
  typia.assert(moderatorRegister);
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorCredentials.email,
      password: moderatorCredentials.password
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate
  });
  typia.assert(moderatorLogin);

  // 2. Register and login as a regular member
  const memberCredentials = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "P@ssw0rd456!"
  } satisfies IMemberAuthenticationMemberSignUp;
  const memberRegister = await api.functional.auth.member.register.signUp(connection, { body: memberCredentials });
  typia.assert(memberRegister);
  const memberLogin = await api.functional.auth.member.login.signIn(connection, { body: memberCredentials });
  typia.assert(memberLogin);

  // Use member's JWT token for post/attachment creation
  if (!connection.headers) connection.headers = {};
  connection.headers.Authorization = memberLogin.setHeaders.Authorization;
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1).slice(0, 40),
      body: RandomGenerator.content()()(1).slice(0, 200),
      tag_ids: null,
      attachments: null
    } satisfies IPolEcoBoardPost.ICreate
  });
  typia.assert(post);
  const attachment = await api.functional.polEcoBoard.member.posts.attachments.create(connection, {
    postId: post.id,
    body: {
      uri: `https://cdn.testdomain.dev/uploads/${typia.random<string & tags.Format<"uuid">>()}`,
      file_name: `document_${RandomGenerator.alphaNumeric(6)}.pdf`,
      file_size_bytes: typia.random<number & tags.Type<"int32"> & tags.Minimum<100> & tags.Maximum<10000000>>() ,
      mime_type: "application/pdf"
    } satisfies IPolEcoBoardAttachment.ICreate
  });
  typia.assert(attachment);

  // 3. Switch back to moderator token for update
  if (!connection.headers) connection.headers = {};
  connection.headers.Authorization = moderatorLogin.setHeaders.Authorization;
  const updatePayload: IPolEcoBoardAttachment.IUpdate = {
    file_name: `updated_${RandomGenerator.alphaNumeric(8)}.pdf`,
    mime_type: "application/vnd.adobe.pdf"
  };
  const updatedAttachment = await api.functional.polEcoBoard.moderator.posts.attachments.update(connection, {
    postId: post.id,
    attachmentId: attachment.id,
    body: updatePayload
  });
  typia.assert(updatedAttachment);

  // 4. Validate field changes
  TestValidator.equals("file_name updated")(updatedAttachment.file_name)(updatePayload.file_name);
  TestValidator.equals("mime_type updated")(updatedAttachment.mime_type)(updatePayload.mime_type);
  TestValidator.equals("attachment id remains")(updatedAttachment.id)(attachment.id);
  TestValidator.equals("post id remains")(updatedAttachment.post_id)(post.id);
  TestValidator.equals("author member id unchanged")(updatedAttachment.author_member_id)(attachment.author_member_id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate not-found error when moderator attempts to update a non-existent attachment.
 *
 * This test ensures the following business logic for the moderator endpoint:
 * - When a moderator is properly registered and logged in
 * - And attempts to update a file attachment with a postId and attachmentId that do not correspond to any actual existing resource
 * - Then, the server must return a not-found (404) or relevant business rule error indicating the resource cannot be found or updated
 * - No successful result or data object must be returned for such a request
 *
 * Steps:
 * 1. Register a unique moderator account (using random valid email and credentials)
 * 2. Login as the new moderator to set the Authorization context
 * 3. Attempt to update an attachment using random (non-existent) postId and attachmentId
 * 4. Assert that the API correctly rejects the request with an error (not found / business rule)
 * 5. Ensure no attachment object or successful output is returned
 */
export async function test_api_post_attachment_update_moderator_invalid_attachment_error(
  connection: api.IConnection
) {
  // 1. Register new moderator
  const moderatorInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "TestPassw0rd!",
    display_name: RandomGenerator.name(),
    consent_status: "accept-latest-privacy",
  } satisfies IPolEcoBoardModeratorRegistration.ICreate;
  const regOutput = await api.functional.auth.moderator.register.signUp(connection, {
    body: moderatorInput,
  });
  typia.assert(regOutput);

  // 2. Login as moderator (set Authorization header)
  const loginOutput = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorInput.email,
      password: moderatorInput.password,
    },
  });
  typia.assert(loginOutput);

  // 3. Randomly generated UUIDs for postId/attachmentId (guaranteed non-existent)
  const invalidPostId = typia.random<string & tags.Format<"uuid">>();
  const invalidAttachmentId = typia.random<string & tags.Format<"uuid">>();
  const updateBody = {
    file_name: "updated_test_file.txt",
    mime_type: "text/plain",
  } satisfies IPolEcoBoardAttachment.IUpdate;

  // 4. Attempt update and expect error
  await TestValidator.error("Should error for non-existent attachment")(
    async () => {
      await api.functional.polEcoBoard.moderator.posts.attachments.update(connection, {
        postId: invalidPostId,
        attachmentId: invalidAttachmentId,
        body: updateBody,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that an admin can update attachment metadata on any post (global admin scope).
 *
 * Business context:
 * Admins, for purposes of compliance or operational support, must be able to edit permitted attachment metadata (such as file_name and mime_type) on any post, regardless of the original post or attachment creator. This ensures regulatory correctness and robust auditability, with clear boundaries between mutable and immutable fields. All updates must produce accurate audit logs (not directly checked here), and changes are validated by the API against strict typing and business constraints.
 *
 * Test steps:
 * 1. Register a new admin account with random business email and password
 * 2. Log in as this admin to validate privilege acquisition
 * 3. Register a new member account and log in
 * 4. As the member, create a post under a random category
 * 5. As the member, upload an attachment to that post
 * 6. Re-authenticate as admin for the following update operation
 * 7. As admin, update the attachment's file_name and mime_type via the admin API
 * 8. Validate that only file_name and mime_type are updated (all other fields are immutable and remain unchanged)
 * 9. Confirm response integrity and field value propagation; audit logging is assumed present (not directly checked from API)
 */
export async function test_api_post_attachment_update_admin_global_scope(
  connection: api.IConnection,
) {
  // 1. Register a new admin account (random email/password)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // 2. Login as admin
  const adminSignIn = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminSignIn);
  // Store admin JWT for later
  const adminHeaders = { ...connection.headers, ...adminSignIn.setHeaders };

  // 3. Register & login a member account
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(12);
  const memberSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberSignUp);
  const memberSignIn = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberSignIn);
  // Switch connection headers to member for subsequent operations
  connection.headers = { ...connection.headers, ...memberSignIn.setHeaders };

  // 4. Create a post as member
  const postBody: IPolEcoBoardPost.ICreate = {
    category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
    tag_ids: null,
    attachments: null,
  };
  const createdPost = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: postBody,
  });
  typia.assert(createdPost);

  // 5. Upload an attachment to that post as member
  const attachmentBody: IPolEcoBoardAttachment.ICreate = {
    uri: `https://cdn.example.com/${RandomGenerator.alphaNumeric(16)}`,
    file_name: `file_${RandomGenerator.alphaNumeric(8)}.pdf`,
    file_size_bytes: typia.random<number & tags.Type<"int32">>(),
    mime_type: "application/pdf",
  };
  const createdAttachment = await api.functional.polEcoBoard.member.posts.attachments.create(connection, {
    postId: createdPost.id,
    body: attachmentBody,
  });
  typia.assert(createdAttachment);

  // 6. Re-authenticate as admin
  connection.headers = adminHeaders;

  // 7. As admin, update the attachment's file_name and mime_type
  const updatedFileName = `ADMINEDIT_${RandomGenerator.alphaNumeric(8)}.pdf`;
  const updatedMimeType = "application/pdf";
  const attachmentUpdateBody: IPolEcoBoardAttachment.IUpdate = {
    file_name: updatedFileName,
    mime_type: updatedMimeType,
  };
  const updatedAttachment = await api.functional.polEcoBoard.admin.posts.attachments.update(connection, {
    postId: createdPost.id,
    attachmentId: createdAttachment.id,
    body: attachmentUpdateBody,
  });
  typia.assert(updatedAttachment);

  // 8. Validate changes: only the allowed fields changed
  TestValidator.equals("attachment id")(updatedAttachment.id)(createdAttachment.id);
  TestValidator.equals("post id")(updatedAttachment.post_id)(createdAttachment.post_id);
  TestValidator.equals("author member id")(updatedAttachment.author_member_id)(createdAttachment.author_member_id);
  TestValidator.equals("file name updated")(updatedAttachment.file_name)(updatedFileName);
  TestValidator.equals("mime type updated")(updatedAttachment.mime_type)(updatedMimeType);
  TestValidator.equals("file size unchanged")(updatedAttachment.file_size_bytes)(createdAttachment.file_size_bytes);
  TestValidator.equals("uri unchanged")(updatedAttachment.uri)(createdAttachment.uri);
  TestValidator.equals("created_at unchanged")(updatedAttachment.created_at)(createdAttachment.created_at);
  TestValidator.equals("deleted_at unchanged")(
    updatedAttachment.deleted_at === undefined ? null : updatedAttachment.deleted_at
  )(
    createdAttachment.deleted_at === undefined ? null : createdAttachment.deleted_at
  );
}

