import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that an admin can fetch an existing notification preference record by its ID.
 *
 * Business context:
 * Only authenticated admins can use the admin endpoint to query any user's notification preferences for audit, compliance, or support operations. This test guarantees the admin path grants access and returns a complete record, and that created per-member preferences are discoverable by the admin.
 *
 * Workflow:
 * 1. Register a new admin (email/password)
 * 2. Login as that admin to establish Authorization context
 * 3. Register a new member (separate email/password)
 * 4. Login as member to create a notification preference record
 * 5. As member, create a notification preference with required payload (member_id set, event_type, channel, opt_in)
 * 6. Switch to admin (login) and fetch notification preference by its ID via privileged endpoint
 * 7. Validate all expected fields: id, member_id, event_type, channel, opt_in, created_at, updated_at
 */
export async function test_api_notification_preference_admin_get_any_success(connection: api.IConnection) {
  // 1. Register new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminRegister = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminRegister);

  // 2. Login as admin (store for switch-back)
  const adminLogin = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLogin);

  // 3. Register a new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const memberRegister = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberRegister);

  // 4. Login as member
  const memberLogin = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(memberLogin);

  // 5. Member creates a notification preference
  // We must know the member's UUID id. Since /auth/member/register returns only setHeaders, we assume the API uses the Authorization header, so when we send member token, /polEcoBoard/member/notificationPreferences takes Auth header and deduces member_id from session, but according to DTO, member_id is required and must be set. So we track member_id after creation if available, or generate and store it if required. For this test, we use typia.random for uuid.
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const eventType = RandomGenerator.pick(["reply", "moderation_action", "announcement"]);
  const channel = RandomGenerator.pick(["email", "push", "in_app", "sms"]);
  const optIn = true;

  const notificationPreference = await api.functional.polEcoBoard.member.notificationPreferences.create(connection, {
    body: {
      member_id: memberId,
      event_type: eventType,
      channel: channel,
      opt_in: optIn,
    } satisfies IPolEcoBoardNotificationPreference.ICreate,
  });
  typia.assert(notificationPreference);

  // 6. Switch to admin by logging in again
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 7. Admin fetches notification preference by ID
  const output = await api.functional.polEcoBoard.admin.notificationPreferences.at(connection, {
    notificationPreferenceId: notificationPreference.id,
  });
  typia.assert(output);

  // 8. Validate all fields present and values match
  TestValidator.equals("id")(output.id)(notificationPreference.id);
  TestValidator.equals("member_id")(output.member_id)(notificationPreference.member_id);
  TestValidator.equals("event_type")(output.event_type)(notificationPreference.event_type);
  TestValidator.equals("channel")(output.channel)(notificationPreference.channel);
  TestValidator.equals("opt_in")(output.opt_in)(notificationPreference.opt_in);
  TestValidator.predicate("created_at is ISO8601 date")(!!output.created_at && !isNaN(Date.parse(output.created_at)));
  TestValidator.predicate("updated_at is ISO8601 date")(!!output.updated_at && !isNaN(Date.parse(output.updated_at)));
}

