import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Test input validation for notification preference creation as a member.
 *
 * This test checks:
 *  1. Proper enforcement of supported event_type and channel values
 *  2. Required field validation
 *  3. Type and format enforcement on field values
 *  4. Ensures that no record is created on invalid input (API returns validation error)
 *
 * Step-by-step process:
 * 1. Register a new member account with a valid email and password
 * 2. Login as the created member and retain Authorization for future requests
 * 3. Attempt to create notification preferences using various invalid data:
 *    - Unsupported event_type (e.g., 'invalid_event')
 *    - Unsupported channel (e.g., 'carrier_pigeon')
 *    - Missing required fields (such as channel, event_type, opt_in, or member_id)
 *    - Malformed values (e.g., non-uuid member_id, opt_in as string, etc.)
 * 4. For each invalid input, expect an actionable validation error from the API and no successful record creation.
 */
export async function test_api_notification_preference_member_create_invalid_values(
  connection: api.IConnection,
) {
  // 1. Register new member
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.Format<"password">>();
  const registration = await api.functional.auth.member.register.signUp(connection, {
    body: { email, password } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(registration);

  // 2. Login as member
  const login = await api.functional.auth.member.login.signIn(connection, {
    body: { email, password } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(login);

  // Helper: generate a valid notification preference payload
  const validPayload = (): IPolEcoBoardNotificationPreference.ICreate => ({
    member_id: typia.random<string & tags.Format<"uuid">>(),
    event_type: "reply",
    channel: "email",
    opt_in: true,
  });

  // Prepare invalid test cases
  const invalidCases: Partial<IPolEcoBoardNotificationPreference.ICreate>[] = [
    // 1. Unsupported event_type
    { ...validPayload(), event_type: "invalid_event" },
    // 2. Unsupported channel
    { ...validPayload(), channel: "carrier_pigeon" },
    // 3. Missing event_type
    (({ event_type, ...rest }) => rest)(validPayload()),
    // 4. Missing channel
    (({ channel, ...rest }) => rest)(validPayload()),
    // 5. Missing opt_in
    (({ opt_in, ...rest }) => rest)(validPayload()),
    // 6. Missing member_id
    (({ member_id, ...rest }) => rest)(validPayload()),
    // 7. Malformed member_id
    { ...validPayload(), member_id: "not-a-uuid" as any },
    // 8. opt_in as string
    { ...validPayload(), opt_in: "yes" as any },
  ];

  // 3. Attempt creation with each invalid input & expect a validation error
  for (const [i, body] of invalidCases.entries()) {
    await TestValidator.error(`invalid notification preference input case #${i + 1}`)(async () => {
      await api.functional.polEcoBoard.member.notificationPreferences.create(connection, {
        body: body as IPolEcoBoardNotificationPreference.ICreate,
      });
    });
  }
}

