 *
 * Steps:
 * 1. Register a new member (user)
 * 2. Create a board category (admin)
 * 3. Create a board in the category (admin)
 * 4. Create an initial tag for assignment (admin)
 * 5. The member creates a post in the board
 * 6. The member assigns the initial tag to their post
 * 7. Create a second tag for updating (admin)
 * 8. The member updates their own post tag assignment to use the new tag
 * 9. Validate the update succeeds: the tag assignment's tag_id is updated, id/post_id remain unchanged
 */
export async function test_api_post_tag_member_update_success(
  connection: api.IConnection,
) {
  // 1. Register member
  const memberEmail = typia.random<string & tags.Format<'email'>>();
