  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.alphaNumeric(10),
      code: RandomGenerator.alphaNumeric(8),
      description: null,
      is_public: true,
      is_archived: false,
      display_order: 1,
    },
  });
  typia.assert(board);

  // 4. Create initial tag (admin)
  const initialTag = await api.functional.polEcoBoard.admin.tags.create(connection, {
    body: {
      name: 'initTag' + RandomGenerator.alphaNumeric(4),
      slug: 'init-tag-' + RandomGenerator.alphaNumeric(4),
      description: null,
    },
  });
  typia.assert(initialTag);

  // 5. Member creates a post in the board
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: 'Initial Test Post',
      body: 'Test post body.',
      tag_ids: null,
      attachments: null,
    },
  });
  typia.assert(post);

  // 6. Member assigns initial tag to post
  const postTag = await api.functional.polEcoBoard.member.posts.postTags.create(connection, {
    postId: post.id,
    body: {
      tag_id: initialTag.id,
    },
  });
  typia.assert(postTag);

  // 7. Create a second tag (admin) for update
  const updatedTag = await api.functional.polEcoBoard.admin.tags.create(connection, {
    body: {
      name: 'updatedTag' + RandomGenerator.alphaNumeric(4),
      slug: 'updated-tag-' + RandomGenerator.alphaNumeric(4),
      description: null,
    },
  });
  typia.assert(updatedTag);

  // 8. Member updates post tag assignment to new tag
  const updatedPostTag = await api.functional.polEcoBoard.member.posts.postTags.update(connection, {
    postId: post.id,
    postTagId: postTag.id,
    body: {
      tag_id: updatedTag.id,
    },
  });
  typia.assert(updatedPostTag);

  // 9. Validate that the update was successful
  TestValidator.equals('tag_id is updated')(updatedPostTag.tag_id)(updatedTag.id);
  TestValidator.equals('post_id unchanged')(updatedPostTag.post_id)(post.id);
  TestValidator.equals('id unchanged')(updatedPostTag.id)(postTag.id);
}

