/**
 * Validate that the admin search endpoint returns a correct empty result set when no admins match the filter criteria.
 *
 * This test ensures that searching for admins with filters that cannot possibly match any existing admin account (e.g., an unused privilege_level or a mismatching status) will return a valid, paginated result with an empty data array and without any errors. This situation can occur in dashboards or assignment workflows where very restrictive filters are applied, so the system must respond gracefully and in compliance with contract.
 *
 * Step-by-step process:
 * 1. Register a new admin account (to ensure at least one exists and to have valid credentials for search).
 * 2. Login as the admin to acquire authentication permissions.
 * 3. Search for admins with a privilege_level that does not exist (e.g., a very high unused value).
 * 4. Assert the returned data array is empty, pagination info is correct, and no errors are thrown.
 */
export async function test_api_admin_search_empty_result(connection: api.IConnection) {
  // 1. Register a new admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  const signUpResponse = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: password
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResponse);

  // 2. Login as that admin (should set Authorization in connection)
  const signInResponse = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: password
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResponse);

  // 3. Search for admins with an impossible privilege_level (e.g., 999)
  const impossiblePrivilegeLevel = 999;
  const output = await api.functional.polEcoBoard.admin.admins.search(connection, {
    body: {
      privilege_level: impossiblePrivilegeLevel,
      page: 1,
      limit: 5
    } satisfies IPolEcoBoardAdmin.IRequest,
  });
  typia.assert(output);

  // 4. Assert correct pagination and empty result
  TestValidator.equals("empty result array")(output.data)([]);
  TestValidator.equals("pagination current page")(output.pagination.current)(1);
  TestValidator.equals("pagination limit")(output.pagination.limit)(5);
  TestValidator.equals("pagination total records")(output.pagination.records)(0);
  TestValidator.equals("pagination total pages")(output.pagination.pages)(0);
}

