  const category = await api.functional.polEcoBoard.admin.categories.create(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(16),
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardCategory.ICreate,
  });
  typia.assert(category);

  // 5. As admin, create a board in that category
  const board = await api.functional.polEcoBoard.admin.boards.create(connection, {
    body: {
      pol_eco_board_category_id: category.id,
      name: RandomGenerator.name(),
      code: RandomGenerator.alphaNumeric(10).toLowerCase(),
      description: RandomGenerator.paragraph()(8),
      is_public: true,
      is_archived: false,
      display_order: typia.random<number & tags.Type<"int32">>(),
    } satisfies IPolEcoBoardBoard.ICreate,
  });
  typia.assert(board);

  // 6. As member (session switching not available), create a post
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: category.id,
      title: RandomGenerator.paragraph()(12),
      body: RandomGenerator.content()()(40),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 7. As admin, create a post edit revision for this post
  const postEdit = await api.functional.polEcoBoard.admin.posts.postEdits.createEdit(connection, {
