/**
 * Test: member cannot retrieve comments on a post if its board is locked/archived.
 *
 * Business context: Platform must strictly restrict access to comments of posts belonging to locked or archived boards, as part of moderation and content lifecycle. This ensures users cannot interact with or view content on boards that have been administratively disabled (locked/archived). This test simulates a standard member workflow, validates permission enforcement, and prevents regression where comments surface from inactive boards.
 *
 * Steps:
 * 1. Register a new member (unique email/display_name, consent_status random static)
 * 2. Log in as that new member; capture session (auth header handled)
 * 3. Admin creates a new category (random name/desc, display_order arbitrary low int)
 * 4. Admin creates a board in this category (random name/code, is_public: true, is_archived: false)
 * 5. Member creates a post on this board's category (title/body > 10 chars, using created category)
 * 6. Admin locks/archives the board (is_archived: true)
 * 7. Attempt as member to list comments on the post: expect runtime error (forbidden/denied)
 *
 * Edge cases: Board archiving after post is created, but before comment list fetch occurs.
 */
export async function test_api_member_comment_list_access_denied_for_locked_post(connection: api.IConnection) {
  // 1. Register member
  const memberEmail = typia.random<string & tags.Format<"email">>();
