/**
 * Test successful creation of a sanction by an admin (e.g., suspension, ban).
 *
 * This test covers the following business workflow:
 * 1. Register a new admin account (for authentication and access).
 * 2. Login as the admin (obtain session/JWT for admin endpoints).
 * 3. Register a new member (who will be the target of the sanction).
 * 4. Create a moderation action record referencing the admin and a report (dummy UUID for report).
 * 5. Call the /polEcoBoard/admin/sanctions endpoint to create a new sanction referencing the moderation action and target member.
 * 6. Validate all compliance/audit fields present and correct in the response.
 *    - ID, moderation_action_id, sanctioned_user_id reference, sanction_type, status, rationale, time boundaries, created_at, updated_at, not deleted.
 *    - All field types and allowed values.
 *    - No overlapping/duplicate sanction exists.
 *
 * Steps validate correctness, reference integrity, required values, and cover business rules for compliance/audit fields.
 */
export async function test_api_sanction_creation_success_admin_role(connection: api.IConnection) {
