  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Register new member (target of sanction)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(14);
  const member: IPolEcoBoardMember = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPassword,
      display_name: RandomGenerator.name(),
      profile_image_uri: null,
      consent_status: "v1.0-consented",
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // 4. Create a moderation action (use admin for operator_id if possible)
  const operatorId = member.id; // For strict compliance, can use the admin if retrievable
  const moderationAction: IPolEcoBoardModerationAction = await api.functional.polEcoBoard.admin.moderationActions.create(connection, {
