  // 5. Create a sanction
  const start = new Date().toISOString();
  const end = new Date(Date.now() + 7 * 24 * 3600 * 1000).toISOString(); // 7 days from now
  const sanction: IPolEcoBoardSanction = await api.functional.polEcoBoard.admin.sanctions.create(connection, {
