  TestValidator.equals("end_at")(
    sanction.end_at
  )(end);
  TestValidator.predicate("created_at and updated_at are valid")(
    typeof sanction.created_at === "string" && typeof sanction.updated_at === "string"
  );
  TestValidator.equals("not soft-deleted")(
    sanction.deleted_at
  )(null);
