/**
 * Attempt to create a new sanction of the same type while another is active for the same user.
 *
 * This test checks whether the API correctly rejects duplicate, overlapping sanctions of the same type for a user. It ensures compliance with business rules preventing double bans or warnings.
 *
 * Steps:
 * 1. Register a new admin account for sanctioning authority
 * 2. Log in as the admin to gain authorization for protected endpoints
 * 3. Register the member/user that will be sanctioned
 * 4. Create a moderation action linking moderator/admin to the event
 * 5. Create an initial "active" sanction for the user with a given type and period
 * 6. Attempt to create a second active sanction for the same user/type and overlapping period — this must fail
 * 7. Confirm that the API rejects the duplicate sanction (business logic error). No duplicate ban/warning should be created.
 */
export async function test_api_sanction_creation_duplicate_active_type_rejected(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Register the member to be sanctioned
  const sanctionedEmail = typia.random<string & tags.Format<"email">>();
  const sanctionedMember = await api.functional.polEcoBoard.members.create(
    connection,
    {
      body: {
        email: sanctionedEmail,
        password_hash: RandomGenerator.alphaNumeric(16),
        display_name: RandomGenerator.name(),
        consent_status: "v1",
        profile_image_uri: null,
      } satisfies IPolEcoBoardMember.ICreate,
    },
  );
  typia.assert(sanctionedMember);

  // 4. Create a moderation action
  const modAction = await api.functional.polEcoBoard.admin.moderationActions.create(
    connection,
    {
      body: {
        report_id: typia.random<string & tags.Format<"uuid">>(),
        operator_id: sanctionedMember.id, // Ideally this would be the admin's id, but SDK does not expose it.
        action_type: "ban",
        target_type: "user",
        status: "completed",
        rationale: "First violation ban",
        outcome: "accepted",
      } satisfies IPolEcoBoardModerationAction.ICreate,
    },
  );
  typia.assert(modAction);

  // 5. Create the initial active sanction for this user
  const sanctionType = "ban";
  const sanctionStart = new Date().toISOString();
  const sanctionEnd = new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString(); // +1 day
  const firstSanction = await api.functional.polEcoBoard.admin.sanctions.create(
    connection,
    {
      body: {
        moderation_action_id: modAction.id,
        sanctioned_user_id: sanctionedMember.id,
        sanction_type: sanctionType,
        status: "active",
        rationale: "User banned for violation.",
        start_at: sanctionStart,
        end_at: sanctionEnd,
      } satisfies IPolEcoBoardSanction.ICreate,
    },
  );
  typia.assert(firstSanction);

  // 6. Attempt a duplicate sanction of the same type and overlapping time
  await TestValidator.error("API should reject duplicate active sanction for same user and type")(
    async () => {
      await api.functional.polEcoBoard.admin.sanctions.create(
        connection,
        {
          body: {
            moderation_action_id: modAction.id,
            sanctioned_user_id: sanctionedMember.id,
            sanction_type: sanctionType,
            status: "active",
            rationale: "Attempt to create duplicate ban while one is active.",
            start_at: sanctionStart,
            end_at: sanctionEnd,
          } satisfies IPolEcoBoardSanction.ICreate,
        },
      );
    },
  );
}

