/**
 * Validate successful creation of a sanction by an authorized moderator, starting from scratch.
 *
 * This test covers the privilege escalation and dependency chain for sanction creation, ensuring compliance with business rules, auditability, and linkage integrity between sanctions, moderation actions, and members.
 *
 * Steps:
 * 1. Register a new moderator with unique credentials and capture ID/email/display_name for subsequent flows.
 * 2. Log in as the registered moderator to obtain a valid authentication context (JWT in Authorization header).
 * 3. Create a new member (user)—this will serve as the sanction target. Capture the assigned user ID for all linked entities.
 * 4. Create a moderation action (e.g., warn) referencing a fake report UUID, performed by the above moderator and targeting the new member. Capture the resulting action ID.
 * 5. Create a sanction (e.g., warning or suspension) as the authenticated moderator, referencing the above moderation action and targeting the user, with future-dated start, optional end, and all required business fields.
 * 6. Validate the sanction creation response: fields are populated and correct, links to moderation action and sanctioned member match previous entities, 'status' and 'sanction_type' are as requested, and audit/compliance-time fields are present and plausible.
 *
 * Edge Cases/Validations:
 * - Moderator must be actually authenticated; attempt fails otherwise (not tested here but precondition).
 * - Member is active at time of sanction.
 * - Sanction does not overlap/conflict with existing (out of scope for this positive path test).
 * - All fields are persisted as per DTO specification.
 */
export async function test_api_sanction_creation_moderator_success(connection: api.IConnection) {
  // 1. Register a new moderator and capture identity
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = "TestPassword1!";
  const moderatorDisplayName = RandomGenerator.name();
  const consentStatus = "v1";
  const registrationResp = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: consentStatus,
    } satisfies IPolEcoBoardModeratorRegistration.ICreate,
  });
  typia.assert(registrationResp);
  const moderatorId = registrationResp.moderatorId;

  // 2. Log in as the registered moderator
  const loginResp = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    } satisfies IPolEcoBoardModeratorAuthentication.ICreate,
  });
  typia.assert(loginResp);
  // Authorization token is set in connection.headers under the hood

  // 3. Create/register a member (sanction target)
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberDisplayName = RandomGenerator.name();
  const memberPasswordHash = RandomGenerator.alphaNumeric(32);
  const memberConsent = "v1";
  const memberResp = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: memberEmail,
      password_hash: memberPasswordHash,
      display_name: memberDisplayName,
      consent_status: memberConsent,
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(memberResp);
  const memberId = memberResp.id;

  // 4. Create a moderation action performed by our moderator against fake report on the target member
  const fakeReportId = typia.random<string & tags.Format<"uuid">>();
  const moderationActionBody = {
    report_id: fakeReportId,
    operator_id: moderatorId,
    action_type: "warn",
    target_type: "user",
    status: "completed",
    rationale: "Repeated posting of prohibited content.",
    outcome: "accepted",
  } satisfies IPolEcoBoardModerationAction.ICreate;
  const moderationActionResp = await api.functional.polEcoBoard.admin.moderationActions.create(connection, {
    body: moderationActionBody,
  });
  typia.assert(moderationActionResp);
  const moderationActionId = moderationActionResp.id;

  // 5. As moderator, create a sanction referencing the action and user
  const startAt = new Date(Date.now() + 60_000).toISOString();
  const endAt = new Date(Date.now() + 86400000).toISOString();
  const sanctionType = "warning";
  const sanctionStatus = "active";
  const sanctionRationale = "Policy breach: warning issued.";
  const sanctionBody = {
    moderation_action_id: moderationActionId,
    sanctioned_user_id: memberId,
    sanction_type: sanctionType,
    status: sanctionStatus,
    rationale: sanctionRationale,
    start_at: startAt,
    end_at: endAt,
  } satisfies IPolEcoBoardSanction.ICreate;
  const sanctionResp = await api.functional.polEcoBoard.moderator.sanctions.create(connection, {
    body: sanctionBody,
  });
  typia.assert(sanctionResp);

  // 6. Validate returned sanction fields
  TestValidator.equals("moderation_action_id")(sanctionResp.moderation_action_id)(moderationActionId);
  TestValidator.equals("sanctioned_user_id")(sanctionResp.sanctioned_user_id)(memberId);
  TestValidator.equals("sanction_type")(sanctionResp.sanction_type)(sanctionType);
  TestValidator.equals("status")(sanctionResp.status)(sanctionStatus);
  TestValidator.equals("rationale")(sanctionResp.rationale)(sanctionRationale);
  TestValidator.equals("start_at")(sanctionResp.start_at)(startAt);
  TestValidator.equals("end_at")(sanctionResp.end_at)(endAt);
  TestValidator.predicate("created_at is date-time")(!!Date.parse(sanctionResp.created_at));
  TestValidator.predicate("updated_at is date-time")(!!Date.parse(sanctionResp.updated_at));
  TestValidator.equals("deleted_at is null")(sanctionResp.deleted_at)(null);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
