  TestValidator.equals("rationale updated")(updateResp.rationale)(newRationale);
  TestValidator.equals("end_at updated")(updateResp.end_at)(newEndAt);
  TestValidator.equals("status updated")(updateResp.status)("active");
  TestValidator.equals("created_at static")(updateResp.created_at)(sanction.created_at);
  TestValidator.predicate("updated_at newer")(new Date(updateResp.updated_at).getTime() >= new Date(sanction.updated_at).getTime());
}

