/**
 * Validates business rule enforcement for forbidden updates on immutable sanction fields.
 *
 * Business context: Sanction entities are linked to specific moderation actions and a particular type
 * (e.g., 'ban', 'suspension') at the moment of their creation. For audit and compliance, fields like
 * `moderation_action_id` and `sanction_type` are considered immutable -- they establish the provenance
 * and nature of the sanction, and may not be updated after the fact by business policy. Attempts to update
 * these fields via the sanctioned update endpoint must be properly rejected by the backend, and an audit
 * trail should log such attempts.
 *
 * Test scenario:
 * 1. Register a new admin (required for privileged actions)
 * 2. Authenticate as admin to set up authorization
 * 3. Create a user/member as the sanction target
 * 4. Create a moderation action as context (linked to the admin as operator)
 * 5. Create a sanction entity referencing the moderation action
 * 6. Attempt to update immutable fields (e.g., sanction_type) via the sanctioned update endpoint
 * 7. Assert that the attempt is rejected with a business logic or validation error
 * 8. Optionally (if supported), confirm that the sanction entity is unchanged
 */
export async function test_api_sanction_update_immutable_field_rejected(connection: api.IConnection) {
  // 1. Register a new admin for privileged actions
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  await api.functional.auth.admin.register.signUp(connection, {
