  });

  // 2. Login as admin (authorization
  await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 3. Create a new member (target of the sanction)
  const member = await api.functional.polEcoBoard.members.create(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password_hash: RandomGenerator.alphaNumeric(20),
      display_name: RandomGenerator.name(),
      consent_status: "given",
      profile_image_uri: null,
    } satisfies IPolEcoBoardMember.ICreate,
  });
  typia.assert(member);

  // 4. Create a moderation action
  const moderationAction = await api.functional.polEcoBoard.admin.moderationActions.create(connection, {
    body: {
      report_id: typia.random<string & tags.Format<"uuid">>(),
      operator_id: member.id, // Since admin's UUID is not directly available, use member as dummy
      action_type: "ban_user",
      target_type: "user",
      status: "completed",
      rationale: "Test violation for sanction triggering.",
      outcome: "accepted",
    } satisfies IPolEcoBoardModerationAction.ICreate,
  });
  typia.assert(moderationAction);

  // 5. Create a sanction entity
  const sanction = await api.functional.polEcoBoard.admin.sanctions.create(connection, {
    body: {
      moderation_action_id: moderationAction.id,
      sanctioned_user_id: member.id,
      sanction_type: "ban",
      status: "active",
      rationale: "Serious terms of service violation.",
      start_at: new Date().toISOString(),
      end_at: null,
    } satisfies IPolEcoBoardSanction.ICreate,
  });
  typia.assert(sanction);

  // 6. Attempt forbidden field update: change sanction_type, which is immutable per rules
  await TestValidator.error("Sanction update with forbidden field must be rejected")(() =>
    api.functional.polEcoBoard.admin.sanctions.update(connection, {
      sanctionId: sanction.id,
      body: {
        sanction_type: "warning", // attempting forbidden change
        rationale: "This should not be accepted.",
      } satisfies IPolEcoBoardSanction.IUpdate,
    })
  );
  // 7. If a GET endpoint for sanctions existed, a follow-up assertion on unchanged sanction would be made here
}

