/**
 * Test the ability of an admin to delete a guest session record in compliance with privacy and audit requirements.
 *
 * This test verifies that:
 * - Only an admin can delete a guest session record.
 * - The guest data is irretrievable after deletion (i.e. it cannot be fetched).
 * - The operation supports compliance by ensuring data is not recoverable post-removal.
 *
 * The workflow is as follows:
 * 1. Register a new admin user account.
 * 2. Log in as that admin to acquire authorization tokens.
 * 3. Create a guest session (public endpoint) and extract its guestId.
 * 4. As the admin, invoke the delete API using the guestId.
 * 5. Note: There is no provided API to fetch a guest session by id, so post-deletion retrieval is not possible to test directly.
 *
 * Log/audit checks are assumed to be implementation-level and not testable via API without additional endpoints.
 */
export async function test_api_guest_delete_valid_admin(
  connection: api.IConnection
) {
  // 1. Register a new admin user
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const signUpResp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(signUpResp);

  // 2. Login as admin to get JWT session
  const signInResp = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(signInResp);

  // 3. Create a guest session (public, no auth needed)
  const guestCreateResp = await api.functional.polEcoBoard.guests.create(connection, {
    body: {
      ip_address: "203.0.113.1",
      device_fingerprint: RandomGenerator.alphaNumeric(16),
      consent_status: "v1.2-accepted",
    } satisfies IPolEcoBoardGuest.ICreate,
  });
  typia.assert(guestCreateResp);
  const guestId = guestCreateResp.id;

  // 4. As authorized admin, delete the guest session record by id
  await api.functional.polEcoBoard.admin.guests.erase(connection, {
    guestId,
  });

  // 5. There is no API provided to fetch a guest session by id, so post-deletion fetch negative check is omitted.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardGuest";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate permission controls for deletion of guest session records.
 *
 * Only administrators should be able to delete guest session records due to the private and sensitive nature of the data. This test ensures that non-admin users — specifically, authenticated members and unauthenticated (public) users — are forbidden from deleting guest sessions via the admin-only endpoint.
 *
 * Test Procedure:
 * 1. Create a new guest session (as unauthenticated user).
 * 2. Register a normal (non-admin) member account and log in as that member.
 * 3. As an authenticated member, attempt to delete the guest session via the admin endpoint. This should result in a forbidden/unauthorized error.
 * 4. Log out to become the public/unauthenticated session.
 * 5. As a public (unauthenticated) user, attempt to delete the guest session via the admin endpoint. Again, this action must fail with a forbidden/unauthorized error.
 *
 * At each step, the API response must be checked to confirm proper enforcement of access controls and that non-admin users never succeed in deletion attempts.
 */
export async function test_api_guest_delete_forbidden_nonadmin(connection: api.IConnection) {
  // 1. Create a new guest session (public)
  const guest = await api.functional.polEcoBoard.guests.create(connection, {
    body: {
      ip_address: '127.0.0.1',
      device_fingerprint: RandomGenerator.alphaNumeric(16),
      consent_status: RandomGenerator.alphabets(8),
    } satisfies IPolEcoBoardGuest.ICreate,
  });
  typia.assert(guest);

  // 2. Register a new member (non-admin)
  const memberEmail = typia.random<string & tags.Format<'email'>>();
  const memberPassword = typia.random<string & tags.Format<'password'>>();
  const signUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(signUpResult);

  // 3. Log in as the member
  const signInResult = await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignIn,
  });
  typia.assert(signInResult);

  // 4. As authenticated member, try to delete guest (should fail)
  await TestValidator.error(
    'non-admin member cannot delete guest via admin endpoint',
  )(async () => {
    await api.functional.polEcoBoard.admin.guests.erase(connection, {
      guestId: guest.id,
    });
  });

  // 5. Become public session (simulate logout by removing Authorization header)
  if (connection.headers) delete connection.headers['Authorization'];

  // 6. As public user, try to delete guest (should fail)
  await TestValidator.error(
    'unauthenticated user cannot delete guest via admin endpoint',
  )(async () => {
    await api.functional.polEcoBoard.admin.guests.erase(connection, {
      guestId: guest.id,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IPageIPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate advanced member search with filters and pagination by an admin.
 *
 * This test ensures that the member search endpoint allows an administrator
 * to search for members using various filters and pagination options,
 * with correct result sets and security constraints. It proves member 
 * information is filtered and sorted per criteria, pagination works, and 
 * sensitive fields (like password hashes) are never present. It also confirms
 * a non-admin is denied access.
 *
 * Steps:
 * 1. Register a new admin account with a random business-valid email and a strong password (min length 8).
 * 2. Log in as the admin to set authentication context (store Authorization header in connection).
 * 3. Register multiple (N=6) member accounts using random emails and display names (using unique substrings for filtering), spaced with different creation intents (for date filtering test).
 * 4. As admin, search:
 *    (a) Without filters: all members, assert expected count >= members created, pagination structure is correct, and each member has allowed fields only (no credentials hashes, etc.)
 *    (b) By partial display_name: filter using a unique substring from one member, verify only that member is returned.
 *    (c) By registration date: filter for members created after a target date (using local test memory for created_at timestamps), verify date-based filtering.
 *    (d) By paging and sorting: query with low limit (e.g. 2), change sort_field and sort_direction, and verify correct ordering/chunk.
 * 5. As a regular member, attempt to perform search and confirm access is denied (catch error).
 */
export async function test_api_member_search_admin_role_filters_pagination(
  connection: api.IConnection,
) {
  // ------ Step 1 & 2: Admin registration and login ------
  const adminEmail = `${RandomGenerator.alphabets(8)}@company.com`;
  const adminPassword = RandomGenerator.alphaNumeric(12);

  // Register admin
  const adminSignUpOutput = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUpOutput);

  // Log in as admin (to set Authorization header)
  const adminLoginOutput = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminLoginOutput);

  // ------ Step 3: Register test member accounts ------
  type TestMember = { email: string; password: string; displayName: string; createdAt: string };
  const createdTestMembers: TestMember[] = [];
  const DISPLAY_NAME_PREFIX = RandomGenerator.alphabets(4);
  for (let i = 0; i < 6; ++i) {
    // Use deterministic display_name prefixes; create some for substring filter test
    const displayName = `${DISPLAY_NAME_PREFIX}_${RandomGenerator.alphabets(5)}_${i}`;
    const email = `${RandomGenerator.alphabets(9)}_${i}@testdomain.com`;
    const password = RandomGenerator.alphaNumeric(10 + i); // ensure valid/unique pw
    // Wait to space out created_at timestamps for date filtering
    await new Promise(res => setTimeout(res, 1100));
    const memberSignUpOutput = await api.functional.auth.member.register.signUp(connection, {
      body: {
        email,
        password,
      } satisfies IMemberAuthenticationMemberSignUp,
    });
    typia.assert(memberSignUpOutput);
    // The actual created_at will only be available via subsequent search, so record local time
    createdTestMembers.push({ email, password, displayName, createdAt: new Date().toISOString() });
  }

  // ------ Step 4a: As admin, search all (no filters) ------
  const allMembersPage = await api.functional.polEcoBoard.admin.members.search(connection, {
    body: {} satisfies IPolEcoBoardMember.IRequest,
  });
  typia.assert(allMembersPage);
  TestValidator.predicate("all test members present")(
    allMembersPage.data.filter(m => createdTestMembers.some(tm => m.email === tm.email)).length >= 6,
  );
  TestValidator.predicate("pagination structure")(
    typeof allMembersPage.pagination.current === "number" &&
    typeof allMembersPage.pagination.limit === "number" &&
    typeof allMembersPage.pagination.records === "number" &&
    typeof allMembersPage.pagination.pages === "number"
  );
  for (const member of allMembersPage.data) {
    // Confirm only allowed member fields are returned, no credentials etc.
    typia.assert(member);
    const forbiddenFields = ["password", "password_hash", "credential_hash"];
    for (const f of forbiddenFields)
      TestValidator.predicate(`field ${f} not present`)(!(f in member));
  }

  // ------ Step 4b: Filter by partial display_name ------
  // Use a unique substring from one test member's display name
  const testDisplayName = createdTestMembers[2].displayName;
  // Use the 2nd segment of the display name (after '_') as filter
  const displayNameSubstring = testDisplayName.split("_")[1].slice(0, 3);
  const displayNameFilteredPage = await api.functional.polEcoBoard.admin.members.search(connection, {
    body: {
      display_name: displayNameSubstring,
    } satisfies IPolEcoBoardMember.IRequest,
  });
  typia.assert(displayNameFilteredPage);
  // Results should include at least one test member with that substring
  TestValidator.predicate("display_name filter matches")(
    displayNameFilteredPage.data.some(m => m.display_name.includes(displayNameSubstring)),
  );

  // ------ Step 4c: Date filtering ------
  // Use a midpoint "created_at" from a local record
  const midIdx = Math.floor(createdTestMembers.length / 2);
  const fromDate = createdTestMembers[midIdx].createdAt;
  const dateFilteredPage = await api.functional.polEcoBoard.admin.members.search(connection, {
    body: {
      created_after: fromDate,
    } satisfies IPolEcoBoardMember.IRequest,
  });
  typia.assert(dateFilteredPage);
  TestValidator.predicate("date filter")(
    dateFilteredPage.data.every(m => Date.parse(m.created_at) >= Date.parse(fromDate)),
  );

  // ------ Step 4d: Paging and sorting ------
  const pageLimit = 2;
  const sortedAscPage = await api.functional.polEcoBoard.admin.members.search(connection, {
    body: {
      limit: pageLimit,
      sort_field: "created_at",
      sort_direction: "asc",
    } satisfies IPolEcoBoardMember.IRequest,
  });
  typia.assert(sortedAscPage);
  TestValidator.equals("page chunk matches limit")(sortedAscPage.data.length)(pageLimit);
  // For ascending, earliest created_at first
  const ascTimestamps = sortedAscPage.data.map(m => m.created_at);
  TestValidator.predicate("sorted ascending")(
    ascTimestamps.every((v, i, arr) => i === 0 || v >= arr[i - 1]),
  );

  // Descending sort
  const sortedDescPage = await api.functional.polEcoBoard.admin.members.search(connection, {
    body: {
      limit: pageLimit,
      sort_field: "created_at",
      sort_direction: "desc",
    } satisfies IPolEcoBoardMember.IRequest,
  });
  typia.assert(sortedDescPage);
  const descTimestamps = sortedDescPage.data.map(m => m.created_at);
  TestValidator.predicate("sorted descending")(
    descTimestamps.every((v, i, arr) => i === 0 || v <= arr[i - 1]),
  );

  // ------ Step 5: Access as non-admin (should fail) ------
  // Log in as one of the test members (simulate member session)
  const testMember = createdTestMembers[0];
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: testMember.email,
      password: testMember.password,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  // Try member search as non-admin
  await TestValidator.error("member search forbidden for non-admin")(async () => {
    await api.functional.polEcoBoard.admin.members.search(connection, {
      body: {} satisfies IPolEcoBoardMember.IRequest,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test admin-restricted retrieval of detailed member account info.
 *
 * This E2E test simulates proper privileged access and data audit workflow for the member management feature.
 *
 * Steps:
 * 1. Register a new member account (for target lookup and population of fields)
 * 2. Register a new admin account
 * 3. Log in as admin to obtain required credentials/tokens for privileged endpoint use
 * 4. Call the GET /polEcoBoard/admin/members/{memberId} endpoint using the admin's authorization
 * 5. Assert that the returned member object contains all expected profile/account fields (id, email, display_name, profile_image_uri, consent_status, is_active, timestamps, no password hash or credentials in output)
 * 6. Compare key returned fields to the values created in step 1 and check business constraints
 */
export async function test_api_member_detail_retrieve_success(connection: api.IConnection) {
  // 1. Register a regular member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = typia.random<string & tags.Format<"password">>();
  const memberSignUpResult = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    },
  });
  typia.assert(memberSignUpResult);

  // 2. Register an admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  const adminSignUpResult = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminSignUpResult);

  // 3. Admin login to get JWT/Credentials
  const adminLoginResult = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    },
  });
  typia.assert(adminLoginResult);
  // Connection headers are now set for admin

  // 4. Retrieve memberId (see note below):
  // The system does not provide a direct way to obtain the UUID of a newly registered member
  // (register does not return id and no search/list endpoint is present), so for a robust E2E
  // we would need a system hook or JWT payload parsing. Here, use a generated UUID to
  // demonstrate workflow. Update this when possible with real ID.
  const memberId = typia.random<string & tags.Format<"uuid">>(); // WARNING: see above note
  const member = await api.functional.polEcoBoard.admin.members.at(connection, { memberId });
  typia.assert(member);

  // Validate structure and business logic of returned member
  TestValidator.predicate("all expected member account fields present")(
    typeof member.id === "string" &&
    typeof member.email === "string" &&
    typeof member.display_name === "string" &&
    typeof member.consent_status === "string" &&
    typeof member.is_active === "boolean" &&
    typeof member.created_at === "string" &&
    typeof member.updated_at === "string" &&
    (member.profile_image_uri === null || typeof member.profile_image_uri === "string" || typeof member.profile_image_uri === "undefined") &&
    (member.deleted_at === null || typeof member.deleted_at === "string" || typeof member.deleted_at === "undefined")
  );
  TestValidator.predicate("No sensitive fields exposed")(Object.keys(member).every(k => !k.toLowerCase().includes("password")));
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardMember";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Test proper enforcement of admin-only access and not found error handling for member detail retrieval.
 *
 * This test covers the following scenarios to ensure both security and business rules:
 *
 * 1. Register and login as an admin for privileged API access.
 * 2. Register and login as a member (for non-admin forbidden attempt).
 * 3. As admin, attempt to retrieve a member by a completely invalid UUID (should yield not found).
 * 4. As member (not admin), attempt to get details via admin endpoint (should be forbidden).
 *
 * Verifies:
 * - Not found enforcement
 * - Role/permission enforcement
 */
export async function test_api_member_detail_retrieve_not_found_or_forbidden(
  connection: api.IConnection,
) {
  // 1. Register and log in as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  await api.functional.auth.admin.login.signIn(connection, {
    body: { email: adminEmail, password: adminPassword } satisfies IPolEcoBoardAdminAuth.SignIn,
  });

  // 2. Register a member for forbidden scenario
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = typia.random<string & tags.Format<"password">>();
  await api.functional.auth.member.register.signUp(connection, {
    body: { email: memberEmail, password: memberPassword } satisfies IMemberAuthenticationMemberSignUp,
  });

  // 3. As admin, try to retrieve a completely non-existent memberId
  const nonExistentMemberId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("not found for invalid member id")(() =>
    api.functional.polEcoBoard.admin.members.at(connection, {
      memberId: nonExistentMemberId,
    }),
  );

  // 4. As a member (non-admin), attempt admin endpoint and expect forbidden
  await api.functional.auth.member.login.signIn(connection, {
    body: { email: memberEmail, password: memberPassword } satisfies IMemberAuthenticationMemberSignIn,
  });
  const someId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("forbidden when non-admin tries to get admin member details")(() =>
    api.functional.polEcoBoard.admin.members.at(connection, {
      memberId: someId,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPageIPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";
import type { IPolEcoBoardModeratorRegistration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorRegistration";
import type { IPolEcoBoardModeratorAuthentication } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardModeratorAuthentication";

/**
 * Validate advanced post search and filtering via the moderator API, enforcing permission boundaries and result accuracy.
 *
 * This test covers registration and authentication flows for both moderator and standard member users, population of post data with varying authors and states (normal, flagged, soft-deleted), and ensures:
 * - The moderator can retrieve and filter posts by fields such as author, status, category, creation date, with correct pagination and result summary data.
 * - The moderator can see both flagged and soft-deleted posts in results when filtering for these states (not directly tested due to API limitations).
 * - Attempts by a regular member to access the moderator search endpoint fail with appropriate permission error (boundary enforcement).
 *
 * Steps:
 * 1. Register and authenticate a moderator
 * 2. Register and authenticate two members
 * 3. Each member creates posts with differing categories and contents
 * 4. As moderator, perform post searches with combinations of filters:
 *    - By author_member_id (should yield only that member's posts)
 *    - By category_id (should filter to posts of that category)
 *    - By creation date range (should respect min/max created_at boundaries)
 *    - By pagination (limit/page)
 *    - By ordering (order_by/order_dir)
 * 5. Validate correctness of search responses (summaries match filters/query as per business rules)
 * 6. As regular member, attempt to call the moderator search endpoint and validate unauthorized/forbidden error.
 */
export async function test_api_moderator_post_search_filters_and_permissions(
  connection: api.IConnection,
) {
  // 1. Register moderator
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorPassword = RandomGenerator.alphabets(12);
  const moderatorDisplayName = RandomGenerator.name();
  const consentStatus = "v1";
  const moderatorReg = await api.functional.auth.moderator.register.signUp(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
      display_name: moderatorDisplayName,
      consent_status: consentStatus,
    },
  });
  typia.assert(moderatorReg);
  TestValidator.equals("Moderator email")(moderatorReg.email)(moderatorEmail);

  // 2. Moderator login (establishes moderator session)
  const moderatorLogin = await api.functional.auth.moderator.login.signIn(connection, {
    body: {
      email: moderatorEmail,
      password: moderatorPassword,
    },
  });
  typia.assert(moderatorLogin);
  TestValidator.equals("Moderator login email")(moderatorLogin.email)(moderatorEmail);

  // 3. Register and authenticate two members
  const memberAccounts = await ArrayUtil.asyncRepeat(2)(async () => {
    const email = typia.random<string & tags.Format<"email">>();
    const password = RandomGenerator.alphabets(14);
    const reg = await api.functional.auth.member.register.signUp(connection, {
      body: {
        email,
        password,
      },
    });
    typia.assert(reg);
    // Authenticate and store for later use
    const login = await api.functional.auth.member.login.signIn(connection, {
      body: {
        email,
        password,
      },
    });
    typia.assert(login);
    return { email, password, login };
  });

  // 4. Each member creates at least two posts (different categories, different content)
  // Use random UUIDs for categories (no category create API)
  const categories = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  const posts: IPolEcoBoardPost[] = [];
  for (const { email, password } of memberAccounts) {
    // Switch to member session
    await api.functional.auth.member.login.signIn(connection, {
      body: { email, password },
    });
    for (let j = 0; j < 2; ++j) {
      const categoryIdx = j % categories.length;
      const res = await api.functional.polEcoBoard.member.posts.create(connection, {
        body: {
          category_id: categories[categoryIdx],
          title: RandomGenerator.paragraph()(10),
          body: RandomGenerator.content()()(30),
          tag_ids: null,
          attachments: null,
        },
      });
      typia.assert(res);
      posts.push(res);
    }
  }

  // 5. As moderator, perform post searches with combinations of filters
  await api.functional.auth.moderator.login.signIn(connection, {
    body: { email: moderatorEmail, password: moderatorPassword },
  });

  // (A) Search by author_member_id (should retrieve only that author's posts)
  for (const post of posts) {
    const result = await api.functional.polEcoBoard.moderator.posts.search(connection, {
      body: { author_member_id: post.author_member_id },
    });
    typia.assert(result);
    TestValidator.predicate("Only relevant member's posts")(
      result.data.every((s) => s.author_member_id === post.author_member_id),
    );
  }

  // (B) Search by category_id
  for (const category_id of categories) {
    const result = await api.functional.polEcoBoard.moderator.posts.search(connection, {
      body: { category_id },
    });
    typia.assert(result);
    TestValidator.predicate("Only category's posts")(
      result.data.every((s) => s.category_id === category_id),
    );
  }

  // (C) By min_created_at/max_created_at using posts' timestamps
  const [minDate, maxDate] = [posts[0].created_at, posts[posts.length - 1].created_at];
  {
    const result = await api.functional.polEcoBoard.moderator.posts.search(connection, {
      body: { min_created_at: minDate, max_created_at: maxDate },
    });
    typia.assert(result);
    TestValidator.predicate("Date filter - all in range")(
      result.data.every(
        (s) => s.created_at >= minDate && s.created_at <= maxDate,
      ),
    );
  }

  // (D) Pagination - limit/page
  {
    const result = await api.functional.polEcoBoard.moderator.posts.search(connection, {
      body: { limit: 1, page: 1 },
    });
    typia.assert(result);
    TestValidator.equals("Should be one per page")(result.data.length)(1);
  }

  // (E) Ordering - order_by/order_dir
  {
    const result = await api.functional.polEcoBoard.moderator.posts.search(connection, {
      body: { order_by: "created_at", order_dir: "desc" },
    });
    typia.assert(result);
    const sorted = [...result.data].sort((a, b) => (a.created_at < b.created_at ? 1 : -1));
    TestValidator.equals("Ordering descending")(result.data.map((s) => s.id))(sorted.map((s) => s.id));
  }

  // 6. Permissions: regular member attempts moderator search (should fail)
  // Use first member
  const { email: memberEmail, password: memberPassword } = memberAccounts[0];
  await api.functional.auth.member.login.signIn(connection, {
    body: { email: memberEmail, password: memberPassword },
  });
  await TestValidator.error("Member forbidden for moderator endpoint")(async () => {
    await api.functional.polEcoBoard.moderator.posts.search(connection, {
      body: {},
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPageIPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPolEcoBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * E2E test: admin can search and filter post listings with all advanced filters, pagination and ordering on polEcoBoard.
 *
 * Business context: Validates that platform admins are able to audit or moderate any post (including deleted/flagged), are able to search by any filterable property (category, author, status, keyword, tag, date, views), and pagination/sorting works as expected. Covers edge cases—including empty result and invalid filters.
 *
 * Steps:
 * 1. Register and login as a new admin
 * 2. Create multiple posts with a diverse mix of category_id, title/body/keywords, tags, and various flags (simulate flagged/deleted by property if feasible)
 * 3. For each filter feature, perform a search with that filter and assert results match expectations
 * 4. Test pagination and ordering options
 * 5. Test edge cases: empty results, invalid search
 */
export async function test_api_admin_post_search_success_and_filtering(connection: api.IConnection) {
  // 1. Register and login as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const registration = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(registration);
  // Login to get Authorization set
  const login = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(login);
  // At this point, connection.headers.Authorization is set to token by SDK

  // 2. Create two fake categories—since there is no endpoint, just generate UUIDs for category_id
  const categoryIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  // Simulate two different tag IDs for tag_ids filtering
  const tagIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];

  // Create four posts, with varying category, title/body/keywords, tags, flagged etc
  const posts: IPolEcoBoardPost[] = [];
  posts.push(await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryIds[0],
      title: "Climate Policy Overview", // contains 'climate'
      body: "This post discusses new global climate policy initiatives.", // contains 'climate'
      tag_ids: [tagIds[0]],
      attachments: [],
    } satisfies IPolEcoBoardPost.ICreate,
  }));
  posts.push(await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryIds[1],
      title: "Economic Recovery Plan", // contains 'economy'
      body: "Stimulus and economic reform discussion.", // contains 'economy'
      tag_ids: [tagIds[1]],
      attachments: [],
    } satisfies IPolEcoBoardPost.ICreate,
  }));
  posts.push(await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryIds[0],
      title: "Flagged: Unusual Activity", // keyword 'flagged', flagged should be set (simulate)
      body: "Moderator has flagged this post for unusual content.",
      tag_ids: [tagIds[0]],
      attachments: [],
    } satisfies IPolEcoBoardPost.ICreate,
  }));
  posts.push(await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: categoryIds[1],
      title: "Deleted: Obsolete Discussion", // keyword 'deleted', will simulate deleted by reading property after creation
      body: "This thread has been deleted by admin.",
      tag_ids: [tagIds[1]],
      attachments: [],
    } satisfies IPolEcoBoardPost.ICreate,
  }));

  for (const post of posts) typia.assert(post);

  // 3. Filtering by category_id should only return posts from that category
  const resCategory = await api.functional.polEcoBoard.admin.posts.search(connection, {
    body: { category_id: categoryIds[0] } satisfies IPolEcoBoardPost.IRequest
  });
  typia.assert(resCategory);
  TestValidator.predicate("all posts have category 0")(
    resCategory.data.every((p) => p.category_id === categoryIds[0])
  );

  // 4. Filtering by tag_ids should only return posts with the tag(s)
  const resTag = await api.functional.polEcoBoard.admin.posts.search(connection, {
    body: { tag_ids: [tagIds[0]] } satisfies IPolEcoBoardPost.IRequest
  });
  typia.assert(resTag);
  // Can't directly check tag match because summary doesn't include tags - at minimum, assert success
  TestValidator.predicate("admin tag search returns summary result")(
    Array.isArray(resTag.data)
  );

  // 5. Filtering by keyword (search in title/body)
  const resKeyword = await api.functional.polEcoBoard.admin.posts.search(connection, {
    body: { search: "climate" } satisfies IPolEcoBoardPost.IRequest
  });
  typia.assert(resKeyword);
  TestValidator.predicate("admin keyword search returns at least one expected post")(
    resKeyword.data.some((p) => p.title.includes("climate"))
  );

  // 6. Filtering by author_member_id
  const authorId = posts[0].author_member_id;
  const resAuthor = await api.functional.polEcoBoard.admin.posts.search(connection, {
    body: { author_member_id: authorId } satisfies IPolEcoBoardPost.IRequest
  });
  typia.assert(resAuthor);
  TestValidator.predicate("all posts have correct author")(
    resAuthor.data.every((p) => p.author_member_id === authorId)
  );

  // 7. Filtering by flagged
  const resUnflagged = await api.functional.polEcoBoard.admin.posts.search(connection, {
    body: { flagged: false } satisfies IPolEcoBoardPost.IRequest
  });
  typia.assert(resUnflagged);
  TestValidator.predicate("all posts are unflagged")(
    resUnflagged.data.every((p) => !p.flagged)
  );

  // 8. Pagination: limit 2, page 1, sort by created_at descending
  const resPage = await api.functional.polEcoBoard.admin.posts.search(connection, {
    body: {
      limit: 2,
      page: 1,
      order_by: "created_at",
      order_dir: "desc",
    } satisfies IPolEcoBoardPost.IRequest
  });
  typia.assert(resPage);
  TestValidator.equals("page size is 2")(resPage.data.length)(2);

  // 9. Edge case: filter by non-existent category
  const resEmptyCategory = await api.functional.polEcoBoard.admin.posts.search(connection, {
    body: { category_id: typia.random<string & tags.Format<"uuid">>() } satisfies IPolEcoBoardPost.IRequest
  });
  typia.assert(resEmptyCategory);
  TestValidator.equals("no posts for bogus category")(resEmptyCategory.data.length)(0);

  // 10. Edge case: filter by non-existent author
  const resEmptyAuthor = await api.functional.polEcoBoard.admin.posts.search(connection, {
    body: { author_member_id: typia.random<string & tags.Format<"uuid">>() } satisfies IPolEcoBoardPost.IRequest
  });
  typia.assert(resEmptyAuthor);
  TestValidator.equals("no posts for bogus author")(resEmptyAuthor.data.length)(0);

  // 11. Edge case: search with empty keyword
  const resEmptySearch = await api.functional.polEcoBoard.admin.posts.search(connection, {
    body: { search: "-unlikely-keyword-" } satisfies IPolEcoBoardPost.IRequest
  });
  typia.assert(resEmptySearch);
  TestValidator.equals("no posts for weird search")(resEmptySearch.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IMemberAuthenticationMemberSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignIn";
import type { IMemberAuthenticationMemberSignInResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignInResult";

/**
 * Validate post detail retrieval and member permission enforcement on PolEcoBoard posts.
 *
 * This test covers full business logic for detail retrieval via /polEcoBoard/member/posts/{postId}:
 *  - Author (member who created the post) can always fetch their own post, even if flagged or deleted
 *  - Regular members cannot see flagged or deleted posts authored by others
 *  - Control: active, public post should be retrievable by all members
 * The test simulates two members, verifying both successful and forbidden flows and the business status in the returned DTO.
 *
 * Step-by-step process:
 * 1. Register member A and log in
 * 2. Member A creates a post
 * 3. Member A fetches own post detail (should succeed)
 * 4. Member A flags the post (sets flagged=true)
 * 5. Member A fetches flagged post as author (should succeed, flagged:true)
 * 6. Member A soft deletes the post (sets deleted_at)
 * 7. Member A fetches own soft deleted post (should succeed, deleted_at!=null)
 * 8. Register member B and log in
 * 9. Member B attempts to fetch flagged or deleted post by member A (should fail/forbidden)
 * 10. Member B creates a fresh post
 * 11. Member A (now as not-author of B's post) fetches public post (should succeed)
 */
export async function test_api_member_get_post_detail_success_and_permission(connection: api.IConnection) {
  // 1. Register first member (memberA) and log in
  const memberA_email = typia.random<string & tags.Format<"email">>();
  const memberA_password = typia.random<string & tags.Format<"password">>();
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberA_email,
      password: memberA_password,
    },
  });
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberA_email,
      password: memberA_password,
    },
  });

  // 2. MemberA creates a public post
  const category_id = typia.random<string & tags.Format<"uuid">>();
  const postA = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id,
      title: "Member A's first post",
      body: "This is the content of the post.",
      tag_ids: null,
      attachments: null,
    },
  });
  typia.assert(postA);
  TestValidator.equals("author_member_id is memberA")(postA.author_member_id)(postA.author_member_id);
  TestValidator.equals("not flagged")(postA.flagged)(false);
  TestValidator.equals("not deleted")(postA.deleted_at)(null);

  // 3. MemberA fetches own post detail
  const postA_detail1 = await api.functional.polEcoBoard.member.posts.at(connection, {
    postId: postA.id,
  });
  typia.assert(postA_detail1);
  TestValidator.equals("same postId")(postA_detail1.id)(postA.id);
  TestValidator.equals("author is memberA")(postA_detail1.author_member_id)(postA.author_member_id);
  TestValidator.equals("not flagged")(postA_detail1.flagged)(false);
  TestValidator.equals("not deleted")(postA_detail1.deleted_at)(null);

  // 4. Flag post (set flagged=true)
  const flaggedPostA = await api.functional.polEcoBoard.member.posts.update(connection, {
    postId: postA.id,
    body: {
      // Keeping original title/body, but set flagged=true (simulated via update)
      // Only the allowed fields in IPolEcoBoardPost.IUpdate will be touched
      title: null,
      body: null,
      tag_ids: null,
      attachments: null,
    },
  });
  typia.assert(flaggedPostA);
  // Since 'flagged' is not directly settable by update (system-controlled), simulate a system state change for demo only.
  // Normally, this would require moderation/reporting API, but for now, we'll check only the update did not break ownership or detail access.

  // 5. MemberA fetches flagged post (should still succeed, possibly flagged=false as per input, unless system triggers flag)
  const postA_detail2 = await api.functional.polEcoBoard.member.posts.at(connection, {
    postId: postA.id,
  });
  typia.assert(postA_detail2);
  TestValidator.equals("same postId")(postA_detail2.id)(postA.id);
  TestValidator.equals("author is memberA")(postA_detail2.author_member_id)(postA.author_member_id);

  // 6. Soft delete the post: we simulate this by calling update (deleted_at not client-settable; assume system marks as soft deleted)
  // As we lack a real delete/flag API, skip true field mutation, check owner can always fetch detail (test policy, not system state).

  // 7. MemberA fetches own post again after simulated "deletion"
  const postA_detail3 = await api.functional.polEcoBoard.member.posts.at(connection, {
    postId: postA.id,
  });
  typia.assert(postA_detail3);
  TestValidator.equals("same postId")(postA_detail3.id)(postA.id);
  TestValidator.equals("author is memberA")(postA_detail3.author_member_id)(postA.author_member_id);

  // 8. Register & login as second member (memberB)
  const memberB_email = typia.random<string & tags.Format<"email">>();
  const memberB_password = typia.random<string & tags.Format<"password">>();
  await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberB_email,
      password: memberB_password,
    },
  });
  await api.functional.auth.member.login.signIn(connection, {
    body: {
      email: memberB_email,
      password: memberB_password,
    },
  });

