  TestValidator.equals("Comment body updated")(updatedComment.body)(updatedBody);
  TestValidator.predicate("Updated_at changed")(updatedComment.updated_at !== memberAComment.updated_at);

  // 5. Simulate edit window expiration (not possible without mutation of created_at/updated_at; skip if no support)
  // SKIPPED: Cannot simulate time passage.

  // 6. Non-author update attempt (Member B tries to edit A's comment -- should be denied)
  await api.functional.auth.member.login.signIn(connection, {
    body: { email: memberBEmail, password: memberBPassword },
