      postId: post.id,
      body: {
        body: RandomGenerator.paragraph()(5),
      } satisfies IPolEcoBoardComment.ICreate,
    },
  );
  typia.assert(comment);

  // 4. Register admin user
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>();
  const signUpAdmin = await api.functional.auth.admin.register.signUp(
    connection,
    {
      body: {
        email: adminEmail,
        password: adminPassword,
      } satisfies IPolEcoBoardAdminAuth.SignUp,
