  TestValidator.equals("comment authored by poster")(comment.author_member_id)(post.author_member_id);
  TestValidator.equals("comment references correct post")(comment.post_id)(post.id);
  TestValidator.equals("comment not deleted")(comment.deleted_at)(null);

