import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPolEcoBoardCommentEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCommentEdit";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate an admin can update mutable fields on a comment edit record for audit trail compliance.
 *
 * This test ensures:
 *  - Members can create posts and comments normally
 *  - Admins can create and update comment edits for audit/moderation purposes
 *  - The edit reason can be updated via the audit/admin endpoint and reflected in persistent records
 *  - Key identity/audit trail invariants are maintained (ids and association remain correct)
 *
 * Workflow:
 * 1. Register a member – needed for authorship
 * 2. Register an admin – for privileged edit/audit actions
 * 3. Admin logs in for session credentials
 * 4. Member creates a post
 * 5. Member comments on post
 * 6. Admin creates a comment edit record for that comment
 * 7. Admin updates the edit reason field using the PUT endpoint
 * 8. Verify the change is reflected and the record is audit-consistent
 */
export async function test_api_comment_edit_admin_correct_fields(
  connection: api.IConnection,
) {
  // 1. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = "TestPw1234!!";
  const memberSignUp = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberSignUp);

  // 2. Register an admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "TestAdmin123!";
  const adminSignUp = await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });
  typia.assert(adminSignUp);

  // 3. Admin logs in to obtain a fresh JWT
  const adminSignIn = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminSignIn);

  // 4. Member creates a post (switch to member session)
  connection.headers = { Authorization: memberSignUp.setHeaders.Authorization };
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(12),
      body: RandomGenerator.content()(1)(),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 5. Member comments on the post
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.paragraph()(3),
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment);

  // 6. Admin creates a comment edit record (switch session to admin)
  connection.headers = { Authorization: adminSignUp.setHeaders.Authorization };
  const commentEdit = await api.functional.polEcoBoard.admin.posts.comments.commentEdits.create(connection, {
    postId: post.id,
    commentId: comment.id,
    body: {
      edit_body: RandomGenerator.paragraph()(4),
      edit_reason: "Initial rationale for moderation",
    } satisfies IPolEcoBoardCommentEdit.ICreate,
  });
  typia.assert(commentEdit);

  // 7. Admin updates the edit reason
  const updatedReason = "Updated rationale for audit compliance.";
  const updatedEdit = await api.functional.polEcoBoard.admin.posts.comments.commentEdits.update(connection, {
    postId: post.id,
    commentId: comment.id,
    commentEditId: commentEdit.id,
    body: {
      edit_reason: updatedReason,
    } satisfies IPolEcoBoardCommentEdit.IUpdate,
  });
  typia.assert(updatedEdit);

  // 8. Verify the update was successful and audit identity/timestamps remain correct
  TestValidator.equals("edit_reason updated")(updatedEdit.edit_reason)(updatedReason);
  TestValidator.equals("record id consistent")(updatedEdit.id)(commentEdit.id);
  TestValidator.equals("comment association consistent")(updatedEdit.comment_id)(commentEdit.comment_id);
  // Timestamps and editor_member_id checks could be added here as needed
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPolEcoBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardPost";
import type { IPolEcoBoardAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAttachment";
import type { IPolEcoBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardComment";
import type { IPolEcoBoardCommentEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardCommentEdit";
import type { IMemberAuthenticationMemberSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUp";
import type { IMemberAuthenticationMemberSignUpResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberAuthenticationMemberSignUpResult";
import type { IPolEcoBoardAdminAuth } from "@ORGANIZATION/PROJECT-api/lib/structures/IPolEcoBoardAdminAuth";
import type { IJwtSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/IJwtSetHeaders";

/**
 * Validate that forbidden/immutable fields cannot be updated in a comment edit by admin.
 *
 * This test confirms the API enforces compliance rules:
 * - Only the allowed field (edit_reason) can be updated in a comment edit record.
 * - Attempts to update forbidden or immutable fields (like id, editor_member_id, etc.) are not possible at type level and must be rejected at runtime if malformed input is sent.
 *
 * Steps:
 * 1. Register a new admin account for authentication.
 * 2. Login as admin for session token.
 * 3. Register a new member for post/comment authoring.
 * 4. As the member, create a post.
 * 5. As the member, create a comment on that post.
 * 6. Switch to admin account, create a comment edit record for compliance/audit.
 * 7. Attempt to update the comment edit with an empty update body (simulating forbidden field update or malformed request, since forbidden fields are not present in IUpdate type). Expect API to reject.
 * 8. Attempt a valid update (only edit_reason). Expect successful update.
 */
export async function test_api_comment_edit_admin_update_forbidden_field(
  connection: api.IConnection,
) {
  // 1. Register a new admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(14);
  await api.functional.auth.admin.register.signUp(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignUp,
  });

  // 2. Login as admin
  const adminSignIn = await api.functional.auth.admin.login.signIn(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IPolEcoBoardAdminAuth.SignIn,
  });
  typia.assert(adminSignIn);
  connection.headers = { ...connection.headers, Authorization: adminSignIn.setHeaders.Authorization };

  // 3. Register a member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = RandomGenerator.alphaNumeric(10);
  const memberRes = await api.functional.auth.member.register.signUp(connection, {
    body: {
      email: memberEmail,
      password: memberPassword,
    } satisfies IMemberAuthenticationMemberSignUp,
  });
  typia.assert(memberRes);

  // 4. Switch to member auth and create a post
  connection.headers = { ...connection.headers, Authorization: memberRes.setHeaders.Authorization };
  const post = await api.functional.polEcoBoard.member.posts.create(connection, {
    body: {
      category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(15),
      body: RandomGenerator.content()(30)(),
    } satisfies IPolEcoBoardPost.ICreate,
  });
  typia.assert(post);

  // 5. Create a comment to the post as member
  const comment = await api.functional.polEcoBoard.member.posts.comments.create(connection, {
    postId: post.id,
    body: {
      body: RandomGenerator.content()(10)(),
    } satisfies IPolEcoBoardComment.ICreate,
  });
  typia.assert(comment);

  // 6. Switch back to admin and create a comment edit record
  connection.headers = { ...connection.headers, Authorization: adminSignIn.setHeaders.Authorization };
  const commentEdit = await api.functional.polEcoBoard.admin.posts.comments.commentEdits.create(connection, {
    postId: post.id,
    commentId: comment.id,
    body: {
      edit_body: RandomGenerator.content()(15)(),
      edit_reason: RandomGenerator.paragraph()(2),
    } satisfies IPolEcoBoardCommentEdit.ICreate,
  });
  typia.assert(commentEdit);

  // 7. Attempt forbidden/malformed update (not possible to send forbidden fields, but simulate empty update, which is not allowed)
  await TestValidator.error("Empty/faulty update body should be rejected")(() =>
    api.functional.polEcoBoard.admin.posts.comments.commentEdits.update(connection, {
      postId: post.id,
      commentId: comment.id,
      commentEditId: commentEdit.id,
      body: {}, // Should be rejected – nothing to update, forbidden in business rules
    })
  );

  // 8. Attempt valid update with allowed field only
  const updated = await api.functional.polEcoBoard.admin.posts.comments.commentEdits.update(connection, {
    postId: post.id,
    commentId: comment.id,
    commentEditId: commentEdit.id,
    body: {
      edit_reason: RandomGenerator.paragraph()(3),
    } satisfies IPolEcoBoardCommentEdit.IUpdate,
  });
  typia.assert(updated);
}

